(216,'child_milestones','m18_scribbles',37,1,NULL,'{\"fa\":\"خط‌خطی می‌کند\",\"en\":\"Scribbles\"}',NULL,'{\"age_months\":18,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(217,'child_milestones','m24_two_word_phrases',38,1,NULL,'{\"fa\":\"دو کلمه را با هم می‌گوید\",\"en\":\"Puts two words together\"}',NULL,'{\"age_months\":24,\"domain\":\"language\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(218,'child_milestones','m24_kicks_ball',39,1,NULL,'{\"fa\":\"به توپ ضربه می‌زند\",\"en\":\"Kicks a ball\"}',NULL,'{\"age_months\":24,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(219,'child_milestones','m24_runs',40,1,NULL,'{\"fa\":\"می‌دود\",\"en\":\"Runs\"}',NULL,'{\"age_months\":24,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(220,'child_milestones','m24_points_in_book',41,1,NULL,'{\"fa\":\"در کتاب به تصاویر اشاره می‌کند\",\"en\":\"Points to pictures in a book\"}',NULL,'{\"age_months\":24,\"domain\":\"cognitive\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(221,'child_milestones','m24_notices_feelings',42,1,NULL,'{\"fa\":\"متوجه ناراحتی دیگران می‌شود\",\"en\":\"Notices when others are upset\"}',NULL,'{\"age_months\":24,\"domain\":\"social\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(222,'child_milestones','m36_converses',43,1,NULL,'{\"fa\":\"در گفت‌وگو چند جمله رد و بدل می‌کند\",\"en\":\"Has a back-and-forth conversation\"}',NULL,'{\"age_months\":36,\"domain\":\"language\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(223,'child_milestones','m36_says_own_name',44,1,NULL,'{\"fa\":\"اسم کوچکش را می‌گوید\",\"en\":\"Says their first name\"}',NULL,'{\"age_months\":36,\"domain\":\"language\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(224,'child_milestones','m36_draws_circle',45,1,NULL,'{\"fa\":\"با دیدن نمونه دایره می‌کشد\",\"en\":\"Draws a circle after you show how\"}',NULL,'{\"age_months\":36,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(225,'child_milestones','m36_dresses_partly',46,1,NULL,'{\"fa\":\"بعضی لباس‌ها را خودش می‌پوشد\",\"en\":\"Puts on some clothes alone\"}',NULL,'{\"age_months\":36,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(226,'child_milestones','m36_plays_with_others',47,1,NULL,'{\"fa\":\"با بچه‌های دیگر بازی می‌کند\",\"en\":\"Plays with other children\"}',NULL,'{\"age_months\":36,\"domain\":\"social\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(227,'child_milestones','m48_tells_story',48,1,NULL,'{\"fa\":\"اتفاقی را که افتاده تعریف می‌کند\",\"en\":\"Tells what happened in a story or their day\"}',NULL,'{\"age_months\":48,\"domain\":\"language\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(228,'child_milestones','m48_names_colours',49,1,NULL,'{\"fa\":\"چند رنگ را نام می‌برد\",\"en\":\"Names a few colours\"}',NULL,'{\"age_months\":48,\"domain\":\"cognitive\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(229,'child_milestones','m48_pretend_play',50,1,NULL,'{\"fa\":\"بازی نقش‌آفرینی می‌کند\",\"en\":\"Plays pretend\"}',NULL,'{\"age_months\":48,\"domain\":\"social\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(230,'child_milestones','m48_catches_ball',51,1,NULL,'{\"fa\":\"توپ بزرگ را می‌گیرد\",\"en\":\"Catches a large ball\"}',NULL,'{\"age_months\":48,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(231,'child_milestones','m48_comforts_others',52,1,NULL,'{\"fa\":\"دیگران را دلداری می‌دهد\",\"en\":\"Comforts others who are hurt or sad\"}',NULL,'{\"age_months\":48,\"domain\":\"social\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(232,'child_milestones','m60_counts_to_ten',53,1,NULL,'{\"fa\":\"تا ۱۰ می‌شمارد\",\"en\":\"Counts to 10\"}',NULL,'{\"age_months\":60,\"domain\":\"cognitive\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(233,'child_milestones','m60_hops_one_foot',54,1,NULL,'{\"fa\":\"روی یک پا لی‌لی می‌کند\",\"en\":\"Hops on one foot\"}',NULL,'{\"age_months\":60,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(234,'child_milestones','m60_writes_letters',55,1,NULL,'{\"fa\":\"چند حرف از اسمش را می‌نویسد\",\"en\":\"Writes some letters of their name\"}',NULL,'{\"age_months\":60,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(235,'child_milestones','m60_follows_rules',56,1,NULL,'{\"fa\":\"در بازی‌ها قانون را رعایت می‌کند\",\"en\":\"Follows rules in simple games\"}',NULL,'{\"age_months\":60,\"domain\":\"social\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(236,'child_milestones','m60_buttons',57,1,NULL,'{\"fa\":\"دکمه‌ها را باز و بسته می‌کند\",\"en\":\"Does and undoes buttons\"}',NULL,'{\"age_months\":60,\"domain\":\"motor\"}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(237,'child_milestone_activities','m2_face_time',1,1,NULL,'{\"fa\":\"صورت به صورت\",\"en\":\"Face to face\"}','{\"fa\":\"در فاصله ۲۰ تا ۳۰ سانتی صورتش با او حرف بزن و لبخند بزن.\",\"en\":\"Talk and smile 20–30 cm from their face.\"}','{\"age_months\":2}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(238,'child_milestone_activities','m2_tummy_time',2,1,NULL,'{\"fa\":\"وقت دمر (Tummy time)\",\"en\":\"Tummy time\"}','{\"fa\":\"روزی چند بار، هر بار یکی دو دقیقه وقتی بیدار است روی شکم بگذارش.\",\"en\":\"A few times a day, a minute or two on the tummy while awake.\"}','{\"age_months\":2}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(239,'child_milestone_activities','m3_tummy_time',3,1,NULL,'{\"fa\":\"وقت دمر (Tummy time)\",\"en\":\"Tummy time\"}','{\"fa\":\"روزی چند بار، هر بار ۳ تا ۵ دقیقه روی شکم؛ گردن و شانه قوی می‌شود.\",\"en\":\"A few times a day, 3 to 5 minutes on the tummy; it strengthens neck and shoulders.\"}','{\"age_months\":3}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(240,'child_milestone_activities','m3_sound_talk',4,1,NULL,'{\"fa\":\"گفت‌وگوی صدا\",\"en\":\"Sound conversations\"}','{\"fa\":\"صداهایش را تکرار کن و منتظر جوابش بمان؛ پایه زبان است.\",\"en\":\"Repeat their sounds and wait for a reply; it is the root of language.\"}','{\"age_months\":3}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(241,'child_milestone_activities','m4_rattle_reach',5,1,NULL,'{\"fa\":\"جغجغه در دسترس\",\"en\":\"Reach for the rattle\"}','{\"fa\":\"اسباب‌بازی را کمی دورتر بگیر تا برای گرفتنش تلاش کند.\",\"en\":\"Hold a toy just out of reach so they stretch for it.\"}','{\"age_months\":4}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(242,'child_milestone_activities','m4_mirror_play',6,1,NULL,'{\"fa\":\"بازی با آینه\",\"en\":\"Mirror play\"}','{\"fa\":\"جلوی آینه با او حرف بزن و چهره‌اش را نشانش بده.\",\"en\":\"Talk to them in front of a mirror and show them their face.\"}','{\"age_months\":4}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(243,'child_milestone_activities','m6_peekaboo',7,1,NULL,'{\"fa\":\"دالی‌موشه\",\"en\":\"Peekaboo\"}','{\"fa\":\"صورتت را بپوشان و دوباره نشان بده؛ می‌خندد و منتظر می‌ماند.\",\"en\":\"Hide your face and show it again; they laugh and wait for it.\"}','{\"age_months\":6}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(244,'child_milestone_activities','m6_supported_sitting',8,1,NULL,'{\"fa\":\"نشستن با تکیه\",\"en\":\"Supported sitting\"}','{\"fa\":\"با بالش دورش را امن کن و بگذار نشستن را تمرین کند.\",\"en\":\"Surround them with cushions and let them practise sitting.\"}','{\"age_months\":6}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(245,'child_milestone_activities','m9_name_things',9,1,NULL,'{\"fa\":\"اسم چیزها\",\"en\":\"Name things\"}','{\"fa\":\"به چیزهایی که نگاه می‌کند اشاره کن و اسمشان را بگو.\",\"en\":\"Point to what they look at and say its name.\"}','{\"age_months\":9}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(246,'child_milestone_activities','m9_crawl_course',10,1,NULL,'{\"fa\":\"مسیر چهاردست‌وپا\",\"en\":\"Crawling course\"}','{\"fa\":\"اسباب‌بازی را کمی دورتر بگذار تا به سمتش برود.\",\"en\":\"Put a toy a little further away so they move toward it.\"}','{\"age_months\":9}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(247,'child_milestone_activities','m12_stack_cups',11,1,NULL,'{\"fa\":\"لیوان‌های تودرتو\",\"en\":\"Stacking cups\"}','{\"fa\":\"لیوان‌ها را روی هم بچینید و خراب کنید.\",\"en\":\"Stack cups together and knock them down.\"}','{\"age_months\":12}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(248,'child_milestone_activities','m12_read_together',12,1,NULL,'{\"fa\":\"کتاب خواندن با هم\",\"en\":\"Read together\"}','{\"fa\":\"کتاب‌های تصویری بخوان و به تصویرها اشاره کن.\",\"en\":\"Read picture books and point to the pictures.\"}','{\"age_months\":12}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(249,'child_milestone_activities','m18_simple_tasks',13,1,NULL,'{\"fa\":\"کارهای کوچک\",\"en\":\"Little jobs\"}','{\"fa\":\"از او بخواه چیزی را بیاورد یا در سبد بگذارد.\",\"en\":\"Ask them to fetch something or put it in a basket.\"}','{\"age_months\":18}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(250,'child_milestone_activities','m24_pretend_kitchen',14,1,NULL,'{\"fa\":\"آشپزی خیالی\",\"en\":\"Pretend kitchen\"}','{\"fa\":\"با ظرف‌های پلاستیکی بازی آشپزی کنید و اسم غذاها را بگو.\",\"en\":\"Play cooking with plastic dishes and name the foods.\"}','{\"age_months\":24}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(251,'child_milestone_activities','m36_story_turns',15,1,NULL,'{\"fa\":\"قصه نوبتی\",\"en\":\"Story turns\"}','{\"fa\":\"یک جمله از قصه را تو بگو و جمله بعدی را او.\",\"en\":\"You say one sentence of a story and they say the next.\"}','{\"age_months\":36}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(252,'child_milestone_activities','m48_colour_hunt',16,1,NULL,'{\"fa\":\"رنگ‌یابی\",\"en\":\"Colour hunt\"}','{\"fa\":\"در خانه یا پارک دنبال چیزهای یک رنگ بگردید.\",\"en\":\"Look for things of one colour at home or in the park.\"}','{\"age_months\":48}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(253,'child_milestone_activities','m60_board_games',17,1,NULL,'{\"fa\":\"بازی‌های نوبتی\",\"en\":\"Turn-taking games\"}','{\"fa\":\"بازی‌های ساده با قانون، مثل مار و پله، صبر و شمردن را تمرین می‌دهد.\",\"en\":\"Simple rule games like snakes and ladders practise patience and counting.\"}','{\"age_months\":60}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(254,'child_milestone_notes','m2',1,1,NULL,'{\"fa\":\"مراحل رشد ۲ ماهگی\",\"en\":\"2-month milestones\"}','{\"fa\":\"اگر تا ۲ ماهگی به صداهای بلند واکنش نداد یا وقتی دمر است سرش را اصلاً بالا نیاورد، در مراجعه بعدی با پزشک در میان بگذار.\",\"en\":\"If by 2 months they don\'t react to loud sounds or never lift their head on the tummy, mention it at the next visit.\"}','{\"age_months\":2}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(255,'child_milestone_notes','m3',2,1,NULL,'{\"fa\":\"مراحل رشد ۳ ماهگی\",\"en\":\"3-month milestones\"}','{\"fa\":\"اگر تا ۴ ماهگی به صدا واکنش نداد، سر را بالا نگرفت یا لبخند نزد، در مراجعه بعدی با پزشک در میان بگذار.\",\"en\":\"If by 4 months they don\'t react to sounds, hold up their head or smile, mention it at the next visit.\"}','{\"age_months\":3}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(256,'child_milestone_notes','m4',3,1,NULL,'{\"fa\":\"مراحل رشد ۴ ماهگی\",\"en\":\"4-month milestones\"}','{\"fa\":\"اگر تا ۴ ماهگی سرش را ثابت نگه نمی‌دارد یا اشیا را با چشم دنبال نمی‌کند، با پزشک کودک صحبت کن.\",\"en\":\"If by 4 months they can\'t hold their head steady or follow things with the eyes, talk to the paediatrician.\"}','{\"age_months\":4}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(257,'child_milestone_notes','m6',4,1,NULL,'{\"fa\":\"مراحل رشد ۶ ماهگی\",\"en\":\"6-month milestones\"}','{\"fa\":\"اگر تا ۶ ماهگی برای گرفتن چیزی دست دراز نمی‌کند یا به آدم‌های آشنا واکنش نشان نمی‌دهد، با پزشک صحبت کن.\",\"en\":\"If by 6 months they don\'t reach for things or respond to familiar people, talk to the doctor.\"}','{\"age_months\":6}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(258,'child_milestone_notes','m9',5,1,NULL,'{\"fa\":\"مراحل رشد ۹ ماهگی\",\"en\":\"9-month milestones\"}','{\"fa\":\"اگر تا ۹ ماهگی با تکیه هم نمی‌نشیند یا به اسمش واکنشی ندارد، در مراجعه بعدی مطرح کن.\",\"en\":\"If by 9 months they can\'t sit even with support or don\'t respond to their name, raise it at the next visit.\"}','{\"age_months\":9}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(259,'child_milestone_notes','m12',6,1,NULL,'{\"fa\":\"مراحل رشد ۱۲ ماهگی\",\"en\":\"12-month milestones\"}','{\"fa\":\"اگر تا ۱۲ ماهگی هیچ کلمه یا اشاره‌ای ندارد یا مهارتی را که داشت از دست داده، با پزشک صحبت کن.\",\"en\":\"If by 12 months there are no words or gestures, or a skill they had is lost, talk to the doctor.\"}','{\"age_months\":12}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(260,'child_milestone_notes','m18',7,1,NULL,'{\"fa\":\"مراحل رشد ۱۸ ماهگی\",\"en\":\"18-month milestones\"}','{\"fa\":\"اگر تا ۱۸ ماهگی راه نمی‌رود یا چند کلمه نمی‌گوید، با پزشک کودک در میان بگذار.\",\"en\":\"If by 18 months they don\'t walk or say a few words, mention it to the paediatrician.\"}','{\"age_months\":18}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(261,'child_milestone_notes','m24',8,1,NULL,'{\"fa\":\"مراحل رشد ۲۴ ماهگی\",\"en\":\"24-month milestones\"}','{\"fa\":\"اگر تا ۲ سالگی دو کلمه را با هم نمی‌گوید یا کارهای ساده را تقلید نمی‌کند، با پزشک صحبت کن.\",\"en\":\"If by 2 years they don\'t put two words together or copy simple actions, talk to the doctor.\"}','{\"age_months\":24}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(262,'child_milestone_notes','m36',9,1,NULL,'{\"fa\":\"مراحل رشد ۳۶ ماهگی\",\"en\":\"36-month milestones\"}','{\"fa\":\"اگر تا ۳ سالگی جمله ساده نمی‌گوید یا با بچه‌های دیگر بازی نمی‌کند، با پزشک صحبت کن.\",\"en\":\"If by 3 years they don\'t speak in simple sentences or play with other children, talk to the doctor.\"}','{\"age_months\":36}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(263,'child_milestone_notes','m48',10,1,NULL,'{\"fa\":\"مراحل رشد ۴۸ ماهگی\",\"en\":\"48-month milestones\"}','{\"fa\":\"اگر تا ۴ سالگی حرفش برای غریبه‌ها قابل فهم نیست یا بازی خیالی ندارد، با پزشک صحبت کن.\",\"en\":\"If by 4 years strangers can\'t understand their speech or there is no pretend play, talk to the doctor.\"}','{\"age_months\":48}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(264,'child_milestone_notes','m60',11,1,NULL,'{\"fa\":\"مراحل رشد ۶۰ ماهگی\",\"en\":\"60-month milestones\"}','{\"fa\":\"اگر تا ۵ سالگی نمی‌تواند داستان کوتاهی تعریف کند یا مهارتی را از دست داده، با پزشک صحبت کن.\",\"en\":\"If by 5 years they can\'t tell a short story or a skill is lost, talk to the doctor.\"}','{\"age_months\":60}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(265,'child_age_notes','m0',1,1,NULL,'{\"fa\":\"نوزادی\",\"en\":\"Newborn\"}','{\"fa\":\"نوزادها بیشتر روز را می‌خوابند و هر ۲ تا ۳ ساعت شیر می‌خورند. نگاه کردن به صورت تو و شنیدن صدایت بهترین بازی این روزهاست.\",\"en\":\"Newborns sleep most of the day and feed every 2–3 hours. Looking at your face and hearing your voice is the best play right now.\"}','{\"age_months\":0}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(266,'child_age_notes','m2',2,1,NULL,'{\"fa\":\"۲ ماهگی\",\"en\":\"2 months\"}','{\"fa\":\"در این سن بیشتر نوزادها اولین لبخندهای اجتماعی را می‌زنند و صداهای نرم درمی‌آورند. هر بچه با سرعت خودش پیش می‌رود.\",\"en\":\"Around now most babies give their first social smiles and make soft cooing sounds. Every baby goes at their own pace.\"}','{\"age_months\":2}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(267,'child_age_notes','m3',3,1,NULL,'{\"fa\":\"۳ ماهگی\",\"en\":\"3 months\"}','{\"fa\":\"بیشتر نوزادها در این سن سرشان را موقع دمر خوابیدن بالا نگه می‌دارند، به صداها می‌خندند و دست‌ها را به دهان می‌برند. اگر هنوز نه، عجله نکن؛ بازه طبیعی وسیع است.\",\"en\":\"Most babies this age hold their head up during tummy time, laugh at sounds and bring their hands to the mouth. If not yet, no rush; the normal range is wide.\"}','{\"age_months\":3}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(268,'child_age_notes','m4',4,1,NULL,'{\"fa\":\"۴ ماهگی\",\"en\":\"4 months\"}','{\"fa\":\"خنده‌های بلند، گرفتن اسباب‌بازی و غلت‌های اول در این ماه‌ها شروع می‌شود. وقت دمر را ادامه بده.\",\"en\":\"Big laughs, holding toys and first rolls start around now. Keep up tummy time.\"}','{\"age_months\":4}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(269,'child_age_notes','m6',5,1,NULL,'{\"fa\":\"۶ ماهگی\",\"en\":\"6 months\"}','{\"fa\":\"بسیاری از بچه‌ها در حدود ۶ ماهگی آماده غذای کمکی می‌شوند و نشستن با تکیه را تمرین می‌کنند.\",\"en\":\"Many babies are ready for first foods around 6 months and practise sitting with support.\"}','{\"age_months\":6}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(270,'child_age_notes','m9',6,1,NULL,'{\"fa\":\"۹ ماهگی\",\"en\":\"9 months\"}','{\"fa\":\"نشستن بدون کمک، چهاردست‌وپا رفتن و غریبی کردن در این سن رایج است.\",\"en\":\"Sitting alone, crawling and being wary of strangers are common at this age.\"}','{\"age_months\":9}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(271,'child_age_notes','m12',7,1,NULL,'{\"fa\":\"۱۲ ماهگی\",\"en\":\"12 months\"}','{\"fa\":\"حدود یک‌سالگی خیلی از بچه‌ها با گرفتن مبل راه می‌روند و اولین کلمه‌ها را می‌گویند.\",\"en\":\"Around their first birthday many children cruise along furniture and say first words.\"}','{\"age_months\":12}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(272,'child_age_notes','m18',8,1,NULL,'{\"fa\":\"۱۸ ماهگی\",\"en\":\"18 months\"}','{\"fa\":\"نوپاها در این سن راه رفتن را تمرین می‌کنند، چند کلمه می‌گویند و دوست دارند کارها را خودشان انجام دهند.\",\"en\":\"Toddlers this age practise walking, say a handful of words and want to do things themselves.\"}','{\"age_months\":18}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(273,'child_age_notes','m24',9,1,NULL,'{\"fa\":\"۲۴ ماهگی\",\"en\":\"24 months\"}','{\"fa\":\"در دو سالگی جمله‌های دوکلمه‌ای، دویدن و بازی‌های تقلیدی رایج است.\",\"en\":\"At two, two-word phrases, running and copycat play are common.\"}','{\"age_months\":24}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(274,'child_age_notes','m36',10,1,NULL,'{\"fa\":\"۳۶ ماهگی\",\"en\":\"36 months\"}','{\"fa\":\"سه‌ساله‌ها جمله می‌سازند، سؤال زیاد می‌پرسند و با بچه‌های دیگر بازی می‌کنند.\",\"en\":\"Three-year-olds speak in sentences, ask lots of questions and play with other children.\"}','{\"age_months\":36}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(275,'child_age_notes','m48',11,1,NULL,'{\"fa\":\"۴۸ ماهگی\",\"en\":\"48 months\"}','{\"fa\":\"چهارساله‌ها قصه تعریف می‌کنند، رنگ‌ها را می‌شناسند و بازی‌های خیالی دارند.\",\"en\":\"Four-year-olds tell stories, know colours and love pretend play.\"}','{\"age_months\":48}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(276,'child_age_notes','m60',12,1,NULL,'{\"fa\":\"۶۰ ماهگی\",\"en\":\"60 months\"}','{\"fa\":\"پنج‌ساله‌ها می‌شمارند، چند حرف می‌نویسند و قانون بازی‌ها را رعایت می‌کنند.\",\"en\":\"Five-year-olds count, write some letters and follow the rules of games.\"}','{\"age_months\":60}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(277,'child_learn','newborn_safe_sleep',1,1,NULL,'{\"fa\":\"خواب امن نوزاد\",\"en\":\"Safe sleep for newborns\"}','{\"fa\":\"به پشت، روی سطح سفت و بدون بالش و پتوی شل؛ در اتاق خودت ولی در تخت جدا.\",\"en\":\"On the back, on a firm flat surface with no pillows or loose blankets; in your room but in their own cot.\"}','{\"topic\":\"sleep\",\"from_months\":0,\"to_months\":2,\"minutes\":4,\"featured\":true}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(278,'child_learn','night_sleep_3m',2,1,NULL,'{\"fa\":\"خواب شبانه از ۳ ماهگی\",\"en\":\"Night sleep from 3 months\"}','{\"fa\":\"چطور روتین ملایم بسازیم: حمام، شیر، نور کم، همان ترتیب هر شب. بدون روش‌های گریه‌درمانی.\",\"en\":\"Building a gentle routine: bath, feed, dim light, the same order every night. No cry-it-out methods.\"}','{\"topic\":\"sleep\",\"from_months\":3,\"to_months\":6,\"minutes\":4,\"featured\":true}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(279,'child_learn','toddler_sleep_routine',3,1,NULL,'{\"fa\":\"روتین خواب نوپا\",\"en\":\"Toddler bedtime routine\"}','{\"fa\":\"ساعت ثابت خواب، قصه کوتاه و صفحه‌نمایش خاموش از یک ساعت قبل.\",\"en\":\"A steady bedtime, a short story and screens off an hour before.\"}','{\"topic\":\"sleep\",\"from_months\":12,\"to_months\":60,\"minutes\":4,\"featured\":true}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(280,'child_learn','breastfeeding_supply',4,1,NULL,'{\"fa\":\"شیردهی و افزایش شیر\",\"en\":\"Breastfeeding and milk supply\"}','{\"fa\":\"شیردهی بر اساس تقاضا، وضعیت درست گرفتن سینه و استراحت، مهم‌ترین عامل‌ها هستند.\",\"en\":\"Feeding on demand, a good latch and rest matter most.\"}','{\"topic\":\"feeding\",\"from_months\":0,\"to_months\":6,\"minutes\":6,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(281,'child_learn','starting_solids',5,1,NULL,'{\"fa\":\"شروع غذای کمکی\",\"en\":\"Starting solid foods\"}','{\"fa\":\"از حدود ۶ ماهگی، با یک غذای ساده و نرم شروع کن و هر چند روز یک غذای تازه اضافه کن.\",\"en\":\"From about 6 months, start with one simple soft food and add a new one every few days.\"}','{\"topic\":\"feeding\",\"from_months\":5,\"to_months\":9,\"minutes\":5,\"featured\":true}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(282,'child_learn','picky_eating',6,1,NULL,'{\"fa\":\"بدغذایی نوپا\",\"en\":\"Picky eating in toddlers\"}','{\"fa\":\"غذای تازه را بارها و بدون اصرار پیشنهاد بده؛ سهم را بچه تعیین می‌کند.\",\"en\":\"Offer new foods many times without pressure; the child decides how much.\"}','{\"topic\":\"feeding\",\"from_months\":12,\"to_months\":60,\"minutes\":5,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(283,'child_learn','evening_crying',7,1,NULL,'{\"fa\":\"دلیل گریه‌های عصرگاهی\",\"en\":\"Why babies cry in the evening\"}','{\"fa\":\"گریه‌های عصر در هفته‌های اول رایج است و معمولاً تا ۳ یا ۴ ماهگی کم می‌شود.\",\"en\":\"Evening fussiness is common in the first weeks and usually eases by 3 or 4 months.\"}','{\"topic\":\"health\",\"from_months\":0,\"to_months\":4,\"minutes\":5,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(284,'child_learn','vaccine_4m',8,1,NULL,'{\"fa\":\"واکسن ۴ ماهگی: چه انتظاری داشته باشم\",\"en\":\"The 4-month vaccines: what to expect\"}','{\"fa\":\"تب خفیف و بی‌قراری یکی دو روز بعد از واکسن طبیعی است؛ در صورت تب بالا با پزشک تماس بگیر.\",\"en\":\"A mild fever and fussiness for a day or two are normal; call the doctor for a high fever.\"}','{\"topic\":\"health\",\"from_months\":3,\"to_months\":5,\"minutes\":3,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(285,'child_learn','teething',9,1,NULL,'{\"fa\":\"دندان درآوردن\",\"en\":\"Teething\"}','{\"fa\":\"آب دهان زیاد و جویدن رایج است؛ حلقه دندانی خنک کمک می‌کند. تب بالا ربطی به دندان ندارد.\",\"en\":\"Drooling and chewing are common; a cool teething ring helps. A high fever is not from teething.\"}','{\"topic\":\"health\",\"from_months\":5,\"to_months\":18,\"minutes\":4,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(286,'child_learn','neck_play',10,1,NULL,'{\"fa\":\"بازی‌های ساده برای تقویت گردن\",\"en\":\"Simple games for neck strength\"}','{\"fa\":\"وقت دمر کوتاه و مکرر، با اسباب‌بازی رنگی جلوی صورتش.\",\"en\":\"Short, frequent tummy time with a bright toy in front of their face.\"}','{\"topic\":\"play\",\"from_months\":2,\"to_months\":5,\"minutes\":4,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(287,'child_learn','crawling_play',11,1,NULL,'{\"fa\":\"بازی‌های حرکتی ۶ تا ۱۲ ماهگی\",\"en\":\"Movement play from 6 to 12 months\"}','{\"fa\":\"فضای امن روی زمین بهترین اسباب‌بازی برای غلت زدن و چهاردست‌وپا رفتن است.\",\"en\":\"A safe space on the floor is the best toy for rolling and crawling.\"}','{\"topic\":\"play\",\"from_months\":6,\"to_months\":12,\"minutes\":4,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(288,'child_learn','toddler_talking',12,1,NULL,'{\"fa\":\"کمک به حرف زدن نوپا\",\"en\":\"Helping toddlers talk\"}','{\"fa\":\"با او زیاد حرف بزن، کارهایت را توصیف کن و جمله‌هایش را کامل‌تر تکرار کن.\",\"en\":\"Talk a lot, describe what you are doing and repeat their words in fuller sentences.\"}','{\"topic\":\"play\",\"from_months\":12,\"to_months\":36,\"minutes\":5,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(289,'child_learn','mother_self_care',13,1,NULL,'{\"fa\":\"مراقبت از خودت در ماه‌های اول\",\"en\":\"Looking after yourself in the first months\"}','{\"fa\":\"خواب کوتاه هر وقت ممکن است، کمک گرفتن از اطرافیان و صحبت درباره حالت، بخشی از مراقبت از بچه است.\",\"en\":\"Naps whenever you can, accepting help and talking about how you feel are part of caring for your baby.\"}','{\"topic\":\"mother\",\"from_months\":0,\"to_months\":12,\"minutes\":7,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(290,'child_learn','mother_return_to_routine',14,1,NULL,'{\"fa\":\"برگشت به روال کار و زندگی\",\"en\":\"Getting back to work and routine\"}','{\"fa\":\"برنامه‌ریزی تدریجی، تقسیم کارها و زمان کوتاهی برای خودت کمک می‌کند.\",\"en\":\"A gradual plan, shared chores and a little time for yourself help.\"}','{\"topic\":\"mother\",\"from_months\":6,\"to_months\":60,\"minutes\":5,\"featured\":false}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(291,'lab_markers','hemoglobin',1,1,NULL,'{\"fa\":\"هموگلوبین\",\"en\":\"Hemoglobin\"}','{\"fa\":\"پروتئینی در گلبول‌های قرمز که اکسیژن را به همه بدن می‌رساند. عدد پایین می‌تواند نشانه کم‌خونی باشد.\",\"en\":\"The protein in red blood cells that carries oxygen around the body. A low value can be a sign of anaemia.\"}','{\"category\":\"cbc\",\"subtitle\":{\"fa\":\"حمل اکسیژن در خون\",\"en\":\"Oxygen carrier in blood\"},\"aliases\":[\"hemoglobin\",\"haemoglobin\",\"hb\",\"hgb\",\"هموگلوبین\"],\"unit\":\"g/dL\",\"typical\":{\"low\":12,\"high\":15.5,\"text\":\"12–15.5\"},\"critical\":{\"urgent_low\":7,\"urgent_high\":20},\"low\":{\"factors\":[{\"fa\":\"خون‌ریزی ماهانه پریود، مخصوصاً پریودهای سنگین\",\"en\":\"Monthly period blood loss, especially heavy periods\"},{\"fa\":\"ذخیره آهن کم یا دریافت کم آهن از غذا\",\"en\":\"Low iron stores or little iron in the diet\"},{\"fa\":\"کمبود ویتامین B12 یا فولات\",\"en\":\"Low vitamin B12 or folate\"}],\"questions\":[{\"fa\":\"آیا کم‌خونی دارم و علتش چیست؟\",\"en\":\"Do I have anaemia, and what is causing it?\"}],\"see_doctor\":{\"fa\":\"اگر خستگی شدید، تنگی نفس، سرگیجه یا تپش قلب داری، زودتر به پزشک مراجعه کن.\",\"en\":\"If you have severe tiredness, shortness of breath, dizziness or palpitations, see a doctor soon.\"}},\"high\":{\"factors\":[{\"fa\":\"کم‌آبی بدن هنگام آزمایش\",\"en\":\"Being dehydrated at the time of the test\"},{\"fa\":\"سیگار کشیدن یا زندگی در ارتفاع بالا\",\"en\":\"Smoking or living at high altitude\"}],\"questions\":[{\"fa\":\"آیا لازم است آزمایش را تکرار کنم؟\",\"en\":\"Should I repeat this test?\"}],\"see_doctor\":{\"fa\":\"برای بررسی علت با پزشک مشورت کن.\",\"en\":\"Talk to a doctor to look into the cause.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(292,'lab_markers','hematocrit',2,1,NULL,'{\"fa\":\"هماتوکریت\",\"en\":\"Hematocrit\"}','{\"fa\":\"درصدی از حجم خون که گلبول‌های قرمز آن را تشکیل می‌دهند. معمولاً همراه هموگلوبین تفسیر می‌شود.\",\"en\":\"The share of blood volume made up of red blood cells. It is usually read together with hemoglobin.\"}','{\"category\":\"cbc\",\"subtitle\":{\"fa\":\"سهم گلبول قرمز در خون\",\"en\":\"Red cell share of blood\"},\"aliases\":[\"hematocrit\",\"haematocrit\",\"hct\",\"pcv\",\"هماتوکریت\"],\"unit\":\"%\",\"typical\":{\"low\":36,\"high\":46,\"text\":\"36–46\"},\"critical\":{\"urgent_low\":21},\"low\":{\"factors\":[{\"fa\":\"کم‌خونی، مثلاً به دلیل کمبود آهن\",\"en\":\"Anaemia, for example from low iron\"},{\"fa\":\"خون‌ریزی پریود\",\"en\":\"Period blood loss\"}],\"questions\":[{\"fa\":\"آیا این عدد با هموگلوبین من هم‌خوانی دارد؟\",\"en\":\"Does this match my hemoglobin result?\"}],\"see_doctor\":{\"fa\":\"همراه با هموگلوبین با پزشک بررسی کن.\",\"en\":\"Review it with a doctor together with your hemoglobin.\"}},\"high\":{\"factors\":[{\"fa\":\"کم‌آبی بدن\",\"en\":\"Dehydration\"},{\"fa\":\"سیگار کشیدن\",\"en\":\"Smoking\"}],\"questions\":[{\"fa\":\"آیا لازم است آزمایش را تکرار کنم؟\",\"en\":\"Should I repeat this test?\"}],\"see_doctor\":{\"fa\":\"برای بررسی علت با پزشک مشورت کن.\",\"en\":\"Talk to a doctor to look into the cause.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(293,'lab_markers','rbc',3,1,NULL,'{\"fa\":\"گلبول قرمز\",\"en\":\"Red blood cells\"}','{\"fa\":\"تعداد گلبول‌های قرمز در هر میکرولیتر خون؛ این سلول‌ها اکسیژن را جابه‌جا می‌کنند.\",\"en\":\"The number of red blood cells per microlitre of blood; these cells carry oxygen.\"}','{\"category\":\"cbc\",\"subtitle\":{\"fa\":\"شمار سلول‌های حامل اکسیژن\",\"en\":\"Count of oxygen-carrying cells\"},\"aliases\":[\"rbc\",\"redbloodcells\",\"redbloodcell\",\"redcellcount\",\"erythrocytes\",\"گلبولقرمز\"],\"unit\":\"10^6/µL\",\"typical\":{\"low\":4.0,\"high\":5.2,\"text\":\"4.0–5.2\"},\"low\":{\"factors\":[{\"fa\":\"کم‌خونی\",\"en\":\"Anaemia\"},{\"fa\":\"کمبود آهن، B12 یا فولات\",\"en\":\"Low iron, B12 or folate\"}],\"questions\":[{\"fa\":\"آیا به آزمایش آهن یا ویتامین‌ها نیاز دارم؟\",\"en\":\"Do I need iron or vitamin tests?\"}],\"see_doctor\":{\"fa\":\"همراه با هموگلوبین با پزشک بررسی کن.\",\"en\":\"Review it with a doctor together with your hemoglobin.\"}},\"high\":{\"factors\":[{\"fa\":\"کم‌آبی بدن\",\"en\":\"Dehydration\"},{\"fa\":\"سیگار کشیدن یا ارتفاع بالا\",\"en\":\"Smoking or high altitude\"}],\"questions\":[{\"fa\":\"آیا لازم است آزمایش را تکرار کنم؟\",\"en\":\"Should I repeat this test?\"}],\"see_doctor\":{\"fa\":\"برای بررسی علت با پزشک مشورت کن.\",\"en\":\"Talk to a doctor to look into the cause.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(294,'lab_markers','wbc',4,1,NULL,'{\"fa\":\"گلبول سفید\",\"en\":\"White blood cells\"}','{\"fa\":\"سلول‌های دستگاه ایمنی که با عفونت مقابله می‌کنند. عفونت، استرس و برخی داروها این عدد را تغییر می‌دهند.\",\"en\":\"Immune cells that fight infection. Infections, stress and some medicines change this number.\"}','{\"category\":\"cbc\",\"subtitle\":{\"fa\":\"سلول‌های ایمنی\",\"en\":\"Immune cells\"},\"aliases\":[\"wbc\",\"whitebloodcells\",\"whitebloodcell\",\"leukocytes\",\"leucocytes\",\"گلبولسفید\"],\"unit\":\"10^3/µL\",\"typical\":{\"low\":4.0,\"high\":11.0,\"text\":\"4.0–11.0\"},\"critical\":{\"urgent_low\":2,\"urgent_high\":30},\"low\":{\"factors\":[{\"fa\":\"عفونت‌های ویروسی اخیر\",\"en\":\"A recent viral infection\"},{\"fa\":\"برخی داروها\",\"en\":\"Some medicines\"}],\"questions\":[{\"fa\":\"آیا باید آزمایش را تکرار کنم؟\",\"en\":\"Should I repeat this test?\"}],\"see_doctor\":{\"fa\":\"اگر تب یا عفونت‌های مکرر داری، زودتر به پزشک مراجعه کن.\",\"en\":\"If you have a fever or frequent infections, see a doctor soon.\"}},\"high\":{\"factors\":[{\"fa\":\"عفونت یا التهاب\",\"en\":\"An infection or inflammation\"},{\"fa\":\"استرس، ورزش شدید یا بارداری\",\"en\":\"Stress, hard exercise or pregnancy\"}],\"questions\":[{\"fa\":\"آیا نشانه عفونت است؟\",\"en\":\"Could this be a sign of infection?\"}],\"see_doctor\":{\"fa\":\"اگر تب، درد یا علائم عفونت داری، با پزشک تماس بگیر.\",\"en\":\"If you have a fever, pain or signs of infection, contact a doctor.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(295,'lab_markers','platelets',5,1,NULL,'{\"fa\":\"پلاکت\",\"en\":\"Platelets\"}','{\"fa\":\"سلول‌های کوچکی که به لخته شدن خون و بند آمدن خون‌ریزی کمک می‌کنند.\",\"en\":\"Small cells that help blood clot and stop bleeding.\"}','{\"category\":\"cbc\",\"subtitle\":{\"fa\":\"لخته شدن خون\",\"en\":\"Blood clotting\"},\"aliases\":[\"platelets\",\"platelet\",\"plt\",\"plateletcount\",\"پلاکت\"],\"unit\":\"10^3/µL\",\"typical\":{\"low\":150,\"high\":450,\"text\":\"150–450\"},\"critical\":{\"urgent_low\":50,\"urgent_high\":1000},\"low\":{\"factors\":[{\"fa\":\"عفونت‌های ویروسی\",\"en\":\"Viral infections\"},{\"fa\":\"برخی داروها\",\"en\":\"Some medicines\"}],\"questions\":[{\"fa\":\"آیا خطر خون‌ریزی دارم؟\",\"en\":\"Am I at risk of bleeding?\"}],\"see_doctor\":{\"fa\":\"اگر کبودی بی‌دلیل، خون‌ریزی لثه یا پریود خیلی سنگین داری، زودتر مراجعه کن.\",\"en\":\"If you bruise easily, your gums bleed or your periods are very heavy, see a doctor soon.\"}},\"high\":{\"factors\":[{\"fa\":\"کمبود آهن\",\"en\":\"Low iron\"},{\"fa\":\"التهاب یا عفونت\",\"en\":\"Inflammation or infection\"}],\"questions\":[{\"fa\":\"آیا به آزمایش آهن نیاز دارم؟\",\"en\":\"Do I need an iron test?\"}],\"see_doctor\":{\"fa\":\"برای بررسی علت با پزشک مشورت کن.\",\"en\":\"Talk to a doctor to look into the cause.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(296,'lab_markers','mcv',6,1,NULL,'{\"fa\":\"حجم متوسط گلبول قرمز (MCV)\",\"en\":\"Mean cell volume (MCV)\"}','{\"fa\":\"اندازه متوسط گلبول‌های قرمز. کوچک بودن آن معمولاً با کمبود آهن و بزرگ بودنش با کمبود B12 یا فولات مرتبط است.\",\"en\":\"The average size of red blood cells. Small cells often go with low iron, large cells with low B12 or folate.\"}','{\"category\":\"cbc\",\"subtitle\":{\"fa\":\"اندازه گلبول قرمز\",\"en\":\"Red cell size\"},\"aliases\":[\"mcv\",\"meancellvolume\",\"meancorpuscularvolume\"],\"unit\":\"fL\",\"typical\":{\"low\":80,\"high\":100,\"text\":\"80–100\"},\"low\":{\"factors\":[{\"fa\":\"کمبود آهن\",\"en\":\"Low iron\"},{\"fa\":\"برخی صفات ارثی خون مثل تالاسمی مینور\",\"en\":\"Some inherited blood traits such as thalassaemia minor\"}],\"questions\":[{\"fa\":\"آیا به آزمایش فریتین یا الکتروفورز نیاز دارم؟\",\"en\":\"Do I need a ferritin or haemoglobin electrophoresis test?\"}],\"see_doctor\":{\"fa\":\"همراه با هموگلوبین و فریتین با پزشک بررسی کن.\",\"en\":\"Review it with a doctor together with hemoglobin and ferritin.\"}},\"high\":{\"factors\":[{\"fa\":\"کمبود ویتامین B12 یا فولات\",\"en\":\"Low vitamin B12 or folate\"},{\"fa\":\"مصرف الکل یا برخی داروها\",\"en\":\"Alcohol or some medicines\"}],\"questions\":[{\"fa\":\"آیا باید B12 و فولات را بررسی کنم؟\",\"en\":\"Should I check B12 and folate?\"}],\"see_doctor\":{\"fa\":\"برای بررسی علت با پزشک مشورت کن.\",\"en\":\"Talk to a doctor to look into the cause.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(297,'lab_markers','ferritin',7,1,NULL,'{\"fa\":\"فریتین\",\"en\":\"Ferritin\"}','{\"fa\":\"پروتئینی که آهن را در بدن ذخیره می‌کند. عدد پایین معمولاً یعنی ذخیره آهن کم است، حتی اگر هموگلوبین هنوز خیلی پایین نیامده باشد.\",\"en\":\"A protein that stores iron in the body. A low value usually means low iron stores, even before hemoglobin drops much.\"}','{\"category\":\"iron\",\"subtitle\":{\"fa\":\"ذخیره آهن بدن\",\"en\":\"Body iron stores\"},\"aliases\":[\"ferritin\",\"serumferritin\",\"فریتین\"],\"unit\":\"ng/mL\",\"typical\":{\"low\":15,\"high\":150,\"text\":\"15–150\"},\"low\":{\"factors\":[{\"fa\":\"خون‌ریزی ماهانه پریود\",\"en\":\"Monthly period blood loss\"},{\"fa\":\"دریافت کم آهن از غذا\",\"en\":\"Little iron in the diet\"},{\"fa\":\"جذب کمتر آهن در برخی شرایط گوارشی\",\"en\":\"Poorer iron absorption in some digestive conditions\"}],\"questions\":[{\"fa\":\"آیا برای ذخیره آهن کم باید مکمل آهن بگیرم؟ چه مقدار و تا کی؟\",\"en\":\"Should I take an iron supplement for low iron stores? How much and for how long?\"},{\"fa\":\"چند وقت دیگر آزمایش را تکرار کنم؟\",\"en\":\"When should I repeat the test?\"}],\"see_doctor\":{\"fa\":\"برای تصمیم درباره مکمل آهن و دوز آن با پزشک مشورت کن. اگر خستگی شدید، تنگی نفس یا تپش قلب داری، زودتر مراجعه کن.\",\"en\":\"Talk to a doctor before deciding on an iron supplement and its dose. If you have severe tiredness, shortness of breath or palpitations, go sooner.\"}},\"high\":{\"factors\":[{\"fa\":\"التهاب یا عفونت اخیر\",\"en\":\"Recent inflammation or infection\"},{\"fa\":\"مصرف مکمل آهن\",\"en\":\"Taking iron supplements\"}],\"questions\":[{\"fa\":\"آیا باید مصرف مکمل آهن را قطع کنم؟\",\"en\":\"Should I stop my iron supplement?\"}],\"see_doctor\":{\"fa\":\"برای بررسی علت با پزشک مشورت کن.\",\"en\":\"Talk to a doctor to look into the cause.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(298,'lab_markers','iron',8,1,NULL,'{\"fa\":\"آهن سرم\",\"en\":\"Serum iron\"}','{\"fa\":\"مقدار آهنی که در لحظه آزمایش در خون است. در طول روز و با غذا تغییر می‌کند و معمولاً همراه فریتین تفسیر می‌شود.\",\"en\":\"The amount of iron in the blood at the time of the test. It changes through the day and with meals, so it is read with ferritin.\"}','{\"category\":\"iron\",\"subtitle\":{\"fa\":\"آهن در گردش خون\",\"en\":\"Circulating iron\"},\"aliases\":[\"iron\",\"serumiron\",\"fe\",\"آهن\",\"آهنسرم\"],\"unit\":\"µg/dL\",\"typical\":{\"low\":50,\"high\":170,\"text\":\"50–170\"},\"low\":{\"factors\":[{\"fa\":\"ذخیره آهن کم\",\"en\":\"Low iron stores\"},{\"fa\":\"خون‌ریزی پریود\",\"en\":\"Period blood loss\"}],\"questions\":[{\"fa\":\"آیا فریتین من هم پایین است؟\",\"en\":\"Is my ferritin low as well?\"}],\"see_doctor\":{\"fa\":\"همراه با فریتین با پزشک بررسی کن.\",\"en\":\"Review it with a doctor together with ferritin.\"}},\"high\":{\"factors\":[{\"fa\":\"مصرف مکمل آهن پیش از آزمایش\",\"en\":\"Taking iron before the test\"}],\"questions\":[{\"fa\":\"آیا لازم است آزمایش را ناشتا تکرار کنم؟\",\"en\":\"Should I repeat the test fasting?\"}],\"see_doctor\":{\"fa\":\"برای بررسی علت با پزشک مشورت کن.\",\"en\":\"Talk to a doctor to look into the cause.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(299,'lab_markers','tsh',9,1,NULL,'{\"fa\":\"TSH\",\"en\":\"TSH\"}','{\"fa\":\"هورمونی از غده هیپوفیز که کار تیروئید را تنظیم می‌کند. TSH بالا معمولاً یعنی تیروئید کم‌کار است و TSH پایین یعنی پرکار.\",\"en\":\"A pituitary hormone that controls the thyroid. A high TSH usually means an underactive thyroid, a low TSH an overactive one.\"}','{\"category\":\"thyroid\",\"subtitle\":{\"fa\":\"تنظیم‌کننده تیروئید\",\"en\":\"Thyroid regulator\"},\"aliases\":[\"tsh\",\"thyrotropin\",\"thyroidstimulatinghormone\"],\"unit\":\"mIU/L\",\"typical\":{\"low\":0.4,\"high\":4.0,\"text\":\"0.4–4.0\"},\"critical\":{\"soon_high\":10,\"soon_low\":0.1},\"low\":{\"factors\":[{\"fa\":\"پرکاری تیروئید\",\"en\":\"An overactive thyroid\"},{\"fa\":\"مصرف زیاد داروی تیروئید\",\"en\":\"Too high a dose of thyroid medicine\"}],\"questions\":[{\"fa\":\"آیا به آزمایش T4 آزاد نیاز دارم؟\",\"en\":\"Do I need a free T4 test?\"}],\"see_doctor\":{\"fa\":\"اگر تپش قلب، کاهش وزن بی‌دلیل یا لرزش دست داری، زودتر مراجعه کن.\",\"en\":\"If you have palpitations, unexplained weight loss or shaky hands, see a doctor soon.\"}},\"high\":{\"factors\":[{\"fa\":\"کم‌کاری تیروئید\",\"en\":\"An underactive thyroid\"},{\"fa\":\"دوز ناکافی داروی تیروئید\",\"en\":\"Too low a dose of thyroid medicine\"}],\"questions\":[{\"fa\":\"آیا تیروئید من روی سیکل یا اقدام به بارداری اثر دارد؟\",\"en\":\"Could my thyroid affect my cycle or trying to conceive?\"},{\"fa\":\"آیا به آزمایش T4 آزاد و آنتی‌بادی تیروئید نیاز دارم؟\",\"en\":\"Do I need free T4 and thyroid antibody tests?\"}],\"see_doctor\":{\"fa\":\"با پزشک درباره تکرار آزمایش و نیاز به درمان صحبت کن؛ در اقدام به بارداری یا بارداری زودتر.\",\"en\":\"Talk to a doctor about repeating the test and whether treatment is needed — sooner if you are trying to conceive or pregnant.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(300,'lab_markers','free_t4',10,1,NULL,'{\"fa\":\"T4 آزاد\",\"en\":\"Free T4\"}','{\"fa\":\"هورمون اصلی تیروئید که آزادانه در خون می‌چرخد. همراه TSH وضعیت تیروئید را نشان می‌دهد.\",\"en\":\"The main thyroid hormone circulating freely in the blood. Together with TSH it shows how the thyroid is working.\"}','{\"category\":\"thyroid\",\"subtitle\":{\"fa\":\"هورمون تیروئید\",\"en\":\"Thyroid hormone\"},\"aliases\":[\"freet4\",\"ft4\",\"t4free\",\"freethyroxine\"],\"unit\":\"ng/dL\",\"typical\":{\"low\":0.8,\"high\":1.8,\"text\":\"0.8–1.8\"},\"low\":{\"factors\":[{\"fa\":\"کم‌کاری تیروئید\",\"en\":\"An underactive thyroid\"}],\"questions\":[{\"fa\":\"آیا به درمان تیروئید نیاز دارم؟\",\"en\":\"Do I need thyroid treatment?\"}],\"see_doctor\":{\"fa\":\"همراه با TSH با پزشک بررسی کن.\",\"en\":\"Review it with a doctor together with TSH.\"}},\"high\":{\"factors\":[{\"fa\":\"پرکاری تیروئید\",\"en\":\"An overactive thyroid\"},{\"fa\":\"مصرف زیاد داروی تیروئید\",\"en\":\"Too high a dose of thyroid medicine\"}],\"questions\":[{\"fa\":\"آیا دوز داروی تیروئید من مناسب است؟\",\"en\":\"Is my thyroid medicine dose right?\"}],\"see_doctor\":{\"fa\":\"همراه با TSH با پزشک بررسی کن.\",\"en\":\"Review it with a doctor together with TSH.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(301,'lab_markers','vitamin_d',11,1,NULL,'{\"fa\":\"ویتامین D\",\"en\":\"Vitamin D\"}','{\"fa\":\"ویتامینی که برای سلامت استخوان، عضله و ایمنی لازم است و بیشتر با نور خورشید ساخته می‌شود.\",\"en\":\"A vitamin needed for bones, muscles and immunity, made mostly with sunlight.\"}','{\"category\":\"vitamin\",\"subtitle\":{\"fa\":\"استخوان و ایمنی\",\"en\":\"Bones and immunity\"},\"aliases\":[\"vitamind\",\"vitd\",\"25ohd\",\"25ohvitamind\",\"25hydroxyvitamind\",\"vitamind25oh\",\"vitamind3\",\"ویتامیند\",\"ویتامیندی\"],\"unit\":\"ng/mL\",\"typical\":{\"low\":30,\"high\":100,\"text\":\"30–100\"},\"critical\":{\"soon_low\":10},\"low\":{\"factors\":[{\"fa\":\"نور کم خورشید یا پوشش زیاد پوست\",\"en\":\"Little sunlight or covered skin\"},{\"fa\":\"دریافت کم از غذا\",\"en\":\"Little vitamin D in the diet\"}],\"questions\":[{\"fa\":\"چه مقدار ویتامین D مصرف کنم و تا کی؟\",\"en\":\"How much vitamin D should I take, and for how long?\"},{\"fa\":\"قبل از بارداری ویتامین D چقدر باید باشد؟\",\"en\":\"What should my vitamin D be before pregnancy?\"}],\"see_doctor\":{\"fa\":\"برای انتخاب دوز مکمل با پزشک مشورت کن.\",\"en\":\"Talk to a doctor to choose a supplement dose.\"}},\"high\":{\"factors\":[{\"fa\":\"مصرف زیاد مکمل ویتامین D\",\"en\":\"Taking a lot of vitamin D supplements\"}],\"questions\":[{\"fa\":\"آیا باید مکمل را کم یا قطع کنم؟\",\"en\":\"Should I lower or stop my supplement?\"}],\"see_doctor\":{\"fa\":\"درباره دوز مکمل با پزشک صحبت کن.\",\"en\":\"Talk to a doctor about your supplement dose.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(302,'lab_markers','b12',12,1,NULL,'{\"fa\":\"ویتامین B12\",\"en\":\"Vitamin B12\"}','{\"fa\":\"ویتامینی که برای ساخت گلبول قرمز و سلامت اعصاب لازم است و بیشتر در غذاهای حیوانی هست.\",\"en\":\"A vitamin needed for red blood cells and nerves, found mostly in animal foods.\"}','{\"category\":\"vitamin\",\"subtitle\":{\"fa\":\"خون و اعصاب\",\"en\":\"Blood and nerves\"},\"aliases\":[\"b12\",\"vitaminb12\",\"vitb12\",\"cobalamin\",\"cyanocobalamin\",\"ویتامینب12\"],\"unit\":\"pg/mL\",\"typical\":{\"low\":200,\"high\":900,\"text\":\"200–900\"},\"critical\":{\"soon_low\":150},\"low\":{\"factors\":[{\"fa\":\"رژیم گیاه‌خواری\",\"en\":\"A vegetarian or vegan diet\"},{\"fa\":\"جذب کم در برخی بیماری‌های گوارشی یا با برخی داروها مثل متفورمین\",\"en\":\"Poor absorption in some digestive conditions or with some medicines such as metformin\"}],\"questions\":[{\"fa\":\"آیا به مکمل B12 نیاز دارم؟\",\"en\":\"Do I need a B12 supplement?\"}],\"see_doctor\":{\"fa\":\"اگر بی‌حسی یا گزگز دست و پا داری، زودتر مراجعه کن.\",\"en\":\"If you have numbness or tingling in your hands or feet, see a doctor soon.\"}},\"high\":{\"factors\":[{\"fa\":\"مصرف مکمل B12\",\"en\":\"Taking B12 supplements\"}],\"questions\":[{\"fa\":\"آیا لازم است کاری انجام دهم؟\",\"en\":\"Do I need to do anything about it?\"}],\"see_doctor\":{\"fa\":\"اگر مکمل مصرف نمی‌کنی، با پزشک مشورت کن.\",\"en\":\"If you do not take supplements, talk to a doctor.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(303,'lab_markers','folate',13,1,NULL,'{\"fa\":\"فولات (اسید فولیک)\",\"en\":\"Folate\"}','{\"fa\":\"ویتامین گروه B که برای ساخت سلول‌ها لازم است و پیش از بارداری و در ماه‌های اول آن اهمیت ویژه دارد.\",\"en\":\"A B vitamin needed to make cells; it matters especially before and early in pregnancy.\"}','{\"category\":\"vitamin\",\"subtitle\":{\"fa\":\"ساخت سلول و بارداری\",\"en\":\"Cell growth and pregnancy\"},\"aliases\":[\"folate\",\"folicacid\",\"serumfolate\",\"اسیدفولیک\",\"فولات\"],\"unit\":\"ng/mL\",\"typical\":{\"low\":3,\"text\":\"≥ 3\"},\"low\":{\"factors\":[{\"fa\":\"دریافت کم سبزیجات برگ‌سبز و حبوبات\",\"en\":\"Few leafy greens and legumes in the diet\"},{\"fa\":\"برخی داروها\",\"en\":\"Some medicines\"}],\"questions\":[{\"fa\":\"چه مقدار اسید فولیک باید مصرف کنم؟\",\"en\":\"How much folic acid should I take?\"}],\"see_doctor\":{\"fa\":\"مخصوصاً اگر اقدام به بارداری داری، با پزشک درباره مکمل صحبت کن.\",\"en\":\"Talk to a doctor about a supplement, especially if you are trying to conceive.\"}},\"high\":{\"factors\":[{\"fa\":\"مصرف مکمل\",\"en\":\"Taking supplements\"}],\"questions\":[{\"fa\":\"آیا لازم است کاری انجام دهم؟\",\"en\":\"Do I need to do anything about it?\"}],\"see_doctor\":{\"fa\":\"معمولاً نگران‌کننده نیست؛ در صورت شک با پزشک صحبت کن.\",\"en\":\"Usually not a concern; ask a doctor if unsure.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(304,'lab_markers','glucose_fasting',14,1,NULL,'{\"fa\":\"قند ناشتا\",\"en\":\"Fasting glucose\"}','{\"fa\":\"مقدار قند خون بعد از حداقل ۸ ساعت ناشتایی. برای بررسی دیابت و پیش‌دیابت استفاده می‌شود.\",\"en\":\"Blood sugar after at least 8 hours without food. Used to check for diabetes and prediabetes.\"}','{\"category\":\"glucose\",\"subtitle\":{\"fa\":\"قند خون\",\"en\":\"Blood sugar\"},\"aliases\":[\"fbs\",\"fastingglucose\",\"fastingbloodsugar\",\"glucosefasting\",\"fastingplasmaglucose\",\"fpg\",\"glucose\",\"bloodsugar\",\"قندناشتا\",\"قندخونناشتا\"],\"unit\":\"mg/dL\",\"typical\":{\"low\":70,\"high\":100,\"text\":\"70–100\"},\"critical\":{\"urgent_low\":54,\"urgent_high\":300,\"soon_high\":126},\"low\":{\"factors\":[{\"fa\":\"ناشتایی طولانی یا ورزش شدید\",\"en\":\"A long fast or hard exercise\"},{\"fa\":\"برخی داروهای دیابت\",\"en\":\"Some diabetes medicines\"}],\"questions\":[{\"fa\":\"آیا افت قند دارم؟\",\"en\":\"Do I have low blood sugar episodes?\"}],\"see_doctor\":{\"fa\":\"اگر لرزش، تعریق یا گیجی داری، فوراً چیزی شیرین بخور و با پزشک تماس بگیر.\",\"en\":\"If you feel shaky, sweaty or confused, eat something sugary right away and contact a doctor.\"}},\"high\":{\"factors\":[{\"fa\":\"ناشتا نبودن هنگام آزمایش\",\"en\":\"Not fasting before the test\"},{\"fa\":\"پیش‌دیابت یا دیابت\",\"en\":\"Prediabetes or diabetes\"},{\"fa\":\"سندرم تخمدان پلی‌کیستیک\",\"en\":\"Polycystic ovary syndrome\"}],\"questions\":[{\"fa\":\"آیا به آزمایش HbA1c نیاز دارم؟\",\"en\":\"Do I need an HbA1c test?\"},{\"fa\":\"چه تغییری در غذا و ورزش کمک می‌کند؟\",\"en\":\"What changes in food and exercise would help?\"}],\"see_doctor\":{\"fa\":\"برای تکرار آزمایش و بررسی پیش‌دیابت با پزشک مشورت کن.\",\"en\":\"Talk to a doctor about repeating the test and checking for prediabetes.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(305,'lab_markers','hba1c',15,1,NULL,'{\"fa\":\"هموگلوبین A1c\",\"en\":\"HbA1c\"}','{\"fa\":\"میانگین قند خون در حدود سه ماه گذشته را نشان می‌دهد و به ناشتایی نیاز ندارد.\",\"en\":\"Shows your average blood sugar over about the last three months; no fasting needed.\"}','{\"category\":\"glucose\",\"subtitle\":{\"fa\":\"میانگین قند ۳ ماه\",\"en\":\"3-month sugar average\"},\"aliases\":[\"hba1c\",\"a1c\",\"glycatedhemoglobin\",\"glycosylatedhemoglobin\",\"hemoglobina1c\",\"haemoglobina1c\",\"هموگلوبینa1c\"],\"unit\":\"%\",\"typical\":{\"low\":4.0,\"high\":5.6,\"text\":\"4.0–5.6\"},\"critical\":{\"soon_high\":6.5},\"low\":{\"factors\":[{\"fa\":\"کم‌خونی یا خون‌ریزی اخیر می‌تواند عدد را کم نشان دهد\",\"en\":\"Anaemia or recent blood loss can make the value read low\"}],\"questions\":[{\"fa\":\"آیا این عدد برای من قابل اعتماد است؟\",\"en\":\"Is this result reliable for me?\"}],\"see_doctor\":{\"fa\":\"در صورت شک با پزشک صحبت کن.\",\"en\":\"Ask a doctor if unsure.\"}},\"high\":{\"factors\":[{\"fa\":\"پیش‌دیابت یا دیابت\",\"en\":\"Prediabetes or diabetes\"}],\"questions\":[{\"fa\":\"آیا پیش‌دیابت یا دیابت دارم؟\",\"en\":\"Do I have prediabetes or diabetes?\"},{\"fa\":\"پیش از بارداری قندم باید در چه حدی باشد؟\",\"en\":\"What should my sugar be before pregnancy?\"}],\"see_doctor\":{\"fa\":\"برای بررسی و برنامه کنترل قند با پزشک مشورت کن.\",\"en\":\"Talk to a doctor about a check-up and a plan to manage blood sugar.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(306,'lab_markers','cholesterol_total',16,1,NULL,'{\"fa\":\"کلسترول کل\",\"en\":\"Total cholesterol\"}','{\"fa\":\"مجموع چربی‌های کلسترولی خون. همراه LDL و HDL برای ارزیابی سلامت قلب و عروق تفسیر می‌شود.\",\"en\":\"All the cholesterol in your blood. Read with LDL and HDL to judge heart and blood vessel health.\"}','{\"category\":\"lipid\",\"subtitle\":{\"fa\":\"چربی خون\",\"en\":\"Blood fats\"},\"aliases\":[\"cholesterol\",\"totalcholesterol\",\"cholesteroltotal\",\"chol\",\"tc\",\"کلسترول\",\"کلسترولکل\"],\"unit\":\"mg/dL\",\"typical\":{\"high\":200,\"text\":\"< 200\"},\"low\":{\"factors\":[{\"fa\":\"معمولاً نگران‌کننده نیست\",\"en\":\"Usually not a concern\"}],\"questions\":[{\"fa\":\"آیا لازم است کاری انجام دهم؟\",\"en\":\"Do I need to do anything about it?\"}],\"see_doctor\":{\"fa\":\"در صورت شک با پزشک صحبت کن.\",\"en\":\"Ask a doctor if unsure.\"}},\"high\":{\"factors\":[{\"fa\":\"رژیم پرچرب و کم‌تحرکی\",\"en\":\"A high-fat diet and little exercise\"},{\"fa\":\"سابقه خانوادگی\",\"en\":\"Family history\"},{\"fa\":\"کم‌کاری تیروئید\",\"en\":\"An underactive thyroid\"}],\"questions\":[{\"fa\":\"خطر بیماری قلبی من چقدر است؟\",\"en\":\"What is my heart disease risk?\"}],\"see_doctor\":{\"fa\":\"برای ارزیابی خطر قلبی و تغییر سبک زندگی با پزشک مشورت کن.\",\"en\":\"Talk to a doctor about your heart risk and lifestyle changes.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(307,'lab_markers','ldl',17,1,NULL,'{\"fa\":\"LDL (کلسترول بد)\",\"en\":\"LDL cholesterol\"}','{\"fa\":\"کلسترولی که بالا بودنش با رسوب در رگ‌ها و خطر بیماری قلبی مرتبط است.\",\"en\":\"Cholesterol that, when high, builds up in arteries and raises heart disease risk.\"}','{\"category\":\"lipid\",\"subtitle\":{\"fa\":\"کلسترول بد\",\"en\":\"Bad cholesterol\"},\"aliases\":[\"ldl\",\"ldlc\",\"ldlcholesterol\",\"کلسترولبد\"],\"unit\":\"mg/dL\",\"typical\":{\"high\":130,\"text\":\"< 130\"},\"critical\":{\"soon_high\":190},\"low\":{\"factors\":[{\"fa\":\"معمولاً نگران‌کننده نیست\",\"en\":\"Usually not a concern\"}],\"questions\":[{\"fa\":\"آیا لازم است کاری انجام دهم؟\",\"en\":\"Do I need to do anything about it?\"}],\"see_doctor\":{\"fa\":\"در صورت شک با پزشک صحبت کن.\",\"en\":\"Ask a doctor if unsure.\"}},\"high\":{\"factors\":[{\"fa\":\"رژیم پرچرب\",\"en\":\"A high-fat diet\"},{\"fa\":\"سابقه خانوادگی\",\"en\":\"Family history\"}],\"questions\":[{\"fa\":\"آیا به دارو نیاز دارم یا تغییر سبک زندگی کافی است؟\",\"en\":\"Do I need medicine, or are lifestyle changes enough?\"}],\"see_doctor\":{\"fa\":\"برای ارزیابی خطر قلبی با پزشک مشورت کن.\",\"en\":\"Talk to a doctor about your heart risk.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(308,'lab_markers','hdl',18,1,NULL,'{\"fa\":\"HDL (کلسترول خوب)\",\"en\":\"HDL cholesterol\"}','{\"fa\":\"کلسترولی که به پاک کردن چربی از رگ‌ها کمک می‌کند؛ عدد بالاتر معمولاً بهتر است.\",\"en\":\"Cholesterol that helps clear fat from arteries; higher is usually better.\"}','{\"category\":\"lipid\",\"subtitle\":{\"fa\":\"کلسترول خوب\",\"en\":\"Good cholesterol\"},\"aliases\":[\"hdl\",\"hdlc\",\"hdlcholesterol\",\"کلسترولخوب\"],\"unit\":\"mg/dL\",\"typical\":{\"low\":50,\"text\":\"≥ 50\"},\"low\":{\"factors\":[{\"fa\":\"کم‌تحرکی\",\"en\":\"Little physical activity\"},{\"fa\":\"سیگار کشیدن\",\"en\":\"Smoking\"},{\"fa\":\"سندرم تخمدان پلی‌کیستیک\",\"en\":\"Polycystic ovary syndrome\"}],\"questions\":[{\"fa\":\"چطور می‌توانم HDL را بالا ببرم؟\",\"en\":\"How can I raise my HDL?\"}],\"see_doctor\":{\"fa\":\"همراه با بقیه چربی‌ها با پزشک بررسی کن.\",\"en\":\"Review it with a doctor together with your other lipids.\"}},\"high\":{\"factors\":[{\"fa\":\"معمولاً نشانه خوبی است\",\"en\":\"Usually a good sign\"}],\"questions\":[{\"fa\":\"آیا لازم است کاری انجام دهم؟\",\"en\":\"Do I need to do anything about it?\"}],\"see_doctor\":{\"fa\":\"در صورت شک با پزشک صحبت کن.\",\"en\":\"Ask a doctor if unsure.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(309,'lab_markers','triglycerides',19,1,NULL,'{\"fa\":\"تری‌گلیسرید\",\"en\":\"Triglycerides\"}','{\"fa\":\"نوعی چربی خون که با غذا، قند و الکل بالا می‌رود. برای آزمایش معمولاً ناشتایی لازم است.\",\"en\":\"A blood fat that rises with food, sugar and alcohol. Fasting is usually needed for the test.\"}','{\"category\":\"lipid\",\"subtitle\":{\"fa\":\"چربی خون\",\"en\":\"Blood fats\"},\"aliases\":[\"triglycerides\",\"triglyceride\",\"tg\",\"trig\",\"تریگلیسرید\"],\"unit\":\"mg/dL\",\"typical\":{\"high\":150,\"text\":\"< 150\"},\"critical\":{\"soon_high\":500,\"urgent_high\":1000},\"low\":{\"factors\":[{\"fa\":\"معمولاً نگران‌کننده نیست\",\"en\":\"Usually not a concern\"}],\"questions\":[{\"fa\":\"آیا لازم است کاری انجام دهم؟\",\"en\":\"Do I need to do anything about it?\"}],\"see_doctor\":{\"fa\":\"در صورت شک با پزشک صحبت کن.\",\"en\":\"Ask a doctor if unsure.\"}},\"high\":{\"factors\":[{\"fa\":\"ناشتا نبودن هنگام آزمایش\",\"en\":\"Not fasting before the test\"},{\"fa\":\"مصرف زیاد قند و کربوهیدرات ساده\",\"en\":\"A lot of sugar and refined carbohydrates\"},{\"fa\":\"مقاومت به انسولین\",\"en\":\"Insulin resistance\"}],\"questions\":[{\"fa\":\"آیا باید آزمایش را ناشتا تکرار کنم؟\",\"en\":\"Should I repeat the test fasting?\"}],\"see_doctor\":{\"fa\":\"برای بررسی و برنامه غذایی با پزشک مشورت کن.\",\"en\":\"Talk to a doctor about a check-up and an eating plan.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(310,'lab_markers','fsh',20,1,NULL,'{\"fa\":\"FSH\",\"en\":\"FSH\"}','{\"fa\":\"هورمونی از هیپوفیز که رشد فولیکول‌های تخمدان را تحریک می‌کند. مقدارش در روزهای مختلف سیکل فرق دارد و معمولاً روز ۲ تا ۴ سیکل اندازه گرفته می‌شود.\",\"en\":\"A pituitary hormone that makes ovarian follicles grow. It varies through the cycle and is usually measured on cycle day 2 to 4.\"}','{\"category\":\"hormone\",\"subtitle\":{\"fa\":\"رشد فولیکول تخمدان\",\"en\":\"Ovarian follicle growth\"},\"aliases\":[\"fsh\",\"folliclestimulatinghormone\"],\"unit\":\"mIU/mL\",\"range_varies\":true,\"typical\":{\"low\":3.5,\"high\":12.5,\"text\":\"3.5–12.5 (follicular)\"},\"low\":{\"factors\":[{\"fa\":\"قرص‌های هورمونی\",\"en\":\"Hormonal contraceptives\"},{\"fa\":\"استرس شدید، کاهش وزن زیاد یا ورزش خیلی سنگین\",\"en\":\"Severe stress, a lot of weight loss or very hard training\"}],\"questions\":[{\"fa\":\"آیا این عدد روی تخمک‌گذاری من اثر دارد؟\",\"en\":\"Does this affect my ovulation?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس روز سیکل با پزشک زنان صحبت کن.\",\"en\":\"Talk to a gynaecologist to read it for your cycle day.\"}},\"high\":{\"factors\":[{\"fa\":\"کاهش ذخیره تخمدان\",\"en\":\"Lower ovarian reserve\"},{\"fa\":\"نزدیک شدن به یائسگی\",\"en\":\"Approaching menopause\"},{\"fa\":\"انجام آزمایش در زمان تخمک‌گذاری\",\"en\":\"Testing around ovulation\"}],\"questions\":[{\"fa\":\"ذخیره تخمدان من چطور است؟\",\"en\":\"What is my ovarian reserve like?\"},{\"fa\":\"آیا آزمایش را باید در روز ۲ تا ۴ سیکل تکرار کنم؟\",\"en\":\"Should I repeat the test on cycle day 2 to 4?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس روز سیکل و سن با پزشک زنان صحبت کن.\",\"en\":\"Talk to a gynaecologist to read it for your cycle day and age.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(311,'lab_markers','lh',21,1,NULL,'{\"fa\":\"LH\",\"en\":\"LH\"}','{\"fa\":\"هورمونی از هیپوفیز که جهش آن باعث تخمک‌گذاری می‌شود. مقدارش در طول سیکل خیلی تغییر می‌کند.\",\"en\":\"A pituitary hormone whose surge triggers ovulation. It changes a lot through the cycle.\"}','{\"category\":\"hormone\",\"subtitle\":{\"fa\":\"محرک تخمک‌گذاری\",\"en\":\"Ovulation trigger\"},\"aliases\":[\"lh\",\"luteinizinghormone\",\"luteinisinghormone\"],\"unit\":\"mIU/mL\",\"range_varies\":true,\"typical\":{\"low\":2.4,\"high\":12.6,\"text\":\"2.4–12.6 (follicular)\"},\"low\":{\"factors\":[{\"fa\":\"قرص‌های هورمونی\",\"en\":\"Hormonal contraceptives\"},{\"fa\":\"استرس یا کاهش وزن زیاد\",\"en\":\"Stress or a lot of weight loss\"}],\"questions\":[{\"fa\":\"آیا تخمک‌گذاری من طبیعی است؟\",\"en\":\"Is my ovulation normal?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس روز سیکل با پزشک زنان صحبت کن.\",\"en\":\"Talk to a gynaecologist to read it for your cycle day.\"}},\"high\":{\"factors\":[{\"fa\":\"آزمایش در زمان جهش LH قبل از تخمک‌گذاری\",\"en\":\"Testing during the LH surge before ovulation\"},{\"fa\":\"سندرم تخمدان پلی‌کیستیک (نسبت LH به FSH بالا)\",\"en\":\"Polycystic ovary syndrome (high LH to FSH ratio)\"},{\"fa\":\"نزدیک شدن به یائسگی\",\"en\":\"Approaching menopause\"}],\"questions\":[{\"fa\":\"آیا نسبت LH به FSH من نشانه PCOS است؟\",\"en\":\"Does my LH to FSH ratio suggest PCOS?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس روز سیکل با پزشک زنان صحبت کن.\",\"en\":\"Talk to a gynaecologist to read it for your cycle day.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(312,'lab_markers','estradiol',22,1,NULL,'{\"fa\":\"استرادیول (E2)\",\"en\":\"Estradiol (E2)\"}','{\"fa\":\"مهم‌ترین هورمون استروژن که تخمدان می‌سازد. مقدارش در طول سیکل بالا و پایین می‌رود.\",\"en\":\"The main oestrogen made by the ovaries. It rises and falls through the cycle.\"}','{\"category\":\"hormone\",\"subtitle\":{\"fa\":\"استروژن اصلی\",\"en\":\"Main oestrogen\"},\"aliases\":[\"estradiol\",\"oestradiol\",\"e2\",\"استرادیول\"],\"unit\":\"pg/mL\",\"range_varies\":true,\"typical\":{\"low\":12.5,\"high\":166,\"text\":\"12.5–166 (follicular)\"},\"low\":{\"factors\":[{\"fa\":\"مرحله ابتدایی سیکل\",\"en\":\"The early part of the cycle\"},{\"fa\":\"نزدیک شدن به یائسگی\",\"en\":\"Approaching menopause\"},{\"fa\":\"کاهش وزن زیاد یا ورزش خیلی سنگین\",\"en\":\"A lot of weight loss or very hard training\"}],\"questions\":[{\"fa\":\"آیا این عدد با روز سیکل من هم‌خوانی دارد؟\",\"en\":\"Does this fit my cycle day?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس روز سیکل با پزشک زنان صحبت کن.\",\"en\":\"Talk to a gynaecologist to read it for your cycle day.\"}},\"high\":{\"factors\":[{\"fa\":\"نزدیک تخمک‌گذاری\",\"en\":\"Close to ovulation\"},{\"fa\":\"داروهای باروری یا هورمونی\",\"en\":\"Fertility or hormonal medicines\"},{\"fa\":\"بارداری\",\"en\":\"Pregnancy\"}],\"questions\":[{\"fa\":\"آیا این عدد با روز سیکل من هم‌خوانی دارد؟\",\"en\":\"Does this fit my cycle day?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس روز سیکل با پزشک زنان صحبت کن.\",\"en\":\"Talk to a gynaecologist to read it for your cycle day.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(313,'lab_markers','progesterone',23,1,NULL,'{\"fa\":\"پروژسترون\",\"en\":\"Progesterone\"}','{\"fa\":\"هورمونی که بعد از تخمک‌گذاری بالا می‌رود و رحم را برای بارداری آماده می‌کند. آزمایش روز ۲۱ (حدود ۷ روز بعد از تخمک‌گذاری) نشان می‌دهد تخمک‌گذاری رخ داده یا نه.\",\"en\":\"A hormone that rises after ovulation and prepares the womb for pregnancy. A day-21 test (about 7 days after ovulation) shows whether ovulation happened.\"}','{\"category\":\"hormone\",\"subtitle\":{\"fa\":\"نشانه تخمک‌گذاری\",\"en\":\"Sign of ovulation\"},\"aliases\":[\"progesterone\",\"prog\",\"p4\",\"day21progesterone\",\"پروژسترون\"],\"unit\":\"ng/mL\",\"range_varies\":true,\"typical\":{\"low\":1.8,\"high\":24,\"text\":\"1.8–24 (luteal)\"},\"low\":{\"factors\":[{\"fa\":\"آزمایش در نیمه اول سیکل\",\"en\":\"Testing in the first half of the cycle\"},{\"fa\":\"تخمک‌گذاری نکردن در آن سیکل\",\"en\":\"No ovulation that cycle\"}],\"questions\":[{\"fa\":\"آیا در این سیکل تخمک‌گذاری داشته‌ام؟\",\"en\":\"Did I ovulate this cycle?\"},{\"fa\":\"آیا آزمایش در روز درست سیکل انجام شده است؟\",\"en\":\"Was the test done on the right cycle day?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس روز سیکل با پزشک زنان صحبت کن.\",\"en\":\"Talk to a gynaecologist to read it for your cycle day.\"}},\"high\":{\"factors\":[{\"fa\":\"فاز لوتئال یا بارداری\",\"en\":\"The luteal phase or pregnancy\"},{\"fa\":\"مکمل پروژسترون\",\"en\":\"Progesterone supplements\"}],\"questions\":[{\"fa\":\"آیا این عدد با روز سیکل من هم‌خوانی دارد؟\",\"en\":\"Does this fit my cycle day?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس روز سیکل با پزشک زنان صحبت کن.\",\"en\":\"Talk to a gynaecologist to read it for your cycle day.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(314,'lab_markers','prolactin',24,1,NULL,'{\"fa\":\"پرولاکتین\",\"en\":\"Prolactin\"}','{\"fa\":\"هورمونی که شیرسازی را تحریک می‌کند. بالا بودنش در غیر شیردهی می‌تواند سیکل و تخمک‌گذاری را مختل کند.\",\"en\":\"A hormone that drives milk production. When high outside breastfeeding it can disturb cycles and ovulation.\"}','{\"category\":\"hormone\",\"subtitle\":{\"fa\":\"هورمون شیرسازی\",\"en\":\"Milk hormone\"},\"aliases\":[\"prolactin\",\"prl\",\"پرولاکتین\"],\"unit\":\"ng/mL\",\"typical\":{\"low\":4.8,\"high\":23.3,\"text\":\"4.8–23.3\"},\"critical\":{\"soon_high\":100},\"low\":{\"factors\":[{\"fa\":\"معمولاً نگران‌کننده نیست\",\"en\":\"Usually not a concern\"}],\"questions\":[{\"fa\":\"آیا لازم است کاری انجام دهم؟\",\"en\":\"Do I need to do anything about it?\"}],\"see_doctor\":{\"fa\":\"در صورت شک با پزشک صحبت کن.\",\"en\":\"Ask a doctor if unsure.\"}},\"high\":{\"factors\":[{\"fa\":\"استرس، خواب کم یا آزمایش بلافاصله بعد از بیدار شدن\",\"en\":\"Stress, poor sleep or testing right after waking\"},{\"fa\":\"شیردهی یا بارداری\",\"en\":\"Breastfeeding or pregnancy\"},{\"fa\":\"برخی داروها\",\"en\":\"Some medicines\"}],\"questions\":[{\"fa\":\"آیا باید آزمایش را در حالت استراحت تکرار کنم؟\",\"en\":\"Should I repeat the test at rest?\"},{\"fa\":\"آیا پرولاکتین بالا روی نظم پریود یا بارداری من اثر دارد؟\",\"en\":\"Could high prolactin affect my periods or getting pregnant?\"}],\"see_doctor\":{\"fa\":\"اگر ترشح شیر از سینه، سردرد یا اختلال دید داری، زودتر مراجعه کن.\",\"en\":\"If you have milky nipple discharge, headaches or vision changes, see a doctor soon.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(315,'lab_markers','amh',25,1,NULL,'{\"fa\":\"AMH\",\"en\":\"AMH\"}','{\"fa\":\"هورمونی که فولیکول‌های کوچک تخمدان می‌سازند و تخمینی از ذخیره تخمدان می‌دهد. با سن کم می‌شود و به‌تنهایی شانس بارداری را تعیین نمی‌کند.\",\"en\":\"A hormone made by small ovarian follicles that estimates ovarian reserve. It falls with age and does not on its own decide the chance of pregnancy.\"}','{\"category\":\"hormone\",\"subtitle\":{\"fa\":\"ذخیره تخمدان\",\"en\":\"Ovarian reserve\"},\"aliases\":[\"amh\",\"antimullerianhormone\",\"antimüllerianhormone\",\"mullerianinhibitinghormone\"],\"unit\":\"ng/mL\",\"range_varies\":true,\"typical\":{\"low\":1.0,\"high\":3.5,\"text\":\"1.0–3.5 (varies with age)\"},\"low\":{\"factors\":[{\"fa\":\"افزایش سن\",\"en\":\"Getting older\"},{\"fa\":\"جراحی یا درمان‌های قبلی تخمدان\",\"en\":\"Past ovarian surgery or treatment\"}],\"questions\":[{\"fa\":\"ذخیره تخمدان من برای سنم چطور است؟\",\"en\":\"What is my ovarian reserve like for my age?\"},{\"fa\":\"آیا باید برای بارداری زودتر اقدام کنم؟\",\"en\":\"Should I try to conceive sooner?\"}],\"see_doctor\":{\"fa\":\"برای تفسیر بر اساس سن و برنامه بارداری با پزشک زنان یا متخصص ناباروری صحبت کن.\",\"en\":\"Talk to a gynaecologist or fertility specialist to read it for your age and plans.\"}},\"high\":{\"factors\":[{\"fa\":\"سندرم تخمدان پلی‌کیستیک\",\"en\":\"Polycystic ovary syndrome\"}],\"questions\":[{\"fa\":\"آیا AMH بالا نشانه PCOS است؟\",\"en\":\"Does a high AMH suggest PCOS?\"}],\"see_doctor\":{\"fa\":\"همراه با سونوگرافی و علائمت با پزشک زنان بررسی کن.\",\"en\":\"Review it with a gynaecologist together with an ultrasound and your symptoms.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00'),
(316,'lab_markers','testosterone',26,1,NULL,'{\"fa\":\"تستوسترون\",\"en\":\"Testosterone\"}','{\"fa\":\"هورمون مردانه‌ای که در زنان هم به مقدار کم ساخته می‌شود. بالا بودنش می‌تواند با آکنه، موهای زائد و سیکل نامنظم همراه باشد.\",\"en\":\"A male hormone that women make in small amounts. A high level can go with acne, unwanted hair and irregular cycles.\"}','{\"category\":\"hormone\",\"subtitle\":{\"fa\":\"آندروژن\",\"en\":\"Androgen\"},\"aliases\":[\"testosterone\",\"totaltestosterone\",\"testosteronetotal\",\"تستوسترون\"],\"unit\":\"ng/dL\",\"typical\":{\"low\":15,\"high\":70,\"text\":\"15–70\"},\"low\":{\"factors\":[{\"fa\":\"قرص‌های هورمونی\",\"en\":\"Hormonal contraceptives\"},{\"fa\":\"نزدیک شدن به یائسگی\",\"en\":\"Approaching menopause\"}],\"questions\":[{\"fa\":\"آیا لازم است کاری انجام دهم؟\",\"en\":\"Do I need to do anything about it?\"}],\"see_doctor\":{\"fa\":\"در صورت شک با پزشک صحبت کن.\",\"en\":\"Ask a doctor if unsure.\"}},\"high\":{\"factors\":[{\"fa\":\"سندرم تخمدان پلی‌کیستیک\",\"en\":\"Polycystic ovary syndrome\"},{\"fa\":\"برخی داروها یا مکمل‌ها\",\"en\":\"Some medicines or supplements\"}],\"questions\":[{\"fa\":\"آیا تستوسترون بالا نشانه PCOS است؟\",\"en\":\"Does a high testosterone suggest PCOS?\"}],\"see_doctor\":{\"fa\":\"همراه با علائمت با پزشک زنان یا غدد بررسی کن.\",\"en\":\"Review it with a gynaecologist or endocrinologist together with your symptoms.\"}}}',1,'2026-09-23 06:30:00','2026-09-23 06:30:00');
/*!40000 ALTER TABLE `catalog_items` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `challenges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `challenges` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) DEFAULT NULL,
  `title` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`title`)),
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`description`)),
  `cycle_day_from` tinyint(3) unsigned DEFAULT NULL,
  `cycle_day_to` tinyint(3) unsigned DEFAULT NULL,
  `category` varchar(255) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `challenges_slug_unique` (`slug`),
  KEY `challenges_active_day_index` (`is_active`,`cycle_day_from`,`cycle_day_to`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `challenges` WRITE;
/*!40000 ALTER TABLE `challenges` DISABLE KEYS */;
INSERT INTO `challenges` VALUES
(1,'log-basal-temperature','{\"fa\":\"\\u062b\\u0628\\u062a \\u062f\\u0645\\u0627\\u06cc \\u0628\\u062f\\u0646\",\"en\":\"Log your body temperature\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u062f\\u0645\\u0627\\u06cc \\u067e\\u0627\\u06cc\\u0647 \\u0628\\u062f\\u0646\\u062a \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646 \\u062a\\u0627 \\u0631\\u0648\\u0646\\u062f \\u0633\\u06cc\\u06a9\\u0644 \\u062f\\u0642\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f\",\"en\":\"Log your basal body temperature today for a more accurate cycle\"}',NULL,NULL,'tracking',1,1,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'log-mood','{\"fa\":\"\\u062d\\u0627\\u0644 \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Log how you feel today\"}','{\"fa\":\"\\u06cc\\u06a9 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u0648\\u0642\\u062a \\u0628\\u06af\\u0630\\u0627\\u0631 \\u0648 \\u062d\\u0627\\u0644 \\u0648 \\u062d\\u0648\\u0635\\u0644\\u0647\\u200c\\u06cc \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Take a minute to log today\'s mood\"}',NULL,NULL,'tracking',1,2,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,'log-symptoms','{\"fa\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 \\u0627\\u0645\\u0631\\u0648\\u0632 \\u0631\\u0627 \\u06a9\\u0627\\u0645\\u0644 \\u06a9\\u0646\",\"en\":\"Complete today\'s symptoms\"}','{\"fa\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646 \\u062a\\u0627 \\u0627\\u0644\\u06af\\u0648\\u0647\\u0627\\u06cc \\u0628\\u062f\\u0646\\u062a \\u0648\\u0627\\u0636\\u062d\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f\",\"en\":\"Log today\'s symptoms so your patterns become clearer\"}',NULL,NULL,'tracking',1,3,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,'log-seven-days','{\"fa\":\"\\u0647\\u0641\\u062a \\u0631\\u0648\\u0632 \\u067e\\u06cc\\u0627\\u067e\\u06cc \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Log seven days in a row\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0647\\u0645 \\u062b\\u0628\\u062a \\u06a9\\u0646 \\u062a\\u0627 \\u0632\\u0646\\u062c\\u06cc\\u0631\\u0647\\u200c\\u06cc \\u0647\\u0641\\u062a\\u200c\\u0631\\u0648\\u0632\\u0647\\u200c\\u0627\\u062a \\u06a9\\u0627\\u0645\\u0644 \\u0634\\u0648\\u062f\",\"en\":\"Log today to complete your seven-day run\"}',NULL,NULL,'tracking',1,4,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(5,'meditate-10-minutes','{\"fa\":\"\\u06f1\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u0645\\u062f\\u06cc\\u062a\\u06cc\\u0634\\u0646\",\"en\":\"10 minutes of meditation\"}','{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0627\\u0647\\u0634 \\u0627\\u0633\\u062a\\u0631\\u0633\\u060c \\u06f1\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u0645\\u062f\\u06cc\\u062a\\u06cc\\u0634\\u0646 \\u06a9\\u0646\",\"en\":\"Meditate for 10 minutes to reduce stress\"}',NULL,NULL,'mindfulness',1,5,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(6,'deep-breathing','{\"fa\":\"\\u067e\\u0646\\u062c \\u0646\\u0641\\u0633 \\u0639\\u0645\\u06cc\\u0642\",\"en\":\"Five deep breaths\"}','{\"fa\":\"\\u0647\\u0631 \\u0648\\u0642\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0631\\u0627 \\u062d\\u0633 \\u06a9\\u0631\\u062f\\u06cc\\u060c \\u067e\\u0646\\u062c \\u0646\\u0641\\u0633 \\u0639\\u0645\\u06cc\\u0642 \\u0648 \\u0622\\u0631\\u0627\\u0645 \\u0628\\u06a9\\u0634\",\"en\":\"Take five slow, deep breaths whenever tension builds\"}',NULL,NULL,'mindfulness',1,6,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(7,'gratitude-note','{\"fa\":\"\\u0633\\u0647 \\u0686\\u06cc\\u0632 \\u062e\\u0648\\u0628 \\u0627\\u0645\\u0631\\u0648\\u0632\",\"en\":\"Three good things\"}','{\"fa\":\"\\u0633\\u0647 \\u0686\\u06cc\\u0632 \\u06a9\\u0647 \\u0627\\u0645\\u0631\\u0648\\u0632 \\u0628\\u0627\\u0628\\u062a\\u0634\\u0627\\u0646 \\u0633\\u067e\\u0627\\u0633\\u06af\\u0632\\u0627\\u0631\\u06cc\\u060c \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u062f\\u062a \\u0628\\u0646\\u0648\\u06cc\\u0633\",\"en\":\"Write down three things you\'re grateful for today\"}',NULL,NULL,'mindfulness',1,7,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(8,'screen-free-hour','{\"fa\":\"\\u06cc\\u06a9 \\u0633\\u0627\\u0639\\u062a \\u0628\\u062f\\u0648\\u0646 \\u0635\\u0641\\u062d\\u0647\\u200c\\u0646\\u0645\\u0627\\u06cc\\u0634\",\"en\":\"One screen-free hour\"}','{\"fa\":\"\\u06cc\\u06a9 \\u0633\\u0627\\u0639\\u062a \\u0627\\u0632 \\u0627\\u0645\\u0631\\u0648\\u0632 \\u0631\\u0627 \\u0628\\u062f\\u0648\\u0646 \\u06af\\u0648\\u0634\\u06cc \\u0648 \\u0646\\u0645\\u0627\\u06cc\\u0634\\u06af\\u0631 \\u0628\\u06af\\u0630\\u0631\\u0627\\u0646\",\"en\":\"Spend one hour today away from phones and screens\"}',NULL,NULL,'mindfulness',1,8,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(9,'healthy-meal','{\"fa\":\"\\u06cc\\u06a9 \\u0648\\u0639\\u062f\\u0647\\u200c\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0628\\u062e\\u0648\\u0631\",\"en\":\"Eat one healthy meal\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u06cc\\u06a9 \\u0648\\u0639\\u062f\\u0647\\u200c\\u06cc \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0648 \\u0645\\u063a\\u0630\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u062f\\u062a \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\",\"en\":\"Prepare one balanced, nutritious meal today\"}',NULL,NULL,'nutrition',1,9,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(10,'drink-water','{\"fa\":\"\\u0647\\u0634\\u062a \\u0644\\u06cc\\u0648\\u0627\\u0646 \\u0622\\u0628\",\"en\":\"Eight glasses of water\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0647\\u0634\\u062a \\u0644\\u06cc\\u0648\\u0627\\u0646 \\u0622\\u0628 \\u0628\\u0646\\u0648\\u0634\\u061b \\u06a9\\u0645\\u200c\\u0622\\u0628\\u06cc \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0631\\u0627 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\",\"en\":\"Drink eight glasses of water today \\u2014 dehydration deepens fatigue\"}',NULL,NULL,'nutrition',1,10,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(11,'iron-rich-food','{\"fa\":\"\\u06cc\\u06a9 \\u062e\\u0648\\u0631\\u0627\\u06a9\\u06cc \\u0622\\u0647\\u0646\\u200c\\u062f\\u0627\\u0631\",\"en\":\"One iron-rich food\"}','{\"fa\":\"\\u062e\\u0648\\u0631\\u0627\\u06a9\\u06cc \\u0622\\u0647\\u0646\\u200c\\u062f\\u0627\\u0631 \\u0645\\u062b\\u0644 \\u0639\\u062f\\u0633\\u060c \\u0627\\u0633\\u0641\\u0646\\u0627\\u062c \\u06cc\\u0627 \\u062e\\u0631\\u0645\\u0627 \\u0628\\u0647 \\u0648\\u0639\\u062f\\u0647\\u200c\\u0627\\u062a \\u0627\\u0636\\u0627\\u0641\\u0647 \\u06a9\\u0646\",\"en\":\"Add an iron-rich food like lentils, spinach or dates to a meal\"}',NULL,NULL,'nutrition',1,11,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(12,'no-added-sugar','{\"fa\":\"\\u06cc\\u06a9 \\u0631\\u0648\\u0632 \\u0628\\u062f\\u0648\\u0646 \\u0642\\u0646\\u062f \\u0627\\u0641\\u0632\\u0648\\u062f\\u0647\",\"en\":\"A day without added sugar\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0631\\u0627 \\u0628\\u062f\\u0648\\u0646 \\u0646\\u0648\\u0634\\u06cc\\u062f\\u0646\\u06cc \\u0648 \\u062e\\u0648\\u0631\\u0627\\u06a9\\u06cc \\u0634\\u06cc\\u0631\\u06cc\\u0646\\u200c\\u0634\\u062f\\u0647 \\u0628\\u06af\\u0630\\u0631\\u0627\\u0646\",\"en\":\"Go today without sweetened drinks or snacks\"}',NULL,NULL,'nutrition',1,12,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(13,'walk-20-minutes','{\"fa\":\"\\u06f2\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\",\"en\":\"Walk for 20 minutes\"}','{\"fa\":\"\\u06cc\\u06a9 \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u06f2\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647\\u200c\\u0627\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0628\\u062f\\u0647\",\"en\":\"Go for a light 20-minute walk\"}',NULL,NULL,'exercise',1,13,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(14,'gentle-stretch','{\"fa\":\"\\u06f5 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u06a9\\u0634\\u0634\",\"en\":\"5 minutes of stretching\"}','{\"fa\":\"\\u0686\\u0646\\u062f \\u062d\\u0631\\u06a9\\u062a \\u06a9\\u0634\\u0634\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0645\\u0631 \\u0648 \\u0644\\u06af\\u0646 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0628\\u062f\\u0647\",\"en\":\"Do a few gentle stretches for your lower back and hips\"}',1,5,'exercise',1,14,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(15,'strength-session','{\"fa\":\"\\u06cc\\u06a9 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u0642\\u062f\\u0631\\u062a\\u06cc \\u06a9\\u0648\\u062a\\u0627\\u0647\",\"en\":\"A short strength session\"}','{\"fa\":\"\\u0627\\u0646\\u0631\\u0698\\u06cc \\u0627\\u0645\\u0631\\u0648\\u0632\\u062a \\u062e\\u0648\\u0628 \\u0627\\u0633\\u062a\\u061b \\u06f2\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u0642\\u062f\\u0631\\u062a\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0628\\u062f\\u0647\",\"en\":\"Your energy is up today \\u2014 do 20 minutes of strength work\"}',NULL,NULL,'exercise',1,15,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(16,'sleep-earlier','{\"fa\":\"\\u0632\\u0648\\u062f\\u062a\\u0631 \\u0628\\u062e\\u0648\\u0627\\u0628\",\"en\":\"Go to bed earlier\"}','{\"fa\":\"\\u0627\\u0645\\u0634\\u0628 \\u06f3\\u06f0 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u0632\\u0648\\u062f\\u062a\\u0631 \\u0628\\u062e\\u0648\\u0627\\u0628 \\u062a\\u0627 \\u062e\\u0648\\u0627\\u0628 \\u0628\\u0647\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\",\"en\":\"Sleep 30 minutes earlier tonight for better rest\"}',NULL,NULL,'sleep',1,16,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(17,'no-caffeine-after-four','{\"fa\":\"\\u0628\\u0639\\u062f \\u0627\\u0632 \\u0639\\u0635\\u0631 \\u0628\\u062f\\u0648\\u0646 \\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646\",\"en\":\"No caffeine after 4pm\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0628\\u0639\\u062f \\u0627\\u0632 \\u0633\\u0627\\u0639\\u062a \\u06f4 \\u0686\\u0627\\u06cc \\u0648 \\u0642\\u0647\\u0648\\u0647 \\u0646\\u062e\\u0648\\u0631 \\u062a\\u0627 \\u0634\\u0628 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\",\"en\":\"Skip coffee and tea after 4pm for an easier night\"}',NULL,NULL,'sleep',1,17,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(18,'phone-out-of-bedroom','{\"fa\":\"\\u06af\\u0648\\u0634\\u06cc \\u0628\\u06cc\\u0631\\u0648\\u0646 \\u0627\\u0632 \\u0627\\u062a\\u0627\\u0642 \\u062e\\u0648\\u0627\\u0628\",\"en\":\"Phone out of the bedroom\"}','{\"fa\":\"\\u0627\\u0645\\u0634\\u0628 \\u06af\\u0648\\u0634\\u06cc \\u0631\\u0627 \\u0628\\u06cc\\u0631\\u0648\\u0646 \\u0627\\u0632 \\u0627\\u062a\\u0627\\u0642 \\u0628\\u06af\\u0630\\u0627\\u0631 \\u0648 \\u0628\\u062f\\u0648\\u0646 \\u0622\\u0646 \\u0628\\u062e\\u0648\\u0627\\u0628\",\"en\":\"Leave your phone outside the bedroom tonight\"}',NULL,NULL,'sleep',1,18,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(19,'warm-compress-period','{\"fa\":\"\\u06a9\\u06cc\\u0633\\u0647\\u200c\\u06cc \\u0622\\u0628 \\u06af\\u0631\\u0645 \\u0631\\u0648\\u06cc \\u0634\\u06a9\\u0645\",\"en\":\"A warm compress on your belly\"}','{\"fa\":\"\\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u0627\\u0648\\u0644 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc\\u060c \\u06f1\\u06f5 \\u062f\\u0642\\u06cc\\u0642\\u0647 \\u06a9\\u06cc\\u0633\\u0647\\u200c\\u06cc \\u0622\\u0628 \\u06af\\u0631\\u0645 \\u062f\\u0631\\u062f\\u0650 \\u0634\\u06a9\\u0645 \\u0631\\u0627 \\u06a9\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\",\"en\":\"In the first days of your period, 15 minutes of heat eases cramps\"}',1,3,'mindfulness',1,19,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(20,'rest-day-period','{\"fa\":\"\\u06cc\\u06a9 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648\\u0627\\u0642\\u0639\\u06cc\",\"en\":\"A real rest\"}','{\"fa\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u06cc\\u06a9 \\u06a9\\u0627\\u0631 \\u0627\\u0632 \\u0644\\u06cc\\u0633\\u062a\\u062a \\u0631\\u0627 \\u062d\\u0630\\u0641 \\u06a9\\u0646 \\u0648 \\u0628\\u0647 \\u0628\\u062f\\u0646\\u062a \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0628\\u062f\\u0647\",\"en\":\"Drop one thing from your list today and let your body rest\"}',1,4,'sleep',1,20,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(21,'iron-after-period','{\"fa\":\"\\u062c\\u0628\\u0631\\u0627\\u0646 \\u0622\\u0647\\u0646 \\u0628\\u0639\\u062f \\u0627\\u0632 \\u067e\\u0631\\u06cc\\u0648\\u062f\",\"en\":\"Replenish iron after your period\"}','{\"fa\":\"\\u0628\\u0639\\u062f \\u0627\\u0632 \\u062e\\u0648\\u0646\\u200c\\u0631\\u06cc\\u0632\\u06cc\\u060c \\u06cc\\u06a9 \\u0648\\u0639\\u062f\\u0647\\u200c\\u06cc \\u0622\\u0647\\u0646\\u200c\\u062f\\u0627\\u0631 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 C \\u0628\\u062e\\u0648\\u0631\",\"en\":\"After bleeding, pair an iron-rich meal with vitamin C\"}',5,9,'nutrition',1,21,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(22,'energy-peak-workout','{\"fa\":\"\\u0627\\u0632 \\u0627\\u0648\\u062c \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\",\"en\":\"Use your energy peak\"}','{\"fa\":\"\\u0627\\u06cc\\u0646 \\u0631\\u0648\\u0632\\u0647\\u0627 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u067e\\u0631\\u0627\\u0646\\u0631\\u0698\\u06cc\\u200c\\u062a\\u0631\\u06cc\\u0646 \\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u0686\\u0631\\u062e\\u0647\\u200c\\u0627\\u0646\\u062f\\u061b \\u06cc\\u06a9 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u062c\\u062f\\u06cc\\u200c\\u062a\\u0631 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0628\\u062f\\u0647\",\"en\":\"These are usually your highest-energy days \\u2014 take on a harder workout\"}',8,14,'exercise',1,22,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(23,'log-fertility-signs','{\"fa\":\"\\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646\",\"en\":\"Log your ovulation signs\"}','{\"fa\":\"\\u062a\\u0631\\u0634\\u062d\\u0627\\u062a \\u0648 \\u062f\\u0645\\u0627\\u06cc \\u0628\\u062f\\u0646\\u062a \\u0631\\u0627 \\u0627\\u06cc\\u0646 \\u0631\\u0648\\u0632\\u0647\\u0627 \\u062b\\u0628\\u062a \\u06a9\\u0646 \\u062a\\u0627 \\u067e\\u0646\\u062c\\u0631\\u0647\\u200c\\u06cc \\u0628\\u0627\\u0631\\u0648\\u0631\\u06cc \\u062f\\u0642\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f\",\"en\":\"Log discharge and temperature these days for a sharper fertile window\"}',12,17,'tracking',1,23,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(24,'magnesium-before-period','{\"fa\":\"\\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0642\\u0628\\u0644 \\u0627\\u0632 \\u067e\\u0631\\u06cc\\u0648\\u062f\",\"en\":\"Magnesium before your period\"}','{\"fa\":\"\\u062e\\u0648\\u0631\\u0627\\u06a9\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0631\\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0645\\u062b\\u0644 \\u0628\\u0627\\u062f\\u0627\\u0645 \\u0648 \\u0634\\u06a9\\u0644\\u0627\\u062a \\u062a\\u0644\\u062e \\u0628\\u0647 \\u0633\\u0646\\u062f\\u0631\\u0645 \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f\",\"en\":\"Magnesium-rich foods like almonds and dark chocolate help with PMS\"}',20,28,'nutrition',1,24,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(25,'gentle-with-yourself-pms','{\"fa\":\"\\u0628\\u0627 \\u062e\\u0648\\u062f\\u062a \\u0645\\u0647\\u0631\\u0628\\u0627\\u0646 \\u0628\\u0627\\u0634\",\"en\":\"Be gentle with yourself\"}','{\"fa\":\"\\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0646\\u0648\\u0633\\u0627\\u0646 \\u062e\\u0644\\u0642 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061b \\u0627\\u0645\\u0631\\u0648\\u0632 \\u06cc\\u06a9 \\u06a9\\u0627\\u0631 \\u0622\\u0631\\u0627\\u0645\\u200c\\u0628\\u062e\\u0634 \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u062f\\u062a \\u0628\\u06a9\\u0646\",\"en\":\"Mood swings before your period are normal \\u2014 do one calming thing for yourself today\"}',24,35,'mindfulness',1,25,'2026-09-23 09:00:00','2026-09-23 09:00:00');
