INSERT INTO `message_contents` VALUES
(1,'cycle_base_non_ttc','menstruation','fa','cycle_base_non_ttc / menstruation','{\"short\":\"\\u0627\\u0645\\u0631\\u0648\\u0632 \\u0631\\u0648\\u0632 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648 \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f\\u062a\\u0647\",\"long\":\"\\u062f\\u0631 \\u062f\\u0648\\u0631\\u0627\\u0646 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc\\u060c \\u0628\\u062f\\u0646\\u062a \\u0646\\u06cc\\u0627\\u0632 \\u0628\\u0647 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648 \\u062a\\u0648\\u062c\\u0647 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0631\\u0647. \\u0628\\u0647 \\u062e\\u0648\\u062f\\u062a \\u0627\\u062c\\u0627\\u0632\\u0647 \\u0628\\u062f\\u0647 \\u06a9\\u0645\\u06cc \\u0622\\u0631\\u0648\\u0645\\u200c\\u062a\\u0631 \\u0628\\u0627\\u0634\\u06cc \\u0648 \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0627\\u062c\\u062a\\u0646\\u0627\\u0628 \\u06a9\\u0646\\u06cc.\",\"action\":\"\\u06cc\\u06a9 \\u0646\\u0648\\u0634\\u06cc\\u062f\\u0646\\u06cc \\u06af\\u0631\\u0645 \\u0628\\u0646\\u0648\\u0634 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\",\"dos\":[\"\\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc\",\"\\u0646\\u0648\\u0634\\u06cc\\u062f\\u0646 \\u0622\\u0628 \\u0641\\u0631\\u0627\\u0648\\u0627\\u0646\",\"\\u0645\\u0635\\u0631\\u0641 \\u0622\\u0647\\u0646\",\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9\"],\"donts\":[\"\\u0648\\u0631\\u0632\\u0634 \\u0633\\u0646\\u06af\\u06cc\\u0646\",\"\\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0632\\u06cc\\u0627\\u062f\",\"\\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0634\\u0648\\u0631\",\"\\u0628\\u06cc\\u200c\\u062e\\u0648\\u0627\\u0628\\u06cc\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,'cycle_base_non_ttc','menstruation','en','cycle_base_non_ttc / menstruation','{\"short\":\"Today is a day for rest and self-care\",\"long\":\"During menstruation, your body needs more rest and attention. Allow yourself to slow down and avoid heavy activities.\",\"action\":\"Have a warm drink and rest\",\"dos\":[\"Get enough rest\",\"Drink plenty of water\",\"Take iron\",\"Light walking\"],\"donts\":[\"Heavy exercise\",\"Too much caffeine\",\"Salty foods\",\"Sleep deprivation\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,'cycle_base_non_ttc','follicular','fa','cycle_base_non_ttc / follicular','{\"short\":\"\\u0627\\u0646\\u0631\\u0698\\u06cc\\u062a \\u062f\\u0627\\u0631\\u0647 \\u0628\\u0631\\u0645\\u06cc\\u200c\\u06af\\u0631\\u062f\\u0647! \\u0648\\u0642\\u062a \\u0634\\u0631\\u0648\\u0639\\u200c\\u0647\\u0627\\u06cc \\u062a\\u0627\\u0632\\u0647\\u200c\\u0633\\u062a\",\"long\":\"\\u062f\\u0631 \\u0641\\u0627\\u0632 \\u0641\\u0648\\u0644\\u06cc\\u06a9\\u0648\\u0644\\u0627\\u0631\\u060c \\u0633\\u0637\\u062d \\u0627\\u0633\\u062a\\u0631\\u0648\\u0698\\u0646 \\u0628\\u0627\\u0644\\u0627 \\u0645\\u06cc\\u0631\\u0647 \\u0648 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0648 \\u062e\\u0644\\u0627\\u0642\\u06cc\\u062a\\u062a \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u067e\\u06cc\\u062f\\u0627 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0647. \\u0628\\u0647\\u062a\\u0631\\u06cc\\u0646 \\u0632\\u0645\\u0627\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0634\\u0631\\u0648\\u0639 \\u067e\\u0631\\u0648\\u0698\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062c\\u062f\\u06cc\\u062f \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u0648\\u0631\\u0632\\u0634\\u06cc \\u0634\\u062f\\u06cc\\u062f\\u062a\\u0631\\u0647.\",\"action\":\"\\u06cc\\u06a9 \\u0647\\u062f\\u0641 \\u062c\\u062f\\u06cc\\u062f \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u062a\\u0639\\u06cc\\u06cc\\u0646 \\u06a9\\u0646\",\"dos\":[\"\\u0648\\u0631\\u0632\\u0634 \\u0628\\u0627 \\u0634\\u062f\\u062a \\u0645\\u062a\\u0648\\u0633\\u0637 \\u062a\\u0627 \\u0628\\u0627\\u0644\\u0627\",\"\\u0634\\u0631\\u0648\\u0639 \\u067e\\u0631\\u0648\\u0698\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062c\\u062f\\u06cc\\u062f\",\"\\u0645\\u0644\\u0627\\u0642\\u0627\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u06cc\",\"\\u06cc\\u0627\\u062f\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u0647\\u0627\\u0631\\u062a \\u062c\\u062f\\u06cc\\u062f\"],\"donts\":[\"\\u0628\\u06cc\\u200c\\u0628\\u0631\\u0646\\u0627\\u0645\\u06af\\u06cc\",\"\\u06a9\\u0645\\u200c\\u062e\\u0648\\u0627\\u0628\\u06cc\",\"\\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0641\\u0631\\u0622\\u0648\\u0631\\u06cc \\u0634\\u062f\\u0647\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,'cycle_base_non_ttc','follicular','en','cycle_base_non_ttc / follicular','{\"short\":\"Your energy is coming back! Time for fresh starts\",\"long\":\"In the follicular phase, estrogen levels rise and your energy and creativity increase. Best time to start new projects and more intense workouts.\",\"action\":\"Set a new goal for this week\",\"dos\":[\"Medium to high intensity exercise\",\"Start new projects\",\"Social meetings\",\"Learn new skills\"],\"donts\":[\"Being unorganized\",\"Sleep deprivation\",\"Processed foods\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(5,'cycle_base_non_ttc','ovulation','fa','cycle_base_non_ttc / ovulation','{\"short\":\"\\u062f\\u0631 \\u0627\\u0648\\u062c \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0648 \\u062c\\u0630\\u0627\\u0628\\u06cc\\u062a \\u0647\\u0633\\u062a\\u06cc!\",\"long\":\"\\u0632\\u0645\\u0627\\u0646 \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc\\u060c \\u0627\\u0646\\u0631\\u0698\\u06cc\\u060c \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f \\u0628\\u0647 \\u0646\\u0641\\u0633 \\u0648 \\u062c\\u0630\\u0627\\u0628\\u06cc\\u062a\\u062a \\u062f\\u0631 \\u0628\\u0627\\u0644\\u0627\\u062a\\u0631\\u06cc\\u0646 \\u062d\\u062f \\u0647\\u0633\\u062a\\u0646. \\u0628\\u0647\\u062a\\u0631\\u06cc\\u0646 \\u0632\\u0645\\u0627\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0631\\u0627\\u0626\\u0647\\u200c\\u0647\\u0627\\u060c \\u0645\\u0630\\u0627\\u06a9\\u0631\\u0627\\u062a \\u0648 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u06cc.\",\"action\":\"\\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0627\\u0631\\u0647\\u0627\\u06cc \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\",\"dos\":[\"\\u0648\\u0631\\u0632\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0642\\u062f\\u0631\\u062a\\u06cc\",\"\\u0627\\u0631\\u0627\\u0626\\u0647 \\u0648 \\u0645\\u0630\\u0627\\u06a9\\u0631\\u0647\",\"\\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u06cc\",\"\\u062a\\u0635\\u0645\\u06cc\\u0645\\u200c\\u06af\\u06cc\\u0631\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0647\\u0645\"],\"donts\":[\"\\u0627\\u0632 \\u062f\\u0633\\u062a \\u062f\\u0627\\u062f\\u0646 \\u0627\\u06cc\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc\",\"\\u0627\\u0646\\u0632\\u0648\\u0627\",\"\\u0628\\u0647 \\u062a\\u0639\\u0648\\u06cc\\u0642 \\u0627\\u0646\\u062f\\u0627\\u062e\\u062a\\u0646 \\u06a9\\u0627\\u0631\\u0647\\u0627\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(6,'cycle_base_non_ttc','ovulation','en','cycle_base_non_ttc / ovulation','{\"short\":\"You\'re at peak energy and attractiveness!\",\"long\":\"During ovulation, your energy, confidence and attractiveness are at their peak. Best time for presentations, negotiations and social activities.\",\"action\":\"Use this energy for important tasks\",\"dos\":[\"Strength training\",\"Presentations and negotiations\",\"Social activities\",\"Important decisions\"],\"donts\":[\"Wasting this energy\",\"Isolation\",\"Procrastination\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
