(23,'cycle_override','mood_sad','fa','cycle_override / mood_sad','{\"message\":\"\\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a \\u0645\\u0646\\u0641\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0647\\u0633\\u062a\\u0646. \\u0628\\u0627 \\u062e\\u0648\\u062f\\u062a \\u0645\\u0647\\u0631\\u0628\\u0627\\u0646 \\u0628\\u0627\\u0634.\",\"action\":\"\\u0628\\u0627 \\u06cc\\u06a9 \\u062f\\u0648\\u0633\\u062a \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646 \\u06cc\\u0627 \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u06a9\\u0646\",\"dos\":[\"\\u0635\\u062d\\u0628\\u062a \\u0628\\u0627 \\u062f\\u0648\\u0633\\u062a\",\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u062f\\u0631 \\u0637\\u0628\\u06cc\\u0639\\u062a\",\"\\u0645\\u0648\\u0633\\u06cc\\u0642\\u06cc \\u0622\\u0631\\u0627\\u0645\",\"\\u0646\\u0648\\u0631 \\u0622\\u0641\\u062a\\u0627\\u0628\"],\"donts\":[\"\\u0627\\u0646\\u0632\\u0648\\u0627\",\"\\u0634\\u0628\\u06a9\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0627\\u062c\\u062a\\u0645\\u0627\\u0639\\u06cc \\u0632\\u06cc\\u0627\\u062f\",\"\\u0642\\u0647\\u0648\\u0647 \\u0632\\u06cc\\u0627\\u062f\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(24,'cycle_override','mood_sad','en','cycle_override / mood_sad','{\"message\":\"Negative feelings are normal. Be kind to yourself.\",\"action\":\"Talk to a friend or take a walk\",\"dos\":[\"Talk to a friend\",\"Walk in nature\",\"Calm music\",\"Sunlight\"],\"donts\":[\"Isolation\",\"Too much social media\",\"Too much coffee\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(25,'cycle_override','mood_angry','fa','cycle_override / mood_angry','{\"message\":\"\\u0639\\u0635\\u0628\\u0627\\u0646\\u06cc\\u062a \\u0647\\u0645 \\u0628\\u062e\\u0634\\u06cc \\u0627\\u0632 \\u0686\\u0631\\u062e\\u0647 \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u0627\\u0633\\u062a.\",\"action\":\"\\u062a\\u0646\\u0641\\u0633 \\u0639\\u0645\\u06cc\\u0642 \\u0648 \\u0641\\u0627\\u0635\\u0644\\u0647 \\u06af\\u0631\\u0641\\u062a\\u0646\",\"dos\":[\"\\u062a\\u0646\\u0641\\u0633 \\u0639\\u0645\\u06cc\\u0642\",\"\\u0648\\u0631\\u0632\\u0634\",\"\\u0646\\u0648\\u0634\\u062a\\u0646 \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a\",\"\\u0641\\u0627\\u0635\\u0644\\u0647 \\u06af\\u0631\\u0641\\u062a\\u0646\"],\"donts\":[\"\\u062a\\u0635\\u0645\\u06cc\\u0645\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u0647\\u0645\",\"\\u0628\\u062d\\u062b \\u06a9\\u0631\\u062f\\u0646\",\"\\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
