(27,'cycle_override','heavy_flow','fa','cycle_override / heavy_flow','{\"message\":\"\\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u0634\\u062f\\u06cc\\u062f \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0646\\u0647 \\u062e\\u0633\\u062a\\u0647\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0628\\u0627\\u0634\\u0647. \\u0622\\u0647\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646.\",\"action\":\"\\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u063a\\u0646\\u06cc \\u0627\\u0632 \\u0622\\u0647\\u0646 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a\",\"dos\":[\"\\u06af\\u0648\\u0634\\u062a \\u0642\\u0631\\u0645\\u0632\",\"\\u0627\\u0633\\u0641\\u0646\\u0627\\u062c\",\"\\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 C\",\"\\u0622\\u0628 \\u0641\\u0631\\u0627\\u0648\\u0627\\u0646\"],\"donts\":[\"\\u0686\\u0627\\u06cc \\u0648 \\u0642\\u0647\\u0648\\u0647 \\u0628\\u0627 \\u063a\\u0630\\u0627\",\"\\u0648\\u0631\\u0632\\u0634 \\u0633\\u0646\\u06af\\u06cc\\u0646\"]}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
