(135,'correlation_cycle','hormone_skin','fa','correlation_cycle / hormone_skin','{\"insight_message\":\"\\u062c\\u0648\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0641\\u0627\\u0632 \\u0634\\u0627\\u06cc\\u0639 \\u0647\\u0633\\u062a\\u0646. \\u0628\\u0627 \\u0634\\u0631\\u0648\\u0639 \\u0641\\u0627\\u0632 \\u0641\\u0648\\u0644\\u06cc\\u06a9\\u0648\\u0644\\u0627\\u0631 \\u0628\\u0647\\u062a\\u0631 \\u0645\\u06cc\\u0634\\u0647.\",\"action\":\"\\u067e\\u0627\\u06a9\\u0633\\u0627\\u0632\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0648 \\u0627\\u062c\\u062a\\u0646\\u0627\\u0628 \\u0627\\u0632 \\u062f\\u0633\\u062a \\u0632\\u062f\\u0646 \\u0628\\u0647 \\u0635\\u0648\\u0631\\u062a\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(136,'correlation_cycle','hormone_skin','en','correlation_cycle / hormone_skin','{\"insight_message\":\"Hormonal acne is common in this phase. It will improve with follicular phase.\",\"action\":\"Gentle cleansing and avoid touching face\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
