(138,'correlation_pregnancy','first_trimester_combo','en','correlation_pregnancy / first_trimester_combo','{\"insight_message\":\"Combination of nausea and fatigue is very common in first trimester, showing strong hormonal changes.\",\"action\":\"Small frequent meals and short rests during day\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(139,'correlation_pregnancy','third_trimester_discomfort','fa','correlation_pregnancy / third_trimester_discomfort','{\"insight_message\":\"\\u0646\\u0627\\u0631\\u0627\\u062d\\u062a\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0628\\u0647 \\u062f\\u0644\\u06cc\\u0644 \\u0631\\u0634\\u062f \\u0646\\u0648\\u0632\\u0627\\u062f \\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0627\\u0633\\u062a.\",\"action\":\"\\u0634\\u0646\\u0627\\u060c \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0628\\u0627 \\u067e\\u0627\\u0647\\u0627\\u06cc \\u0628\\u0627\\u0644\\u0627\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(140,'correlation_pregnancy','third_trimester_discomfort','en','correlation_pregnancy / third_trimester_discomfort','{\"insight_message\":\"Third trimester discomforts are due to baby growth and body preparing for delivery.\",\"action\":\"Swimming, prenatal yoga and resting with elevated legs\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(141,'correlation_pregnancy','pregnancy_mood','fa','correlation_pregnancy / pregnancy_mood','{\"insight_message\":\"\\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u062f\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0647\\u0633\\u062a\\u0646 \\u0627\\u0645\\u0627 \\u0627\\u06af\\u0631 \\u0627\\u062f\\u0627\\u0645\\u0647\\u200c\\u062f\\u0627\\u0631 \\u0628\\u0627\\u0634\\u0646 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"action\":\"\\u0628\\u0627 \\u0647\\u0645\\u0633\\u0631 \\u06cc\\u0627 \\u062f\\u0648\\u0633\\u062a \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646 \\u0648 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0646\\u06cc\\u0627\\u0632 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
(142,'correlation_pregnancy','pregnancy_mood','en','correlation_pregnancy / pregnancy_mood','{\"insight_message\":\"Mood changes in pregnancy are normal but if persistent, talk to your doctor.\",\"action\":\"Talk to partner or friend and consult doctor if needed\"}',1,1,0,'2026-09-23 09:00:00','2026-09-23 09:00:00'),
