INSERT INTO `pregnancy_weekly_content` VALUES
(1,1,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0648\\u0644 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0646\\u0648\\u0632 \\u062c\\u0646\\u06cc\\u0646\\u06cc \\u0634\\u06a9\\u0644 \\u0646\\u06af\\u0631\\u0641\\u062a\\u0647 \\u0627\\u0633\\u062a\\u061b \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u0631 \\u0627\\u0633\\u0627\\u0633 \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0631\\u0648\\u0632 \\u0622\\u062e\\u0631\\u06cc\\u0646 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0634\\u0645\\u0631\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u062f\\u0646 \\u0634\\u0645\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0648 \\u0644\\u0627\\u0646\\u0647\\u200c\\u06af\\u0632\\u06cc\\u0646\\u06cc \\u0627\\u062d\\u062a\\u0645\\u0627\\u0644\\u06cc \\u0627\\u0633\\u062a. \\u062f\\u0631 \\u0648\\u0627\\u0642\\u0639 \\u0644\\u0642\\u0627\\u062d \\u0647\\u0646\\u0648\\u0632 \\u0627\\u062a\\u0641\\u0627\\u0642 \\u0646\\u06cc\\u0641\\u062a\\u0627\\u062f\\u0647 \\u0648 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647\\u200c\\u0627\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0627\\u0628\\u0644 \\u0630\\u06a9\\u0631 \\u0646\\u06cc\\u0633\\u062a.\",\"en\":\"In week one there is no embryo yet; this week is counted from the first day of your last period. Your body is preparing for ovulation and possible implantation.\"}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u062f\\u0646 \\u0634\\u0645\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062f\\u0641\\u0639 \\u067e\\u0648\\u0634\\u0634 \\u0631\\u062d\\u0645 \\u0642\\u0628\\u0644\\u06cc \\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0686\\u0631\\u062e\\u0647 \\u062c\\u062f\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0645\\u0639\\u0645\\u0648\\u0644 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u0645\\u062d\\u0633\\u0648\\u0633 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0646\\u0648\\u0632 \\u0631\\u062e \\u0646\\u062f\\u0627\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"Your body is shedding the previous uterine lining and preparing a new cycle. You may notice typical period symptoms; no pregnancy signs yet.\"}','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0631\\u0648\\u0632\\u0627\\u0646\\u0647 \\u0631\\u0627 \\u0627\\u0632 \\u0647\\u0645\\u06cc\\u0646 \\u062d\\u0627\\u0644\\u0627 \\u0634\\u0631\\u0648\\u0639 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0645\\u0635\\u0631\\u0641 \\u0627\\u0644\\u06a9\\u0644 \\u0648 \\u062f\\u062e\\u0627\\u0646\\u06cc\\u0627\\u062a \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u0646\\u0645\\u0627\\u06cc\\u06cc\\u062f. \\u06cc\\u06a9 \\u0631\\u0698\\u06cc\\u0645 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0648 \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0645\\u0635\\u0631\\u0641 \\u0647\\u0631 \\u062f\\u0627\\u0631\\u0648\\u06cc\\u06cc \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Start a daily folic acid supplement now and avoid alcohol and smoking. Eat a balanced diet, sleep well, and check any medication with your doctor.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u0642\\u0635\\u062f \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0632\\u0645\\u0627\\u0646 \\u062e\\u0648\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0634\\u0631\\u0648\\u0639 \\u0645\\u06a9\\u0645\\u0644 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0648 \\u062b\\u0628\\u062a \\u062a\\u0627\\u0631\\u06cc\\u062e \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0627\\u0633\\u062a. \\u06cc\\u06a9 \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647 \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0645\\u0641\\u06cc\\u062f \\u0628\\u0627\\u0634\\u062f. \\u0633\\u0628\\u06a9 \\u0632\\u0646\\u062f\\u06af\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0631\\u0627 \\u067e\\u0627\\u06cc\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"If planning pregnancy, this is a good week to begin folic acid and track your period date. A pre-conception checkup can help.\"}','{\"fa\":\"\\u0628\\u062f\\u0646 \\u0634\\u0645\\u0627 \\u0647\\u0646\\u0648\\u0632 \\u062f\\u0631 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0639\\u0627\\u062f\\u06cc \\u0642\\u0631\\u0627\\u0631 \\u062f\\u0627\\u0631\\u062f \\u0648 \\u062a\\u0637\\u0627\\u0628\\u0642 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0622\\u063a\\u0627\\u0632 \\u0646\\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u062a\\u0645\\u0631\\u06a9\\u0632 \\u0628\\u0631 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u062c\\u0633\\u0645\\u06cc \\u0648 \\u0631\\u0648\\u0627\\u0646\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u062d\\u062a\\u0645\\u0627\\u0644\\u06cc \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a.\",\"en\":\"Your body is still in its normal state and pregnancy adaptation has not begun. Focus on physical and mental readiness.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0631\\u06a9\\u06cc\\u0628\\u06cc \\u0627\\u0632 \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0634\\u0631\\u0648\\u0639 \\u0645\\u0633\\u06cc\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0648 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631\\u0627\\u062a \\u0648\\u0627\\u0642\\u0639\\u200c\\u0628\\u06cc\\u0646\\u0627\\u0646\\u0647 \\u0628\\u0647 \\u0634\\u0645\\u0627 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0635\\u062d\\u0628\\u062a \\u0628\\u0627 \\u0647\\u0645\\u0633\\u0631 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0627\\u0637\\u0645\\u06cc\\u0646\\u0627\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u0628\\u062f\\u0647\\u062f.\",\"en\":\"You may feel a mix of excitement and worry about the journey ahead. Staying calm and realistic helps; talking with your partner can reassure you.\"}','{\"fa\":\"\\u0631\\u0648\\u0632\\u0627\\u0646\\u0647 \\u06f4\\u06f0\\u06f0 \\u0645\\u06cc\\u06a9\\u0631\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9\\u060c \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0628\\u0631\\u06af\\u200c\\u0633\\u0628\\u0632 \\u0648 \\u063a\\u0644\\u0627\\u062a \\u06a9\\u0627\\u0645\\u0644 \\u0631\\u0627 \\u062f\\u0631 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0628\\u06af\\u0646\\u062c\\u0627\\u0646\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u0645\\u062d\\u062f\\u0648\\u062f \\u06a9\\u0646\\u06cc\\u062f. \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u067e\\u0627\\u06cc\\u0647 \\u0631\\u0634\\u062f \\u0633\\u0627\\u0644\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a.\",\"en\":\"Include 400 mcg folic acid daily, leafy greens and whole grains. Drink enough water and limit caffeine.\"}','{\"fa\":\"\\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0633\\u0628\\u06a9 \\u0645\\u0627\\u0646\\u0646\\u062f \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0648 \\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0648\\u0631\\u0632\\u0634 \\u0645\\u0646\\u0638\\u0645 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0628\\u062f\\u0646 \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0647\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0633\\u06cc\\u0627\\u0631 \\u0634\\u062f\\u06cc\\u062f \\u0628\\u062f\\u0648\\u0646 \\u0645\\u0634\\u0648\\u0631\\u062a \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep up light activity like walking and gentle stretching to prepare your body. Avoid very intense exercise without advice.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u0642\\u0635\\u062f \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u062f\\u060c \\u06cc\\u06a9 \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0633\\u0644\\u0627\\u0645\\u062a \\u0639\\u0645\\u0648\\u0645\\u06cc \\u0648 \\u0648\\u0627\\u06a9\\u0633\\u06cc\\u0646\\u0627\\u0633\\u06cc\\u0648\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0627\\u0635 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0644\\u0627\\u0632\\u0645 \\u0646\\u06cc\\u0633\\u062a. \\u0633\\u0627\\u0628\\u0642\\u0647 \\u067e\\u0632\\u0634\\u06a9\\u06cc \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"A pre-conception visit to review general health and vaccinations is helpful. No pregnancy-specific test is needed this week.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0631\\u0627 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0648\\u0644 \\u0628\\u062f\\u0648\\u0646 \\u0648\\u062c\\u0648\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0634\\u0645\\u0631\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061f\",\"answer\":\"\\u0645\\u062d\\u0627\\u0633\\u0628\\u0647 \\u0633\\u0646 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0632 \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0631\\u0648\\u0632 \\u0622\\u062e\\u0631\\u06cc\\u0646 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0622\\u063a\\u0627\\u0632 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u060c \\u0628\\u0646\\u0627\\u0628\\u0631\\u0627\\u06cc\\u0646 \\u062f\\u0648 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0648\\u0644 \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0644\\u0642\\u0627\\u062d \\u062f\\u0631 \\u0646\\u0638\\u0631 \\u06af\\u0631\\u0641\\u062a\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0628\\u0627\\u06cc\\u062f \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0631\\u0627 \\u0634\\u0631\\u0648\\u0639 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0628\\u0647\\u062a\\u0631 \\u0627\\u0633\\u062a \\u0645\\u0635\\u0631\\u0641 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0631\\u0627 \\u062d\\u062a\\u06cc \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0648 \\u0627\\u0632 \\u0647\\u0645\\u06cc\\u0646 \\u062d\\u0627\\u0644\\u0627 \\u0622\\u063a\\u0627\\u0632 \\u06a9\\u0646\\u06cc\\u062f \\u062a\\u0627 \\u0627\\u0632 \\u0631\\u0634\\u062f \\u0633\\u0627\\u0644\\u0645 \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u0639\\u0635\\u0628\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"Why is week one counted without an embryo?\",\"answer\":\"Gestational age is measured from the first day of your last period, so the first two weeks come before conception.\"},{\"question\":\"When should I start folic acid?\",\"answer\":\"It is best to begin folic acid even before conception to support healthy neural development.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(2,2,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u062f\\u0648\\u0645 \\u0646\\u06cc\\u0632 \\u062c\\u0646\\u06cc\\u0646\\u06cc \\u0648\\u062c\\u0648\\u062f \\u0646\\u062f\\u0627\\u0631\\u062f \\u0648 \\u0628\\u062f\\u0646 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0627\\u0633\\u062a. \\u062a\\u062e\\u0645\\u06a9 \\u0628\\u0627\\u0644\\u063a \\u062f\\u0631 \\u0622\\u0633\\u062a\\u0627\\u0646\\u0647 \\u0622\\u0632\\u0627\\u062f \\u0634\\u062f\\u0646 \\u0627\\u0632 \\u062a\\u062e\\u0645\\u062f\\u0627\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u062f\\u0627\\u0631\\u062f. \\u0644\\u0642\\u0627\\u062d \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062f\\u0631 \\u067e\\u0627\\u06cc\\u0627\\u0646 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0645\\u0645\\u06a9\\u0646 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"There is still no embryo in week two; your body is preparing for ovulation. A mature egg is about to be released, and conception may occur near the end of this week.\"}','{\"fa\":\"\\u067e\\u0648\\u0634\\u0634 \\u062f\\u0627\\u062e\\u0644\\u06cc \\u0631\\u062d\\u0645 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0636\\u062e\\u06cc\\u0645 \\u0634\\u062f\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0627 \\u0628\\u0633\\u062a\\u0631\\u06cc \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0628\\u0631\\u0627\\u06cc \\u0644\\u0627\\u0646\\u0647\\u200c\\u06af\\u0632\\u06cc\\u0646\\u06cc \\u0641\\u0631\\u0627\\u0647\\u0645 \\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0645\\u0627\\u0646\\u0646\\u062f \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u062a\\u0631\\u0634\\u062d\\u0627\\u062a \\u0631\\u0627 \\u0645\\u062a\\u0648\\u062c\\u0647 \\u0634\\u0648\\u06cc\\u062f. \\u0633\\u0637\\u062d \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u200c\\u0647\\u0627 \\u0631\\u0648 \\u0628\\u0647 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0633\\u062a.\",\"en\":\"The uterine lining is thickening to prepare for implantation. You may notice ovulation signs such as changes in discharge as hormone levels rise.\"}','{\"fa\":\"\\u0628\\u0647 \\u0645\\u0635\\u0631\\u0641 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0627\\u0633\\u062a\\u0631\\u0633 \\u0632\\u06cc\\u0627\\u062f \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u062e\\u0648\\u0627\\u0628 \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0645\\u0635\\u0631\\u0641 \\u0627\\u0644\\u06a9\\u0644 \\u0648 \\u0633\\u06cc\\u06af\\u0627\\u0631 \\u0628\\u0647\\u200c\\u0637\\u0648\\u0631 \\u06a9\\u0627\\u0645\\u0644 \\u062f\\u0648\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue folic acid and avoid excess stress. Keep a healthy diet and regular sleep, and fully avoid alcohol and smoking.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u062f\\u0631 \\u062a\\u0644\\u0627\\u0634 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0633\\u062a\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u062d\\u062a\\u0645\\u0627\\u0644 \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0628\\u0627\\u0644\\u0627\\u0633\\u062a \\u0648 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0646\\u0627\\u0633\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0627\\u0631\\u0648\\u0631\\u06cc \\u0627\\u0633\\u062a. \\u067e\\u06cc\\u06af\\u06cc\\u0631\\u06cc \\u0639\\u0644\\u0627\\u0626\\u0645 \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0633\\u0628\\u06a9 \\u0632\\u0646\\u062f\\u06af\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"If trying to conceive, ovulation is likely this week, making it a fertile window. Tracking ovulation signs can help.\"}','{\"fa\":\"\\u0628\\u062f\\u0646 \\u0634\\u0645\\u0627 \\u0628\\u0627 \\u062a\\u0631\\u0634\\u062d \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u200c\\u0647\\u0627\\u06cc \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0644\\u0642\\u0627\\u062d \\u0627\\u062d\\u062a\\u0645\\u0627\\u0644\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0648 \\u0628\\u062e\\u0634\\u06cc \\u0627\\u0632 \\u0686\\u0631\\u062e\\u0647 \\u0628\\u0627\\u0631\\u0648\\u0631\\u06cc \\u0627\\u0633\\u062a.\",\"en\":\"Your body prepares for possible conception through ovulation hormones. These changes are a natural part of the fertility cycle.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u062f\\u0648\\u0631\\u0647 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631\\u060c \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0627\\u0645\\u06cc\\u062f \\u06cc\\u0627 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u062d\\u0641\\u0638 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0648 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u0627\\u0632 \\u0641\\u0634\\u0627\\u0631 \\u0631\\u0648\\u0627\\u0646\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u0645\\u0633\\u06cc\\u0631 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a. \\u0628\\u0627 \\u062e\\u0648\\u062f\\u062a\\u0627\\u0646 \\u0645\\u0647\\u0631\\u0628\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"During this waiting phase you may feel hopeful or anxious. Staying calm and easing pressure on yourself matters; be kind to yourself.\"}','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9\\u060c \\u0622\\u0647\\u0646 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u06a9\\u0627\\u0641\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0645\\u06cc\\u0648\\u0647 \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u062a\\u0627\\u0632\\u0647 \\u0648 \\u0622\\u0628 \\u0641\\u0631\\u0627\\u0648\\u0627\\u0646 \\u0628\\u062e\\u0634 \\u0645\\u0647\\u0645 \\u0631\\u0698\\u06cc\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0641\\u0631\\u0622\\u0648\\u0631\\u06cc\\u200c\\u0634\\u062f\\u0647 \\u06a9\\u0645\\u062a\\u0631 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue folic acid, iron and enough protein. Fresh fruit, vegetables and plenty of water are key; limit processed foods.\"}','{\"fa\":\"\\u0648\\u0631\\u0632\\u0634 \\u0633\\u0628\\u06a9 \\u062a\\u0627 \\u0645\\u062a\\u0648\\u0633\\u0637 \\u0645\\u0627\\u0646\\u0646\\u062f \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0648 \\u06cc\\u0648\\u06af\\u0627 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a \\u0648 \\u0628\\u0647 \\u062a\\u0639\\u0627\\u062f\\u0644 \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Light to moderate exercise like walking and yoga supports hormonal balance. Avoid high-risk activities and listen to your body.\"}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0627\\u0635\\u06cc \\u0644\\u0627\\u0632\\u0645 \\u0646\\u06cc\\u0633\\u062a\\u060c \\u0627\\u0645\\u0627 \\u06a9\\u06cc\\u062a \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0647 \\u062a\\u0634\\u062e\\u06cc\\u0635 \\u0632\\u0645\\u0627\\u0646 \\u0628\\u0627\\u0631\\u0648\\u0631\\u06cc \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u062f\\u0627\\u0634\\u062a\\u0646 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u06cc \\u0632\\u0645\\u06cc\\u0646\\u0647\\u200c\\u0627\\u06cc \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"No specific test is needed, but an ovulation kit can help identify your fertile window. Consult your doctor about any underlying condition.\"}','{\"fa\":[{\"question\":\"\\u0628\\u0647\\u062a\\u0631\\u06cc\\u0646 \\u0632\\u0645\\u0627\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0627\\u0631\\u0648\\u0631\\u06cc \\u06a9\\u062f\\u0627\\u0645 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u062a\\u062e\\u0645\\u06a9\\u200c\\u06af\\u0630\\u0627\\u0631\\u06cc\\u060c \\u06cc\\u0639\\u0646\\u06cc \\u0627\\u0648\\u0627\\u0633\\u0637 \\u0686\\u0631\\u062e\\u0647\\u060c \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc\\u0646 \\u0627\\u062d\\u062a\\u0645\\u0627\\u0644 \\u0628\\u0627\\u0631\\u0648\\u0631\\u06cc \\u0631\\u0627 \\u062f\\u0627\\u0631\\u0646\\u062f.\"},{\"question\":\"\\u0622\\u06cc\\u0627 \\u062a\\u0633\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0645\\u0639\\u062a\\u0628\\u0631 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u062e\\u06cc\\u0631\\u060c \\u0686\\u0648\\u0646 \\u0644\\u0642\\u0627\\u062d \\u0647\\u0646\\u0648\\u0632 \\u062a\\u062b\\u0628\\u06cc\\u062a \\u0646\\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a \\u0648 \\u062a\\u0633\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0645\\u0631\\u062d\\u0644\\u0647 \\u0646\\u062a\\u06cc\\u062c\\u0647 \\u062f\\u0642\\u06cc\\u0642\\u06cc \\u0646\\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f.\"}],\"en\":[{\"question\":\"When is the most fertile time?\",\"answer\":\"The days around ovulation, in the middle of your cycle, offer the highest chance of conception.\"},{\"question\":\"Is a pregnancy test reliable this week?\",\"answer\":\"No, conception has not yet been established, so a test now will not be accurate.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(3,3,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u0648\\u0645 \\u0644\\u0642\\u0627\\u062d \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0627\\u0633\\u067e\\u0631\\u0645 \\u0648 \\u062a\\u062e\\u0645\\u06a9 \\u0628\\u0647 \\u0647\\u0645 \\u0645\\u06cc\\u200c\\u067e\\u06cc\\u0648\\u0646\\u062f\\u0646\\u062f \\u062a\\u0627 \\u06cc\\u06a9 \\u0633\\u0644\\u0648\\u0644 \\u0648\\u0627\\u062d\\u062f \\u0628\\u0647 \\u0646\\u0627\\u0645 \\u0632\\u06cc\\u06af\\u0648\\u062a \\u0628\\u0633\\u0627\\u0632\\u0646\\u062f. \\u0627\\u06cc\\u0646 \\u0633\\u0644\\u0648\\u0644 \\u0628\\u0647 \\u0633\\u0631\\u0639\\u062a \\u062a\\u0642\\u0633\\u06cc\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0628\\u0647 \\u0633\\u0645\\u062a \\u0631\\u062d\\u0645 \\u062d\\u0631\\u06a9\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0647\\u0646\\u0648\\u0632 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u0642\\u0627\\u0628\\u0644 \\u0645\\u0634\\u0627\\u0647\\u062f\\u0647\\u200c\\u0627\\u06cc \\u0648\\u062c\\u0648\\u062f \\u0646\\u062f\\u0627\\u0631\\u062f \\u0648 \\u0647\\u0645\\u0647 \\u0686\\u06cc\\u0632 \\u062f\\u0631 \\u0633\\u0637\\u062d \\u0645\\u06cc\\u06a9\\u0631\\u0648\\u0633\\u06a9\\u0648\\u067e\\u06cc \\u0627\\u0633\\u062a.\",\"en\":\"Fertilization happens in week three as sperm and egg unite to form a single cell, the zygote. It divides rapidly while traveling to the uterus; everything is still microscopic.\"}','{\"fa\":\"\\u0632\\u06cc\\u06af\\u0648\\u062a \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062d\\u0631\\u06a9\\u062a \\u0628\\u0647 \\u0633\\u0645\\u062a \\u0631\\u062d\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u0644\\u0627\\u0646\\u0647\\u200c\\u06af\\u0632\\u06cc\\u0646\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u0628\\u062f\\u0646 \\u0647\\u0646\\u0648\\u0632 \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u0645\\u062d\\u0633\\u0648\\u0633\\u06cc \\u0646\\u0634\\u0627\\u0646 \\u0646\\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f. \\u0628\\u0631\\u062e\\u06cc \\u0632\\u0646\\u0627\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0644\\u06a9\\u0647\\u200c\\u0628\\u06cc\\u0646\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0644\\u0627\\u0646\\u0647\\u200c\\u06af\\u0632\\u06cc\\u0646\\u06cc \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u0646\\u062f. \\u0633\\u0637\\u062d \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u200c\\u0647\\u0627 \\u0628\\u0647\\u200c\\u062a\\u062f\\u0631\\u06cc\\u062c \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u0627\\u0633\\u062a.\",\"en\":\"The zygote is moving toward the uterus to implant, with few visible changes yet. Some women notice light implantation spotting as hormones gradually shift.\"}','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0648 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u062f\\u0627\\u0631\\u0648\\u0647\\u0627\\u06cc \\u0628\\u062f\\u0648\\u0646 \\u062a\\u062c\\u0648\\u06cc\\u0632 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0642\\u0631\\u0627\\u0631 \\u06af\\u0631\\u0641\\u062a\\u0646 \\u062f\\u0631 \\u0645\\u0639\\u0631\\u0636 \\u0645\\u0648\\u0627\\u062f \\u0634\\u06cc\\u0645\\u06cc\\u0627\\u06cc\\u06cc \\u0648 \\u0627\\u0634\\u0639\\u0647 \\u062f\\u0648\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Take folic acid and healthy nutrition seriously and avoid over-the-counter drugs. Stay away from chemicals and radiation, and rest well.\"}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u062d\\u0633\\u0627\\u0633\\u060c \\u062d\\u0641\\u0638 \\u0633\\u0628\\u06a9 \\u0632\\u0646\\u062f\\u06af\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0627\\u0647\\u0645\\u06cc\\u062a \\u0632\\u06cc\\u0627\\u062f\\u06cc \\u062f\\u0627\\u0631\\u062f \\u0686\\u0648\\u0646 \\u0644\\u0627\\u0646\\u0647\\u200c\\u06af\\u0632\\u06cc\\u0646\\u06cc \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0634\\u06a9\\u0644\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0633\\u062a. \\u0627\\u0632 \\u0639\\u0648\\u0627\\u0645\\u0644 \\u0645\\u0636\\u0631 \\u062f\\u0648\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0645\\u0646\\u0638\\u0645 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"In this sensitive week, a healthy lifestyle matters greatly as implantation begins. Avoid harmful factors and take supplements regularly.\"}','{\"fa\":\"\\u0628\\u062f\\u0646 \\u0634\\u0645\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0631\\u062f\\u0646 \\u0631\\u062d\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u0630\\u06cc\\u0631\\u0634 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a \\u0648 \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u062a\\u0648\\u0644\\u06cc\\u062f \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0622\\u063a\\u0627\\u0632 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0627\\u06cc\\u0646 \\u062a\\u0637\\u0627\\u0628\\u0642 \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u067e\\u0627\\u06cc\\u0647 \\u06cc\\u06a9 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"Your body is preparing the uterus to receive the embryo, and pregnancy hormone production will soon begin. This early adaptation lays the groundwork.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u0646\\u0648\\u0632 \\u0627\\u0632 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0622\\u06af\\u0627\\u0647 \\u0646\\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a \\u0645\\u0639\\u0645\\u0648\\u0644 \\u0631\\u0648\\u0632\\u0645\\u0631\\u0647 \\u0631\\u0627 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u06af\\u0631 \\u062f\\u0631 \\u062a\\u0644\\u0627\\u0634 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0633\\u062a\\u06cc\\u062f\\u060c \\u0627\\u0645\\u06cc\\u062f \\u0648 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u0622\\u0631\\u0627\\u0645\\u0634 \\u062e\\u0648\\u062f \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"You may not yet know you are pregnant and feel your usual daily emotions. If trying to conceive, hope and anticipation are natural.\"}','{\"fa\":\"\\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9\\u060c \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u062f\\u0631 \\u0627\\u0648\\u0644\\u0648\\u06cc\\u062a \\u0642\\u0631\\u0627\\u0631 \\u062f\\u0647\\u06cc\\u062f \\u062a\\u0627 \\u0627\\u0632 \\u062a\\u0642\\u0633\\u06cc\\u0645 \\u0633\\u0644\\u0648\\u0644\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0634\\u0648\\u062f. \\u0645\\u0635\\u0631\\u0641 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u062a\\u0627\\u0632\\u0647 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Prioritize folic acid, omega-3 and protein to support healthy cell division. Keep eating fresh foods and drinking enough water; limit caffeine.\"}','{\"fa\":\"\\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0645\\u0627\\u0646\\u0646\\u062f \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0631\\u0648\\u0632\\u0627\\u0646\\u0647 \\u06a9\\u0627\\u0641\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u0628\\u0647 \\u06af\\u0631\\u062f\\u0634 \\u062e\\u0648\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0648 \\u0636\\u0631\\u0628\\u0647\\u200c\\u0627\\u06cc \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0647 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0628\\u062f\\u0646 \\u062a\\u0648\\u062c\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Gentle activity such as daily walking is enough and supports circulation. Avoid heavy or high-impact workouts and heed your body.\"}','{\"fa\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0646\\u0648\\u0632 \\u0646\\u062a\\u06cc\\u062c\\u0647 \\u0642\\u0627\\u0628\\u0644 \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u06cc \\u0646\\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f \\u0648 \\u0628\\u0647\\u062a\\u0631 \\u0627\\u0633\\u062a \\u0686\\u0646\\u062f \\u0631\\u0648\\u0632 \\u0635\\u0628\\u0631 \\u06a9\\u0646\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0648\\u062c\\u0648\\u062f \\u0633\\u0627\\u0628\\u0642\\u0647 \\u0633\\u0642\\u0637 \\u06cc\\u0627 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u06cc \\u062e\\u0627\\u0635\\u060c \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062f\\u0631 \\u0645\\u06cc\\u0627\\u0646 \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f.\",\"en\":\"A pregnancy test is not yet reliable, so it is better to wait a few days. Discuss any history of miscarriage or specific condition with your doctor.\"}','{\"fa\":[{\"question\":\"\\u0644\\u06a9\\u0647\\u200c\\u0628\\u06cc\\u0646\\u06cc \\u0644\\u0627\\u0646\\u0647\\u200c\\u06af\\u0632\\u06cc\\u0646\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u0644\\u06a9\\u0647\\u200c\\u0628\\u06cc\\u0646\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0647\\u0646\\u06af\\u0627\\u0645 \\u0644\\u0627\\u0646\\u0647\\u200c\\u06af\\u0632\\u06cc\\u0646\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0628\\u0627\\u0634\\u062f\\u060c \\u0627\\u0645\\u0627 \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u0634\\u062f\\u06cc\\u062f \\u0628\\u0627\\u06cc\\u062f \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u0645 \\u062a\\u0633\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u062f\\u0647\\u0645\\u061f\",\"answer\":\"\\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062d\\u062f\\u0648\\u062f \\u06cc\\u06a9 \\u0647\\u0641\\u062a\\u0647 \\u067e\\u0633 \\u0627\\u0632 \\u0644\\u0642\\u0627\\u062d \\u06cc\\u0627 \\u0628\\u0639\\u062f \\u0627\\u0632 \\u0639\\u0642\\u0628 \\u0627\\u0641\\u062a\\u0627\\u062f\\u0646 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u062a\\u0633\\u062a \\u062f\\u0642\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u062e\\u0648\\u0627\\u0647\\u062f \\u0628\\u0648\\u062f.\"}],\"en\":[{\"question\":\"Is implantation spotting normal?\",\"answer\":\"Yes, light spotting at implantation can be normal, but heavy bleeding should be checked by a doctor.\"},{\"question\":\"When can I take a pregnancy test?\",\"answer\":\"A test is usually more accurate about a week after conception or after a missed period.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(4,4,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0686\\u0647\\u0627\\u0631\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u062f\\u0627\\u0646\\u0647 \\u062e\\u0634\\u062e\\u0627\\u0634 \\u0648 \\u062d\\u062f\\u0648\\u062f \\u06f2 \\u0645\\u06cc\\u0644\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0644\\u0627\\u0646\\u0647\\u200c\\u06af\\u0632\\u06cc\\u0646\\u06cc \\u062f\\u0631 \\u062f\\u06cc\\u0648\\u0627\\u0631\\u0647 \\u0631\\u062d\\u0645 \\u06a9\\u0627\\u0645\\u0644 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0644\\u0627\\u06cc\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0644\\u0648\\u0644\\u06cc \\u06a9\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0645\\u06cc\\u200c\\u0633\\u0627\\u0632\\u0646\\u062f \\u0634\\u06a9\\u0644 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u0646\\u062f. \\u062c\\u0641\\u062a \\u0648 \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0646\\u06cc\\u0632 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u0634\\u06a9\\u06cc\\u0644 \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"At week four the embryo is about the size of a poppy seed, roughly 2 mm. Implantation completes and the cell layers that form organs begin to develop, along with the placenta and amniotic sac.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627 \\u0645\\u0627\\u0646\\u0646\\u062f \\u062e\\u0633\\u062a\\u06af\\u06cc\\u060c \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u0633\\u06cc\\u0646\\u0647 \\u0648 \\u0639\\u0642\\u0628 \\u0627\\u0641\\u062a\\u0627\\u062f\\u0646 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u062f\\u0646 \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u062a\\u0648\\u0644\\u06cc\\u062f \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc (hCG) \\u06a9\\u0631\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u0628\\u0631\\u062e\\u06cc \\u0632\\u0646\\u0627\\u0646 \\u0647\\u0646\\u0648\\u0632 \\u0647\\u06cc\\u0686 \\u0639\\u0644\\u0627\\u0645\\u062a\\u06cc \\u0646\\u062f\\u0627\\u0631\\u0646\\u062f.\",\"en\":\"You may notice first signs such as fatigue, breast tenderness and a missed period. Your body has started producing the pregnancy hormone hCG, though some women feel nothing yet.\"}','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0627\\u0644\\u06a9\\u0644\\u060c \\u0633\\u06cc\\u06af\\u0627\\u0631 \\u0648 \\u062f\\u0627\\u0631\\u0648\\u0647\\u0627\\u06cc \\u063a\\u06cc\\u0631\\u0645\\u062c\\u0627\\u0632 \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u062f\\u0648\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0631\\u0627 \\u062f\\u0631 \\u0627\\u0648\\u0644\\u0648\\u06cc\\u062a \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f. \\u0627\\u0632 \\u0628\\u0644\\u0646\\u062f \\u06a9\\u0631\\u062f\\u0646 \\u0627\\u062c\\u0633\\u0627\\u0645 \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u062e\\u0648\\u062f\\u062f\\u0627\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue folic acid and completely avoid alcohol, smoking and unapproved drugs. Prioritize healthy nutrition and rest, and avoid lifting heavy objects.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u062a\\u0633\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0645\\u062b\\u0628\\u062a \\u0634\\u062f\\u060c \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0645\\u0635\\u0631\\u0641 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627\\u06cc \\u062a\\u062c\\u0648\\u06cc\\u0632\\u0634\\u062f\\u0647 \\u0631\\u0627 \\u0622\\u063a\\u0627\\u0632 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0633\\u0628\\u06a9 \\u0632\\u0646\\u062f\\u06af\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u0646\\u0645\\u0627\\u06cc\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u063a\\u06cc\\u0631\\u0639\\u0627\\u062f\\u06cc \\u0631\\u0627 \\u06cc\\u0627\\u062f\\u062f\\u0627\\u0634\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"If your test is positive, schedule your first prenatal visit. Begin prescribed supplements and maintain a healthy lifestyle, noting any unusual symptoms.\"}','{\"fa\":\"\\u0628\\u062f\\u0646 \\u0634\\u0645\\u0627 \\u0628\\u0627 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u0637\\u0627\\u0628\\u0642 \\u0628\\u0627 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u062f\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0648 \\u062c\\u0633\\u0645\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0631\\u0627 \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u06cc\\u0646 \\u0631\\u0648\\u0646\\u062f \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a.\",\"en\":\"Your body is adapting to its new state with rising pregnancy hormones. You may sense mild mood and physical changes, which are entirely normal.\"}','{\"fa\":\"\\u0622\\u06af\\u0627\\u0647\\u06cc \\u0627\\u0632 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0634\\u0627\\u062f\\u06cc\\u060c \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u06cc\\u0627 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0628\\u0647 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0646\\u0648\\u0633\\u0627\\u0646\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0628\\u0647 \\u062f\\u0644\\u06cc\\u0644 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0627\\u0637\\u0631\\u0627\\u0641\\u06cc\\u0627\\u0646 \\u0628\\u0647 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0634\\u0645\\u0627 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"Learning you are pregnant can bring joy, excitement or anxiety. Mood swings from hormonal changes are normal, and support from loved ones helps.\"}','{\"fa\":\"\\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9\\u060c \\u0622\\u0647\\u0646 \\u0648 \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0631\\u0627 \\u062f\\u0631 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u063a\\u0630\\u0627\\u06cc\\u06cc \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u062a\\u0647\\u0648\\u0639 \\u0627\\u062d\\u062a\\u0645\\u0627\\u0644\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u062e\\u0627\\u0645 \\u0648 \\u0646\\u067e\\u062e\\u062a\\u0647 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep folic acid, iron and calcium in your diet. Small frequent meals help ease possible nausea; drink enough water and avoid raw or undercooked foods.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0648 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u06a9\\u0634\\u0634\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0627\\u0633\\u062a. \\u0627\\u0632 \\u0648\\u0631\\u0632\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0634\\u062f\\u06cc\\u062f \\u0648 \\u067e\\u0631\\u062e\\u0637\\u0631 \\u062e\\u0648\\u062f\\u062f\\u0627\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u06af\\u0631 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u062f \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0628\\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Walking and gentle stretching suit this week. Avoid intense or risky sports, and rest when you feel tired.\"}','{\"fa\":\"\\u062a\\u0633\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062e\\u0627\\u0646\\u06af\\u06cc \\u06cc\\u0627 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 hCG \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u062a\\u0623\\u06cc\\u06cc\\u062f \\u06a9\\u0646\\u062f. \\u0628\\u0627 \\u062a\\u0623\\u06cc\\u06cc\\u062f \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc\\u060c \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0645\\u0644\\u0627\\u0642\\u0627\\u062a \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u062a\\u0648\\u0644\\u062f \\u0648\\u0642\\u062a \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0648 \\u0633\\u0644\\u0627\\u0645\\u062a \\u0639\\u0645\\u0648\\u0645\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"A home test or blood hCG test can confirm pregnancy. Once confirmed, book your first prenatal visit where blood pressure and general health are checked.\"}','{\"fa\":[{\"question\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u062e\\u0633\\u062a\\u06af\\u06cc\\u060c \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u0633\\u06cc\\u0646\\u0647\\u060c \\u062a\\u0647\\u0648\\u0639 \\u062e\\u0641\\u06cc\\u0641 \\u0648 \\u0639\\u0642\\u0628 \\u0627\\u0641\\u062a\\u0627\\u062f\\u0646 \\u0642\\u0627\\u0639\\u062f\\u06af\\u06cc \\u0627\\u0632 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u0647\\u0633\\u062a\\u0646\\u062f.\"},{\"question\":\"\\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u067e\\u0632\\u0634\\u06a9\\u0627\\u0646 \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0645\\u0644\\u0627\\u0642\\u0627\\u062a \\u0631\\u0627 \\u062d\\u062f\\u0648\\u062f \\u0647\\u0641\\u062a\\u0647 \\u06f6 \\u062a\\u0627 \\u06f8 \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f\\u060c \\u0627\\u0645\\u0627 \\u0628\\u0627 \\u062a\\u0623\\u06cc\\u06cc\\u062f \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u06cc\\u062f \\u0648\\u0642\\u062a \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"What are early pregnancy symptoms?\",\"answer\":\"Fatigue, breast tenderness, mild nausea and a missed period are common early signs.\"},{\"question\":\"When is the first prenatal visit?\",\"answer\":\"Doctors usually suggest around weeks 6 to 8, but you can book once pregnancy is confirmed.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(5,5,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u067e\\u0646\\u062c\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u062f\\u0627\\u0646\\u0647 \\u06a9\\u0646\\u062c\\u062f \\u0648 \\u062d\\u062f\\u0648\\u062f \\u06f3 \\u0645\\u06cc\\u0644\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0644\\u0648\\u0644\\u0647 \\u0639\\u0635\\u0628\\u06cc \\u06a9\\u0647 \\u0645\\u063a\\u0632 \\u0648 \\u0646\\u062e\\u0627\\u0639 \\u0631\\u0627 \\u0645\\u06cc\\u200c\\u0633\\u0627\\u0632\\u062f \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0634\\u06a9\\u0644\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u0642\\u0644\\u0628 \\u06a9\\u0648\\u0686\\u06a9 \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u062a\\u067e\\u06cc\\u062f\\u0646 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0631\\u0634\\u062f \\u0628\\u0633\\u06cc\\u0627\\u0631 \\u0633\\u0631\\u06cc\\u0639 \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0627\\u06cc\\u0647 \\u0622\\u063a\\u0627\\u0632 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"At week five the embryo is about the size of a sesame seed, roughly 3 mm. The neural tube forming the brain and spinal cord is developing and the tiny heart begins to beat.\"}','{\"fa\":\"\\u0639\\u0644\\u0627\\u0626\\u0645\\u06cc \\u0645\\u0627\\u0646\\u0646\\u062f \\u062a\\u0647\\u0648\\u0639 \\u0635\\u0628\\u062d\\u06af\\u0627\\u0647\\u06cc\\u060c \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0648 \\u062a\\u06a9\\u0631\\u0631 \\u0627\\u062f\\u0631\\u0627\\u0631 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0634\\u0631\\u0648\\u0639 \\u0634\\u0648\\u062f. \\u0633\\u06cc\\u0646\\u0647\\u200c\\u0647\\u0627 \\u062d\\u0633\\u0627\\u0633\\u200c\\u062a\\u0631 \\u0648 \\u0633\\u0646\\u06af\\u06cc\\u0646\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f. \\u0646\\u0648\\u0633\\u0627\\u0646\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0628\\u0647 \\u062f\\u0644\\u06cc\\u0644 \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u200c\\u0647\\u0627 \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a.\",\"en\":\"Symptoms such as morning sickness, fatigue and frequent urination may begin. Breasts become more tender and heavy, and mood swings from hormones are common.\"}','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0645\\u0646\\u0638\\u0645 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0645\\u0627\\u0646\\u0646\\u062f \\u06af\\u0648\\u0634\\u062a \\u062e\\u0627\\u0645 \\u0648 \\u067e\\u0646\\u06cc\\u0631 \\u063a\\u06cc\\u0631\\u067e\\u0627\\u0633\\u062a\\u0648\\u0631\\u06cc\\u0632\\u0647 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0627\\u0633\\u062a\\u0631\\u0633 \\u062f\\u0648\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u062f\\u0627\\u0631\\u0648\\u0647\\u0627 \\u0631\\u0627 \\u0641\\u0642\\u0637 \\u0628\\u0627 \\u062a\\u062c\\u0648\\u06cc\\u0632 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue prenatal supplements and avoid risky foods like raw meat and unpasteurized cheese. Rest well, reduce stress, and take medicines only as prescribed.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u0647\\u0646\\u0648\\u0632 \\u0628\\u0647 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u0646\\u06a9\\u0631\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0646\\u0627\\u0633\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0627\\u0633\\u062a. \\u0628\\u0631\\u0627\\u06cc \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u062a\\u0647\\u0648\\u0639\\u060c \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0628\\u062e\\u0648\\u0631\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0645\\u0627\\u0646\\u0646\\u062f \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\",\"en\":\"If you have not yet seen a doctor, this is a good week for your first visit. Manage nausea with small frequent meals and take warning signs like bleeding seriously.\"}','{\"fa\":\"\\u062d\\u062c\\u0645 \\u062e\\u0648\\u0646 \\u0628\\u062f\\u0646 \\u0634\\u0645\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0633\\u062a \\u062a\\u0627 \\u0628\\u0647 \\u062c\\u0646\\u06cc\\u0646 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0631\\u0634\\u062f \\u062e\\u0648\\u0646\\u200c\\u0631\\u0633\\u0627\\u0646\\u06cc \\u06a9\\u0646\\u062f. \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0639\\u062b \\u0627\\u062d\\u0633\\u0627\\u0633 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0648 \\u0633\\u0631\\u06af\\u06cc\\u062c\\u0647 \\u0634\\u0648\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u062a\\u062f\\u0631\\u06cc\\u062c \\u0628\\u0627 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0645\\u0627\\u0647\\u0646\\u06af \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"Your blood volume is increasing to nourish the growing embryo, which can cause fatigue and dizziness. Your body is gradually syncing with pregnancy.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u06cc\\u0646 \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0648 \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0633\\u0644\\u0627\\u0645\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u062f\\u0631 \\u0646\\u0648\\u0633\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u06cc\\u0646 \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u0635\\u062d\\u0628\\u062a \\u0628\\u0627 \\u0647\\u0645\\u0633\\u0631 \\u06cc\\u0627 \\u06cc\\u06a9 \\u062f\\u0648\\u0633\\u062a \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0622\\u0631\\u0627\\u0645\\u0634\\u200c\\u0628\\u062e\\u0634 \\u0628\\u0627\\u0634\\u062f.\",\"en\":\"You may swing between excitement and worry about the baby\\u2019s health. These feelings are entirely normal; talking with your partner or a friend can soothe you.\"}','{\"fa\":\"\\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9\\u060c \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 B6 \\u0648 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u062a\\u0647\\u0648\\u0639 \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u062f. \\u0632\\u0646\\u062c\\u0628\\u06cc\\u0644 \\u0648 \\u06a9\\u0631\\u0627\\u06a9\\u0631 \\u0633\\u0627\\u062f\\u0647 \\u06af\\u0632\\u06cc\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062e\\u0648\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0635\\u0628\\u062d \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0686\\u0631\\u0628 \\u0648 \\u062a\\u0646\\u062f \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Folic acid, vitamin B6 and enough fluids can ease nausea. Ginger and plain crackers are good morning options; avoid greasy and spicy foods.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0628\\u0647 \\u0628\\u0647\\u0628\\u0648\\u062f \\u062d\\u0627\\u0644 \\u0639\\u0645\\u0648\\u0645\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u06af\\u0631 \\u062e\\u0633\\u062a\\u0647 \\u0647\\u0633\\u062a\\u06cc\\u062f\\u060c \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0631\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0648\\u0631\\u0632\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0634\\u062f\\u06cc\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Light walking and breathing exercises improve overall wellbeing. If tired, reduce activity and rest; avoid intense workouts.\"}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u060c \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646\\u060c \\u06af\\u0631\\u0648\\u0647 \\u062e\\u0648\\u0646\\u06cc\\u060c Rh \\u0648 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0639\\u0641\\u0648\\u0646\\u062a\\u200c\\u0647\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0623\\u06cc\\u06cc\\u062f \\u0645\\u062d\\u0644 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u0634\\u0648\\u062f. \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0648 \\u0648\\u0632\\u0646 \\u062b\\u0628\\u062a \\u0645\\u06cc\\u200c\\u06af\\u0631\\u062f\\u062f.\",\"en\":\"At your first visit, blood tests, blood group, Rh and infection screening are done. An early ultrasound may be advised to confirm the pregnancy location.\"}','{\"fa\":[{\"question\":\"\\u062a\\u0647\\u0648\\u0639 \\u0635\\u0628\\u062d\\u06af\\u0627\\u0647\\u06cc \\u0686\\u0642\\u062f\\u0631 \\u0637\\u0648\\u0644 \\u0645\\u06cc\\u200c\\u06a9\\u0634\\u062f\\u061f\",\"answer\":\"\\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062a\\u0647\\u0648\\u0639 \\u0627\\u0632 \\u0647\\u0641\\u062a\\u0647 \\u06f5 \\u0634\\u0631\\u0648\\u0639 \\u0648 \\u062a\\u0627 \\u062d\\u062f\\u0648\\u062f \\u0647\\u0641\\u062a\\u0647 \\u06f1\\u06f2 \\u062a\\u0627 \\u06f1\\u06f4 \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u06cc\\u0627\\u0628\\u062f\\u060c \\u0627\\u0645\\u0627 \\u062f\\u0631 \\u0647\\u0631 \\u0641\\u0631\\u062f \\u0645\\u062a\\u0641\\u0627\\u0648\\u062a \\u0627\\u0633\\u062a.\"},{\"question\":\"\\u0622\\u06cc\\u0627 \\u062a\\u0647\\u0648\\u0639 \\u0646\\u0634\\u0627\\u0646\\u0647 \\u0633\\u0644\\u0627\\u0645\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u062a\\u0647\\u0648\\u0639 \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a \\u0627\\u0645\\u0627 \\u0646\\u0628\\u0648\\u062f \\u0622\\u0646 \\u0647\\u0645 \\u0646\\u06af\\u0631\\u0627\\u0646\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0646\\u06cc\\u0633\\u062a\\u061b \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u062a\\u0647\\u0648\\u0639 \\u0634\\u062f\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0641\\u0631\\u0627\\u063a \\u0645\\u06a9\\u0631\\u0631 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"How long does morning sickness last?\",\"answer\":\"Nausea usually starts around week five and eases by weeks 12 to 14, though it varies for each person.\"},{\"question\":\"Is nausea a sign of a healthy pregnancy?\",\"answer\":\"Nausea is common, but its absence is not worrying; see a doctor if vomiting is severe.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(6,6,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0634\\u0634\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0639\\u062f\\u0633 \\u0648 \\u062d\\u062f\\u0648\\u062f \\u06f5 \\u0645\\u06cc\\u0644\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u06a9\\u0648\\u0686\\u06a9 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0642\\u0627\\u0628\\u0644 \\u062a\\u0634\\u062e\\u06cc\\u0635 \\u0627\\u0633\\u062a \\u0648 \\u062c\\u0648\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062f\\u0633\\u062a \\u0648 \\u067e\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0638\\u0627\\u0647\\u0631 \\u0634\\u062f\\u0646 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0686\\u0647\\u0631\\u0647 \\u0648 \\u0633\\u0627\\u062e\\u062a\\u0627\\u0631 \\u0645\\u063a\\u0632 \\u0646\\u06cc\\u0632 \\u0628\\u0647\\u200c\\u062a\\u062f\\u0631\\u06cc\\u062c \\u0634\\u06a9\\u0644 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u062f.\",\"en\":\"At week six the embryo is about the size of a lentil, roughly 5 mm. The tiny heartbeat is now detectable and limb buds are appearing, while the face and brain structures gradually take shape.\"}','{\"fa\":\"\\u062a\\u0647\\u0648\\u0639\\u060c \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0648 \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u0628\\u0647 \\u0628\\u0648\\u0647\\u0627 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0634\\u062f\\u06cc\\u062f\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062a\\u06a9\\u0631\\u0631 \\u0627\\u062f\\u0631\\u0627\\u0631 \\u0648 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f. \\u0628\\u0631\\u062e\\u06cc \\u0632\\u0646\\u0627\\u0646 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0628\\u0632\\u0627\\u0642 \\u06cc\\u0627 \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u062f\\u0631 \\u0630\\u0627\\u0626\\u0642\\u0647 \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f.\",\"en\":\"Nausea, fatigue and sensitivity to smells may intensify. Frequent urination and mood changes continue, and some women notice more saliva or altered taste.\"}','{\"fa\":\"\\u0628\\u0647 \\u0645\\u0635\\u0631\\u0641 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u062e\\u0648\\u062f\\u062f\\u0631\\u0645\\u0627\\u0646\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0647\\u0648\\u0639 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u06af\\u0631\\u0633\\u0646\\u06af\\u06cc \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u062e\\u0648\\u062f\\u062f\\u0627\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u06cc\\u0627 \\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f \\u0641\\u0648\\u0631\\u0627\\u064b \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062a\\u0645\\u0627\\u0633 \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\",\"en\":\"Continue supplements and avoid self-medicating for nausea. Drink enough water and don\\u2019t stay hungry long; contact your doctor immediately for bleeding or severe pain.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0627\\u0648\\u0644 \\u0631\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0647\\u0645\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0642\\u062f\\u0627\\u0645 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u062e\\u0633\\u062a\\u06af\\u06cc\\u060c \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0631 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0628\\u06af\\u0646\\u062c\\u0627\\u0646\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u06cc\\u0627\\u062f\\u062f\\u0627\\u0634\\u062a \\u06a9\\u0646\\u06cc\\u062f \\u062a\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062f\\u0631 \\u0645\\u06cc\\u0627\\u0646 \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f.\",\"en\":\"If you haven\\u2019t had your first visit, arrange it this week. Build in more rest to manage fatigue and note your symptoms to share with your doctor.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0628\\u0632\\u0631\\u06af \\u0634\\u062f\\u0646 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0633\\u0646\\u06af\\u06cc\\u0646\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u062f\\u0631 \\u0646\\u0627\\u062d\\u06cc\\u0647 \\u0644\\u06af\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u06af\\u0631\\u062f\\u0634 \\u062e\\u0648\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u0634\\u062a\\u06cc\\u0628\\u0627\\u0646\\u06cc \\u0627\\u0632 \\u062c\\u0646\\u06cc\\u0646 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0628\\u062e\\u0634\\u06cc \\u0627\\u0632 \\u0631\\u0648\\u0646\\u062f \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a.\",\"en\":\"The uterus is enlarging and you may feel mild heaviness in the pelvis. Your circulation adapts to support the baby, all part of the natural process.\"}','{\"fa\":\"\\u0646\\u0648\\u0633\\u0627\\u0646\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0648 \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u0639\\u0627\\u0637\\u0641\\u06cc \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0632\\u0648\\u062f\\u062a\\u0631 \\u062e\\u0633\\u062a\\u0647 \\u06cc\\u0627 \\u0632\\u0648\\u062f\\u0631\\u0646\\u062c \\u0634\\u0648\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648 \\u06af\\u0641\\u062a\\u06af\\u0648 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a\\u062a\\u0627\\u0646 \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"Mood swings and emotional sensitivity are common this week. You may tire or feel irritable more easily; rest and sharing your feelings help.\"}','{\"fa\":\"\\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u06a9\\u0631\\u0628\\u0648\\u0647\\u06cc\\u062f\\u0631\\u0627\\u062a \\u067e\\u06cc\\u0686\\u06cc\\u062f\\u0647 \\u0628\\u0647 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u062a\\u0647\\u0648\\u0639 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0632\\u0646\\u062c\\u0628\\u06cc\\u0644\\u060c \\u0644\\u06cc\\u0645\\u0648 \\u0648 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u062e\\u0646\\u06a9 \\u0645\\u0641\\u06cc\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0645\\u0635\\u0631\\u0641 \\u0622\\u0647\\u0646 \\u0648 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Small frequent meals with protein and complex carbs help control nausea. Ginger, lemon and cool fluids can help; keep taking iron and folic acid.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u062a\\u0648\\u0627\\u0646 \\u062f\\u0627\\u0631\\u06cc\\u062f\\u060c \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u06a9\\u0648\\u062a\\u0627\\u0647 \\u0648 \\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u062f\\u0631 \\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u067e\\u0631\\u062a\\u0647\\u0648\\u0639\\u060c \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0631\\u0627 \\u062f\\u0631 \\u0627\\u0648\\u0644\\u0648\\u06cc\\u062a \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f. \\u0628\\u0647 \\u0633\\u06cc\\u06af\\u0646\\u0627\\u0644\\u200c\\u0647\\u0627\\u06cc \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u0627\\u062d\\u062a\\u0631\\u0627\\u0645 \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f.\",\"en\":\"If you have energy, short walks and gentle stretching help. On nauseous days, prioritize rest and respect your body\\u2019s signals.\"}','{\"fa\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0627\\u0648\\u0627\\u06cc\\u0644 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0623\\u06cc\\u06cc\\u062f \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u0633\\u0646 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0634\\u0648\\u062f. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634\\u200c\\u0647\\u0627\\u06cc \\u062e\\u0648\\u0646 \\u067e\\u0627\\u06cc\\u0647 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u0634\\u062f\\u0646 \\u062a\\u06a9\\u0645\\u06cc\\u0644 \\u0645\\u06cc\\u200c\\u06af\\u0631\\u062f\\u062f. \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0648 \\u0648\\u0632\\u0646 \\u067e\\u06cc\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"An early ultrasound may be done to confirm the fetal heartbeat and gestational age. Baseline blood tests are completed if not done yet.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0634\\u0646\\u06cc\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061f\",\"answer\":\"\\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0627\\u0632 \\u0647\\u0641\\u062a\\u0647 \\u06f6 \\u062f\\u0631 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0642\\u0627\\u0628\\u0644 \\u0645\\u0634\\u0627\\u0647\\u062f\\u0647 \\u0627\\u0633\\u062a\\u060c \\u0647\\u0631\\u0686\\u0646\\u062f \\u06af\\u0627\\u0647\\u06cc \\u06a9\\u0645\\u06cc \\u062f\\u06cc\\u0631\\u062a\\u0631 \\u062f\\u06cc\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0628\\u0631\\u0627\\u06cc \\u062a\\u0647\\u0648\\u0639 \\u0634\\u062f\\u06cc\\u062f \\u0686\\u0647 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9\\u060c \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u0648 \\u0632\\u0646\\u062c\\u0628\\u06cc\\u0644 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u061b \\u0627\\u06af\\u0631 \\u0627\\u0633\\u062a\\u0641\\u0631\\u0627\\u063a \\u0645\\u0627\\u0646\\u0639 \\u0646\\u0648\\u0634\\u06cc\\u062f\\u0646 \\u0622\\u0628 \\u0634\\u062f\\u060c \\u062d\\u062a\\u0645\\u0627\\u064b \\u0628\\u0647 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"When is the fetal heartbeat detectable?\",\"answer\":\"A heartbeat is usually visible on ultrasound from week six, though sometimes slightly later.\"},{\"question\":\"What should I do for severe nausea?\",\"answer\":\"Small meals, enough fluids and ginger help; if vomiting stops you from drinking, see your doctor.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(7,7,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0647\\u0641\\u062a\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0628\\u0644\\u0648\\u0628\\u0631\\u06cc \\u0648 \\u062d\\u062f\\u0648\\u062f \\u06f1 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0633\\u0631 \\u0646\\u0633\\u0628\\u062a \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u0628\\u0632\\u0631\\u06af\\u200c\\u062a\\u0631 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u063a\\u0632 \\u0628\\u0647 \\u0633\\u0631\\u0639\\u062a \\u0631\\u0634\\u062f \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062f\\u0633\\u062a\\u200c\\u0647\\u0627 \\u0648 \\u067e\\u0627\\u0647\\u0627 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u06a9\\u0644 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u0646\\u062f \\u0648 \\u06a9\\u0644\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f.\",\"en\":\"At week seven the embryo is about the size of a blueberry, roughly 1 cm. The head is large relative to the body as the brain grows rapidly, and arms, legs and kidneys develop further.\"}','{\"fa\":\"\\u062a\\u0647\\u0648\\u0639 \\u0648 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u0633\\u06cc\\u0646\\u0647 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u0628\\u0631\\u062e\\u06cc \\u0632\\u0646\\u0627\\u0646 \\u0644\\u06a9\\u0647\\u200c\\u0628\\u06cc\\u0646\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u06cc\\u0627 \\u0646\\u0641\\u062e \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f. \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u067e\\u0648\\u0633\\u062a\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0646\\u06cc\\u0632 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0638\\u0627\\u0647\\u0631 \\u0634\\u0648\\u062f.\",\"en\":\"Nausea and fatigue continue and breast tenderness may increase. Some women notice light spotting or bloating, and mild skin changes can appear.\"}','{\"fa\":\"\\u0628\\u0647 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u0635\\u0631\\u0641 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u067e\\u0627\\u06cc\\u0628\\u0646\\u062f \\u0628\\u0645\\u0627\\u0646\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u062e\\u0627\\u0645 \\u0648 \\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u062e\\u0648\\u062f\\u062f\\u0627\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u063a\\u06cc\\u0631\\u0639\\u0627\\u062f\\u06cc \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0637\\u0631\\u062d \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Stick to healthy eating and supplements, and avoid raw foods and excess caffeine. Rest enough, avoid heavy activity, and report unusual symptoms.\"}','{\"fa\":\"\\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0633\\u0648\\u0627\\u0644\\u0627\\u062a \\u062e\\u0648\\u062f \\u0631\\u0627 \\u06cc\\u0627\\u062f\\u062f\\u0627\\u0634\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u062a\\u0647\\u0648\\u0639 \\u0648 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0645\\u0635\\u0631\\u0641 \\u0622\\u0628 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\",\"en\":\"Keep up regular prenatal visits and note your questions. Plan to manage nausea and fatigue, and take hydration and rest seriously.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u062f\\u0648 \\u0628\\u0631\\u0627\\u0628\\u0631 \\u062d\\u0627\\u0644\\u062a \\u0639\\u0627\\u062f\\u06cc \\u0628\\u0632\\u0631\\u06af \\u0634\\u062f\\u0647 \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u06cc \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0641\\u0634\\u0627\\u0631 \\u062f\\u0631 \\u0634\\u06a9\\u0645 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u062f\\u0646 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u0648\\u0644\\u06cc\\u062f \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u062e\\u0648\\u0646 \\u0648 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0627\\u0633\\u062a. \\u0627\\u06cc\\u0646 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631\\u06cc\\u200c\\u0647\\u0627 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"The uterus has roughly doubled in size and you may feel mild abdominal pressure. Your body is producing more blood and fluids as it adapts.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a \\u0634\\u062f\\u06cc\\u062f \\u0648 \\u0646\\u0648\\u0633\\u0627\\u0646\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u06a9\\u0647 \\u0646\\u0627\\u0634\\u06cc \\u0627\\u0632 \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u200c\\u0647\\u0627\\u0633\\u062a. \\u06a9\\u0645\\u06cc \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u0633\\u0644\\u0627\\u0645\\u062a \\u0631\\u0648\\u0627\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u062c\\u0633\\u0645 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"You may feel intense emotions and mood swings driven by hormones. Some worry about the pregnancy is normal; mental care matters as much as physical.\"}','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u063a\\u0644\\u0627\\u062a \\u06a9\\u0627\\u0645\\u0644 \\u0648 \\u0645\\u06cc\\u0648\\u0647\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u062f\\u0631 \\u0637\\u0648\\u0644 \\u0631\\u0648\\u0632 \\u067e\\u062e\\u0634 \\u06a9\\u0646\\u06cc\\u062f \\u062a\\u0627 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u067e\\u0627\\u06cc\\u062f\\u0627\\u0631 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0622\\u0647\\u0646 \\u0648 \\u0641\\u0648\\u0644\\u0627\\u062a \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0645\\u0647\\u0645 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u06a9\\u0645\\u200c\\u0622\\u0628\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"Spread protein, whole grains and fruit through the day for steady energy. Iron and folate remain important; drink enough fluids to prevent dehydration.\"}','{\"fa\":\"\\u0648\\u0631\\u0632\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0645\\u0627\\u0646\\u0646\\u062f \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u067e\\u0631\\u0641\\u0634\\u0627\\u0631 \\u0648 \\u0628\\u0644\\u0646\\u062f \\u06a9\\u0631\\u062f\\u0646 \\u0627\\u062c\\u0633\\u0627\\u0645 \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0633\\u0631\\u06af\\u06cc\\u062c\\u0647 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0631\\u0627 \\u0645\\u062a\\u0648\\u0642\\u0641 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Gentle exercise like walking and prenatal yoga eases fatigue. Avoid high-impact moves and heavy lifting, and stop if you feel dizzy.\"}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u067e\\u06cc\\u06af\\u06cc\\u0631\\u06cc \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u0648 \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u067e\\u0632\\u0634\\u06a9 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0648\\u062c\\u0648\\u062f \\u0631\\u06cc\\u0633\\u06a9\\u060c \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u06a9\\u0646\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"This week usually involves follow-up on initial tests and a doctor visit. If there is risk, an ultrasound may be advised; report any warning signs.\"}','{\"fa\":[{\"question\":\"\\u0646\\u0641\\u062e \\u0648 \\u0644\\u06a9\\u0647\\u200c\\u0628\\u06cc\\u0646\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0646\\u0641\\u062e \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a \\u0648 \\u0644\\u06a9\\u0647\\u200c\\u0628\\u06cc\\u0646\\u06cc \\u062e\\u06cc\\u0644\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0628\\u0627\\u0634\\u062f\\u060c \\u0627\\u0645\\u0627 \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u062f\\u0631\\u062f \\u0628\\u0627\\u06cc\\u062f \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0686\\u0637\\u0648\\u0631 \\u0628\\u0627 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u06a9\\u0646\\u0627\\u0631 \\u0628\\u06cc\\u0627\\u06cc\\u0645\\u061f\",\"answer\":\"\\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0648\\u062a\\u0627\\u0647 \\u062f\\u0631 \\u0637\\u0648\\u0644 \\u0631\\u0648\\u0632\\u060c \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0634\\u0628\\u0627\\u0646\\u0647 \\u0648 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0628\\u0647 \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u062e\\u0633\\u062a\\u06af\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"}],\"en\":[{\"question\":\"Are bloating and light spotting normal?\",\"answer\":\"Bloating is common and very light spotting can be normal, but bleeding with pain should be checked.\"},{\"question\":\"How can I cope with fatigue?\",\"answer\":\"Short daytime rests, enough night sleep and balanced meals help manage tiredness.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(8,8,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0647\\u0634\\u062a\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0644\\u0648\\u0628\\u06cc\\u0627 \\u0642\\u0631\\u0645\\u0632\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f1.\\u06f6 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u06a9\\u0645\\u062a\\u0631 \\u0627\\u0632 \\u06f1 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u0646\\u06af\\u0634\\u062a\\u0627\\u0646 \\u062f\\u0633\\u062a \\u0648 \\u067e\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0634\\u06a9\\u0644\\u200c\\u06af\\u06cc\\u0631\\u06cc\\u200c\\u0627\\u0646\\u062f \\u0648 \\u067e\\u0644\\u06a9\\u200c\\u0647\\u0627 \\u0648 \\u0644\\u0628 \\u0628\\u0627\\u0644\\u0627\\u06cc\\u06cc \\u0646\\u0645\\u0627\\u06cc\\u0627\\u0646 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u06a9\\u0648\\u0686\\u06a9 \\u062c\\u0646\\u06cc\\u0646 \\u0622\\u063a\\u0627\\u0632 \\u0634\\u062f\\u0647 \\u0627\\u0645\\u0627 \\u0647\\u0646\\u0648\\u0632 \\u062d\\u0633 \\u0646\\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"At week eight the fetus is about the size of a kidney bean, roughly 1.6 cm and under 1 g. Fingers and toes are forming, eyelids and the upper lip appear, and tiny movements begin though unfelt.\"}','{\"fa\":\"\\u062a\\u0647\\u0648\\u0639\\u060c \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0648 \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u0633\\u06cc\\u0646\\u0647 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0647 \\u0627\\u0648\\u062c \\u062e\\u0648\\u062f \\u0628\\u0631\\u0633\\u062f. \\u06a9\\u0645\\u0631 \\u0634\\u0644\\u0648\\u0627\\u0631\\u0647\\u0627 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u06cc \\u062a\\u0646\\u06af\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f\\u060c \\u0647\\u0631\\u0686\\u0646\\u062f \\u0634\\u06a9\\u0645 \\u0647\\u0646\\u0648\\u0632 \\u0628\\u0631\\u062c\\u0633\\u062a\\u0647 \\u0646\\u06cc\\u0633\\u062a. \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"Nausea, fatigue and breast tenderness may peak. Your waistband may feel tighter although the belly isn\\u2019t showing yet, and mood changes continue.\"}','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0648 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0627\\u0644\\u06a9\\u0644\\u060c \\u0633\\u06cc\\u06af\\u0627\\u0631 \\u0648 \\u06a9\\u0627\\u0641\\u0626\\u06cc\\u0646 \\u0632\\u06cc\\u0627\\u062f \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0647\\u0648\\u0639 \\u062f\\u0627\\u0631\\u0648 \\u062e\\u0648\\u062f\\u0633\\u0631\\u0627\\u0646\\u0647 \\u0645\\u0635\\u0631\\u0641 \\u0646\\u06a9\\u0646\\u06cc\\u062f. \\u062e\\u0648\\u0627\\u0628 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Maintain supplements and healthy eating, and avoid alcohol, smoking and excess caffeine. Don\\u2019t self-medicate for nausea, and get enough sleep and rest.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u0647\\u0646\\u0648\\u0632 \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0631\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u062f\\u0648\\u0631\\u0647 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0646\\u0627\\u0633\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0623\\u06cc\\u06cc\\u062f \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0648 \\u0633\\u0646 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0633\\u0648\\u0627\\u0644\\u0627\\u062a \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0645\\u0635\\u0631\\u0641 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\",\"en\":\"If you haven\\u2019t had your first ultrasound, this is a good time to confirm the pregnancy and gestational age. Prepare questions for your visit and stay hydrated.\"}','{\"fa\":\"\\u062d\\u062c\\u0645 \\u062e\\u0648\\u0646 \\u0648 \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u0634\\u0645\\u0627 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u06cc\\u0627\\u0641\\u062a\\u0647 \\u062a\\u0627 \\u0646\\u06cc\\u0627\\u0632 \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062a\\u0623\\u0645\\u06cc\\u0646 \\u06a9\\u0646\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u062d\\u0633\\u0627\\u0633 \\u06af\\u0631\\u0645\\u0627\\u0632\\u062f\\u06af\\u06cc \\u06cc\\u0627 \\u0633\\u0631\\u06af\\u06cc\\u062c\\u0647 \\u06af\\u0627\\u0647\\u200c\\u0628\\u0647\\u200c\\u06af\\u0627\\u0647 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u0622\\u0631\\u0627\\u0645\\u06cc \\u0628\\u0627 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0645\\u0627\\u0647\\u0646\\u06af \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"Your blood volume and heart rate rise to meet the baby\\u2019s needs. You may occasionally feel warm or dizzy as your body steadily adapts.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u06cc\\u0646 \\u0634\\u0627\\u062f\\u06cc \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0646\\u0648\\u0633\\u0627\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u06af\\u0627\\u0647\\u06cc \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0622\\u0633\\u06cc\\u0628\\u200c\\u067e\\u0630\\u06cc\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u06cc\\u0646 \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a \\u0628\\u0627 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u0645\\u0631\\u062a\\u0628\\u0637 \\u0627\\u0633\\u062a. \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0639\\u0627\\u0637\\u0641\\u06cc \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"You may swing between joy and anxiety and sometimes feel vulnerable. These feelings link to hormonal shifts; emotional support and rest help.\"}','{\"fa\":\"\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0622\\u0647\\u0646 \\u0631\\u0627 \\u062f\\u0631 \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627 \\u0628\\u06af\\u0646\\u062c\\u0627\\u0646\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0628\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0645\\u06cc\\u0648\\u0647\\u200c\\u0647\\u0627 \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u062a\\u0627\\u0632\\u0647 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u0647\\u0645 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0628\\u0633\\u06cc\\u0627\\u0631 \\u0686\\u0631\\u0628 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Include protein, calcium and iron in meals and eat light, frequent portions. Fresh fruit, vegetables and enough water matter; avoid very greasy foods.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0627\\u0633\\u062a. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0634\\u062f\\u06cc\\u062f \\u0648 \\u067e\\u0631\\u062e\\u0637\\u0631 \\u062e\\u0648\\u062f\\u062f\\u0627\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u06af\\u0631 \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0636\\u0639\\u0641 \\u06a9\\u0631\\u062f\\u06cc\\u062f \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Gentle walking and pelvic floor exercises suit this week. Avoid intense or risky activities and rest if you feel weak.\"}','{\"fa\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0639\\u06cc\\u06cc\\u0646 \\u0633\\u0646 \\u062f\\u0642\\u06cc\\u0642 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0648 \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u062f\\u0648\\u0631\\u0647 \\u0631\\u0627\\u06cc\\u062c \\u0627\\u0633\\u062a. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634\\u200c\\u0647\\u0627\\u06cc \\u062e\\u0648\\u0646 \\u062a\\u06a9\\u0645\\u06cc\\u0644\\u06cc \\u0646\\u06cc\\u0632 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0634\\u0648\\u062f. \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0648 \\u0648\\u0632\\u0646 \\u062b\\u0628\\u062a \\u0645\\u06cc\\u200c\\u06af\\u0631\\u062f\\u062f.\",\"en\":\"An early dating ultrasound to set gestational age and confirm the heartbeat is common now. Additional blood tests may be done, and vitals are recorded.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0631\\u0627 \\u0647\\u0646\\u0648\\u0632 \\u0634\\u06a9\\u0645\\u0645 \\u0628\\u0631\\u062c\\u0633\\u062a\\u0647 \\u0646\\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0647\\u0634\\u062a\\u0645 \\u0631\\u062d\\u0645 \\u0647\\u0646\\u0648\\u0632 \\u06a9\\u0648\\u0686\\u06a9 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0634\\u06a9\\u0645 \\u062a\\u0627 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0639\\u062f \\u0627\\u0632 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0628\\u0631\\u062c\\u0633\\u062a\\u0647 \\u0646\\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0622\\u06cc\\u0627 \\u0645\\u0635\\u0631\\u0641 \\u062f\\u0627\\u0631\\u0648 \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0631\\u062f\\u0631\\u062f \\u0628\\u06cc\\u200c\\u062e\\u0637\\u0631 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0631\\u062e\\u06cc \\u062f\\u0627\\u0631\\u0648\\u0647\\u0627 \\u062f\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0645\\u062c\\u0627\\u0632 \\u0646\\u06cc\\u0633\\u062a\\u0646\\u062f\\u061b \\u0628\\u0631\\u0627\\u06cc \\u0647\\u0631 \\u062f\\u0627\\u0631\\u0648\\u06cc\\u06cc \\u062d\\u062a\\u06cc \\u0645\\u0633\\u06a9\\u0646 \\u0633\\u0627\\u062f\\u0647 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"Why isn\\u2019t my belly showing yet?\",\"answer\":\"At week eight the uterus is still small, and a visible bump usually appears after the first trimester.\"},{\"question\":\"Is it safe to take medicine for a headache?\",\"answer\":\"Some drugs are unsafe in pregnancy; check with your doctor before any medicine, even a simple painkiller.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(9,9,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0646\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0627\\u0646\\u06af\\u0648\\u0631\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f2.\\u06f3 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f2 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627\\u06cc \\u0627\\u0635\\u0644\\u06cc \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0634\\u06a9\\u0644\\u200c\\u06af\\u06cc\\u0631\\u06cc\\u200c\\u0627\\u0646\\u062f \\u0648 \\u062f\\u0645 \\u062c\\u0646\\u06cc\\u0646\\u06cc \\u0646\\u0627\\u067e\\u062f\\u06cc\\u062f \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0639\\u0636\\u0644\\u0627\\u062a \\u06a9\\u0648\\u0686\\u06a9 \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f \\u0648 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0638\\u0631\\u06cc\\u0641 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"At week nine the fetus is about the size of a grape, roughly 2.3 cm and nearly 2 g. Major organs are forming, the embryonic tail disappears, and small muscles begin to work.\"}','{\"fa\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0645\\u0627\\u0646\\u0646\\u062f \\u062a\\u0647\\u0648\\u0639 \\u0648 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u067e\\u0648\\u0633\\u062a\\u06cc \\u0648 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u062c\\u0632\\u0626\\u06cc \\u0648\\u0632\\u0646 \\u0631\\u0627 \\u0645\\u062a\\u0648\\u062c\\u0647 \\u0634\\u0648\\u06cc\\u062f. \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u0639\\u0627\\u0637\\u0641\\u06cc \\u0646\\u06cc\\u0632 \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a.\",\"en\":\"First-trimester symptoms like nausea and fatigue continue. You may notice skin changes and a slight weight gain, and emotional sensitivity is common.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0627\\u0633\\u062a\\u0631\\u0633 \\u0648 \\u06a9\\u0645\\u200c\\u062e\\u0648\\u0627\\u0628\\u06cc \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0627\\u0632 \\u0642\\u0631\\u0627\\u0631 \\u06af\\u0631\\u0641\\u062a\\u0646 \\u062f\\u0631 \\u0645\\u0639\\u0631\\u0636 \\u0645\\u0648\\u0627\\u062f \\u0634\\u06cc\\u0645\\u06cc\\u0627\\u06cc\\u06cc \\u062e\\u0627\\u0646\\u06af\\u06cc \\u0645\\u0636\\u0631 \\u062f\\u0648\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0646\\u06af\\u0631\\u0627\\u0646\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062f\\u0631 \\u0645\\u06cc\\u0627\\u0646 \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements, and avoid stress and sleep loss. Stay away from harmful household chemicals and report worrying symptoms.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u067e\\u06cc\\u0634 \\u0631\\u0648 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0645\\u0635\\u0631\\u0641 \\u0622\\u0628 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep regular visits and discuss upcoming screenings with your doctor. Have a plan to manage first-trimester symptoms, and maintain hydration and rest.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0628\\u0632\\u0631\\u06af \\u0634\\u062f\\u0646 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0646\\u0641\\u062e \\u06cc\\u0627 \\u0633\\u0646\\u06af\\u06cc\\u0646\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u06af\\u0648\\u0627\\u0631\\u0634 \\u06a9\\u0646\\u062f\\u062a\\u0631 \\u0639\\u0645\\u0644 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u06a9\\u0647 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0639\\u062b \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0634\\u0648\\u062f. \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0637\\u0628\\u06cc\\u0639\\u06cc\\u200c\\u0627\\u0646\\u062f.\",\"en\":\"The uterus is enlarging and you may feel bloated or heavy. Digestion slows, which can cause constipation; these changes are normal.\"}','{\"fa\":\"\\u0646\\u0648\\u0633\\u0627\\u0646\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0648 \\u06af\\u0627\\u0647\\u06cc \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0641\\u0631\\u0633\\u0648\\u062f\\u06af\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0648\\u062c\\u0648\\u062f \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0646\\u0633\\u0628\\u062a \\u0628\\u0647 \\u0622\\u06cc\\u0646\\u062f\\u0647 \\u0647\\u0645 \\u0647\\u06cc\\u062c\\u0627\\u0646\\u200c\\u0632\\u062f\\u0647 \\u0648 \\u0647\\u0645 \\u0646\\u06af\\u0631\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u06af\\u0641\\u062a\\u06af\\u0648 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0628\\u0647 \\u062a\\u0639\\u0627\\u062f\\u0644 \\u0631\\u0648\\u0627\\u0646\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"Mood swings and occasional exhaustion may occur. You might feel both excited and anxious about the future; talking and rest support balance.\"}','{\"fa\":\"\\u0641\\u06cc\\u0628\\u0631 \\u06a9\\u0627\\u0641\\u06cc \\u0627\\u0632 \\u0645\\u06cc\\u0648\\u0647\\u060c \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0648 \\u063a\\u0644\\u0627\\u062a \\u06a9\\u0627\\u0645\\u0644 \\u0628\\u0647 \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0622\\u0647\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u0641\\u0631\\u0627\\u0648\\u0627\\u0646 \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0641\\u0631\\u0622\\u0648\\u0631\\u06cc\\u200c\\u0634\\u062f\\u0647 \\u0628\\u06a9\\u0627\\u0647\\u06cc\\u062f.\",\"en\":\"Enough fiber from fruit, vegetables and whole grains helps prevent constipation. Keep up protein and iron, drink plenty of water, and cut processed foods.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0631\\u0648\\u0632\\u0627\\u0646\\u0647 \\u0648 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u06a9\\u0634\\u0634\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0647 \\u06af\\u0648\\u0627\\u0631\\u0634 \\u0648 \\u062e\\u0644\\u0642\\u200c\\u0648\\u062e\\u0648 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u067e\\u0631\\u0641\\u0634\\u0627\\u0631 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0631\\u0627 \\u0628\\u0627 \\u062a\\u0648\\u062c\\u0647 \\u0628\\u0647 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u062e\\u0648\\u062f \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Daily walking and gentle stretching aid digestion and mood. Avoid high-impact workouts and adjust activity to your energy level.\"}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u067e\\u06cc\\u06af\\u06cc\\u0631\\u06cc \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f \\u0648 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u062a\\u0648\\u0636\\u06cc\\u062d \\u062f\\u0647\\u062f. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634\\u200c\\u0647\\u0627\\u06cc \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0646\\u06cc\\u0627\\u0632 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u062e\\u0648\\u062f \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits continue and your doctor may explain first-trimester screening. Routine tests are done as needed; report your symptoms.\"}','{\"fa\":[{\"question\":\"\\u0628\\u0631\\u0627\\u06cc \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0686\\u0647 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0645\\u0635\\u0631\\u0641 \\u0641\\u06cc\\u0628\\u0631\\u060c \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0648 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u061b \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u062a\\u062f\\u0627\\u0648\\u0645 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\\u06cc\\u062f.\"},{\"question\":\"\\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0645\\u062c\\u0645\\u0648\\u0639\\u0647\\u200c\\u0627\\u06cc \\u0627\\u0632 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u0648 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0628\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u06f1\\u06f1 \\u062a\\u0627 \\u06f1\\u06f3 \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0631\\u0632\\u06cc\\u0627\\u0628\\u06cc \\u0633\\u0644\\u0627\\u0645\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"What helps pregnancy constipation?\",\"answer\":\"Fiber, enough water and gentle activity help; if it persists, consult your doctor.\"},{\"question\":\"What is first-trimester screening?\",\"answer\":\"It is a set of blood tests and an ultrasound, usually done between weeks 11 and 13 to assess the baby\\u2019s health.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(10,10,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u062a\\u0648\\u062a\\u200c\\u0641\\u0631\\u0646\\u06af\\u06cc\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f3.\\u06f1 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f4 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0631\\u0633\\u0645\\u0627\\u064b \\u0648\\u0627\\u0631\\u062f \\u0645\\u0631\\u062d\\u0644\\u0647 \\u062c\\u0646\\u06cc\\u0646\\u06cc (fetus) \\u0634\\u062f\\u0647 \\u0648 \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627\\u06cc \\u062d\\u06cc\\u0627\\u062a\\u06cc \\u0627\\u0635\\u0644\\u06cc \\u0634\\u06a9\\u0644 \\u06af\\u0631\\u0641\\u062a\\u0647\\u200c\\u0627\\u0646\\u062f. \\u0646\\u0627\\u062e\\u0646\\u200c\\u0647\\u0627 \\u0648 \\u062c\\u0648\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062f\\u0646\\u062f\\u0627\\u0646 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0631\\u0634\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"At week ten the fetus is about the size of a strawberry, roughly 3.1 cm and nearly 4 g. It has officially entered the fetal stage with vital organs formed, and nails and tooth buds are developing.\"}','{\"fa\":\"\\u062a\\u0647\\u0648\\u0639 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u0646\\u0648\\u0632 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u062f \\u0627\\u0645\\u0627 \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u0628\\u0647\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0631\\u06af\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0648\\u0633\\u062a\\u06cc \\u0628\\u0631\\u062c\\u0633\\u062a\\u0647\\u200c\\u062a\\u0631 \\u0648 \\u0633\\u06cc\\u0646\\u0647\\u200c\\u0647\\u0627 \\u0628\\u0632\\u0631\\u06af\\u200c\\u062a\\u0631 \\u0634\\u0648\\u0646\\u062f. \\u06a9\\u0645\\u0631 \\u0644\\u0628\\u0627\\u0633\\u200c\\u0647\\u0627 \\u06a9\\u0645\\u06cc \\u062a\\u0646\\u06af\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"Nausea may still linger but should soon ease. Skin veins may become more visible and breasts larger, and your clothes may feel a bit tighter.\"}','{\"fa\":\"\\u0645\\u0635\\u0631\\u0641 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0648 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0645\\u0631\\u0627\\u0642\\u0628 \\u0628\\u0647\\u062f\\u0627\\u0634\\u062a \\u062f\\u0647\\u0627\\u0646 \\u0648 \\u062f\\u0646\\u062f\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u06cc\\u0627 \\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f \\u0641\\u0648\\u0631\\u0627\\u064b \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062a\\u0645\\u0627\\u0633 \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\",\"en\":\"Continue supplements and balanced nutrition, and avoid risky activities. Take care of dental hygiene, and contact your doctor at once for bleeding or severe pain.\"}','{\"fa\":\"\\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0632\\u0645\\u0627\\u0646 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0647\\u0645\\u0627\\u0647\\u0646\\u06af \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u062b\\u0628\\u062a \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u067e\\u06cc\\u0634 \\u0631\\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0648\\u06cc\\u062f.\",\"en\":\"Coordinate the timing of first-trimester screening with your doctor. Keep regular visits and symptom tracking, and prepare for the upcoming ultrasound.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06af\\u0631\\u06cc\\u067e\\u200c\\u0641\\u0631\\u0648\\u062a \\u0634\\u062f\\u0647 \\u0648 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0627\\u0632 \\u0644\\u06af\\u0646 \\u0628\\u0627\\u0644\\u0627\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0622\\u06cc\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06af\\u0627\\u0647\\u06cc \\u062f\\u0631\\u062f \\u0631\\u0628\\u0627\\u0637 \\u06af\\u0631\\u062f \\u0631\\u0627 \\u062f\\u0631 \\u067e\\u0647\\u0644\\u0648\\u0647\\u0627 \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u062e\\u0648\\u0628\\u06cc \\u0628\\u0627 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus is now grapefruit-sized and rising above the pelvis. You may sometimes feel round ligament twinges in your sides as your body adapts well.\"}','{\"fa\":\"\\u0628\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0634\\u062f\\u0646 \\u0628\\u0647 \\u067e\\u0627\\u06cc\\u0627\\u0646 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u06cc \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0627 \\u0627\\u06cc\\u0646 \\u062d\\u0627\\u0644 \\u0646\\u0648\\u0633\\u0627\\u0646\\u0627\\u062a \\u062e\\u0644\\u0642\\u06cc \\u0647\\u0646\\u0648\\u0632 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"As the first trimester nears its end you may feel a bit more settled. Still, mood swings remain normal; keep up self-care and rest.\"}','{\"fa\":\"\\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u0622\\u0647\\u0646\\u060c \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u067e\\u0627\\u06cc\\u0647 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0644\\u0628\\u0646\\u06cc\\u0627\\u062a \\u06a9\\u0645\\u200c\\u0686\\u0631\\u0628\\u060c \\u062d\\u0628\\u0648\\u0628\\u0627\\u062a \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0628\\u0631\\u06af\\u200c\\u0633\\u0628\\u0632 \\u0631\\u0627 \\u0628\\u06af\\u0646\\u062c\\u0627\\u0646\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0648 \\u0645\\u06cc\\u0627\\u0646\\u200c\\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Calcium, iron, folic acid and protein remain the nutritional base. Include low-fat dairy, legumes and leafy greens, with enough water and healthy snacks.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u06af\\u0632\\u06cc\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u062e\\u0648\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0634\\u0631\\u0648\\u0639 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0648 \\u0627\\u0641\\u062a\\u0627\\u062f\\u0646 \\u0627\\u062d\\u062a\\u0645\\u0627\\u0644\\u06cc \\u062f\\u0648\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga are good options this week. Begin pelvic floor exercises and avoid risky moves and possible falls.\"}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u062f\\u0648\\u0631\\u0647 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 NIPT (\\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0644\\u0648\\u0644\\u06cc) \\u0628\\u0647\\u200c\\u0639\\u0646\\u0648\\u0627\\u0646 \\u06af\\u0632\\u06cc\\u0646\\u0647 \\u063a\\u06cc\\u0631\\u062a\\u0647\\u0627\\u062c\\u0645\\u06cc \\u0645\\u0637\\u0631\\u062d \\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0648 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f. \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0622\\u062a\\u06cc \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"A non-invasive NIPT blood screen may be offered as an option now. Routine visits and blood-pressure checks continue; discuss upcoming screening with your doctor.\"}','{\"fa\":[{\"question\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 NIPT \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u06cc\\u06a9 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u063a\\u06cc\\u0631\\u062a\\u0647\\u0627\\u062c\\u0645\\u06cc \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u062e\\u0637\\u0631 \\u0628\\u0631\\u062e\\u06cc \\u0627\\u062e\\u062a\\u0644\\u0627\\u0644\\u0627\\u062a \\u06a9\\u0631\\u0648\\u0645\\u0648\\u0632\\u0648\\u0645\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0628\\u0627 \\u062f\\u0642\\u062a \\u0628\\u0627\\u0644\\u0627 \\u0627\\u0631\\u0632\\u06cc\\u0627\\u0628\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"},{\"question\":\"\\u062f\\u0631\\u062f \\u062e\\u0641\\u06cc\\u0641 \\u067e\\u0647\\u0644\\u0648 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u06a9\\u0634\\u06cc\\u062f\\u06af\\u06cc \\u0631\\u0628\\u0627\\u0637 \\u06af\\u0631\\u062f \\u0631\\u062d\\u0645 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062f\\u0631\\u062f \\u062e\\u0641\\u06cc\\u0641 \\u067e\\u0647\\u0644\\u0648 \\u0627\\u06cc\\u062c\\u0627\\u062f \\u06a9\\u0646\\u062f\\u061b \\u0627\\u0645\\u0627 \\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f \\u06cc\\u0627 \\u0645\\u062f\\u0627\\u0648\\u0645 \\u0628\\u0627\\u06cc\\u062f \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"What is the NIPT test?\",\"answer\":\"It is a non-invasive blood test that accurately assesses the risk of some chromosomal conditions.\"},{\"question\":\"Is mild side pain normal?\",\"answer\":\"Round ligament stretching can cause mild side pain, but severe or constant pain should be checked.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(11,11,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u06cc\\u0627\\u0632\\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0627\\u0646\\u062c\\u06cc\\u0631\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4.\\u06f1 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f7 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0633\\u0631 \\u0647\\u0646\\u0648\\u0632 \\u0628\\u0632\\u0631\\u06af \\u0627\\u0633\\u062a \\u0627\\u0645\\u0627 \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u0633\\u0631\\u0639\\u062a \\u0631\\u0634\\u062f \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u0627\\u0646\\u06af\\u0634\\u062a\\u0627\\u0646 \\u0627\\u0632 \\u0647\\u0645 \\u062c\\u062f\\u0627 \\u0634\\u062f\\u0647\\u200c\\u0627\\u0646\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u067e\\u0631\\u0627\\u06a9\\u0646\\u062f\\u0647 \\u0648 \\u0628\\u0627\\u0632 \\u0648 \\u0628\\u0633\\u062a\\u0647 \\u06a9\\u0631\\u062f\\u0646 \\u0645\\u0634\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"At week eleven the fetus is about the size of a fig, roughly 4.1 cm and nearly 7 g. The head is still large but the body grows fast, fingers separate, and the baby makes scattered movements.\"}','{\"fa\":\"\\u062a\\u0647\\u0648\\u0639 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0631\\u0648 \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u06af\\u0630\\u0627\\u0631\\u062f \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f. \\u0631\\u062d\\u0645 \\u0628\\u0647\\u200c\\u062a\\u062f\\u0631\\u06cc\\u062c \\u0628\\u0627\\u0644\\u0627\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0622\\u06cc\\u062f \\u0648 \\u0634\\u06a9\\u0645 \\u06a9\\u0645\\u06cc \\u067e\\u0631 \\u0628\\u0647 \\u0646\\u0638\\u0631 \\u0645\\u06cc\\u200c\\u0631\\u0633\\u062f. \\u0645\\u0648\\u0647\\u0627 \\u0648 \\u0646\\u0627\\u062e\\u0646\\u200c\\u0647\\u0627 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0633\\u0631\\u06cc\\u0639\\u200c\\u062a\\u0631 \\u0631\\u0634\\u062f \\u06a9\\u0646\\u0646\\u062f.\",\"en\":\"Nausea usually starts to ease and you may feel more energetic. The uterus rises gradually, the belly looks a little fuller, and hair and nails may grow faster.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0631\\u0698\\u06cc\\u0645\\u200c\\u0647\\u0627\\u06cc \\u0644\\u0627\\u063a\\u0631\\u06cc \\u062e\\u0648\\u062f\\u062f\\u0627\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and plan for first-trimester screening. Avoid weight-loss diets and keep up gentle activity.\"}','{\"fa\":\"\\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0622\\u063a\\u0627\\u0632 \\u0628\\u0627\\u0632\\u0647 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0627\\u0633\\u062a\\u061b \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc NT \\u0647\\u0645\\u0627\\u0647\\u0646\\u06af \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0633\\u0648\\u0627\\u0644\\u0627\\u062a \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0627\\u0632 \\u0642\\u0628\\u0644 \\u06cc\\u0627\\u062f\\u062f\\u0627\\u0634\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"This week begins the first-trimester screening window; arrange the NT scan with your doctor. Keep regular visits and note your questions in advance.\"}','{\"fa\":\"\\u062d\\u062c\\u0645 \\u062e\\u0648\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06af\\u0627\\u0647\\u06cc \\u0627\\u062d\\u0633\\u0627\\u0633 \\u06af\\u0631\\u0645\\u0627 \\u06cc\\u0627 \\u062a\\u0639\\u0631\\u06cc\\u0642 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u06a9\\u0646\\u06cc\\u062f. \\u0644\\u062b\\u0647\\u200c\\u0647\\u0627 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062d\\u0633\\u0627\\u0633\\u200c\\u062a\\u0631 \\u0634\\u0648\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u062e\\u0648\\u0628\\u06cc \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0628\\u0627 \\u0646\\u06cc\\u0627\\u0632\\u0647\\u0627\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0648\\u0641\\u0642 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f.\",\"en\":\"Blood volume has increased and you may feel warmer or sweat more. Gums can become more sensitive as your body adapts to the baby\\u2019s needs.\"}','{\"fa\":\"\\u0628\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u062a\\u0647\\u0648\\u0639 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0631\\u0648\\u062d\\u06cc\\u0647 \\u0628\\u0647\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0628\\u0647 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0645\\u06cc\\u062f\\u0648\\u0627\\u0631\\u062a\\u0631 \\u0634\\u0648\\u06cc\\u062f. \\u0628\\u0627 \\u0627\\u06cc\\u0646 \\u062d\\u0627\\u0644\\u060c \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0628\\u0631\\u0627\\u06cc \\u0646\\u062a\\u0627\\u06cc\\u062c \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u06a9\\u0645\\u06cc \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u200c\\u0622\\u0648\\u0631 \\u0628\\u0627\\u0634\\u062f. \\u0622\\u0631\\u0627\\u0645\\u0634 \\u062e\\u0648\\u062f \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"As nausea eases you may feel brighter and more hopeful. Still, waiting for screening results can bring some anxiety; try to stay calm.\"}','{\"fa\":\"\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0622\\u0647\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u06cc\\u062f \\u06a9\\u0627\\u0641\\u06cc \\u0627\\u0632 \\u0637\\u0631\\u06cc\\u0642 \\u0646\\u0645\\u06a9 \\u06cc\\u062f\\u062f\\u0627\\u0631 \\u0648 \\u0644\\u0628\\u0646\\u06cc\\u0627\\u062a \\u062f\\u0631\\u06cc\\u0627\\u0641\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0645\\u06cc\\u0648\\u0647 \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0631\\u0646\\u06af\\u0627\\u0631\\u0646\\u06af \\u0628\\u062e\\u0648\\u0631\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0627\\u0647\\u0645\\u06cc\\u062a \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"Continue protein, calcium and iron and get enough iodine from iodized salt and dairy. Eat colorful fruit and vegetables and stay well hydrated.\"}','{\"fa\":\"\\u0628\\u0627 \\u0628\\u0627\\u0632\\u06af\\u0634\\u062a \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u06cc\\u062f \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0645\\u0646\\u0638\\u0645\\u200c\\u062a\\u0631 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0631\\u062e\\u0637\\u0631 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"With returning energy you can do walking and prenatal yoga more regularly. Keep up pelvic floor exercises and avoid risky activities.\"}','{\"fa\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0634\\u0641\\u0627\\u0641\\u06cc\\u062a \\u067e\\u0634\\u062a \\u06af\\u0631\\u062f\\u0646 (NT) \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0627\\u06cc\\u0646 \\u0622\\u0632\\u0645\\u0648\\u0646 \\u062e\\u0637\\u0631 \\u0628\\u0631\\u062e\\u06cc \\u0627\\u062e\\u062a\\u0644\\u0627\\u0644\\u0627\\u062a \\u06a9\\u0631\\u0648\\u0645\\u0648\\u0632\\u0648\\u0645\\u06cc \\u0631\\u0627 \\u0627\\u0631\\u0632\\u06cc\\u0627\\u0628\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0648 \\u0648\\u0632\\u0646 \\u0646\\u06cc\\u0632 \\u062b\\u0628\\u062a \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The nuchal translucency (NT) ultrasound with a blood test for first-trimester screening is done from this week. It assesses the risk of some chromosomal conditions.\"}','{\"fa\":[{\"question\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc NT \\u0686\\u0647 \\u0686\\u06cc\\u0632\\u06cc \\u0631\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u061f\",\"answer\":\"\\u0636\\u062e\\u0627\\u0645\\u062a \\u0645\\u0627\\u06cc\\u0639 \\u067e\\u0634\\u062a \\u06af\\u0631\\u062f\\u0646 \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u062f \\u06a9\\u0647 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u062e\\u0637\\u0631 \\u0627\\u062e\\u062a\\u0644\\u0627\\u0644\\u0627\\u062a \\u06a9\\u0631\\u0648\\u0645\\u0648\\u0632\\u0648\\u0645\\u06cc \\u0631\\u0627 \\u0627\\u0631\\u0632\\u06cc\\u0627\\u0628\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"},{\"question\":\"\\u0686\\u0631\\u0627 \\u0627\\u0646\\u0631\\u0698\\u06cc\\u200c\\u0627\\u0645 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0627 \\u067e\\u0627\\u06cc\\u0627\\u0646 \\u06cc\\u0627\\u0641\\u062a\\u0646 \\u0627\\u0648\\u062c \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644\\u060c \\u0628\\u0633\\u06cc\\u0627\\u0631\\u06cc \\u0627\\u0632 \\u0632\\u0646\\u0627\\u0646 \\u06a9\\u0627\\u0647\\u0634 \\u062a\\u0647\\u0648\\u0639 \\u0648 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f.\"}],\"en\":[{\"question\":\"What does the NT scan check?\",\"answer\":\"It measures the fluid at the back of the baby\\u2019s neck, which with a blood test assesses chromosomal risk.\"},{\"question\":\"Why do I have more energy?\",\"answer\":\"As the peak of first-trimester hormones passes, many women feel less nausea and more energy.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(12,12,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u062f\\u0648\\u0627\\u0632\\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0644\\u06cc\\u0645\\u0648\\u062a\\u0631\\u0634\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f5.\\u06f4 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1\\u06f4 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0631\\u0641\\u0644\\u06a9\\u0633\\u200c\\u0647\\u0627 \\u0634\\u06a9\\u0644 \\u06af\\u0631\\u0641\\u062a\\u0647\\u200c\\u0627\\u0646\\u062f \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0627\\u0646\\u06af\\u0634\\u062a\\u0627\\u0646\\u0634 \\u0631\\u0627 \\u062d\\u0631\\u06a9\\u062a \\u062f\\u0647\\u062f. \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627\\u06cc \\u062d\\u06cc\\u0627\\u062a\\u06cc \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u062f\\u0631 \\u062c\\u0627\\u06cc \\u062e\\u0648\\u062f \\u0642\\u0631\\u0627\\u0631 \\u06af\\u0631\\u0641\\u062a\\u0647\\u200c\\u0627\\u0646\\u062f \\u0648 \\u0628\\u0647 \\u0631\\u0634\\u062f \\u0627\\u062f\\u0627\\u0645\\u0647 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f.\",\"en\":\"At week twelve the fetus is about the size of a lime, roughly 5.4 cm and nearly 14 g. Reflexes have formed, the baby can move its fingers, and vital organs are now in place and maturing.\"}','{\"fa\":\"\\u0628\\u0627 \\u067e\\u0627\\u06cc\\u0627\\u0646 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644\\u060c \\u062a\\u0647\\u0648\\u0639 \\u0648 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u06cc\\u0627\\u0628\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u062c\\u0633\\u062a\\u06af\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0634\\u06a9\\u0645 \\u0631\\u0627 \\u0645\\u062a\\u0648\\u062c\\u0647 \\u0634\\u0648\\u06cc\\u062f. \\u0627\\u0634\\u062a\\u0647\\u0627 \\u0628\\u0647\\u200c\\u062a\\u062f\\u0631\\u06cc\\u062c \\u0628\\u0647\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"As the first trimester ends, nausea and fatigue usually decrease. You may notice a slight baby bump and your appetite gradually improves.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0645\\u0631\\u0627\\u0642\\u0628 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0648\\u0632\\u0646 \\u0633\\u0627\\u0644\\u0645 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u0632 \\u0627\\u0633\\u062a\\u0631\\u0633 \\u0628\\u06cc\\u0634 \\u0627\\u0632 \\u062d\\u062f \\u0648 \\u0628\\u06cc\\u200c\\u062e\\u0648\\u0627\\u0628\\u06cc \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue balanced nutrition and supplements and aim for healthy weight gain. Avoid excess stress and sleeplessness, and keep gentle regular activity.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0631\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u0622\\u062e\\u0631\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0628\\u0631\\u0627\\u06cc NT \\u0627\\u0633\\u062a. \\u0646\\u062a\\u0627\\u06cc\\u062c \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"If you haven\\u2019t done first-trimester screening, these are the last suitable weeks for the NT scan. Review test results with your doctor and keep regular visits.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0627\\u0632 \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646 \\u0644\\u06af\\u0646 \\u0628\\u0627\\u0644\\u0627\\u062a\\u0631 \\u0622\\u0645\\u062f\\u0647 \\u0648 \\u0634\\u06a9\\u0645 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0645\\u0634\\u062e\\u0635 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u062c\\u0631\\u06cc\\u0627\\u0646 \\u062e\\u0648\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0627\\u0639\\u062b \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0628\\u06cc\\u0646\\u06cc \\u06cc\\u0627 \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0644\\u062b\\u0647 \\u0634\\u0648\\u062f. \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"The uterus has risen above the pelvic bone and the bump begins to show. Increased blood flow may cause nasal congestion or mild gum bleeding, which is normal.\"}','{\"fa\":\"\\u0631\\u0633\\u06cc\\u062f\\u0646 \\u0628\\u0647 \\u067e\\u0627\\u06cc\\u0627\\u0646 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0627\\u063a\\u0644\\u0628 \\u062d\\u0633 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0648 \\u0627\\u0637\\u0645\\u06cc\\u0646\\u0627\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u0628\\u0647 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u062f\\u0627\\u0631\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0639\\u0644\\u0627\\u0645 \\u062e\\u0628\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u062a\\u0631 \\u0634\\u0648\\u06cc\\u062f. \\u0628\\u0627 \\u0627\\u06cc\\u0646 \\u062d\\u0627\\u0644 \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a \\u0645\\u062a\\u063a\\u06cc\\u0631 \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a.\",\"en\":\"Reaching the end of the first trimester often brings relief and reassurance. You may feel readier to share the news, though changing emotions remain normal.\"}','{\"fa\":\"\\u06a9\\u0627\\u0644\\u0631\\u06cc \\u06a9\\u0627\\u0641\\u06cc \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0627\\u0633\\u06cc\\u062f \\u0641\\u0648\\u0644\\u06cc\\u06a9 \\u0631\\u0627 \\u062a\\u0623\\u0645\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u063a\\u0644\\u0627\\u062a \\u06a9\\u0627\\u0645\\u0644 \\u0648 \\u0645\\u06cc\\u0648\\u0647 \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0631\\u0627 \\u062f\\u0631 \\u0627\\u0648\\u0644\\u0648\\u06cc\\u062a \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f. \\u0627\\u0632 \\u0645\\u0635\\u0631\\u0641 \\u0628\\u06cc\\u0634 \\u0627\\u0632 \\u062d\\u062f \\u0642\\u0646\\u062f \\u0648 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0641\\u0631\\u0622\\u0648\\u0631\\u06cc\\u200c\\u0634\\u062f\\u0647 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Provide enough calories with protein, iron, calcium and folic acid. Favor whole grains, fruit and vegetables, and limit excess sugar and processed foods.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u062f\\u0648\\u0631\\u0647 \\u0639\\u0627\\u0644\\u06cc \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0645\\u0646\\u0638\\u0645 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0628\\u0627 \\u062e\\u0637\\u0631 \\u0627\\u0641\\u062a\\u0627\\u062f\\u0646 \\u06cc\\u0627 \\u0636\\u0631\\u0628\\u0647 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga are excellent now. Do pelvic floor exercises regularly and avoid moves with a risk of falling or impact.\"}','{\"fa\":\"\\u0647\\u0641\\u062a\\u0647 \\u062f\\u0648\\u0627\\u0632\\u062f\\u0647\\u0645 \\u0622\\u062e\\u0631\\u06cc\\u0646 \\u0628\\u0627\\u0632\\u0647 \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc NT \\u0648 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u062a\\u0631\\u06a9\\u06cc\\u0628\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0627\\u0633\\u062a. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0646\\u0634\\u0627\\u0646\\u06af\\u0631\\u0647\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0648 \\u0648\\u0632\\u0646 \\u062b\\u0628\\u062a \\u0645\\u06cc\\u200c\\u06af\\u0631\\u062f\\u062f.\",\"en\":\"Week twelve is the last suitable window for the NT scan and combined first-trimester screening. A blood test for markers is done, and vitals are recorded.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u0645 \\u062e\\u0628\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0627\\u0639\\u0644\\u0627\\u0645 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0628\\u0633\\u06cc\\u0627\\u0631\\u06cc \\u067e\\u0633 \\u0627\\u0632 \\u067e\\u0627\\u06cc\\u0627\\u0646 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u06a9\\u0647 \\u062e\\u0637\\u0631 \\u0633\\u0642\\u0637 \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u06cc\\u0627\\u0628\\u062f \\u062e\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u0639\\u0644\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f\\u060c \\u0627\\u0645\\u0627 \\u0627\\u06cc\\u0646 \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u0627\\u0646\\u062a\\u062e\\u0627\\u0628 \\u0634\\u062e\\u0635\\u06cc \\u0627\\u0633\\u062a.\"},{\"question\":\"\\u0622\\u06cc\\u0627 \\u0628\\u0631\\u062c\\u0633\\u062a\\u06af\\u06cc \\u0634\\u06a9\\u0645 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u062f\\u0631 \\u067e\\u0627\\u06cc\\u0627\\u0646 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0628\\u0631\\u062c\\u0633\\u062a\\u06af\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0634\\u06a9\\u0645 \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a \\u0648 \\u062f\\u0631 \\u0647\\u0631 \\u0641\\u0631\\u062f \\u0645\\u062a\\u0641\\u0627\\u0648\\u062a \\u0638\\u0627\\u0647\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"When can I announce the pregnancy?\",\"answer\":\"Many share the news after the first trimester when miscarriage risk drops, but it is entirely a personal choice.\"},{\"question\":\"Is a bump normal at this week?\",\"answer\":\"Yes, a slight bump is common at the end of the first trimester and appears differently for each woman.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(13,13,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u0632\\u062f\\u0647\\u0645 \\u06a9\\u0647 \\u0622\\u063a\\u0627\\u0632 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0627\\u0633\\u062a\\u060c \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0644\\u06cc\\u0645\\u0648\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f7.\\u06f4 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f2\\u06f3 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u062b\\u0631 \\u0627\\u0646\\u06af\\u0634\\u062a \\u0634\\u06a9\\u0644 \\u06af\\u0631\\u0641\\u062a\\u0647 \\u0648 \\u062a\\u0627\\u0631\\u0647\\u0627\\u06cc \\u0635\\u0648\\u062a\\u06cc \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0633\\u0627\\u062e\\u062a\\u0647 \\u0634\\u062f\\u0646 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0645\\u06a9\\u062f \\u0648 \\u0628\\u0628\\u0644\\u0639\\u062f.\",\"en\":\"At week thirteen, the start of the second trimester, the fetus is about the size of a lemon, roughly 7.4 cm and nearly 23 g. Fingerprints have formed, vocal cords are developing, and the baby can suck and swallow.\"}','{\"fa\":\"\\u0628\\u0627 \\u0648\\u0631\\u0648\\u062f \\u0628\\u0647 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u0627\\u0632\\u0645\\u06cc\\u200c\\u06af\\u0631\\u062f\\u062f \\u0648 \\u062a\\u0647\\u0648\\u0639 \\u06a9\\u0645\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0634\\u062a\\u0647\\u0627 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u06cc\\u0627\\u0628\\u062f \\u0648 \\u0634\\u06a9\\u0645 \\u06a9\\u0645\\u06cc \\u0628\\u0631\\u062c\\u0633\\u062a\\u0647\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u0628\\u0631\\u062e\\u06cc \\u0632\\u0646\\u0627\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u067e\\u0648\\u0633\\u062a\\u06cc \\u0645\\u0627\\u0646\\u0646\\u062f \\u062e\\u0637 \\u062a\\u06cc\\u0631\\u0647 \\u0634\\u06a9\\u0645 \\u0631\\u0627 \\u0645\\u06cc\\u200c\\u0628\\u06cc\\u0646\\u0646\\u062f.\",\"en\":\"Entering the second trimester, energy usually returns and nausea fades. Appetite may rise and the bump grow, and some women notice skin changes like the linea nigra.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0648\\u0632\\u0646 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0622\\u0647\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0627\\u0632 \\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u0647 \\u067e\\u0634\\u062a \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0639\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0645\\u0646\\u0638\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and moderate weight gain, and take calcium and iron seriously. In later weeks avoid lying flat on your back for long, and stay active.\"}','{\"fa\":\"\\u0646\\u062a\\u0627\\u06cc\\u062c \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0627\\u0648\\u0644 \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0631\\u0627 \\u062f\\u0631 \\u0646\\u0638\\u0631 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0648 \\u0648\\u0631\\u0632\\u0634 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Review first-trimester screening results with your doctor and plan for the anomaly scan ahead. Keep regular visits and plan your nutrition and exercise.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0632\\u0631\\u06af\\u200c\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0648 \\u0631\\u0628\\u0627\\u0637\\u200c\\u0647\\u0627\\u06cc \\u0646\\u06af\\u0647\\u062f\\u0627\\u0631\\u0646\\u062f\\u0647 \\u06a9\\u0634\\u06cc\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f \\u06a9\\u0647 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062f\\u0631\\u062f \\u062e\\u0641\\u06cc\\u0641 \\u067e\\u0647\\u0644\\u0648 \\u0627\\u06cc\\u062c\\u0627\\u062f \\u06a9\\u0646\\u062f. \\u062c\\u0641\\u062a \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0628\\u0647\\u200c\\u0637\\u0648\\u0631 \\u06a9\\u0627\\u0645\\u0644 \\u0648\\u0638\\u06cc\\u0641\\u0647 \\u062a\\u063a\\u0630\\u06cc\\u0647 \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0628\\u0631 \\u0639\\u0647\\u062f\\u0647 \\u062f\\u0627\\u0631\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u062b\\u0628\\u0627\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus is larger and supporting ligaments stretch, which can cause mild side pain. The placenta now fully nourishes the baby and the body works more steadily.\"}','{\"fa\":\"\\u0628\\u0633\\u06cc\\u0627\\u0631\\u06cc \\u0627\\u0632 \\u0632\\u0646\\u0627\\u0646 \\u062f\\u0631 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0648 \\u0634\\u0627\\u062f\\u0627\\u0628\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0631\\u0646\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0639\\u0627\\u0637\\u0641\\u06cc \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631\\u06cc \\u0628\\u0627 \\u062c\\u0646\\u06cc\\u0646 \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0627 \\u0627\\u06cc\\u0646 \\u062d\\u0627\\u0644 \\u06af\\u0627\\u0647\\u06cc \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u062c\\u062f\\u06cc\\u062f \\u0647\\u0645 \\u067e\\u06cc\\u0634 \\u0645\\u06cc\\u200c\\u0622\\u06cc\\u062f.\",\"en\":\"Many women feel calmer and more vibrant in the second trimester. You may feel a stronger bond with the baby, though new worries can occasionally arise.\"}','{\"fa\":\"\\u0628\\u0627 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0634\\u062a\\u0647\\u0627\\u060c \\u06a9\\u06cc\\u0641\\u06cc\\u062a \\u063a\\u0630\\u0627 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a\\u061b \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u0644\\u0628\\u0646\\u06cc\\u0627\\u062a\\u060c \\u063a\\u0644\\u0627\\u062a \\u06a9\\u0627\\u0645\\u0644 \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0631\\u0627 \\u062f\\u0631 \\u0627\\u0648\\u0644\\u0648\\u06cc\\u062a \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f. \\u0622\\u0647\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u062d\\u062c\\u0645 \\u062e\\u0648\\u0646 \\u0636\\u0631\\u0648\\u0631\\u06cc \\u0627\\u0633\\u062a. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"As appetite grows, food quality matters; prioritize protein, dairy, whole grains and vegetables. Iron is vital for rising blood volume, and drink enough water.\"}','{\"fa\":\"\\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0632\\u0645\\u0627\\u0646 \\u062e\\u0648\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0645\\u0646\\u0638\\u0645 \\u0645\\u0627\\u0646\\u0646\\u062f \\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u062a\\u0646\\u062f\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0633\\u062a. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u06a9\\u0634\\u0634\\u06cc \\u0645\\u0641\\u06cc\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0641\\u0631\\u0627\\u0637 \\u0646\\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"The second trimester is a good time for regular activity like brisk walking, swimming and prenatal yoga. Pelvic floor and stretching exercises help; don\\u2019t overdo it.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u062a\\u0631\\u06a9\\u06cc\\u0628\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u0634\\u062f\\u0647\\u060c \\u0627\\u06cc\\u0646 \\u0622\\u062e\\u0631\\u06cc\\u0646 \\u0641\\u0631\\u0635\\u062a \\u0627\\u0633\\u062a \\u0648 \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u067e\\u0633 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 (\\u06a9\\u0648\\u0627\\u062f \\u0645\\u0627\\u0631\\u06a9\\u0631) \\u0645\\u0637\\u0631\\u062d \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u063a\\u06cc\\u0631\\u0639\\u0627\\u062f\\u06cc \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"If combined screening wasn\\u2019t done this is the last chance, and second-trimester quad screening becomes an option. Routine visits continue; report unusual symptoms.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0631\\u0627 \\u062f\\u0631 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0628\\u0647\\u062a\\u0631 \\u062d\\u0633 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u06a9\\u0627\\u0647\\u0634 \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u200c\\u0647\\u0627\\u06cc \\u0639\\u0627\\u0645\\u0644 \\u062a\\u0647\\u0648\\u0639 \\u0648 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631\\u06cc \\u0628\\u062f\\u0646 \\u0628\\u0627\\u0639\\u062b \\u0628\\u0627\\u0632\\u06af\\u0634\\u062a \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0648 \\u0628\\u0647\\u0628\\u0648\\u062f \\u062d\\u0627\\u0644 \\u0639\\u0645\\u0648\\u0645\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u062e\\u0637 \\u062a\\u06cc\\u0631\\u0647 \\u0631\\u0648\\u06cc \\u0634\\u06a9\\u0645 \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0647 \\u0622\\u0646 \\u0644\\u06cc\\u0646\\u0647\\u200c\\u0622 \\u0646\\u06cc\\u06af\\u0631\\u0627 \\u0645\\u06cc\\u200c\\u06af\\u0648\\u06cc\\u0646\\u062f \\u06a9\\u0647 \\u0628\\u0647 \\u062f\\u0644\\u06cc\\u0644 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u0627\\u06cc\\u062c\\u0627\\u062f \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u067e\\u0633 \\u0627\\u0632 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u062d\\u0648 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"Why do I feel better in the second trimester?\",\"answer\":\"Lower nausea-causing hormones and body adaptation restore energy and wellbeing.\"},{\"question\":\"What is the dark line on my belly?\",\"answer\":\"It is called the linea nigra, caused by hormonal changes, and usually fades after birth.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(14,14,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0686\\u0647\\u0627\\u0631\\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0647\\u0644\\u0648\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f8.\\u06f7 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f4\\u06f3 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u06a9\\u0631\\u06a9 \\u0638\\u0631\\u06cc\\u0641\\u06cc \\u0628\\u0647 \\u0646\\u0627\\u0645 \\u0644\\u0627\\u0646\\u0648\\u06af\\u0648 \\u0628\\u062f\\u0646 \\u0631\\u0627 \\u0645\\u06cc\\u200c\\u067e\\u0648\\u0634\\u0627\\u0646\\u062f \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062d\\u0627\\u0644\\u0627\\u062a \\u0635\\u0648\\u0631\\u062a \\u0628\\u06af\\u06cc\\u0631\\u062f. \\u06a9\\u0628\\u062f \\u0648 \\u06a9\\u0644\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u06a9\\u0627\\u0631 \\u06a9\\u0631\\u062f\\u0647\\u200c\\u0627\\u0646\\u062f.\",\"en\":\"At week fourteen the fetus is about the size of a peach, roughly 8.7 cm and nearly 43 g. Fine hair called lanugo covers the body, the baby can make facial expressions, and the liver and kidneys start working.\"}','{\"fa\":\"\\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0648 \\u06a9\\u0627\\u0647\\u0634 \\u062a\\u0647\\u0648\\u0639 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f \\u0648 \\u0627\\u0634\\u062a\\u0647\\u0627 \\u0628\\u0647\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0634\\u06a9\\u0645 \\u0628\\u0647\\u200c\\u0648\\u0636\\u0648\\u062d \\u0628\\u0631\\u062c\\u0633\\u062a\\u0647\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u0628\\u0631\\u062e\\u06cc \\u0632\\u0646\\u0627\\u0646 \\u062f\\u0631\\u062f \\u0631\\u0628\\u0627\\u0637 \\u06af\\u0631\\u062f \\u0631\\u0627 \\u062f\\u0631 \\u067e\\u0647\\u0644\\u0648\\u0647\\u0627 \\u062d\\u0633 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f.\",\"en\":\"More energy and less nausea usually continue and appetite improves. The bump may become clearly visible, and some women feel round ligament pain in the sides.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u063a\\u0630\\u06cc \\u0648 \\u0645\\u0635\\u0631\\u0641 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u067e\\u0631\\u062e\\u0648\\u0631\\u06cc \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u0644\\u0628\\u0627\\u0633 \\u0631\\u0627\\u062d\\u062a \\u0648 \\u06a9\\u0641\\u0634 \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0628\\u067e\\u0648\\u0634\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue nutritious eating and supplements and avoid overeating. Wear comfortable clothes and supportive shoes, and keep regular activity.\"}','{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0648 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u067e\\u06cc\\u0634 \\u0631\\u0648 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u067e\\u0648\\u0633\\u062a \\u0648 \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0631\\u0627 \\u062f\\u0631 \\u0646\\u0638\\u0631 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Plan for second-trimester screening and the upcoming anomaly scan. Keep regular visits and blood-pressure checks, and mind skin care and constipation.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0622\\u06cc\\u062f \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646 \\u0634\\u0631\\u0645\\u06af\\u0627\\u0647\\u06cc \\u0642\\u0627\\u0628\\u0644 \\u0644\\u0645\\u0633 \\u0628\\u0627\\u0634\\u062f. \\u062c\\u0631\\u06cc\\u0627\\u0646 \\u062e\\u0648\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u067e\\u0648\\u0633\\u062a \\u0631\\u0627 \\u0634\\u0627\\u062f\\u0627\\u0628\\u200c\\u062a\\u0631 \\u06a9\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u062b\\u0628\\u0627\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062e\\u0648\\u062f \\u0631\\u0627 \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus rises and may be felt above the pubic bone. Increased blood flow can give the skin a healthy glow as the body settles more steadily.\"}','{\"fa\":\"\\u062d\\u0627\\u0644 \\u0639\\u0645\\u0648\\u0645\\u06cc \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0628\\u0647\\u062a\\u0631 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0646\\u0648\\u0632\\u0627\\u062f \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0628\\u0627 \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0627\\u06af\\u0631 \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u062f \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u06cc\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9\\u0627\\u0646 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Overall mood is usually better and you may feel more excited to prepare for the baby. The bond grows; if worried, talk to your doctor or loved ones.\"}','{\"fa\":\"\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0631\\u0634\\u062f \\u0645\\u063a\\u0632 \\u0648 \\u0628\\u062f\\u0646 \\u062c\\u0646\\u06cc\\u0646 \\u062a\\u0623\\u0645\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0645\\u0627\\u0647\\u06cc \\u06a9\\u0645\\u200c\\u062c\\u06cc\\u0648\\u0647\\u060c \\u062a\\u062e\\u0645\\u200c\\u0645\\u0631\\u063a \\u0648 \\u0645\\u063a\\u0632\\u0647\\u0627 \\u0645\\u0641\\u06cc\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0641\\u06cc\\u0628\\u0631 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Provide protein, iron, calcium and omega-3 for the baby\\u2019s brain and body. Low-mercury fish, eggs and nuts help; eat enough fiber to prevent constipation.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0642\\u062f\\u0631\\u062a\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0627\\u0633\\u062a. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u062f\\u0631\\u0627\\u0632 \\u06a9\\u0634\\u06cc\\u062f\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u0647 \\u067e\\u0634\\u062a \\u0648 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle strength exercises suit this week. Keep up pelvic floor work and avoid long back-lying and risky moves.\"}','{\"fa\":\"\\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0634\\u0627\\u0645\\u0644 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u06a9\\u0648\\u0627\\u062f \\u0645\\u0627\\u0631\\u06a9\\u0631 \\u0648 AFP \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0642\\u0627\\u0628\\u0644 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u06cc\\u0646 \\u0622\\u0632\\u0645\\u0648\\u0646 \\u062e\\u0637\\u0631 \\u0646\\u0642\\u0635 \\u0644\\u0648\\u0644\\u0647 \\u0639\\u0635\\u0628\\u06cc \\u0648 \\u0628\\u0631\\u062e\\u06cc \\u0627\\u062e\\u062a\\u0644\\u0627\\u0644\\u0627\\u062a \\u0631\\u0627 \\u0627\\u0631\\u0632\\u06cc\\u0627\\u0628\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"Second-trimester screening including the quad marker and AFP blood test can be done from this week. It assesses the risk of neural tube defects and some conditions.\"}','{\"fa\":[{\"question\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 AFP \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0627\\u0646\\u062f\\u0627\\u0632\\u0647\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0622\\u0644\\u0641\\u0627\\u0641\\u062a\\u0648\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u062f\\u0631 \\u062e\\u0648\\u0646 \\u0645\\u0627\\u062f\\u0631 \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0646\\u0642\\u0635 \\u0644\\u0648\\u0644\\u0647 \\u0639\\u0635\\u0628\\u06cc \\u0648 \\u0628\\u0631\\u062e\\u06cc \\u0627\\u062e\\u062a\\u0644\\u0627\\u0644\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u062f\\u0631\\u062f \\u0631\\u0628\\u0627\\u0637 \\u06af\\u0631\\u062f \\u0686\\u06af\\u0648\\u0646\\u0647 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u062f\\u0631\\u062f\\u06cc \\u062a\\u06cc\\u0632 \\u0648 \\u06a9\\u0648\\u062a\\u0627\\u0647 \\u062f\\u0631 \\u067e\\u0647\\u0644\\u0648\\u0647\\u0627 \\u0647\\u0646\\u06af\\u0627\\u0645 \\u062d\\u0631\\u06a9\\u062a \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u0628\\u0647 \\u062f\\u0644\\u06cc\\u0644 \\u06a9\\u0634\\u06cc\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u0631\\u0628\\u0627\\u0637\\u200c\\u0647\\u0627\\u06cc \\u0631\\u062d\\u0645 \\u0631\\u062e \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f \\u0648 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0628\\u06cc\\u200c\\u062e\\u0637\\u0631 \\u0627\\u0633\\u062a.\"}],\"en\":[{\"question\":\"What is the AFP test?\",\"answer\":\"It measures alpha-fetoprotein in the mother\\u2019s blood to screen for neural tube defects and some conditions.\"},{\"question\":\"What is round ligament pain?\",\"answer\":\"It is a brief sharp pain in the sides during movement from stretching uterine ligaments, usually harmless.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(15,15,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u067e\\u0627\\u0646\\u0632\\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0633\\u06cc\\u0628\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f1\\u06f0 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f7\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0646\\u0648\\u0631 \\u0631\\u0627 \\u0627\\u0632 \\u067e\\u0634\\u062a \\u067e\\u0644\\u06a9\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0633\\u062a\\u0647 \\u062d\\u0633 \\u06a9\\u0646\\u062f \\u0648 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062f\\u0633\\u062a \\u0648 \\u067e\\u0627 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0645\\u062d\\u06a9\\u0645 \\u0634\\u062f\\u0646 \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"At week fifteen the fetus is about the size of an apple, roughly 10 cm and nearly 70 g. It can sense light through closed eyelids, moves its limbs more, and its bones are hardening.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0627\\u0634\\u062a\\u0647\\u0627 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u06cc\\u0627\\u0628\\u062f. \\u0628\\u0631\\u062e\\u06cc \\u0632\\u0646\\u0627\\u0646 \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0628\\u06cc\\u0646\\u06cc \\u06cc\\u0627 \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0644\\u062b\\u0647 \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f. \\u0634\\u06a9\\u0645 \\u0628\\u0647\\u200c\\u062a\\u062f\\u0631\\u06cc\\u062c \\u06af\\u0631\\u062f\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"You may feel more energetic with a growing appetite. Some women experience nasal congestion or mild gum bleeding, and the belly gradually rounds out.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0645\\u0631\\u0627\\u0642\\u0628 \\u0628\\u0647\\u062f\\u0627\\u0634\\u062a \\u062f\\u0647\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u0632 \\u0642\\u0631\\u0627\\u0631 \\u06af\\u0631\\u0641\\u062a\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u062f\\u0631 \\u0648\\u0636\\u0639\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0646\\u0627\\u0645\\u0646\\u0627\\u0633\\u0628 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue balanced nutrition and supplements and maintain oral hygiene. Avoid staying long in awkward positions and keep regular activity.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u06a9\\u0648\\u0627\\u062f \\u0631\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0646\\u0627\\u0633\\u0628\\u06cc \\u0627\\u0633\\u062a. \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u067e\\u06cc\\u0634 \\u0631\\u0648 \\u0647\\u0645\\u0627\\u0647\\u0646\\u06af \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"If you haven\\u2019t had the quad screen, this is a good week. Coordinate the upcoming anomaly scan and keep regular visits.\"}','{\"fa\":\"\\u062d\\u062c\\u0645 \\u062e\\u0648\\u0646 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u06cc\\u0627\\u0641\\u062a\\u0647 \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06af\\u0627\\u0647\\u06cc \\u0633\\u0631\\u06af\\u06cc\\u062c\\u0647 \\u062e\\u0641\\u06cc\\u0641 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0645\\u0641\\u0627\\u0635\\u0644 \\u06a9\\u0645\\u06cc \\u0634\\u0644\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f \\u062a\\u0627 \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0631\\u0634\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0648\\u062f. \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"Blood volume has increased and you may feel occasional mild dizziness. Joints loosen a little to prepare the body for growth; these changes are normal.\"}','{\"fa\":\"\\u0631\\u0648\\u062d\\u06cc\\u0647 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0628\\u0647\\u062a\\u0631 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0627\\u06cc \\u0622\\u06cc\\u0646\\u062f\\u0647 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0627 \\u0627\\u06cc\\u0646 \\u062d\\u0627\\u0644 \\u06af\\u0627\\u0647\\u06cc \\u062d\\u0648\\u0627\\u0633\\u200c\\u067e\\u0631\\u062a\\u06cc \\u06cc\\u0627 \\u0641\\u0631\\u0627\\u0645\\u0648\\u0634\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0622\\u0632\\u0627\\u0631\\u062f\\u0647\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u0628\\u0627 \\u062e\\u0648\\u062f\\u062a\\u0627\\u0646 \\u0645\\u0647\\u0631\\u0628\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Mood is usually better and you may start planning ahead. Still, pregnancy forgetfulness can be bothersome; be gentle with yourself.\"}','{\"fa\":\"\\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 D \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646\\u200c\\u0633\\u0627\\u0632\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0647\\u0645\\u06cc\\u062a \\u062f\\u0627\\u0631\\u0646\\u062f. \\u0644\\u0628\\u0646\\u06cc\\u0627\\u062a\\u060c \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0628\\u0631\\u06af\\u200c\\u0633\\u0628\\u0632 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0628\\u0627\\u06a9\\u06cc\\u0641\\u06cc\\u062a \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0647\\u0646 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0631\\u0627 \\u0641\\u0631\\u0627\\u0645\\u0648\\u0634 \\u0646\\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Calcium and vitamin D matter for the baby\\u2019s bones. Eat dairy, leafy greens and quality protein, and don\\u2019t forget iron and enough water.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062d\\u0641\\u0638 \\u062a\\u0646\\u0627\\u0633\\u0628 \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u06a9\\u0634\\u0634\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0633\\u0631\\u06af\\u06cc\\u062c\\u0647\\u060c \\u0622\\u0647\\u0633\\u062a\\u0647 \\u062d\\u0631\\u06a9\\u062a \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga help stay fit. Continue pelvic floor and stretching exercises, and if dizzy, move slowly and hydrate.\"}','{\"fa\":\"\\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 (\\u06a9\\u0648\\u0627\\u062f \\u0645\\u0627\\u0631\\u06a9\\u0631 \\u0648 AFP) \\u062f\\u0631 \\u0628\\u0627\\u0632\\u0647 \\u0647\\u0641\\u062a\\u0647 \\u06f1\\u06f5 \\u062a\\u0627 \\u06f1\\u06f8 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0646\\u06cc\\u0627\\u0632\\u060c \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0622\\u0645\\u0646\\u06cc\\u0648\\u0633\\u0646\\u062a\\u0632 \\u0631\\u0627 \\u0645\\u0637\\u0631\\u062d \\u06a9\\u0646\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0648 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"Second-trimester screening (quad marker and AFP) is done in the weeks 15 to 18 window. If needed, your doctor may discuss amniocentesis; routine checks continue.\"}','{\"fa\":[{\"question\":\"\\u0622\\u0645\\u0646\\u06cc\\u0648\\u0633\\u0646\\u062a\\u0632 \\u0686\\u06cc\\u0633\\u062a \\u0648 \\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0644\\u0627\\u0632\\u0645 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0646\\u0645\\u0648\\u0646\\u0647\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u0645\\u0627\\u06cc\\u0639 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u062f\\u0642\\u06cc\\u0642 \\u06a9\\u0631\\u0648\\u0645\\u0648\\u0632\\u0648\\u0645\\u200c\\u0647\\u0627\\u0633\\u062a \\u0648 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u067e\\u0631\\u062e\\u0637\\u0631 \\u06cc\\u0627 \\u0633\\u0646 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0645\\u0627\\u062f\\u0631 \\u0645\\u0637\\u0631\\u062d \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0641\\u0631\\u0627\\u0645\\u0648\\u0634\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0648\\u0627\\u0642\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u0648 \\u06a9\\u0645\\u200c\\u062e\\u0648\\u0627\\u0628\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0639\\u062b \\u062d\\u0648\\u0627\\u0633\\u200c\\u067e\\u0631\\u062a\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0634\\u0648\\u062f \\u06a9\\u0647 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0645\\u0648\\u0642\\u062a\\u06cc \\u0627\\u0633\\u062a.\"}],\"en\":[{\"question\":\"What is amniocentesis and when is it needed?\",\"answer\":\"It samples amniotic fluid to examine chromosomes, usually offered for high-risk screening or older maternal age.\"},{\"question\":\"Is pregnancy brain real?\",\"answer\":\"Yes, hormonal changes and poor sleep can cause mild forgetfulness, which is usually temporary.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(16,16,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0634\\u0627\\u0646\\u0632\\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0622\\u0648\\u0648\\u06a9\\u0627\\u062f\\u0648\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f1\\u06f1.\\u06f6 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1\\u06f0\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0639\\u0636\\u0644\\u0627\\u062a \\u0635\\u0648\\u0631\\u062a \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0627\\u062e\\u0645 \\u06cc\\u0627 \\u062d\\u0627\\u0644\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u062e\\u062a\\u0644\\u0641 \\u0628\\u06af\\u06cc\\u0631\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0647\\u0645\\u0627\\u0647\\u0646\\u06af\\u200c\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u062d\\u0633 \\u0634\\u0648\\u062f.\",\"en\":\"At week sixteen the fetus is about the size of an avocado, roughly 11.6 cm and nearly 100 g. Facial muscles work so the baby can frown, and movements grow more coordinated and may soon be felt.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062e\\u0641\\u06cc\\u0641 \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0622\\u06cc\\u0646\\u062f\\u0647 \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f. \\u0634\\u06a9\\u0645 \\u0648\\u0627\\u0636\\u062d\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u067e\\u0648\\u0633\\u062a \\u0634\\u06a9\\u0645 \\u062f\\u0686\\u0627\\u0631 \\u062e\\u0627\\u0631\\u0634 \\u0634\\u0648\\u062f. \\u0627\\u0634\\u062a\\u0647\\u0627 \\u0648 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062e\\u0648\\u0628 \\u0627\\u0633\\u062a.\",\"en\":\"You may feel the first faint baby movements in the coming weeks. The bump grows clearer, the belly skin may itch, and appetite and energy are usually good.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0645\\u0631\\u0637\\u0648\\u0628\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u0648\\u0633\\u062a \\u0634\\u06a9\\u0645 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0628\\u0644\\u0646\\u062f \\u06a9\\u0631\\u062f\\u0646 \\u0627\\u062c\\u0633\\u0627\\u0645 \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u062e\\u0648\\u062f\\u062f\\u0627\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and moisturize the belly skin. Avoid lifting heavy objects and keep regular activity.\"}','{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u06a9\\u0647 \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0648\\u06cc\\u062f. \\u0627\\u06af\\u0631 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u06a9\\u0648\\u0627\\u062f \\u0631\\u0627 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0647\\u0645\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0642\\u062f\\u0627\\u0645 \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Prepare for the anomaly scan coming soon. If you haven\\u2019t had the quad screen, do it this week, and keep regular visits.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0628\\u06cc\\u0646 \\u0646\\u0627\\u0641 \\u0648 \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646 \\u0634\\u0631\\u0645\\u06af\\u0627\\u0647\\u06cc \\u0642\\u0631\\u0627\\u0631 \\u062f\\u0627\\u0631\\u062f \\u0648 \\u0645\\u0631\\u06a9\\u0632 \\u062b\\u0642\\u0644 \\u0628\\u062f\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u062e\\u0641\\u06cc\\u0641 \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u062e\\u0648\\u0628\\u06cc \\u0648\\u0632\\u0646 \\u0627\\u0636\\u0627\\u0641\\u0647 \\u0631\\u0627 \\u062a\\u062d\\u0645\\u0644 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus now sits between the navel and pubic bone and your center of gravity shifts. You may feel mild back pain as the body handles the added weight.\"}','{\"fa\":\"\\u062d\\u0633 \\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0628\\u0627 \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u060c \\u0628\\u0647\\u200c\\u0648\\u06cc\\u0698\\u0647 \\u0628\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0634\\u062f\\u0646 \\u0628\\u0647 \\u062d\\u0633 \\u06a9\\u0631\\u062f\\u0646 \\u062d\\u0631\\u06a9\\u0627\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u0633\\u0644\\u0627\\u0645\\u062a \\u0631\\u0648\\u0627\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"The bond with the baby strengthens, especially as movements approach. You may feel more excitement and anticipation; keep caring for your mental health.\"}','{\"fa\":\"\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u063a\\u0646\\u06cc \\u0627\\u0632 \\u0641\\u06cc\\u0628\\u0631 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0631\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f. \\u0627\\u0632 \\u0645\\u06cc\\u0627\\u0646\\u200c\\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue protein, iron, calcium and omega-3 and drink enough water. Fiber-rich foods reduce constipation; choose healthy snacks.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0642\\u0648\\u06cc\\u062a\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u06a9\\u0645\\u0631 \\u0648 \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0635\\u062d\\u06cc\\u062d \\u0631\\u0627 \\u0631\\u0639\\u0627\\u06cc\\u062a \\u06a9\\u0646\\u06cc\\u062f \\u062a\\u0627 \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u06a9\\u0645\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u0627\\u0632 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and back and pelvic floor strengthening help. Maintain good posture to ease back pain and avoid risky moves.\"}','{\"fa\":\"\\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0628\\u0627\\u0632\\u0647 \\u0642\\u0627\\u0628\\u0644 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0627\\u0633\\u062a \\u0648 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0648 \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a.\",\"en\":\"Second-trimester screening is still available now, and the anomaly scan will be scheduled soon. Routine visits include blood pressure and fetal heartbeat checks.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062d\\u0633 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0628\\u0633\\u06cc\\u0627\\u0631\\u06cc \\u0627\\u0632 \\u0645\\u0627\\u062f\\u0631\\u0627\\u0646 \\u0627\\u0648\\u0644\\u06cc\\u0646 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0631\\u0627 \\u0628\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u06f1\\u06f6 \\u062a\\u0627 \\u06f2\\u06f0 \\u062d\\u0633 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f\\u061b \\u062f\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0648\\u0644 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u06cc \\u062f\\u06cc\\u0631\\u062a\\u0631 \\u0628\\u0627\\u0634\\u062f.\"},{\"question\":\"\\u062e\\u0627\\u0631\\u0634 \\u067e\\u0648\\u0633\\u062a \\u0634\\u06a9\\u0645 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u06a9\\u0634\\u06cc\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u067e\\u0648\\u0633\\u062a \\u0628\\u0627\\u0639\\u062b \\u062e\\u0627\\u0631\\u0634 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061b \\u0645\\u0631\\u0637\\u0648\\u0628\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u060c \\u0627\\u0645\\u0627 \\u062e\\u0627\\u0631\\u0634 \\u0634\\u062f\\u06cc\\u062f \\u0633\\u0631\\u0627\\u0633\\u0631\\u06cc \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0637\\u0631\\u062d \\u06a9\\u0646\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"When will I feel the baby move?\",\"answer\":\"Many mothers feel first movements between weeks 16 and 20; in a first pregnancy it may be a bit later.\"},{\"question\":\"Is belly itching normal?\",\"answer\":\"Yes, stretching skin causes itching; moisturizer helps, but report severe widespread itching to your doctor.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(17,17,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0647\\u0641\\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0634\\u0644\\u063a\\u0645\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f1\\u06f3 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1\\u06f4\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0644\\u0627\\u06cc\\u0647 \\u0686\\u0631\\u0628\\u06cc \\u0645\\u062d\\u0627\\u0641\\u0638 \\u0632\\u06cc\\u0631 \\u067e\\u0648\\u0633\\u062a \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u062a\\u0634\\u06a9\\u06cc\\u0644 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u0627\\u0633\\u06a9\\u0644\\u062a \\u0627\\u0632 \\u063a\\u0636\\u0631\\u0648\\u0641 \\u0628\\u0647 \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646 \\u062a\\u0628\\u062f\\u06cc\\u0644 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0635\\u062f\\u0627\\u0647\\u0627 \\u0631\\u0627 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u062d\\u0633 \\u06a9\\u0646\\u062f.\",\"en\":\"At week seventeen the fetus is about the size of a turnip, roughly 13 cm and nearly 140 g. A protective fat layer begins forming under the skin, the skeleton turns from cartilage to bone, and the baby starts sensing sounds.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0634\\u062a\\u0647\\u0627 \\u0632\\u06cc\\u0627\\u062f \\u0648 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u062e\\u0648\\u0628\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0634\\u06a9\\u0645 \\u0648\\u0627\\u0636\\u062d\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u0628\\u0631\\u062e\\u06cc \\u0632\\u0646\\u0627\\u0646 \\u062a\\u0639\\u0631\\u06cc\\u0642 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u06cc\\u0627 \\u06af\\u0631\\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u062e\\u0641\\u06cc\\u0641 \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"You may have a strong appetite and good energy as the bump grows clearer. Some women sweat more or feel mild flushes, and you may sense early baby movements.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u063a\\u0630\\u06cc \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0648\\u0632\\u0646 \\u0646\\u0627\\u06af\\u0647\\u0627\\u0646\\u06cc \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u06a9\\u0641\\u0634 \\u0631\\u0627\\u062d\\u062a \\u0628\\u067e\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u062f\\u0631\\u0633\\u062a \\u0631\\u0627 \\u0631\\u0639\\u0627\\u06cc\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue nutritious eating and supplements and avoid sudden weight gain. Wear comfortable shoes, keep good posture, and stay active.\"}','{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u06a9\\u0647 \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06f1\\u06f8 \\u062a\\u0627 \\u06f2\\u06f2 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0648\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u063a\\u06cc\\u0631\\u0639\\u0627\\u062f\\u06cc \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Prepare for the anomaly scan done in weeks 18 to 22. Keep regular visits and blood-pressure checks, and report unusual symptoms.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0628\\u0632\\u0631\\u06af \\u0634\\u062f\\u0646 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06af\\u0627\\u0647\\u06cc \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0641\\u0634\\u0627\\u0631 \\u062f\\u0631 \\u0646\\u0627\\u062d\\u06cc\\u0647 \\u06a9\\u0645\\u0631 \\u0648 \\u0644\\u06af\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u0642\\u0644\\u0628\\u06cc\\u200c\\u0639\\u0631\\u0648\\u0642\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u067e\\u0634\\u062a\\u06cc\\u0628\\u0627\\u0646\\u06cc \\u0627\\u0632 \\u062c\\u0646\\u06cc\\u0646 \\u0633\\u062e\\u062a\\u200c\\u062a\\u0631 \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u062e\\u0648\\u0628\\u06cc \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus is enlarging and you may feel pressure in the back and pelvis. The cardiovascular system works harder to support the baby as the body adapts well.\"}','{\"fa\":\"\\u0628\\u0627 \\u062d\\u0633 \\u06a9\\u0631\\u062f\\u0646 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0627\\u062d\\u062a\\u0645\\u0627\\u0644\\u06cc \\u062c\\u0646\\u06cc\\u0646\\u060c \\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0639\\u0627\\u0637\\u0641\\u06cc \\u0639\\u0645\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0631\\u0648\\u06cc\\u0627\\u0647\\u0627\\u06cc \\u0648\\u0627\\u0636\\u062d\\u200c\\u062a\\u0631\\u06cc \\u0647\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u062d\\u0641\\u0638 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"Feeling possible baby movements deepens the emotional bond. You may also have more vivid dreams; staying calm and well rested matters.\"}','{\"fa\":\"\\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 D \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0631\\u0634\\u062f \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646 \\u0648 \\u0639\\u0636\\u0644\\u0647 \\u062c\\u0646\\u06cc\\u0646 \\u0636\\u0631\\u0648\\u0631\\u06cc \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0622\\u0647\\u0646 \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u06a9\\u0645\\u200c\\u062e\\u0648\\u0646\\u06cc \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0645\\u06cc\\u0648\\u0647\\u060c \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u062e\\u0648\\u0631\\u06cc\\u062f.\",\"en\":\"Calcium, vitamin D and protein are essential for the baby\\u2019s bones and muscles. Continue iron to prevent anemia and eat fruit, vegetables and enough water.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0642\\u0648\\u06cc\\u062a \\u06a9\\u0645\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0646\\u0627\\u06af\\u0647\\u0627\\u0646\\u06cc \\u0648 \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga suit this week. Keep pelvic floor and back-strengthening exercises and avoid sudden or risky moves.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u06a9\\u0648\\u0627\\u062f \\u0631\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u0622\\u062e\\u0631\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0627\\u0633\\u062a. \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0648 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"If you haven\\u2019t had the quad screen, these are the last suitable weeks. The anomaly scan will be scheduled soon; routine visits and growth checks continue.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0631\\u0627 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0639\\u0631\\u0642 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u062d\\u062c\\u0645 \\u062e\\u0648\\u0646 \\u0648 \\u0645\\u062a\\u0627\\u0628\\u0648\\u0644\\u06cc\\u0633\\u0645 \\u062f\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0627\\u0639\\u062b \\u062a\\u0639\\u0631\\u06cc\\u0642 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u06a9\\u0647 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a.\"},{\"question\":\"\\u0631\\u0648\\u06cc\\u0627\\u0647\\u0627\\u06cc \\u0648\\u0627\\u0636\\u062d \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0686\\u0631\\u0627 \\u0631\\u062e \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f\\u061f\",\"answer\":\"\\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0647\\u0648\\u0631\\u0645\\u0648\\u0646\\u06cc \\u0648 \\u06a9\\u06cc\\u0641\\u06cc\\u062a \\u062e\\u0648\\u0627\\u0628 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0639\\u062b \\u0631\\u0648\\u06cc\\u0627\\u0647\\u0627\\u06cc \\u0632\\u0646\\u062f\\u0647\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f \\u0648 \\u062c\\u0627\\u06cc \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u0646\\u06cc\\u0633\\u062a.\"}],\"en\":[{\"question\":\"Why am I sweating more?\",\"answer\":\"Increased blood volume and metabolism in pregnancy cause more sweating, which is usually normal.\"},{\"question\":\"Why do I have vivid pregnancy dreams?\",\"answer\":\"Hormonal changes and sleep quality can cause more vivid dreams and are nothing to worry about.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(18,18,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0647\\u062c\\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0641\\u0644\\u0641\\u0644 \\u062f\\u0644\\u0645\\u0647\\u200c\\u0627\\u06cc\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f1\\u06f4.\\u06f2 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1\\u06f9\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u06af\\u0648\\u0634\\u200c\\u0647\\u0627 \\u0628\\u0647 \\u0645\\u0648\\u0642\\u0639\\u06cc\\u062a \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0631\\u0633\\u06cc\\u062f\\u0647\\u200c\\u0627\\u0646\\u062f \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0635\\u062f\\u0627\\u0647\\u0627 \\u0631\\u0627 \\u0645\\u06cc\\u200c\\u0634\\u0646\\u0648\\u062f. \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u0639\\u0635\\u0628\\u06cc \\u0628\\u0647\\u200c\\u0633\\u0631\\u0639\\u062a \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u06a9\\u0627\\u0645\\u0644 \\u0627\\u0633\\u062a.\",\"en\":\"At week eighteen the fetus is about the size of a bell pepper, roughly 14.2 cm and nearly 190 g. The ears have reached their final position and the baby hears sounds, while the nervous system develops rapidly.\"}','{\"fa\":\"\\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0648\\u0627\\u0636\\u062d\\u200c\\u062a\\u0631 \\u062d\\u0633 \\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f\\u060c \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0639\\u0636\\u0644\\u0627\\u062a \\u067e\\u0627 \\u0648 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0634\\u062a\\u0647\\u0627 \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0645\\u0631\\u06a9\\u0632 \\u062b\\u0642\\u0644 \\u0628\\u062f\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u06a9\\u0631\\u062f\\u0647 \\u0648 \\u062a\\u0639\\u0627\\u062f\\u0644 \\u06a9\\u0645\\u06cc \\u0645\\u062a\\u0641\\u0627\\u0648\\u062a \\u0627\\u0633\\u062a.\",\"en\":\"Baby movements may feel clearer. You might experience back pain, leg cramps and more appetite, and your shifting center of gravity slightly changes balance.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u0635\\u0631\\u0641 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u0647 \\u067e\\u0634\\u062a \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u06a9\\u0641\\u0634 \\u0631\\u0627\\u062d\\u062a \\u0628\\u067e\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u062f\\u0631\\u0633\\u062a \\u0631\\u0627 \\u0631\\u0639\\u0627\\u06cc\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and avoid long back-lying. Wear comfortable shoes, keep good posture, and drink enough water.\"}','{\"fa\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc (\\u0628\\u0631\\u0631\\u0633\\u06cc \\u062f\\u0642\\u06cc\\u0642 \\u0622\\u0646\\u0627\\u062a\\u0648\\u0645\\u06cc \\u062c\\u0646\\u06cc\\u0646) \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061b \\u0622\\u0646 \\u0631\\u0627 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0633\\u0648\\u0627\\u0644\\u0627\\u062a \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u0632\\u0634\\u06a9 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"The anomaly scan (detailed fetal anatomy check) is done from this week; schedule it. Keep regular visits and prepare your questions for the doctor.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0628\\u0647 \\u0646\\u0632\\u062f\\u06cc\\u06a9\\u06cc \\u0646\\u0627\\u0641 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0631\\u0648\\u06cc \\u0639\\u0631\\u0648\\u0642 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06af\\u0627\\u0647\\u06cc \\u0633\\u0631\\u06af\\u06cc\\u062c\\u0647 \\u0627\\u06cc\\u062c\\u0627\\u062f \\u06a9\\u0646\\u062f. \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 \\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f\\u0646 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0648\\u0632\\u0646 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus now nears the navel and pressure on vessels may cause occasional dizziness. Side-sleeping becomes more comfortable as the body adapts to weight changes.\"}','{\"fa\":\"\\u062d\\u0633 \\u06a9\\u0631\\u062f\\u0646 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u063a\\u0644\\u0628 \\u0634\\u0627\\u062f\\u06cc \\u0648 \\u0627\\u0637\\u0645\\u06cc\\u0646\\u0627\\u0646 \\u0645\\u06cc\\u200c\\u0622\\u0648\\u0631\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0646\\u0648\\u0632\\u0627\\u062f \\u0647\\u06cc\\u062c\\u0627\\u0646\\u200c\\u0632\\u062f\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u06af\\u0631 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u062f\\u0627\\u0631\\u06cc\\u062f\\u060c \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0622\\u0646 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Feeling the baby move often brings joy and reassurance. You may be excited to prepare for the baby; if anxious, talk about it.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0648 \\u067e\\u062a\\u0627\\u0633\\u06cc\\u0645 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u0646\\u062f \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0639\\u0636\\u0644\\u0627\\u062a \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u0646\\u062f. \\u0645\\u0648\\u0632\\u060c \\u0644\\u0628\\u0646\\u06cc\\u0627\\u062a\\u060c \\u0645\\u063a\\u0632\\u0647\\u0627 \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0628\\u0631\\u06af\\u200c\\u0633\\u0628\\u0632 \\u0645\\u0641\\u06cc\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"Iron, calcium, magnesium and potassium can help reduce cramps. Bananas, dairy, nuts and leafy greens help; drink enough water.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0639\\u0636\\u0644\\u0627\\u062a \\u067e\\u0627 \\u0627\\u0632 \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0627\\u06cc\\u0633\\u062a\\u0627\\u062f\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle leg stretches help prevent cramps. Keep pelvic floor exercises and avoid standing for long periods.\"}','{\"fa\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u062f\\u0642\\u06cc\\u0642 \\u0633\\u0627\\u062e\\u062a\\u0627\\u0631 \\u0642\\u0644\\u0628\\u060c \\u0645\\u063a\\u0632\\u060c \\u0633\\u062a\\u0648\\u0646 \\u0641\\u0642\\u0631\\u0627\\u062a \\u0648 \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u062c\\u0646\\u0633\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0646\\u06cc\\u0632 \\u0627\\u063a\\u0644\\u0628 \\u0642\\u0627\\u0628\\u0644 \\u062a\\u0634\\u062e\\u06cc\\u0635 \\u0627\\u0633\\u062a. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"The anomaly ultrasound to examine the heart, brain, spine and organs in detail is done from this week. The baby\\u2019s sex is often identifiable, and routine visits continue.\"}','{\"fa\":[{\"question\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0686\\u0647 \\u0686\\u06cc\\u0632\\u0647\\u0627\\u06cc\\u06cc \\u0631\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u061f\",\"answer\":\"\\u0633\\u0627\\u062e\\u062a\\u0627\\u0631 \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627\\u060c \\u0642\\u0644\\u0628\\u060c \\u0645\\u063a\\u0632\\u060c \\u0633\\u062a\\u0648\\u0646 \\u0641\\u0642\\u0631\\u0627\\u062a\\u060c \\u062c\\u0641\\u062a \\u0648 \\u0645\\u0627\\u06cc\\u0639 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0631\\u0627 \\u0628\\u0627 \\u062f\\u0642\\u062a \\u0627\\u0631\\u0632\\u06cc\\u0627\\u0628\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u062a\\u0627 \\u0627\\u0632 \\u0631\\u0634\\u062f \\u0633\\u0627\\u0644\\u0645 \\u0627\\u0637\\u0645\\u06cc\\u0646\\u0627\\u0646 \\u062d\\u0627\\u0635\\u0644 \\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0628\\u0631\\u0627\\u06cc \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0639\\u0636\\u0644\\u0627\\u062a \\u067e\\u0627 \\u0686\\u0647 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645\\u060c \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0648 \\u0645\\u0648\\u0627\\u062f \\u0645\\u0639\\u062f\\u0646\\u06cc \\u0645\\u0627\\u0646\\u0646\\u062f \\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0648 \\u067e\\u062a\\u0627\\u0633\\u06cc\\u0645 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u061b \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f \\u0648 \\u0645\\u062f\\u0627\\u0648\\u0645 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"What does the anomaly scan check?\",\"answer\":\"It carefully assesses the organs, heart, brain, spine, placenta and amniotic fluid to confirm healthy development.\"},{\"question\":\"What helps leg cramps?\",\"answer\":\"Gentle stretching, enough water and minerals like magnesium and potassium help; see a doctor if pain is severe or constant.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(19,19,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0646\\u0648\\u0632\\u062f\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0627\\u0646\\u0628\\u0647\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f1\\u06f5.\\u06f3 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f2\\u06f4\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u067e\\u0648\\u0634\\u0634 \\u0645\\u062d\\u0627\\u0641\\u0638 \\u0686\\u0631\\u0628\\u06cc\\u200c\\u0645\\u0627\\u0646\\u0646\\u062f\\u06cc \\u0628\\u0647 \\u0646\\u0627\\u0645 \\u0648\\u0631\\u0646\\u06cc\\u06a9\\u0633 \\u0631\\u0648\\u06cc \\u067e\\u0648\\u0633\\u062a \\u0634\\u06a9\\u0644 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u062f. \\u062d\\u0648\\u0627\\u0633 \\u0628\\u06cc\\u0646\\u0627\\u06cc\\u06cc\\u060c \\u0634\\u0646\\u0648\\u0627\\u06cc\\u06cc \\u0648 \\u0686\\u0634\\u0627\\u06cc\\u06cc \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u06a9\\u0627\\u0645\\u0644 \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"At week nineteen the fetus is about the size of a mango, roughly 15.3 cm and nearly 240 g. A protective waxy coating called vernix forms on the skin, and sight, hearing and taste are developing.\"}','{\"fa\":\"\\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0646\\u0638\\u0645\\u200c\\u062a\\u0631 \\u0648 \\u0648\\u0627\\u0636\\u062d\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f\\u060c \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u067e\\u0648\\u0633\\u062a\\u06cc \\u06cc\\u0627 \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0628\\u06cc\\u0646\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0631\\u0634\\u062f \\u0634\\u06a9\\u0645 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0631 \\u062a\\u0639\\u0627\\u062f\\u0644 \\u0648 \\u0631\\u0627\\u0647 \\u0631\\u0641\\u062a\\u0646 \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f.\",\"en\":\"Baby movements become more regular and clear. You may have back pain, skin changes or nasal congestion, and the growing bump can affect balance and walking.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u0627\\u0633\\u062a\\u0631\\u0633 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0627\\u0647\\u0634 \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0627\\u0632 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062f\\u0631\\u0633\\u062a \\u0628\\u062f\\u0646 \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue balanced nutrition and supplements and avoid excess stress. Use good posture and rest to ease back pain, and stay active.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0631\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0646\\u0627\\u0633\\u0628\\u06cc \\u0627\\u0633\\u062a. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0645\\u0627\\u0646\\u0646\\u062f \\u0648\\u0631\\u0645 \\u0634\\u062f\\u06cc\\u062f \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\",\"en\":\"If you haven\\u2019t had the anomaly scan, this is a good week. Keep regular visits and blood-pressure checks, and take warning signs like severe swelling seriously.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0647 \\u0633\\u0637\\u062d \\u0646\\u0627\\u0641 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u067e\\u0648\\u0633\\u062a \\u0634\\u06a9\\u0645 \\u06a9\\u0634\\u06cc\\u062f\\u0647 \\u0648 \\u062d\\u0633\\u0627\\u0633 \\u0634\\u0648\\u062f. \\u0631\\u0628\\u0627\\u0637\\u200c\\u0647\\u0627 \\u0634\\u0644\\u200c\\u062a\\u0631 \\u0634\\u062f\\u0647\\u200c\\u0627\\u0646\\u062f \\u06a9\\u0647 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0631 \\u0645\\u0641\\u0627\\u0635\\u0644 \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u0645\\u0648\\u0641\\u0642\\u06cc\\u062a \\u062e\\u0648\\u062f \\u0631\\u0627 \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus reaches the navel and the belly skin may stretch and feel tender. Ligaments are looser, which can affect joints, as the body adjusts successfully.\"}','{\"fa\":\"\\u0628\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645\\u060c \\u062d\\u0633 \\u0645\\u0627\\u062f\\u0631\\u0627\\u0646\\u0647 \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0646\\u062a\\u062e\\u0627\\u0628 \\u0646\\u0627\\u0645 \\u0648 \\u062e\\u0631\\u06cc\\u062f \\u0644\\u0648\\u0627\\u0632\\u0645 \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u06af\\u0631 \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u062f \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"With regular movements the maternal bond grows stronger. You may be excited to choose names and buy items; if worried, talk to your doctor.\"}','{\"fa\":\"\\u0622\\u0647\\u0646 \\u0648 \\u0648\\u06cc\\u062a\\u0627\\u0645\\u06cc\\u0646 C \\u0631\\u0627 \\u0628\\u0627 \\u0647\\u0645 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f \\u062a\\u0627 \\u062c\\u0630\\u0628 \\u0622\\u0647\\u0646 \\u0628\\u0647\\u062a\\u0631 \\u0634\\u0648\\u062f \\u0648 \\u0627\\u0632 \\u06a9\\u0645\\u200c\\u062e\\u0648\\u0646\\u06cc \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u06a9\\u0646\\u062f. \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0628\\u0631\\u0627\\u06cc \\u06af\\u0648\\u0627\\u0631\\u0634 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"Take iron with vitamin C to boost absorption and prevent anemia. Continue calcium and protein, and keep enough water and fiber for digestion.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0648 \\u0628\\u0647\\u0628\\u0648\\u062f \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u062a\\u0639\\u0627\\u062f\\u0644 \\u062e\\u0648\\u062f \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0627\\u0641\\u0631\\u0627\\u0637 \\u0646\\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga ease back pain and improve sleep. Keep pelvic floor exercises, mind your balance, and don\\u2019t overdo it.\"}','{\"fa\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0628\\u0627\\u0632\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645\\u200c\\u0634\\u062f\\u0646\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646 \\u0648 \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u063a\\u06cc\\u0631\\u0639\\u0627\\u062f\\u06cc \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"The anomaly scan is still possible now and fetal growth is assessed. Routine visits include blood pressure, weight and fetal heartbeat; report unusual symptoms.\"}','{\"fa\":[{\"question\":\"\\u0648\\u0631\\u0646\\u06cc\\u06a9\\u0633 \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u067e\\u0648\\u0634\\u0634 \\u0645\\u0648\\u0645\\u06cc\\u200c\\u0634\\u06a9\\u0644\\u06cc \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u067e\\u0648\\u0633\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062f\\u0631 \\u0628\\u0631\\u0627\\u0628\\u0631 \\u0645\\u0627\\u06cc\\u0639 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0645\\u062d\\u0627\\u0641\\u0638\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u062a\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u0642\\u06cc \\u0645\\u06cc\\u200c\\u0645\\u0627\\u0646\\u062f.\"},{\"question\":\"\\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0686\\u0637\\u0648\\u0631 \\u06a9\\u0627\\u0647\\u0634 \\u062f\\u0647\\u0645\\u061f\",\"answer\":\"\\u0648\\u0636\\u0639\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u062f\\u0631\\u0633\\u062a\\u060c \\u06a9\\u0641\\u0634 \\u0631\\u0627\\u062d\\u062a\\u060c \\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0648 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0627\\u0632 \\u0628\\u0627\\u0644\\u0634 \\u0647\\u0646\\u06af\\u0627\\u0645 \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u061b \\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0637\\u0631\\u062d \\u06a9\\u0646\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"What is vernix?\",\"answer\":\"It is a waxy coating that protects the baby\\u2019s skin from amniotic fluid and remains until near birth.\"},{\"question\":\"How can I reduce pregnancy back pain?\",\"answer\":\"Good posture, comfortable shoes, gentle stretching and a pillow while sleeping help; report severe pain to your doctor.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(20,20,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u0645 \\u06a9\\u0647 \\u0646\\u06cc\\u0645\\u0647 \\u0631\\u0627\\u0647 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0633\\u062a\\u060c \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0645\\u0648\\u0632\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f2\\u06f5 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 (\\u0627\\u0632 \\u0633\\u0631 \\u062a\\u0627 \\u067e\\u0627\\u0634\\u0646\\u0647) \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f3\\u06f0\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647\\u200c\\u0637\\u0648\\u0631 \\u0645\\u0646\\u0638\\u0645 \\u062d\\u0631\\u06a9\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u060c \\u0645\\u06cc\\u200c\\u0628\\u0644\\u0639\\u062f \\u0648 \\u0627\\u0644\\u06af\\u0648\\u06cc \\u062e\\u0648\\u0627\\u0628 \\u0648 \\u0628\\u06cc\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0631\\u062f. \\u0645\\u0648 \\u0648 \\u0646\\u0627\\u062e\\u0646\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0631\\u0634\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"At week twenty, the halfway point, the fetus is about the size of a banana, roughly 25 cm crown-to-heel and nearly 300 g. The baby moves regularly, swallows, and has sleep-wake patterns, while hair and nails grow.\"}','{\"fa\":\"\\u0634\\u06a9\\u0645 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0628\\u0647\\u200c\\u0648\\u0636\\u0648\\u062d \\u0628\\u0631\\u062c\\u0633\\u062a\\u0647 \\u0627\\u0633\\u062a \\u0648 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0646\\u0638\\u0645 \\u062d\\u0633 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644\\u060c \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633 \\u062e\\u0641\\u06cc\\u0641 \\u06cc\\u0627 \\u062a\\u0648\\u0631\\u0645 \\u067e\\u0627 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u067e\\u0648\\u0633\\u062a \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062f\\u0686\\u0627\\u0631 \\u062a\\u0631\\u06a9\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0634\\u0634\\u06cc \\u0634\\u0648\\u062f.\",\"en\":\"The bump is now clearly visible and baby movements are felt regularly. You may have heartburn, mild shortness of breath or leg swelling, and stretch marks can appear.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 (\\u062a\\u0631\\u062c\\u06cc\\u062d\\u0627\\u064b \\u0686\\u067e) \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f. \\u0627\\u0632 \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0627\\u0647\\u0634 \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and sleep on your side, preferably the left. Avoid heavy meals to reduce heartburn and stay active.\"}','{\"fa\":\"\\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u0645 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0639\\u0645\\u0648\\u0644 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0627\\u0633\\u062a\\u061b \\u0627\\u06af\\u0631 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f \\u062d\\u062a\\u0645\\u0627\\u064b \\u0647\\u0645\\u0627\\u0647\\u0646\\u06af \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0634\\u0631\\u0648\\u0639 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Week twenty is the usual time for the anomaly scan; if not done, arrange it. Keep regular visits and blood-pressure checks and begin noting fetal movements.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0647 \\u0633\\u0637\\u062d \\u0646\\u0627\\u0641 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u0645\\u0631\\u06a9\\u0632 \\u062b\\u0642\\u0644 \\u062c\\u062f\\u06cc\\u062f \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0645\\u0639\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0627\\u06cc\\u062c\\u0627\\u062f \\u06a9\\u0646\\u062f. \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u06af\\u0631\\u062f\\u0634 \\u062e\\u0648\\u0646 \\u0628\\u0627 \\u0642\\u062f\\u0631\\u062a \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus reaches the navel and the body has adjusted to a new center of gravity. Pressure on the stomach can cause heartburn as circulation works strongly.\"}','{\"fa\":\"\\u0631\\u0633\\u06cc\\u062f\\u0646 \\u0628\\u0647 \\u0646\\u06cc\\u0645\\u0647 \\u0631\\u0627\\u0647 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u063a\\u0644\\u0628 \\u062d\\u0633 \\u062f\\u0633\\u062a\\u0627\\u0648\\u0631\\u062f \\u0648 \\u0627\\u0645\\u06cc\\u062f\\u0648\\u0627\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u0622\\u0648\\u0631\\u062f. \\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0628\\u0627 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0632 \\u0637\\u0631\\u06cc\\u0642 \\u062d\\u0631\\u06a9\\u0627\\u062a\\u0634 \\u0639\\u0645\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Reaching the halfway point often brings a sense of achievement and hope. The bond deepens through the baby\\u2019s movements; keep up self-care and rest.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0628\\u062e\\u0648\\u0631\\u06cc\\u062f. \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u062a\\u0646\\u062f \\u0648 \\u0686\\u0631\\u0628 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0622\\u0628 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue iron, calcium and protein and eat small frequent meals for heartburn. Avoid spicy and greasy foods and get enough water and fiber.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u06cc\\u062f\\u0647\\u200c\\u0622\\u0644 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0628\\u0647 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u062f\\u0631\\u0627\\u0632 \\u06a9\\u0634\\u06cc\\u062f\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u0647 \\u067e\\u0634\\u062a \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga are ideal this week. Pelvic floor exercises help prepare for birth; avoid long back-lying.\"}','{\"fa\":\"\\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0648\\u0645\\u0627\\u0644\\u06cc \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u06f1\\u06f8 \\u062a\\u0627 \\u06f2\\u06f2 \\u0648 \\u0627\\u063a\\u0644\\u0628 \\u062f\\u0631 \\u0647\\u0645\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0622\\u0646\\u0627\\u062a\\u0648\\u0645\\u06cc \\u06a9\\u0627\\u0645\\u0644 \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646 \\u0648 \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a.\",\"en\":\"The anomaly scan is usually done in weeks 18 to 22, often this week, examining the baby\\u2019s full anatomy. Routine visits include blood pressure, weight and fetal heartbeat.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0631\\u0627 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u0645 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0627\\u06cc\\u0646 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0622\\u0646\\u0627\\u062a\\u0648\\u0645\\u06cc \\u06a9\\u0627\\u0645\\u0644 \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u0628\\u0633\\u06cc\\u0627\\u0631\\u06cc \\u0627\\u0632 \\u0646\\u0627\\u0647\\u0646\\u062c\\u0627\\u0631\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0627\\u062e\\u062a\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0645\\u0631\\u062d\\u0644\\u0647 \\u0634\\u0646\\u0627\\u0633\\u0627\\u06cc\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"},{\"question\":\"\\u0628\\u0631\\u0627\\u06cc \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0686\\u0647 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9\\u060c \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u0627\\u0632 \\u063a\\u0630\\u0627\\u06cc \\u062a\\u0646\\u062f \\u0648 \\u0686\\u0631\\u0628\\u060c \\u0648 \\u0646\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f\\u0646 \\u0628\\u0644\\u0627\\u0641\\u0627\\u0635\\u0644\\u0647 \\u067e\\u0633 \\u0627\\u0632 \\u063a\\u0630\\u0627 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u061b \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0634\\u062f\\u06cc\\u062f \\u0628\\u0648\\u062f\\u0646 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0634\\u0648\\u0631\\u062a \\u06a9\\u0646\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"Why is the week-20 scan important?\",\"answer\":\"It reviews the baby\\u2019s full anatomy and detects many structural anomalies at this stage.\"},{\"question\":\"What helps heartburn?\",\"answer\":\"Small meals, avoiding spicy and greasy food, and not lying down right after eating help; see a doctor if severe.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(21,21,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u06cc\\u06a9\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0647\\u0648\\u06cc\\u062c\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f2\\u06f6.\\u06f7 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f3\\u06f6\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0627\\u06cc\\u0639 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0631\\u0627 \\u0645\\u06cc\\u200c\\u0628\\u0644\\u0639\\u062f \\u06a9\\u0647 \\u0628\\u0647 \\u0631\\u0634\\u062f \\u062f\\u0633\\u062a\\u06af\\u0627\\u0647 \\u06af\\u0648\\u0627\\u0631\\u0634 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062f\\u0633\\u062a \\u0648 \\u067e\\u0627 \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631 \\u0648 \\u0645\\u0646\\u0638\\u0645\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"At week twenty-one the fetus is about the size of a carrot, roughly 26.7 cm and nearly 360 g. The baby swallows amniotic fluid, aiding gut development, and limb movements grow stronger and more regular.\"}','{\"fa\":\"\\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0648\\u0627\\u0636\\u062d \\u0648 \\u0645\\u0646\\u0638\\u0645 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0634\\u062a\\u0647\\u0627\\u060c \\u062a\\u0648\\u0631\\u0645 \\u062e\\u0641\\u06cc\\u0641 \\u067e\\u0627 \\u0648 \\u062a\\u0631\\u06a9\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0648\\u0633\\u062a\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0647\\u0646\\u0648\\u0632 \\u062e\\u0648\\u0628 \\u0627\\u0633\\u062a.\",\"en\":\"Baby movements are now clear and regular. You may have more appetite, mild leg swelling and stretch marks, and energy is usually still good.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u067e\\u0627\\u0647\\u0627 \\u0631\\u0627 \\u0647\\u0646\\u06af\\u0627\\u0645 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0628\\u0627\\u0644\\u0627 \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f. \\u0627\\u0632 \\u0627\\u06cc\\u0633\\u062a\\u0627\\u062f\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0646\\u0645\\u06a9 \\u0631\\u0627 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and elevate your legs when resting. Avoid standing long, drink enough water, and moderate salt.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0628\\u0647 \\u06cc\\u06a9 \\u0639\\u0627\\u062f\\u062a \\u0631\\u0648\\u0632\\u0627\\u0646\\u0647 \\u062a\\u0628\\u062f\\u06cc\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0622\\u06cc\\u0646\\u062f\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0648\\u06cc\\u062f.\",\"en\":\"Keep regular visits and growth checks. Make counting baby movements a daily habit and prepare for gestational diabetes screening in coming weeks.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0639\\u0631\\u0648\\u0642 \\u067e\\u0627 \\u0628\\u0627\\u0639\\u062b \\u062a\\u0648\\u0631\\u0645 \\u0634\\u0648\\u062f. \\u0645\\u0641\\u0627\\u0635\\u0644 \\u0634\\u0644\\u200c\\u062a\\u0631 \\u0634\\u062f\\u0647\\u200c\\u0627\\u0646\\u062f \\u0648 \\u0631\\u0627\\u0647 \\u0631\\u0641\\u062a\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0645\\u062a\\u0641\\u0627\\u0648\\u062a \\u0628\\u0627\\u0634\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u0645\\u0648\\u0641\\u0642\\u06cc\\u062a \\u062e\\u0648\\u062f \\u0631\\u0627 \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus is above the navel and pressure on leg veins may cause swelling. Joints are looser and walking may feel different as the body adapts well.\"}','{\"fa\":\"\\u062d\\u0633 \\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0628\\u0627 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0632 \\u0637\\u0631\\u06cc\\u0642 \\u062d\\u0631\\u06a9\\u0627\\u062a\\u0634 \\u0639\\u0645\\u06cc\\u0642\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0627\\u062a\\u0627\\u0642 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u06af\\u0631 \\u06af\\u0627\\u0647\\u06cc \\u0646\\u06af\\u0631\\u0627\\u0646 \\u0647\\u0633\\u062a\\u06cc\\u062f\\u060c \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a.\",\"en\":\"The bond deepens through the baby\\u2019s movements. You may be excited to prepare the nursery; occasional worry is normal.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u063a\\u0646\\u06cc \\u0627\\u0632 \\u067e\\u062a\\u0627\\u0633\\u06cc\\u0645 \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u062a\\u0648\\u0631\\u0645 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u0642\\u0646\\u062f \\u0648 \\u0646\\u0645\\u06a9 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Continue iron, calcium and protein and eat enough fiber to prevent constipation. Potassium-rich foods help reduce swelling; limit excess sugar and salt.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u062a\\u0648\\u0631\\u0645 \\u0648 \\u0628\\u0647\\u0628\\u0648\\u062f \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga reduce swelling and improve sleep. Keep pelvic floor exercises and rest when tired.\"}','{\"fa\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646 \\u0648 \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062a\\u062d\\u0645\\u0644 \\u06af\\u0644\\u0648\\u06a9\\u0632 \\u067e\\u06cc\\u0634 \\u0631\\u0648 \\u062a\\u0648\\u0636\\u06cc\\u062d \\u062f\\u0647\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits this week include blood pressure, weight and fetal heartbeat. Your doctor may explain the upcoming glucose tolerance test; report warning signs.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0631\\u0627 \\u067e\\u0627\\u0647\\u0627\\u06cc\\u0645 \\u0648\\u0631\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f\\u061f\",\"answer\":\"\\u0641\\u0634\\u0627\\u0631 \\u0631\\u062d\\u0645 \\u0628\\u0631 \\u0639\\u0631\\u0648\\u0642 \\u0648 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0628\\u062f\\u0646 \\u0628\\u0627\\u0639\\u062b \\u062a\\u0648\\u0631\\u0645 \\u062e\\u0641\\u06cc\\u0641 \\u067e\\u0627 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061b \\u0628\\u0627\\u0644\\u0627 \\u06af\\u0630\\u0627\\u0634\\u062a\\u0646 \\u067e\\u0627\\u0647\\u0627 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0627\\u0645\\u0627 \\u062a\\u0648\\u0631\\u0645 \\u0646\\u0627\\u06af\\u0647\\u0627\\u0646\\u06cc \\u0648 \\u0634\\u062f\\u06cc\\u062f \\u0631\\u0627 \\u0628\\u0647 \\u067e\\u0632\\u0634\\u06a9 \\u0628\\u06af\\u0648\\u06cc\\u06cc\\u062f.\"},{\"question\":\"\\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0686\\u06af\\u0648\\u0646\\u0647 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u062f\\u0631 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0634\\u062e\\u0635\\u06cc \\u0627\\u0632 \\u0631\\u0648\\u0632 \\u06a9\\u0647 \\u062c\\u0646\\u06cc\\u0646 \\u0641\\u0639\\u0627\\u0644\\u200c\\u062a\\u0631 \\u0627\\u0633\\u062a\\u060c \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0631\\u0627 \\u0628\\u0634\\u0645\\u0627\\u0631\\u06cc\\u062f\\u061b \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u062d\\u0633\\u0648\\u0633 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0628\\u0627\\u06cc\\u062f \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"Why are my legs swelling?\",\"answer\":\"Uterine pressure on veins and more body fluid cause mild leg swelling; elevating the legs helps, but report sudden severe swelling.\"},{\"question\":\"How do I count baby movements?\",\"answer\":\"Count movements at a set time when the baby is active; a noticeable drop should be checked.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(22,22,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u062f\\u0648\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u067e\\u0627\\u067e\\u0627\\u06cc\\u0627\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f2\\u06f7.\\u06f8 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f4\\u06f3\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u062d\\u0633 \\u0644\\u0627\\u0645\\u0633\\u0647 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u06a9\\u0627\\u0645\\u0644 \\u0627\\u0633\\u062a \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0635\\u0648\\u0631\\u062a \\u0648 \\u0628\\u0646\\u062f \\u0646\\u0627\\u0641 \\u0631\\u0627 \\u0644\\u0645\\u0633 \\u06a9\\u0646\\u062f. \\u0627\\u0628\\u0631\\u0648\\u0647\\u0627 \\u0648 \\u0645\\u0698\\u0647\\u200c\\u0647\\u0627 \\u0638\\u0627\\u0647\\u0631 \\u0634\\u062f\\u0647\\u200c\\u0627\\u0646\\u062f.\",\"en\":\"At week twenty-two the fetus is about the size of a papaya, roughly 27.8 cm and nearly 430 g. The sense of touch is developing and the baby may touch its face and cord, while eyebrows and eyelashes have appeared.\"}','{\"fa\":\"\\u0634\\u06a9\\u0645 \\u0628\\u0647\\u200c\\u0648\\u0636\\u0648\\u062d \\u0628\\u0632\\u0631\\u06af \\u0634\\u062f\\u0647 \\u0648 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0648\\u0631\\u0645 \\u062e\\u0641\\u06cc\\u0641\\u060c \\u0648\\u0627\\u0631\\u06cc\\u0633 \\u06cc\\u0627 \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u0644\\u062b\\u0647 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0645\\u0648\\u0647\\u0627 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u067e\\u0631\\u067e\\u0634\\u062a\\u200c\\u062a\\u0631 \\u0628\\u0647 \\u0646\\u0638\\u0631 \\u0628\\u0631\\u0633\\u0646\\u062f.\",\"en\":\"The belly is clearly larger and movements are stronger. You may have mild swelling, varicose veins or gum sensitivity, and hair may look fuller.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u0648\\u0627\\u0631\\u06cc\\u0633 \\u0632\\u06cc\\u0627\\u062f \\u0646\\u0627\\u06cc\\u0633\\u062a\\u06cc\\u062f. \\u0628\\u0647\\u062f\\u0627\\u0634\\u062a \\u062f\\u0647\\u0627\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and avoid prolonged standing to prevent varicose veins. Take oral hygiene seriously and stay active.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0647\\u0645\\u0627\\u0647\\u0646\\u06af \\u06a9\\u0646\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0644\\u0627\\u0633\\u200c\\u0647\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep regular visits and coordinate the gestational diabetes test with your doctor. Continue counting movements and plan for childbirth classes.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0639\\u0631\\u0648\\u0642 \\u0644\\u06af\\u0646 \\u0628\\u0627\\u0639\\u062b \\u0648\\u0627\\u0631\\u06cc\\u0633 \\u06cc\\u0627 \\u0628\\u0648\\u0627\\u0633\\u06cc\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u062c\\u0645 \\u062e\\u0648\\u0646 \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0628\\u0627\\u0644\\u0627\\u0633\\u062a. \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u062e\\u0648\\u0628\\u06cc \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0631\\u0627 \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus is above the navel and pelvic vein pressure may cause varicose veins or hemorrhoids. Blood volume remains high as the body manages these changes.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u06cc\\u0646 \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0645\\u0633\\u0626\\u0648\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u067e\\u06cc\\u0634 \\u0631\\u0648 \\u062f\\u0631 \\u0646\\u0648\\u0633\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u0631\\u062a\\u0628\\u0627\\u0637 \\u0628\\u0627 \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0635\\u062d\\u0628\\u062a \\u0628\\u0627 \\u0647\\u0645\\u0633\\u0631 \\u0648 \\u062f\\u0648\\u0633\\u062a\\u0627\\u0646 \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"You may swing between excitement and worry about upcoming responsibilities. The bond strengthens; talking with your partner and friends helps.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u0641\\u06cc\\u0628\\u0631 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0648 \\u0628\\u0648\\u0627\\u0633\\u06cc\\u0631 \\u0645\\u0647\\u0645 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0633\\u0628\\u0632\\u06cc\\u062c\\u0627\\u062a \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0641\\u0631\\u0622\\u0648\\u0631\\u06cc\\u200c\\u0634\\u062f\\u0647 \\u0648 \\u0642\\u0646\\u062f \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Iron, calcium, fiber and enough water matter to prevent constipation and hemorrhoids. Keep protein and vegetables; limit processed foods and sugar.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0647 \\u06af\\u0631\\u062f\\u0634 \\u062e\\u0648\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u0627\\u0632 \\u0648\\u0627\\u0631\\u06cc\\u0633 \\u0645\\u06cc\\u200c\\u06a9\\u0627\\u0647\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0646\\u0634\\u0633\\u062a\\u0646 \\u06cc\\u0627 \\u0627\\u06cc\\u0633\\u062a\\u0627\\u062f\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle exercise aid circulation and reduce varicose veins. Keep pelvic floor work and avoid sitting or standing too long.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646 \\u0648 \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062a\\u062d\\u0645\\u0644 \\u06af\\u0644\\u0648\\u06a9\\u0632 \\u0628\\u0631\\u0627\\u06cc \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06f2\\u06f4 \\u062a\\u0627 \\u06f2\\u06f8 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u063a\\u06cc\\u0631\\u0639\\u0627\\u062f\\u06cc \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits include blood pressure, weight and fetal growth. The glucose tolerance test for gestational diabetes is usually scheduled in weeks 24 to 28.\"}','{\"fa\":[{\"question\":\"\\u0648\\u0627\\u0631\\u06cc\\u0633 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062e\\u0637\\u0631\\u0646\\u0627\\u06a9 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0648\\u0627\\u0631\\u06cc\\u0633 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0628\\u06cc\\u200c\\u062e\\u0637\\u0631 \\u0627\\u0633\\u062a \\u0648 \\u0627\\u063a\\u0644\\u0628 \\u067e\\u0633 \\u0627\\u0632 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0647\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061b \\u062d\\u0631\\u06a9\\u062a \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u0628\\u0627\\u0644\\u0627 \\u06af\\u0630\\u0627\\u0634\\u062a\\u0646 \\u067e\\u0627\\u0647\\u0627 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"},{\"question\":\"\\u0628\\u0648\\u0627\\u0633\\u06cc\\u0631 \\u062f\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0686\\u0631\\u0627 \\u0631\\u062e \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f\\u061f\",\"answer\":\"\\u0641\\u0634\\u0627\\u0631 \\u0631\\u062d\\u0645 \\u0648 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0639\\u062b \\u0628\\u0648\\u0627\\u0633\\u06cc\\u0631 \\u0634\\u0648\\u062f\\u061b \\u0641\\u06cc\\u0628\\u0631\\u060c \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0648 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u0627\\u0632 \\u0632\\u0648\\u0631 \\u0632\\u062f\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"}],\"en\":[{\"question\":\"Are pregnancy varicose veins dangerous?\",\"answer\":\"They are usually harmless and often improve after birth; regular movement and elevating the legs help.\"},{\"question\":\"Why do hemorrhoids happen in pregnancy?\",\"answer\":\"Uterine pressure and constipation can cause them; fiber, water and avoiding straining help.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(23,23,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u0633\\u0648\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06af\\u0631\\u06cc\\u067e\\u200c\\u0641\\u0631\\u0648\\u062a\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f2\\u06f8.\\u06f9 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f5\\u06f0\\u06f1 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u06a9\\u0627\\u0645\\u0644 \\u0631\\u06af\\u200c\\u0647\\u0627\\u06cc \\u062e\\u0648\\u0646\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0646\\u0641\\u0633 \\u0622\\u06cc\\u0646\\u062f\\u0647 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0635\\u062f\\u0627\\u0647\\u0627\\u06cc \\u0628\\u06cc\\u0631\\u0648\\u0646 \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0648\\u062f \\u0648 \\u0628\\u0647 \\u0622\\u0646\\u200c\\u0647\\u0627 \\u0648\\u0627\\u06a9\\u0646\\u0634 \\u0646\\u0634\\u0627\\u0646 \\u062f\\u0647\\u062f.\",\"en\":\"At week twenty-three the fetus is about the size of a grapefruit, roughly 28.9 cm and nearly 501 g. The lungs are developing blood vessels for future breathing, and the baby can hear and respond to outside sounds.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0648\\u0631\\u0645 \\u067e\\u0627 \\u0648 \\u062f\\u0633\\u062a\\u060c \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0648 \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0648 \\u0642\\u0627\\u0628\\u0644 \\u0645\\u0634\\u0627\\u0647\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u067e\\u0648\\u0633\\u062a \\u0634\\u06a9\\u0645 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u06a9\\u0634\\u06cc\\u062f\\u0647 \\u0648 \\u062d\\u0633\\u0627\\u0633 \\u0634\\u0648\\u062f.\",\"en\":\"Leg and hand swelling, heartburn and back pain may increase. Baby movements are strong and visible, and the belly skin may stretch and feel more tender.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0628\\u0627\\u0644\\u0627 \\u0645\\u0627\\u0646\\u0646\\u062f \\u0633\\u0631\\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u067e\\u0627\\u0647\\u0627 \\u0631\\u0627 \\u0628\\u0627\\u0644\\u0627 \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take high-blood-pressure signs like severe headache seriously. Elevate your legs, rest, and drink enough water.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0648\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633 \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f \\u0648 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0628\\u0631\\u0648\\u0632 \\u0641\\u0648\\u0631\\u0627\\u064b \\u0627\\u0642\\u062f\\u0627\\u0645 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep regular visits and prepare for the diabetes test. Continue counting movements, learn preterm labor signs, and act quickly if they appear.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u062e\\u0641\\u06cc\\u0641 (\\u0628\\u0631\\u0627\\u06a9\\u0633\\u062a\\u0648\\u0646 \\u0647\\u06cc\\u06a9\\u0633) \\u0631\\u0627 \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f. \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0645\\u062b\\u0627\\u0646\\u0647 \\u0648 \\u0645\\u0639\\u062f\\u0647 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0631\\u0627\\u062d\\u0644 \\u0628\\u0639\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus is above the navel and you may feel mild practice contractions (Braxton Hicks). Pressure on the bladder and stomach increases as the body prepares.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0634\\u062f\\u0646 \\u0628\\u0647 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645\\u060c \\u0627\\u0641\\u06a9\\u0627\\u0631 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u06a9\\u0645\\u06cc \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u0622\\u0645\\u0648\\u0632\\u0634 \\u0648 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u0628\\u062f\\u0647\\u062f.\",\"en\":\"As the third trimester nears you may think more about birth. Some anxiety is normal; education and preparation can bring more calm.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0645\\u0635\\u0631\\u0641 \\u0646\\u0645\\u06a9 \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u062a\\u0648\\u0631\\u0645 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0641\\u06cc\\u0628\\u0631 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u06af\\u0648\\u0627\\u0631\\u0634 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a. \\u0645\\u06cc\\u0627\\u0646\\u200c\\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0627\\u0644\\u0645 \\u0628\\u062e\\u0648\\u0631\\u06cc\\u062f.\",\"en\":\"Continue iron, calcium and protein and moderate salt to manage swelling. Fiber and enough water matter for digestion; choose healthy snacks.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0648 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0628\\u06cc\\u0634 \\u0627\\u0632 \\u062d\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga remain helpful. Practice breathing exercises for birth and avoid risky activities and overexertion.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646 \\u0648 \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062a\\u062d\\u0645\\u0644 \\u06af\\u0644\\u0648\\u06a9\\u0632 \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0648\\u062c\\u0648\\u062f \\u0631\\u06cc\\u0633\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633\\u060c \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0631\\u0633\\u06cc\\u200c\\u0647\\u0627\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u06a9\\u0646\\u062f.\",\"en\":\"Routine visits include blood pressure, weight and fetal growth. The glucose tolerance test is done soon; if preterm risk exists, the doctor may advise more checks.\"}','{\"fa\":[{\"question\":\"\\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0628\\u0631\\u0627\\u06a9\\u0633\\u062a\\u0648\\u0646 \\u0647\\u06cc\\u06a9\\u0633 \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0648 \\u0628\\u06cc\\u200c\\u062f\\u0631\\u062f \\u0631\\u062d\\u0645 \\u0647\\u0633\\u062a\\u0646\\u062f \\u06a9\\u0647 \\u0628\\u062f\\u0646 \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f\\u061b \\u0627\\u06af\\u0631 \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u062f\\u0631\\u062f\\u0646\\u0627\\u06a9 \\u0634\\u062f\\u0646\\u062f \\u0628\\u0647 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\"},{\"question\":\"\\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633 \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645\\u060c \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc\\u060c \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0645\\u062f\\u0627\\u0648\\u0645 \\u06cc\\u0627 \\u0646\\u0634\\u062a \\u0645\\u0627\\u06cc\\u0639 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0646\\u0634\\u0627\\u0646\\u0647 \\u0628\\u0627\\u0634\\u062f \\u0648 \\u0646\\u06cc\\u0627\\u0632 \\u0628\\u0647 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u0641\\u0648\\u0631\\u06cc \\u062f\\u0627\\u0631\\u062f.\"}],\"en\":[{\"question\":\"What are Braxton Hicks contractions?\",\"answer\":\"They are painless practice contractions preparing the body for labor; see a doctor if they become regular and painful.\"},{\"question\":\"What are signs of preterm labor?\",\"answer\":\"Regular contractions, pelvic pressure, constant back pain or fluid leakage can be signs needing urgent care.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(24,24,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u0686\\u0647\\u0627\\u0631\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0628\\u0644\\u0627\\u0644\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f3\\u06f0 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f6\\u06f0\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0645\\u0631\\u0632 \\u062d\\u06cc\\u0627\\u062a\\u200c\\u067e\\u0630\\u06cc\\u0631\\u06cc \\u062f\\u0631 \\u0646\\u0638\\u0631 \\u06af\\u0631\\u0641\\u062a\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0645\\u0627\\u062f\\u0647 \\u0633\\u0648\\u0631\\u0641\\u06a9\\u062a\\u0627\\u0646\\u062a \\u062a\\u0648\\u0644\\u06cc\\u062f \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f. \\u067e\\u0648\\u0633\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0647\\u0646\\u0648\\u0632 \\u0686\\u0631\\u0648\\u06a9\\u06cc\\u062f\\u0647 \\u0627\\u0633\\u062a \\u0627\\u0645\\u0627 \\u0686\\u0631\\u0628\\u06cc \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0627\\u0633\\u062a.\",\"en\":\"At week twenty-four the fetus is about the size of an ear of corn, roughly 30 cm and nearly 600 g. This week marks the threshold of viability and the lungs produce surfactant, while the skin is still wrinkled but fat is increasing.\"}','{\"fa\":\"\\u0634\\u06a9\\u0645 \\u0628\\u0632\\u0631\\u06af\\u200c\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644\\u060c \\u062a\\u0648\\u0631\\u0645 \\u0648 \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u067e\\u0648\\u0633\\u062a \\u0634\\u06a9\\u0645 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0628\\u06a9\\u0634\\u062f \\u0648 \\u062e\\u0627\\u0631\\u0634 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"The belly is larger and heartburn, swelling and back pain may increase. Movements are strong, and the belly skin may stretch more and itch.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u0628\\u0647\\u200c\\u0645\\u0648\\u0642\\u0639 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0648\\u0632\\u0646 \\u0646\\u0627\\u06af\\u0647\\u0627\\u0646\\u06cc \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0628\\u0627\\u0644\\u0627 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and do the diabetes test on time. Avoid sudden weight gain and take high-blood-pressure signs seriously.\"}','{\"fa\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062a\\u062d\\u0645\\u0644 \\u06af\\u0644\\u0648\\u06a9\\u0632 \\u0628\\u0631\\u0627\\u06cc \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061b \\u0622\\u0646 \\u0631\\u0627 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f.\",\"en\":\"The glucose tolerance test to screen for gestational diabetes is done from this week; complete it. Keep regular visits and movement counts, and know warning signs.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0647 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u062f\\u06cc\\u0627\\u0641\\u0631\\u0627\\u06af\\u0645 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u0641\\u0633 \\u0631\\u0627 \\u06a9\\u0645\\u06cc \\u0633\\u062e\\u062a\\u200c\\u062a\\u0631 \\u06a9\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u0634\\u062a\\u06cc\\u0628\\u0627\\u0646\\u06cc \\u0627\\u0632 \\u0631\\u0634\\u062f \\u0633\\u0631\\u06cc\\u0639 \\u062c\\u0646\\u06cc\\u0646 \\u0633\\u062e\\u062a \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"The uterus is above the navel and pressure on the diaphragm may make breathing a bit harder. The body works hard to support the baby\\u2019s rapid growth.\"}','{\"fa\":\"\\u0628\\u0627 \\u0648\\u0631\\u0648\\u062f \\u0628\\u0647 \\u0645\\u0631\\u062d\\u0644\\u0647 \\u062d\\u06cc\\u0627\\u062a\\u200c\\u067e\\u0630\\u06cc\\u0631\\u06cc \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062d\\u0633 \\u0627\\u0637\\u0645\\u06cc\\u0646\\u0627\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0628\\u0627 \\u0627\\u06cc\\u0646 \\u062d\\u0627\\u0644\\u060c \\u0641\\u06a9\\u0631 \\u06a9\\u0631\\u062f\\u0646 \\u0628\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628\\u200c\\u0622\\u0648\\u0631 \\u0628\\u0627\\u0634\\u062f. \\u0622\\u0645\\u0648\\u0632\\u0634 \\u0648 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"Reaching viability may bring more reassurance. Still, thinking about birth can cause anxiety; education and support help.\"}','{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0642\\u0646\\u062f \\u062e\\u0648\\u0646\\u060c \\u06a9\\u0631\\u0628\\u0648\\u0647\\u06cc\\u062f\\u0631\\u0627\\u062a\\u200c\\u0647\\u0627\\u06cc \\u067e\\u06cc\\u0686\\u06cc\\u062f\\u0647 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u0627\\u06cc\\u06af\\u0632\\u06cc\\u0646 \\u0642\\u0646\\u062f \\u0633\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0646\\u06af\\u0647 \\u062f\\u0627\\u0631\\u06cc\\u062f.\",\"en\":\"To manage blood sugar, replace simple sugars with complex carbs and protein. Continue iron, calcium and fiber, drink enough water, and keep balanced meals.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0648 \\u0634\\u0646\\u0627 \\u0628\\u0647 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0642\\u0646\\u062f \\u062e\\u0648\\u0646 \\u0648 \\u06a9\\u0627\\u0647\\u0634 \\u062a\\u0648\\u0631\\u0645 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0634\\u062f\\u06cc\\u062f \\u0648 \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking and swimming help control blood sugar and reduce swelling. Keep pelvic floor and breathing exercises and avoid intense or risky activities.\"}','{\"fa\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062a\\u062d\\u0645\\u0644 \\u06af\\u0644\\u0648\\u06a9\\u0632 (GTT) \\u0628\\u0631\\u0627\\u06cc \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0631 \\u0628\\u0627\\u0632\\u0647 \\u0647\\u0641\\u062a\\u0647 \\u06f2\\u06f4 \\u062a\\u0627 \\u06f2\\u06f8 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646 \\u0648 \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u063a\\u06cc\\u0631\\u0639\\u0627\\u062f\\u06cc \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"The glucose tolerance test (GTT) for gestational diabetes screening is done in the weeks 24 to 28 window. Routine visits include blood pressure, weight and fetal growth.\"}','{\"fa\":[{\"question\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0686\\u06af\\u0648\\u0646\\u0647 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0645\\u062d\\u0644\\u0648\\u0644 \\u0642\\u0646\\u062f\\u06cc \\u0645\\u06cc\\u200c\\u0646\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0633\\u0637\\u062d \\u0642\\u0646\\u062f \\u062e\\u0648\\u0646 \\u062f\\u0631 \\u0641\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0634\\u062e\\u0635 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u062a\\u0627 \\u0646\\u062d\\u0648\\u0647 \\u067e\\u0631\\u062f\\u0627\\u0632\\u0634 \\u0642\\u0646\\u062f \\u062a\\u0648\\u0633\\u0637 \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0634\\u0648\\u062f.\"},{\"question\":\"\\u062d\\u06cc\\u0627\\u062a\\u200c\\u067e\\u0630\\u06cc\\u0631\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u06cc\\u0639\\u0646\\u06cc \\u0686\\u0647\\u061f\",\"answer\":\"\\u06cc\\u0639\\u0646\\u06cc \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0627 \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0648\\u06cc\\u0698\\u0647 \\u067e\\u0632\\u0634\\u06a9\\u06cc \\u0634\\u0627\\u0646\\u0633 \\u0632\\u0646\\u062f\\u0647 \\u0645\\u0627\\u0646\\u062f\\u0646 \\u062e\\u0627\\u0631\\u062c \\u0627\\u0632 \\u0631\\u062d\\u0645 \\u0631\\u0627 \\u062f\\u0627\\u0631\\u062f\\u060c \\u0647\\u0631\\u0686\\u0646\\u062f \\u0631\\u0633\\u06cc\\u062f\\u0646 \\u0628\\u0647 \\u062a\\u0631\\u0645 \\u0628\\u0633\\u06cc\\u0627\\u0631 \\u0645\\u0647\\u0645\\u200c\\u062a\\u0631 \\u0627\\u0633\\u062a.\"}],\"en\":[{\"question\":\"How does the diabetes test work?\",\"answer\":\"You drink a glucose solution and blood sugar is measured at intervals to see how your body processes sugar.\"},{\"question\":\"What does fetal viability mean?\",\"answer\":\"From this week the baby has a chance of surviving outside the womb with intensive care, though reaching term is far better.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(25,25,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u067e\\u0646\\u062c\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06af\\u0644\\u200c\\u06a9\\u0644\\u0645\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f3\\u06f4.\\u06f6 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f6\\u06f6\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u067e\\u0648\\u0633\\u062a \\u0635\\u0627\\u0641\\u200c\\u062a\\u0631 \\u0648 \\u0635\\u0648\\u0631\\u062a\\u06cc\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0686\\u0631\\u0628\\u06cc \\u0632\\u06cc\\u0631 \\u067e\\u0648\\u0633\\u062a \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0645\\u06cc\\u200c\\u06cc\\u0627\\u0628\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u0631\\u0641\\u0644\\u06a9\\u0633 \\u06af\\u0631\\u0641\\u062a\\u0646 \\u0628\\u0627 \\u062f\\u0633\\u062a \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"At week twenty-five the fetus is about the size of a cauliflower, roughly 34.6 cm and nearly 660 g. The skin becomes smoother and pinker as subcutaneous fat increases, and the baby develops a grasp reflex.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f\\u060c \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0648 \\u062a\\u0648\\u0631\\u0645 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f \\u0648 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u06a9\\u0645\\u06cc \\u06a9\\u0627\\u0647\\u0634 \\u06cc\\u0627\\u0628\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0648 \\u0645\\u0646\\u0638\\u0645 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062f\\u0686\\u0627\\u0631 \\u0633\\u0646\\u062f\\u0631\\u0645 \\u062a\\u0648\\u0646\\u0644 \\u06a9\\u0627\\u0631\\u067e\\u0627\\u0644 \\u062e\\u0641\\u06cc\\u0641 \\u062f\\u0631 \\u062f\\u0633\\u062a \\u0634\\u0648\\u06cc\\u062f.\",\"en\":\"Back pain, heartburn and swelling may increase and energy dip slightly. Movements are strong and regular, and you may develop mild carpal tunnel in the hands.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u06af\\u0631 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0631\\u06cc\\u062f \\u0631\\u0698\\u06cc\\u0645 \\u062a\\u062c\\u0648\\u06cc\\u0632\\u06cc \\u0631\\u0627 \\u0631\\u0639\\u0627\\u06cc\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0634\\u0627\\u0631 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u0631 \\u0645\\u0686 \\u062f\\u0633\\u062a \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and follow any prescribed diet if you have gestational diabetes. Avoid prolonged wrist strain and rest enough.\"}','{\"fa\":\"\\u0627\\u06af\\u0631 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0631\\u0627 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0644\\u0627\\u0633\\u200c\\u0647\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u062b\\u0628\\u062a\\u200c\\u0646\\u0627\\u0645 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"If you haven\\u2019t done the diabetes test, do it this week. Keep regular visits and movement counts, and enroll in childbirth classes.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u062a\\u0631 \\u0622\\u0645\\u062f\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0645\\u0639\\u062f\\u0647 \\u0648 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u0627\\u062d\\u062a\\u0628\\u0627\\u0633 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0639\\u062b \\u062a\\u0648\\u0631\\u0645 \\u0648 \\u0628\\u06cc\\u200c\\u062d\\u0633\\u06cc \\u062f\\u0633\\u062a \\u0634\\u0648\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u0627\\u06cc\\u0646 \\u062a\\u063a\\u06cc\\u06cc\\u0631\\u0627\\u062a \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus is higher and pressure on the stomach and lungs increases. Fluid retention can cause swelling and hand numbness as the body adapts.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u06a9\\u0645\\u06cc \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0631\\u0648\\u0627\\u0646\\u06cc \\u0631\\u0627 \\u0647\\u0645\\u0632\\u0645\\u0627\\u0646 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0641\\u06a9\\u0631 \\u06a9\\u0631\\u062f\\u0646 \\u0628\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0646\\u0648\\u0632\\u0627\\u062f \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648 \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u062e\\u0648\\u062f \\u0631\\u0627 \\u062f\\u0631 \\u0627\\u0648\\u0644\\u0648\\u06cc\\u062a \\u0628\\u06af\\u0630\\u0627\\u0631\\u06cc\\u062f.\",\"en\":\"You may feel both excitement and some mental fatigue. Thinking about preparing for the baby is common; prioritize rest and self-care.\"}','{\"fa\":\"\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0642\\u0646\\u062f \\u0633\\u0627\\u062f\\u0647 \\u0631\\u0627 \\u0645\\u062d\\u062f\\u0648\\u062f \\u06a9\\u0646\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u063a\\u0646\\u06cc \\u0627\\u0632 \\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"Continue protein, iron, calcium and fiber and limit simple sugars. Magnesium-rich foods help reduce cramps; drink enough water.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0648 \\u0628\\u0647\\u0628\\u0648\\u062f \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0645\\u0686 \\u062f\\u0633\\u062a \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0627\\u0647\\u0634 \\u0628\\u06cc\\u200c\\u062d\\u0633\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle stretching ease back pain and improve sleep. Keep pelvic floor exercises and do wrist movements to reduce numbness.\"}','{\"fa\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062a\\u062d\\u0645\\u0644 \\u06af\\u0644\\u0648\\u06a9\\u0632 \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0628\\u0627\\u0632\\u0647 \\u0642\\u0627\\u0628\\u0644 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0627\\u0633\\u062a. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646 \\u0648 \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u06a9\\u0645\\u200c\\u062e\\u0648\\u0646\\u06cc\\u060c \\u0645\\u06a9\\u0645\\u0644 \\u0622\\u0647\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u0634\\u0648\\u062f.\",\"en\":\"The glucose tolerance test is still available now. Routine visits include blood pressure, weight and fetal growth, and iron may be adjusted if anemic.\"}','{\"fa\":[{\"question\":\"\\u0628\\u06cc\\u200c\\u062d\\u0633\\u06cc \\u062f\\u0633\\u062a \\u062f\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u0627\\u062d\\u062a\\u0628\\u0627\\u0633 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0627\\u0639\\u062b \\u0633\\u0646\\u062f\\u0631\\u0645 \\u062a\\u0648\\u0646\\u0644 \\u06a9\\u0627\\u0631\\u067e\\u0627\\u0644 \\u062e\\u0641\\u06cc\\u0641 \\u0634\\u0648\\u062f \\u06a9\\u0647 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u067e\\u0633 \\u0627\\u0632 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0647\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0627\\u06af\\u0631 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u0645 \\u0686\\u0647 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0628\\u0627 \\u0631\\u0639\\u0627\\u06cc\\u062a \\u0631\\u0698\\u06cc\\u0645 \\u063a\\u0630\\u0627\\u06cc\\u06cc\\u060c \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0628\\u062f\\u0646\\u06cc \\u0648 \\u06af\\u0627\\u0647\\u06cc \\u062f\\u0627\\u0631\\u0648\\u060c \\u0642\\u0646\\u062f \\u062e\\u0648\\u0646 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061b \\u067e\\u0632\\u0634\\u06a9 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0631\\u0627 \\u062a\\u0639\\u06cc\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"}],\"en\":[{\"question\":\"Is hand numbness normal in pregnancy?\",\"answer\":\"Yes, fluid retention can cause mild carpal tunnel, which usually improves after birth.\"},{\"question\":\"What if I have gestational diabetes?\",\"answer\":\"It is managed with diet, activity and sometimes medication; your doctor sets the right plan.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(26,26,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u0634\\u0634\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06a9\\u0627\\u0647\\u0648\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f3\\u06f5.\\u06f6 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f7\\u06f6\\u06f0 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0686\\u0634\\u0645\\u200c\\u0647\\u0627 \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u0628\\u0627\\u0632 \\u0634\\u062f\\u0646 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0646\\u0648\\u0631 \\u0648\\u0627\\u06a9\\u0646\\u0634 \\u0646\\u0634\\u0627\\u0646 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f. \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0628\\u0647 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0627\\u062f\\u0627\\u0645\\u0647 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f.\",\"en\":\"At week twenty-six the fetus is about the size of a head of lettuce, roughly 35.6 cm and nearly 760 g. The eyes begin to open and the baby responds to light, while the lungs keep practicing breathing movements.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u062a\\u0648\\u0631\\u0645 \\u0648 \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f \\u0648 \\u062e\\u0648\\u0627\\u0628 \\u0633\\u062e\\u062a\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0648 \\u06af\\u0627\\u0647\\u06cc \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u0633\\u06a9\\u0633\\u06a9\\u0647 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0631\\u0627 \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Blood pressure, swelling and back pain may rise and sleep becomes harder. Movements are strong, sometimes with hiccups, and you may feel practice contractions.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0645\\u0627\\u0646\\u0646\\u062f \\u0633\\u0631\\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f \\u0648 \\u062a\\u0627\\u0631\\u06cc \\u062f\\u06cc\\u062f \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take pre-eclampsia signs like severe headache and blurred vision seriously. Sleep on your side and hydrate.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0627\\u06af\\u0631 \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0631\\u0627 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0634\\u0631\\u0648\\u0639 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep regular visits and do the diabetes test if not done. Continue counting movements and plan for the start of the third trimester.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0627\\u0633\\u062a \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0645\\u0639\\u062f\\u0647 \\u0648 \\u0645\\u062b\\u0627\\u0646\\u0647 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u0627\\u062d\\u062a\\u0628\\u0627\\u0633 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0633\\u0627\\u0632\\u06af\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus is above the navel and pressure on the stomach and bladder increases. Fluid retention continues as the body prepares for the third trimester.\"}','{\"fa\":\"\\u0628\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0634\\u062f\\u0646 \\u0628\\u0647 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0631\\u06a9\\u06cc\\u0628\\u06cc \\u0627\\u0632 \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u062e\\u0648\\u0627\\u0628 \\u0646\\u0627\\u06a9\\u0627\\u0641\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0631 \\u062e\\u0644\\u0642\\u200c\\u0648\\u062e\\u0648 \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0627\\u0647\\u0645\\u06cc\\u062a \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"As the third trimester nears you may feel a mix of excitement and anxiety. Poor sleep can affect mood; rest and support matter.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u06af\\u0631 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u062f\\u0627\\u0631\\u06cc\\u062f \\u0642\\u0646\\u062f \\u0631\\u0627 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u063a\\u0646\\u06cc \\u0627\\u0632 \\u0641\\u06cc\\u0628\\u0631 \\u0648 \\u067e\\u062a\\u0627\\u0633\\u06cc\\u0645 \\u0645\\u0641\\u06cc\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f \\u0648 \\u0646\\u0645\\u06a9 \\u0631\\u0627 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue iron, calcium and protein and control sugar if diabetic. Fiber- and potassium-rich foods help; drink enough water and moderate salt.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0648 \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0648 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0628\\u06cc\\u0634 \\u0627\\u0632 \\u062d\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga remain helpful. Keep breathing and pelvic floor exercises and avoid heavy activity and overexertion.\"}','{\"fa\":\"\\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062a\\u062d\\u0645\\u0644 \\u06af\\u0644\\u0648\\u06a9\\u0632 \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0628\\u0627\\u0632\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645\\u200c\\u0634\\u062f\\u0646\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0648\\u0632\\u0646 \\u0648 \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"The glucose tolerance test is still possible now and blood pressure is checked for pre-eclampsia. Routine visits include weight and fetal growth.\"}','{\"fa\":[{\"question\":\"\\u0639\\u0644\\u0627\\u0626\\u0645 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646 \\u0628\\u0627\\u0644\\u0627\\u060c \\u0633\\u0631\\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f\\u060c \\u062a\\u0627\\u0631\\u06cc \\u062f\\u06cc\\u062f\\u060c \\u062f\\u0631\\u062f \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0634\\u06a9\\u0645 \\u0648 \\u0648\\u0631\\u0645 \\u0646\\u0627\\u06af\\u0647\\u0627\\u0646\\u06cc \\u0627\\u0632 \\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u0633\\u062a \\u0648 \\u0646\\u06cc\\u0627\\u0632 \\u0628\\u0647 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u0641\\u0648\\u0631\\u06cc \\u062f\\u0627\\u0631\\u062f.\"},{\"question\":\"\\u0633\\u06a9\\u0633\\u06a9\\u0647 \\u062c\\u0646\\u06cc\\u0646 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u0633\\u06a9\\u0633\\u06a9\\u0647 \\u062c\\u0646\\u06cc\\u0646 \\u06a9\\u0647 \\u0628\\u0647\\u200c\\u0635\\u0648\\u0631\\u062a \\u062d\\u0631\\u06a9\\u0627\\u062a \\u0631\\u06cc\\u062a\\u0645\\u06cc\\u06a9 \\u062d\\u0633 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0648 \\u0646\\u0634\\u0627\\u0646\\u0647 \\u0631\\u0634\\u062f \\u0633\\u0627\\u0644\\u0645 \\u0627\\u0633\\u062a.\"}],\"en\":[{\"question\":\"What are pre-eclampsia signs?\",\"answer\":\"High blood pressure, severe headache, blurred vision, upper-abdomen pain and sudden swelling are signs needing urgent care.\"},{\"question\":\"Are fetal hiccups normal?\",\"answer\":\"Yes, fetal hiccups felt as rhythmic movements are entirely normal and a sign of healthy development.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(27,27,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u0647\\u0641\\u062a\\u0645 \\u06a9\\u0647 \\u067e\\u0627\\u06cc\\u0627\\u0646 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u062f\\u0648\\u0645 \\u0627\\u0633\\u062a\\u060c \\u062c\\u0646\\u06cc\\u0646 \\u062d\\u062f\\u0648\\u062f \\u06f3\\u06f6.\\u06f6 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f8\\u06f7\\u06f5 \\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0645\\u063a\\u0632 \\u0628\\u0647\\u200c\\u0633\\u0631\\u0639\\u062a \\u0631\\u0634\\u062f \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0644\\u06af\\u0648\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u062e\\u0648\\u0627\\u0628 \\u0648 \\u0628\\u06cc\\u062f\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0631\\u062f. \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0628\\u0647 \\u0628\\u0644\\u0648\\u063a \\u062e\\u0648\\u062f \\u0627\\u062f\\u0627\\u0645\\u0647 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f.\",\"en\":\"At week twenty-seven, the end of the second trimester, the fetus is about 36.6 cm and nearly 875 g. The brain grows rapidly, the baby has regular sleep-wake patterns, and the lungs keep maturing.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f\\u060c \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633 \\u0648 \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0639\\u0636\\u0644\\u0627\\u062a \\u067e\\u0627 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0648 \\u0645\\u0646\\u0638\\u0645 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062e\\u0648\\u0627\\u0628 \\u0628\\u0647 \\u062f\\u0644\\u06cc\\u0644 \\u0628\\u0632\\u0631\\u06af\\u06cc \\u0634\\u06a9\\u0645 \\u062f\\u0634\\u0648\\u0627\\u0631\\u062a\\u0631 \\u0634\\u0648\\u062f.\",\"en\":\"Back pain, shortness of breath and leg cramps may increase. Movements are strong and regular, and sleep may be harder due to the larger belly.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u0627\\u0628 \\u0628\\u0647\\u062a\\u0631 \\u0627\\u0632 \\u0628\\u0627\\u0644\\u0634 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633 \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f. \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and use a pregnancy pillow for better sleep. Know preterm labor signs, sleep on your side, and hydrate.\"}','{\"fa\":\"\\u0628\\u0627 \\u0648\\u0631\\u0648\\u062f \\u0628\\u0647 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645\\u060c \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0645\\u06a9\\u0631\\u0631\\u200c\\u062a\\u0631 \\u0634\\u0648\\u0646\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0644\\u0627\\u0633\\u200c\\u0647\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u062a\\u0647\\u06cc\\u0647 \\u0644\\u0648\\u0627\\u0632\\u0645 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Entering the third trimester, visits may become more frequent. Take movement counting seriously and plan childbirth classes and baby supplies.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u062f\\u06cc\\u0627\\u0641\\u0631\\u0627\\u06af\\u0645 \\u062a\\u0646\\u0641\\u0633 \\u0631\\u0627 \\u06a9\\u0645\\u06cc \\u0633\\u062e\\u062a\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0645\\u0641\\u0627\\u0635\\u0644 \\u0648 \\u0631\\u0628\\u0627\\u0637\\u200c\\u0647\\u0627 \\u0634\\u0644\\u200c\\u062a\\u0631 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0631\\u0627\\u062d\\u0644 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus is above the navel and pressure on the diaphragm makes breathing a bit harder. Joints and ligaments are looser as the body prepares for the final stages.\"}','{\"fa\":\"\\u0628\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0634\\u062f\\u0646 \\u0628\\u0647 \\u0645\\u0631\\u0627\\u062d\\u0644 \\u067e\\u0627\\u06cc\\u0627\\u0646\\u06cc\\u060c \\u0627\\u0641\\u06a9\\u0627\\u0631 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0648\\u0627\\u0644\\u062f\\u06af\\u0631\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u06a9\\u0645\\u06cc \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u06cc\\u0627 \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0639\\u0627\\u0637\\u0641\\u06cc \\u0648 \\u0622\\u0645\\u0648\\u0632\\u0634 \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"As the final stages approach, thoughts about birth and parenting grow. Some anxiety or excitement is normal; emotional support and education help.\"}','{\"fa\":\"\\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646\\u060c \\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645 \\u0648 \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0628\\u0631\\u0627\\u06cc \\u0631\\u0634\\u062f \\u0645\\u063a\\u0632 \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0647\\u0645 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0641\\u06cc\\u0628\\u0631 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0627\\u0632 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u0642\\u0646\\u062f \\u0648 \\u0646\\u0645\\u06a9 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Protein, iron, calcium and omega-3 matter for the baby\\u2019s brain growth. Fiber and enough water prevent constipation; limit excess sugar and salt.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u062f\\u0631\\u062f\\u0647\\u0627 \\u0648 \\u0628\\u0647\\u0628\\u0648\\u062f \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0648 \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0641\\u0631\\u0627\\u0637 \\u0646\\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle stretching ease aches and improve sleep. Keep breathing and pelvic floor exercises; listen to your body and don\\u2019t overdo it.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646 \\u0648 \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0646\\u062a\\u0627\\u06cc\\u062c \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062f\\u06cc\\u0627\\u0628\\u062a \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0634\\u0648\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0627\\u062f\\u0631\\u0627\\u0646 Rh \\u0645\\u0646\\u0641\\u06cc\\u060c \\u062a\\u0632\\u0631\\u06cc\\u0642 \\u0622\\u0646\\u062a\\u06cc\\u200c\\u062f\\u06cc (\\u0631\\u0648\\u06af\\u0627\\u0645) \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u0645\\u0637\\u0631\\u062d \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits include blood pressure, weight and fetal growth, and diabetes test results may be reviewed. For Rh-negative mothers, anti-D (RhoGAM) will be discussed soon.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0637\\u0648\\u0631 \\u0628\\u0647\\u062a\\u0631 \\u0628\\u062e\\u0648\\u0627\\u0628\\u0645\\u061f\",\"answer\":\"\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f\\u0646 \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648\\u06cc \\u0686\\u067e\\u060c \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u0627\\u0632 \\u0628\\u0627\\u0644\\u0634 \\u0628\\u06cc\\u0646 \\u067e\\u0627\\u0647\\u0627 \\u0648 \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u0627\\u0632 \\u063a\\u0630\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0642\\u0628\\u0644 \\u0627\\u0632 \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"},{\"question\":\"\\u0686\\u0631\\u0627 \\u0646\\u0641\\u0633\\u0645 \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0641\\u0634\\u0627\\u0631 \\u0631\\u062d\\u0645 \\u0628\\u0631 \\u062f\\u06cc\\u0627\\u0641\\u0631\\u0627\\u06af\\u0645 \\u0628\\u0627\\u0639\\u062b \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633 \\u062e\\u0641\\u06cc\\u0641 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u06a9\\u0647 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061b \\u0627\\u0645\\u0627 \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633 \\u0646\\u0627\\u06af\\u0647\\u0627\\u0646\\u06cc \\u0648 \\u0634\\u062f\\u06cc\\u062f \\u0628\\u0627\\u06cc\\u062f \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"How can I sleep better?\",\"answer\":\"Sleeping on your left side, a pillow between the legs and avoiding heavy meals before bed help.\"},{\"question\":\"Why is my breathing heavier?\",\"answer\":\"Uterine pressure on the diaphragm causes mild breathlessness, which is normal; sudden severe breathlessness should be checked.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(28,28,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u0647\\u0634\\u062a\\u0645 \\u06a9\\u0647 \\u0622\\u063a\\u0627\\u0632 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0627\\u0633\\u062a\\u060c \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0628\\u0627\\u062f\\u0645\\u062c\\u0627\\u0646\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f3\\u06f7.\\u06f6 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u067e\\u0644\\u06a9 \\u0628\\u0632\\u0646\\u062f \\u0648 \\u0631\\u0648\\u06cc\\u0627 \\u0628\\u0628\\u06cc\\u0646\\u062f \\u0648 \\u0645\\u063a\\u0632 \\u0634\\u06cc\\u0627\\u0631\\u0647\\u0627\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u067e\\u06cc\\u062f\\u0627 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0686\\u0634\\u0645\\u200c\\u0647\\u0627 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0628\\u0627\\u0632 \\u0648 \\u0628\\u0633\\u062a\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f.\",\"en\":\"At week twenty-eight, the start of the third trimester, the fetus is about the size of an eggplant, roughly 37.6 cm and nearly 1 kg. The baby can blink and dream, the brain develops more folds, and the eyes now open and close.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633\\u060c \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644\\u060c \\u062a\\u0648\\u0631\\u0645 \\u0648 \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0648 \\u0645\\u0646\\u0638\\u0645 \\u0627\\u0633\\u062a \\u0648 \\u0628\\u0627\\u06cc\\u062f \\u067e\\u06cc\\u06af\\u06cc\\u0631\\u06cc \\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0628\\u0627\\u0632\\u06af\\u0631\\u062f\\u062f.\",\"en\":\"Shortness of breath, heartburn, swelling and back pain may increase. Movements are strong and regular and should be tracked, and third-trimester fatigue may return.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0648 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633 \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f. \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take movement counting seriously. Know pre-eclampsia and preterm labor signs, sleep on your side, and rest enough.\"}','{\"fa\":\"\\u062f\\u0631 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0647\\u0631 \\u062f\\u0648 \\u0647\\u0641\\u062a\\u0647 \\u06cc\\u06a9\\u200c\\u0628\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0627\\u062f\\u0631\\u0627\\u0646 Rh \\u0645\\u0646\\u0641\\u06cc\\u060c \\u062a\\u0632\\u0631\\u06cc\\u0642 \\u0622\\u0646\\u062a\\u06cc\\u200c\\u062f\\u06cc \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0644\\u0648\\u0627\\u0632\\u0645 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0631\\u0627 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"In the third trimester visits usually become every two weeks. For Rh-negative mothers, an anti-D injection is recommended this week; prepare your birth plan and baby supplies.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0647\\u200c\\u0633\\u0631\\u0639\\u062a \\u0628\\u0632\\u0631\\u06af \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627\\u06cc \\u062f\\u0627\\u062e\\u0644\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u062f\\u0646 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u0646\\u06af\\u0647 \\u0645\\u06cc\\u200c\\u062f\\u0627\\u0631\\u062f. \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u0642\\u0644\\u0628\\u06cc\\u200c\\u0639\\u0631\\u0648\\u0642\\u06cc \\u0628\\u0627 \\u0627\\u0648\\u062c \\u062d\\u062c\\u0645 \\u062e\\u0648\\u0646 \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus grows quickly and presses more on internal organs. The body retains more fluid and the cardiovascular system works at peak blood volume.\"}','{\"fa\":\"\\u0648\\u0631\\u0648\\u062f \\u0628\\u0647 \\u0645\\u0631\\u062d\\u0644\\u0647 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u062f\\u0647\\u062f. \\u0641\\u06a9\\u0631 \\u06a9\\u0631\\u062f\\u0646 \\u0628\\u0647 \\u0646\\u0642\\u0634 \\u0648\\u0627\\u0644\\u062f\\u06af\\u0631\\u06cc \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a. \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u0633\\u0644\\u0627\\u0645\\u062a \\u0631\\u0648\\u0627\\u0646 \\u0628\\u0633\\u06cc\\u0627\\u0631 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"Entering the final stage can heighten excitement and anxiety about birth. Thinking about the parenting role is common; mental health care is very important.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0628\\u0631\\u0627\\u06cc \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0636\\u0631\\u0648\\u0631\\u06cc \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0641\\u06cc\\u0628\\u0631 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0627\\u0632 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0631\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f.\",\"en\":\"Iron, calcium, protein and omega-3 are essential for the baby\\u2019s growth. Fiber and enough water prevent constipation, and small frequent meals reduce heartburn.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0647 \\u06af\\u0631\\u062f\\u0634 \\u062e\\u0648\\u0646 \\u0648 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle exercise aid circulation and birth readiness. Keep pelvic floor and breathing exercises and avoid risky activities.\"}','{\"fa\":\"\\u0628\\u0631\\u0627\\u06cc \\u0645\\u0627\\u062f\\u0631\\u0627\\u0646 Rh \\u0645\\u0646\\u0641\\u06cc\\u060c \\u062a\\u0632\\u0631\\u06cc\\u0642 \\u0627\\u06cc\\u0645\\u0648\\u0646\\u0648\\u06af\\u0644\\u0648\\u0628\\u0648\\u0644\\u06cc\\u0646 \\u0622\\u0646\\u062a\\u06cc\\u200c\\u062f\\u06cc (\\u0631\\u0648\\u06af\\u0627\\u0645) \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u06f2\\u06f8 \\u0628\\u0631\\u0627\\u06cc \\u067e\\u06cc\\u0634\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u062d\\u0633\\u0627\\u0633\\u06cc\\u062a \\u062e\\u0648\\u0646\\u06cc \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0645\\u200c\\u062e\\u0648\\u0646\\u06cc \\u0648 \\u06a9\\u0646\\u062a\\u0631\\u0644 \\u0642\\u0646\\u062f \\u0646\\u06cc\\u0632 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u06a9\\u0631\\u0627\\u0631 \\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"For Rh-negative mothers, an anti-D immunoglobulin (RhoGAM) injection is given at week 28 to prevent blood sensitization. Blood tests for anemia and sugar may be repeated.\"}','{\"fa\":[{\"question\":\"\\u062a\\u0632\\u0631\\u06cc\\u0642 \\u0631\\u0648\\u06af\\u0627\\u0645 (\\u0622\\u0646\\u062a\\u06cc\\u200c\\u062f\\u06cc) \\u0628\\u0631\\u0627\\u06cc \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0627\\u06af\\u0631 \\u062e\\u0648\\u0646 \\u0645\\u0627\\u062f\\u0631 Rh \\u0645\\u0646\\u0641\\u06cc \\u0648 \\u062c\\u0646\\u06cc\\u0646 Rh \\u0645\\u062b\\u0628\\u062a \\u0628\\u0627\\u0634\\u062f\\u060c \\u0627\\u06cc\\u0646 \\u062a\\u0632\\u0631\\u06cc\\u0642 \\u0627\\u0632 \\u0633\\u0627\\u062e\\u062a\\u0647 \\u0634\\u062f\\u0646 \\u0622\\u0646\\u062a\\u06cc\\u200c\\u0628\\u0627\\u062f\\u06cc \\u062e\\u0637\\u0631\\u0646\\u0627\\u06a9 \\u0639\\u0644\\u06cc\\u0647 \\u062e\\u0648\\u0646 \\u062c\\u0646\\u06cc\\u0646 \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"},{\"question\":\"\\u0686\\u0646\\u062f \\u0628\\u0627\\u0631 \\u062f\\u0631 \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0628\\u0647 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062a\\u0627 \\u0647\\u0641\\u062a\\u0647 \\u06f3\\u06f6 \\u0647\\u0631 \\u062f\\u0648 \\u0647\\u0641\\u062a\\u0647 \\u06cc\\u06a9\\u200c\\u0628\\u0627\\u0631 \\u0648 \\u067e\\u0633 \\u0627\\u0632 \\u0622\\u0646 \\u0647\\u0641\\u062a\\u06af\\u06cc\\u060c \\u0645\\u06af\\u0631 \\u0627\\u06cc\\u0646\\u06a9\\u0647 \\u067e\\u0632\\u0634\\u06a9 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u062f\\u06cc\\u06af\\u0631\\u06cc \\u062a\\u0639\\u06cc\\u06cc\\u0646 \\u06a9\\u0646\\u062f.\"}],\"en\":[{\"question\":\"What is the RhoGAM (anti-D) injection for?\",\"answer\":\"If the mother is Rh-negative and the baby Rh-positive, it prevents harmful antibodies from forming against the baby\\u2019s blood.\"},{\"question\":\"How often should I visit in the third trimester?\",\"answer\":\"Usually every two weeks until week 36 and weekly after, unless your doctor sets a different plan.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(29,29,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0628\\u06cc\\u0633\\u062a\\u200c\\u0648\\u0646\\u0647\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06a9\\u062f\\u0648 \\u062d\\u0644\\u0648\\u0627\\u06cc\\u06cc\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f3\\u06f8.\\u06f6 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1.\\u06f2 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0639\\u0636\\u0644\\u0627\\u062a \\u0648 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u0628\\u0644\\u0648\\u063a \\u0647\\u0633\\u062a\\u0646\\u062f \\u0648 \\u0645\\u063a\\u0632 \\u0628\\u0647\\u200c\\u0633\\u0631\\u0639\\u062a \\u0631\\u0634\\u062f \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062f\\u0645\\u0627\\u06cc \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u0631\\u0627 \\u062a\\u0627 \\u062d\\u062f\\u06cc \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u06a9\\u0646\\u062f.\",\"en\":\"At week twenty-nine the fetus is about the size of a butternut squash, roughly 38.6 cm and nearly 1.2 kg. Muscles and lungs are maturing, the brain grows fast, and the baby can now partly regulate its own temperature.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633\\u060c \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644\\u060c \\u0628\\u0648\\u0627\\u0633\\u06cc\\u0631 \\u0648 \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0639\\u0636\\u0644\\u0627\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0648 \\u06af\\u0627\\u0647\\u06cc \\u062f\\u0631\\u062f\\u0646\\u0627\\u06a9 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0648 \\u0645\\u0634\\u06a9\\u0644\\u0627\\u062a \\u062e\\u0648\\u0627\\u0628 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Shortness of breath, heartburn, hemorrhoids and cramps may increase. Movements are strong and sometimes uncomfortable, and you may have fatigue and sleep issues.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0648\\u0627\\u0633\\u06cc\\u0631 \\u0641\\u06cc\\u0628\\u0631 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0627\\u0632 \\u0627\\u06cc\\u0633\\u062a\\u0627\\u062f\\u0646 \\u0637\\u0648\\u0644\\u0627\\u0646\\u06cc \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and eat enough fiber and water for hemorrhoids. Take movement counting seriously, avoid long standing, and rest.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u06af\\u0631 Rh \\u0645\\u0646\\u0641\\u06cc \\u0647\\u0633\\u062a\\u06cc\\u062f \\u0648 \\u062a\\u0632\\u0631\\u06cc\\u0642 \\u0622\\u0646\\u062a\\u06cc\\u200c\\u062f\\u06cc \\u0646\\u0634\\u062f\\u0647\\u060c \\u067e\\u06cc\\u06af\\u06cc\\u0631\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0647\\u06cc\\u0647 \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647\\u200c\\u0631\\u06cc\\u0632\\u06cc \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep regular visits and discuss your birth plan with your doctor. If Rh-negative and anti-D not given, follow up, and plan to prepare your hospital bag.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0647\\u200c\\u0633\\u0631\\u0639\\u062a \\u0628\\u0632\\u0631\\u06af \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0645\\u0639\\u062f\\u0647\\u060c \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0648 \\u0645\\u062b\\u0627\\u0646\\u0647 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0627\\u062d\\u062a\\u0628\\u0627\\u0633 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0648\\u0631\\u0645 \\u0631\\u0627 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u062f\\u0647\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0627\\u06cc\\u0627\\u0646\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus grows fast and presses more on the stomach, lungs and bladder. Fluid retention may increase swelling as the body prepares for the final weeks.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u062f\\u06cc\\u062f\\u0646 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0628\\u0627 \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0631 \\u062e\\u0644\\u0642\\u200c\\u0648\\u062e\\u0648 \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f. \\u0635\\u062d\\u0628\\u062a \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"Excitement to meet the baby may mix with worry about birth. Fatigue can affect mood; sharing feelings and resting help.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u06af\\u0631\\u0641\\u062a\\u06af\\u06cc \\u0639\\u0636\\u0644\\u0627\\u062a \\u0645\\u0646\\u06cc\\u0632\\u06cc\\u0645 \\u0648 \\u067e\\u062a\\u0627\\u0633\\u06cc\\u0645 \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0631\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f.\",\"en\":\"Continue iron, calcium, protein and fiber and take magnesium and potassium for cramps. Drink enough water; small meals reduce heartburn.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u062f\\u0631\\u062f\\u0647\\u0627 \\u0648 \\u0628\\u0647\\u0628\\u0648\\u062f \\u062e\\u0648\\u0627\\u0628 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle stretching ease aches and improve sleep. Keep pelvic floor and breathing exercises and listen to your body.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0631\\u0634\\u062f \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0642\\u0631\\u0627\\u0631\\u06af\\u06cc\\u0631\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0622\\u0632\\u0645\\u0627\\u06cc\\u0634 \\u062e\\u0648\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0645\\u200c\\u062e\\u0648\\u0646\\u06cc \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u06a9\\u0631\\u0627\\u0631 \\u0634\\u0648\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0648 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits include blood pressure, weight, fetal growth and baby\\u2019s position. A blood test for anemia may be repeated; report pre-eclampsia and preterm labor signs.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u0628\\u0647\\u062a\\u0631 \\u0627\\u0633\\u062a \\u062a\\u0627 \\u062d\\u062f\\u0648\\u062f \\u0647\\u0641\\u062a\\u0647 \\u06f3\\u06f2 \\u062a\\u0627 \\u06f3\\u06f5 \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f \\u062a\\u0627 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u062a\\u0631 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\"},{\"question\":\"\\u062d\\u0631\\u06a9\\u0627\\u062a \\u062f\\u0631\\u062f\\u0646\\u0627\\u06a9 \\u062c\\u0646\\u06cc\\u0646 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u0628\\u0627 \\u0628\\u0632\\u0631\\u06af\\u200c\\u062a\\u0631 \\u0634\\u062f\\u0646 \\u062c\\u0646\\u06cc\\u0646 \\u0644\\u06af\\u062f\\u0647\\u0627 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0645\\u062d\\u06a9\\u0645\\u200c\\u062a\\u0631 \\u0648 \\u06af\\u0627\\u0647\\u06cc \\u0646\\u0627\\u0631\\u0627\\u062d\\u062a\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f \\u06a9\\u0647 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a.\"}],\"en\":[{\"question\":\"When should I pack my hospital bag?\",\"answer\":\"It is best to pack it by around weeks 32 to 35 so you are ready in case of earlier labor.\"},{\"question\":\"Are uncomfortable baby movements normal?\",\"answer\":\"Yes, as the baby grows, kicks may feel firmer and sometimes uncomfortable, which is normal.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(30,30,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0627\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06a9\\u0644\\u0645\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f3\\u06f9.\\u06f9 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1.\\u06f3 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0645\\u063a\\u0632 \\u0634\\u06cc\\u0627\\u0631\\u0647\\u0627 \\u0648 \\u0686\\u06cc\\u0646\\u200c\\u0647\\u0627\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u067e\\u06cc\\u062f\\u0627 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u0645\\u063a\\u0632 \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646 \\u062a\\u0648\\u0644\\u06cc\\u062f \\u06af\\u0644\\u0628\\u0648\\u0644 \\u0642\\u0631\\u0645\\u0632 \\u0631\\u0627 \\u0628\\u0631 \\u0639\\u0647\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u062f. \\u06a9\\u0631\\u06a9 \\u0644\\u0627\\u0646\\u0648\\u06af\\u0648 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0646\\u0627\\u067e\\u062f\\u06cc\\u062f \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"At week thirty the fetus is about the size of a cabbage, roughly 39.9 cm and nearly 1.3 kg. The brain develops more grooves and folds, the bone marrow takes over red blood cell production, and the lanugo begins to disappear.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633\\u060c \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f\\u060c \\u062a\\u0648\\u0631\\u0645 \\u0648 \\u0645\\u0634\\u06a9\\u0644\\u0627\\u062a \\u062e\\u0648\\u0627\\u0628 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u0631\\u0627 \\u062d\\u0633 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Shortness of breath, back pain, swelling and sleep issues may increase. Movements are strong, and you may feel more practice contractions.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u0627\\u0628 \\u0628\\u0647\\u062a\\u0631 \\u0627\\u0632 \\u0628\\u0627\\u0644\\u0634 \\u0627\\u0633\\u062a\\u0641\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633 \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and use pillows for better sleep. Take movement counting seriously and know preterm labor signs.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u06a9\\u0644\\u0627\\u0633\\u200c\\u0647\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0634\\u06cc\\u0631\\u062f\\u0647\\u06cc \\u062b\\u0628\\u062a\\u200c\\u0646\\u0627\\u0645 \\u06a9\\u0646\\u06cc\\u062f. \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep regular visits and finalize your birth plan. Enroll in childbirth and breastfeeding classes and start preparing your hospital bag.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0627\\u0633\\u062a \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u062f\\u06cc\\u0627\\u0641\\u0631\\u0627\\u06af\\u0645 \\u0648 \\u0645\\u062b\\u0627\\u0646\\u0647 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0641\\u0627\\u0635\\u0644 \\u0644\\u06af\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0634\\u0644\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0647\\u200c\\u062e\\u0648\\u0628\\u06cc \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0631\\u0627\\u062d\\u0644 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus is above the navel and pressure on the diaphragm and bladder increases. Pelvic joints loosen for birth as the body prepares for the final stages.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0628\\u0631\\u0627\\u06cc \\u062f\\u06cc\\u062f\\u0646 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0628\\u0627 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0641\\u06a9\\u0631 \\u06a9\\u0631\\u062f\\u0646 \\u0628\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u0622\\u0645\\u0648\\u0632\\u0634 \\u0648 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u0646\\u06af\\u0631\\u0627\\u0646\\u06cc \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"Anticipation to meet the baby may mix with fatigue and anxiety. Thinking about birth is natural; education and support reduce worry.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0627\\u0632 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u0648 \\u062a\\u0648\\u0631\\u0645 \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u0642\\u0646\\u062f \\u0648 \\u0646\\u0645\\u06a9 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Continue iron, calcium, protein and omega-3 and eat enough fiber. Enough water helps prevent constipation and swelling; limit excess sugar and salt.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0628\\u0647 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga aid birth readiness. Keep pelvic floor and breathing exercises, avoid heavy activity, and rest.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0631\\u0634\\u062f \\u0648 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0642\\u0631\\u0627\\u0631\\u06af\\u06cc\\u0631\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0646\\u06cc\\u0627\\u0632 \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0631\\u0634\\u062f \\u0631\\u0627 \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u06a9\\u0646\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits include blood pressure, weight, growth and the baby\\u2019s position. Your doctor may advise a growth ultrasound if needed; report warning signs.\"}','{\"fa\":[{\"question\":\"\\u06a9\\u0644\\u0627\\u0633\\u200c\\u0647\\u0627\\u06cc \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f\\u0646\\u062f\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u0627\\u06cc\\u0646 \\u06a9\\u0644\\u0627\\u0633\\u200c\\u0647\\u0627 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0645\\u0631\\u0627\\u062d\\u0644 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646\\u060c \\u062a\\u06a9\\u0646\\u06cc\\u06a9\\u200c\\u0647\\u0627\\u06cc \\u062a\\u0646\\u0641\\u0633 \\u0648 \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0622\\u0645\\u0648\\u0632\\u0634 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f \\u0648 \\u0627\\u0639\\u062a\\u0645\\u0627\\u062f\\u200c\\u0628\\u0647\\u200c\\u0646\\u0641\\u0633 \\u0634\\u0645\\u0627 \\u0631\\u0627 \\u0628\\u0627\\u0644\\u0627 \\u0645\\u06cc\\u200c\\u0628\\u0631\\u0646\\u062f.\"},{\"question\":\"\\u0648\\u0636\\u0639\\u06cc\\u062a \\u0642\\u0631\\u0627\\u0631\\u06af\\u06cc\\u0631\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0647\\u0646\\u0648\\u0632 \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0686\\u0631\\u062e\\u062f\\u061b \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0628\\u0639\\u062f \\u0627\\u0647\\u0645\\u06cc\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u067e\\u06cc\\u062f\\u0627 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"}],\"en\":[{\"question\":\"Are childbirth classes helpful?\",\"answer\":\"Yes, they teach the stages of labor, breathing techniques and newborn care and boost your confidence.\"},{\"question\":\"Does the baby\\u2019s position matter now?\",\"answer\":\"The baby may still turn at this week; the final position becomes more important in later weeks.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(31,31,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u06cc\\u06a9\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0646\\u0627\\u0631\\u06af\\u06cc\\u0644\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4\\u06f1.\\u06f1 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1.\\u06f5 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0645\\u063a\\u0632 \\u0628\\u0627 \\u0633\\u0631\\u0639\\u062a \\u0632\\u06cc\\u0627\\u062f\\u06cc \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u06a9\\u0627\\u0645\\u0644 \\u0627\\u0631\\u062a\\u0628\\u0627\\u0637\\u0627\\u062a \\u0639\\u0635\\u0628\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0633\\u0631 \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0628\\u0686\\u0631\\u062e\\u0627\\u0646\\u062f. \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0628\\u0647 \\u0628\\u0644\\u0648\\u063a \\u0627\\u062f\\u0627\\u0645\\u0647 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u0646\\u062f.\",\"en\":\"At week thirty-one the fetus is about the size of a coconut, roughly 41.1 cm and nearly 1.5 kg. The brain is rapidly forming neural connections, the baby can turn its head, and the lungs keep maturing.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633\\u060c \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f\\u060c \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0648 \\u0646\\u0634\\u062a \\u062e\\u0641\\u06cc\\u0641 \\u06a9\\u0644\\u0633\\u062a\\u0631\\u0648\\u0645 \\u0627\\u0632 \\u0633\\u06cc\\u0646\\u0647 \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0627\\u0633\\u062a. \\u062e\\u0648\\u0627\\u0628 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062f\\u0634\\u0648\\u0627\\u0631\\u062a\\u0631 \\u0634\\u0648\\u062f.\",\"en\":\"You may experience shortness of breath, back pain, practice contractions and slight colostrum leakage from the breasts. Movements are strong and sleep may be harder.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0627\\u06cc \\u062e\\u0648\\u0627\\u0628 \\u0628\\u0647\\u062a\\u0631 \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633 \\u0648 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and sleep on your side for better rest. Take movement counting seriously and know preterm labor and pre-eclampsia signs.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0646\\u06cc\\u062f. \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0648 \\u0634\\u06cc\\u0631\\u062f\\u0647\\u06cc \\u0627\\u0637\\u0644\\u0627\\u0639\\u0627\\u062a \\u06a9\\u0633\\u0628 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep regular visits and review your birth plan with your doctor. Prepare your hospital bag and learn about newborn care and breastfeeding.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0648 \\u0645\\u062b\\u0627\\u0646\\u0647 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u0633\\u06cc\\u0646\\u0647\\u200c\\u0647\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0634\\u06cc\\u0631\\u062f\\u0647\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f \\u0648 \\u06a9\\u0644\\u0633\\u062a\\u0631\\u0648\\u0645 \\u062a\\u0648\\u0644\\u06cc\\u062f \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus is above the navel and pressure on the lungs and bladder increases. The breasts prepare for feeding by producing colostrum as the body readies for birth.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u06a9\\u0645\\u06cc \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0634\\u062f\\u0646 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0631 \\u062e\\u0644\\u0642\\u200c\\u0648\\u062e\\u0648 \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f. \\u0622\\u0645\\u0648\\u0632\\u0634 \\u0648 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0645\\u06cc\\u200c\\u0622\\u0648\\u0631\\u062f.\",\"en\":\"You may feel excitement and some anxiety about the approaching birth. Fatigue can affect mood; education and support bring calm.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0627\\u0632 \\u062a\\u0648\\u0631\\u0645 \\u0648 \\u06cc\\u0628\\u0648\\u0633\\u062a \\u062c\\u0644\\u0648\\u06af\\u06cc\\u0631\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0631\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f.\",\"en\":\"Continue iron, calcium, protein and omega-3 and eat enough fiber. Enough water helps prevent swelling and constipation, and small meals reduce heartburn.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06a9\\u0634\\u0634 \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0647 \\u06a9\\u0627\\u0647\\u0634 \\u062f\\u0631\\u062f\\u0647\\u0627 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle stretching ease aches. Practice pelvic floor and breathing exercises for birth and avoid heavy activity.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0631\\u0634\\u062f \\u0648 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0631\\u0634\\u062f \\u06cc\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u0627\\u06cc\\u0639 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0631\\u0627 \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u06a9\\u0646\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits include blood pressure, weight, growth and the baby\\u2019s position. Your doctor may advise a growth ultrasound or amniotic fluid check; report warning signs.\"}','{\"fa\":[{\"question\":\"\\u0646\\u0634\\u062a \\u06a9\\u0644\\u0633\\u062a\\u0631\\u0648\\u0645 \\u0627\\u0632 \\u0633\\u06cc\\u0646\\u0647 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0644\\u0647\\u060c \\u062a\\u0631\\u0627\\u0648\\u0634 \\u0645\\u0627\\u06cc\\u0639 \\u0632\\u0631\\u062f\\u0631\\u0646\\u06af \\u06a9\\u0644\\u0633\\u062a\\u0631\\u0648\\u0645 \\u062f\\u0631 \\u0627\\u0648\\u0627\\u062e\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u0646\\u0634\\u0627\\u0646\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0634\\u06cc\\u0631\\u062f\\u0647\\u06cc \\u0627\\u0633\\u062a.\"},{\"question\":\"\\u0686\\u0637\\u0648\\u0631 \\u0628\\u0627 \\u0628\\u06cc\\u200c\\u062e\\u0648\\u0627\\u0628\\u06cc \\u06a9\\u0646\\u0627\\u0631 \\u0628\\u06cc\\u0627\\u06cc\\u0645\\u061f\",\"answer\":\"\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f\\u0646 \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 \\u0628\\u0627 \\u0628\\u0627\\u0644\\u0634 \\u062d\\u0645\\u0627\\u06cc\\u062a\\u06cc\\u060c \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0642\\u0628\\u0644 \\u0627\\u0632 \\u062e\\u0648\\u0627\\u0628 \\u0648 \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0622\\u0631\\u0627\\u0645\\u200c\\u0628\\u062e\\u0634 \\u0634\\u0628\\u0627\\u0646\\u0647 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"}],\"en\":[{\"question\":\"Is colostrum leakage normal?\",\"answer\":\"Yes, leaking yellowish colostrum in late pregnancy is normal and shows the body is preparing to breastfeed.\"},{\"question\":\"How can I cope with insomnia?\",\"answer\":\"Side-sleeping with a support pillow, fewer fluids before bed and a calming night routine help.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(32,32,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u062f\\u0648\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06a9\\u062f\\u0648\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4\\u06f2.\\u06f4 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1.\\u06f7 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0646\\u0627\\u062e\\u0646\\u200c\\u0647\\u0627 \\u06a9\\u0627\\u0645\\u0644 \\u0634\\u062f\\u0647 \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0686\\u0631\\u0628\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u0632\\u06cc\\u0631 \\u067e\\u0648\\u0633\\u062a \\u0630\\u062e\\u06cc\\u0631\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0628\\u0633\\u06cc\\u0627\\u0631\\u06cc \\u0627\\u0632 \\u062c\\u0646\\u06cc\\u0646\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0631\\u0648 \\u0628\\u0647 \\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u0646\\u062f.\",\"en\":\"At week thirty-two the fetus is about the size of a squash, roughly 42.4 cm and nearly 1.7 kg. The nails are complete and more fat is stored under the skin, and many babies settle head-down this week.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633\\u060c \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644\\u060c \\u062a\\u0648\\u0631\\u0645 \\u0648 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0627\\u0645\\u0627 \\u0641\\u0636\\u0627\\u06cc \\u06a9\\u0645\\u062a\\u0631\\u06cc \\u062f\\u0627\\u0631\\u062f. \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0633\\u0647\\u200c\\u0645\\u0627\\u0647\\u0647 \\u0633\\u0648\\u0645 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"Shortness of breath, heartburn, swelling and practice contractions may increase. Movements are strong but with less room, and third-trimester fatigue continues.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u0631\\u0633 \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f. \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0632\\u06cc\\u0627\\u062f \\u067e\\u0631\\u0647\\u06cc\\u0632 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take movement counting seriously. Know preterm labor signs, sleep on your side, and avoid overexertion.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0647\\u0631 \\u062f\\u0648 \\u0647\\u0641\\u062a\\u0647 \\u06cc\\u06a9\\u200c\\u0628\\u0627\\u0631 \\u0627\\u0633\\u062a\\u061b \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0642\\u0631\\u0627\\u0631\\u06af\\u06cc\\u0631\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0634\\u06cc\\u0631\\u062f\\u0647\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0648\\u06cc\\u062f.\",\"en\":\"Visits are usually every two weeks; prepare your birth plan and hospital bag. Discuss the baby\\u2019s position with your doctor and get ready for breastfeeding.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0628\\u0647 \\u0628\\u0627\\u0644\\u0627\\u06cc \\u0646\\u0627\\u0641 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0645\\u0639\\u062f\\u0647 \\u0648 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0632\\u06cc\\u0627\\u062f \\u0627\\u0633\\u062a. \\u0645\\u0641\\u0627\\u0635\\u0644 \\u0644\\u06af\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0634\\u0644\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0627 \\u0630\\u062e\\u06cc\\u0631\\u0647 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus is above the navel with high pressure on the stomach and lungs. Pelvic joints loosen for birth as the body stores energy for labor.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0648\\u0627\\u0644\\u062f\\u06af\\u0631\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0635\\u0628\\u0631 \\u0634\\u0645\\u0627 \\u0631\\u0627 \\u06a9\\u0645 \\u06a9\\u0646\\u062f. \\u0635\\u062d\\u0628\\u062a \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0627\\u062d\\u0633\\u0627\\u0633\\u0627\\u062a \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"Excitement and anxiety about birth and parenting may grow. Fatigue can shorten your patience; sharing feelings and resting help.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u063a\\u0646\\u06cc \\u0627\\u0632 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0630\\u062e\\u06cc\\u0631\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0627\\u0632 \\u0642\\u0646\\u062f \\u0648 \\u0646\\u0645\\u06a9 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Continue iron, calcium, protein and fiber and drink enough water. Energy-rich foods help build reserves for labor; limit excess sugar and salt.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u06cc\\u0648\\u06af\\u0627\\u06cc \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0647\\u0645\\u0686\\u0646\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0641\\u0631\\u0627\\u0637 \\u0646\\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Walking, swimming and prenatal yoga remain helpful. Keep pelvic floor and breathing exercises for birth; listen to your body and don\\u2019t overdo it.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0631\\u0634\\u062f \\u0648 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0642\\u0631\\u0627\\u0631\\u06af\\u06cc\\u0631\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u0645\\u0627\\u06cc\\u0639 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0634\\u0648\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits include blood pressure, weight, growth and the baby\\u2019s position. An ultrasound may check the baby\\u2019s position and amniotic fluid; report warning signs.\"}','{\"fa\":[{\"question\":\"\\u0627\\u06af\\u0631 \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0648 \\u0628\\u0647 \\u0628\\u0627\\u0644\\u0627 \\u0628\\u0627\\u0634\\u062f \\u0686\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061f\",\"answer\":\"\\u0647\\u0646\\u0648\\u0632 \\u0641\\u0631\\u0635\\u062a \\u0628\\u0631\\u0627\\u06cc \\u0686\\u0631\\u062e\\u0634 \\u062c\\u0646\\u06cc\\u0646 \\u0648\\u062c\\u0648\\u062f \\u062f\\u0627\\u0631\\u062f\\u061b \\u0627\\u06af\\u0631 \\u062a\\u0627 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u067e\\u0627\\u06cc\\u0627\\u0646\\u06cc \\u0628\\u0631\\u06cc\\u0686 \\u0628\\u0645\\u0627\\u0646\\u062f\\u060c \\u067e\\u0632\\u0634\\u06a9 \\u06af\\u0632\\u06cc\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0627\\u0633\\u0628 \\u0631\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"},{\"question\":\"\\u06a9\\u0627\\u0647\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0686\\u0637\\u0648\\u0631 \\u062a\\u0634\\u062e\\u06cc\\u0635 \\u062f\\u0647\\u0645\\u061f\",\"answer\":\"\\u0627\\u06af\\u0631 \\u0627\\u0644\\u06af\\u0648\\u06cc \\u0645\\u0639\\u0645\\u0648\\u0644 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u06a9\\u0645 \\u0634\\u062f \\u06cc\\u0627 \\u062a\\u063a\\u06cc\\u06cc\\u0631 \\u06a9\\u0631\\u062f\\u060c \\u0628\\u0644\\u0627\\u0641\\u0627\\u0635\\u0644\\u0647 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062a\\u0645\\u0627\\u0633 \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"What if the baby is breech?\",\"answer\":\"There is still time to turn; if it stays breech near the end, your doctor will review suitable options.\"},{\"question\":\"How do I notice reduced movements?\",\"answer\":\"If the usual movement pattern decreases or changes, contact your doctor immediately.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(33,33,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u0633\\u0648\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0622\\u0646\\u0627\\u0646\\u0627\\u0633\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4\\u06f3.\\u06f7 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f1.\\u06f9 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646\\u200c\\u0647\\u0627\\u06cc \\u062c\\u0645\\u062c\\u0645\\u0647 \\u0647\\u0646\\u0648\\u0632 \\u0646\\u0631\\u0645 \\u0648 \\u0627\\u0646\\u0639\\u0637\\u0627\\u0641\\u200c\\u067e\\u0630\\u06cc\\u0631 \\u0647\\u0633\\u062a\\u0646\\u062f \\u062a\\u0627 \\u0627\\u0632 \\u06a9\\u0627\\u0646\\u0627\\u0644 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0639\\u0628\\u0648\\u0631 \\u06a9\\u0646\\u0646\\u062f. \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u0627\\u06cc\\u0645\\u0646\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u0642\\u0648\\u06cc\\u062a \\u0627\\u0633\\u062a.\",\"en\":\"At week thirty-three the fetus is about the size of a pineapple, roughly 43.7 cm and nearly 1.9 kg. The skull bones are still soft and flexible to pass through the birth canal, and the baby\\u2019s immune system is strengthening.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633\\u060c \\u062a\\u0648\\u0631\\u0645\\u060c \\u06a9\\u0645\\u0631\\u062f\\u0631\\u062f \\u0648 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u062d\\u0633\\u0627\\u0633 \\u0641\\u0634\\u0627\\u0631 \\u062f\\u0631 \\u0644\\u06af\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Shortness of breath, swelling, back pain and practice contractions may increase. Movements are strong, and you may feel pressure in the pelvis.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0645\\u0627\\u0646\\u0646\\u062f \\u0648\\u0631\\u0645 \\u0646\\u0627\\u06af\\u0647\\u0627\\u0646\\u06cc \\u0648 \\u0633\\u0631\\u062f\\u0631\\u062f \\u0634\\u062f\\u06cc\\u062f \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take pre-eclampsia signs like sudden swelling and severe headache seriously. Keep counting movements and rest enough.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u06a9\\u0646\\u06cc\\u062f. \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u06cc\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0634\\u0631\\u0648\\u0639 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0634\\u0645\\u0627\\u0631\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0627\\u0636\\u0637\\u0631\\u0627\\u0631\\u06cc \\u0631\\u0627 \\u062f\\u0631 \\u062f\\u0633\\u062a\\u0631\\u0633 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Keep regular visits and finalize your birth plan. Your hospital bag should be ready; review the signs of labor and keep emergency numbers handy.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0641\\u0636\\u0627\\u06cc \\u0632\\u06cc\\u0627\\u062f\\u06cc \\u0627\\u0634\\u063a\\u0627\\u0644 \\u06a9\\u0631\\u062f\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627 \\u0632\\u06cc\\u0627\\u062f \\u0627\\u0633\\u062a. \\u0627\\u062d\\u062a\\u0628\\u0627\\u0633 \\u0645\\u0627\\u06cc\\u0639\\u0627\\u062a \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0648\\u0631\\u0645 \\u0631\\u0627 \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u062f\\u0647\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The uterus fills much space with high pressure on the organs. Fluid retention may increase swelling as the body prepares for the approaching birth.\"}','{\"fa\":\"\\u0628\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0634\\u062f\\u0646 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0647\\u0645\\u0632\\u0645\\u0627\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u063a\\u0631\\u06cc\\u0632\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u062e\\u0627\\u0646\\u0647 (\\u0644\\u0627\\u0646\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc) \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0639\\u0627\\u0644 \\u0634\\u0648\\u062f. \\u0622\\u0645\\u0648\\u0632\\u0634 \\u0648 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"As birth nears you may feel both excitement and anxiety. A nesting instinct to prepare the home may appear; education and support help.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0645\\u063a\\u0630\\u06cc \\u0648 \\u0645\\u062a\\u0639\\u0627\\u062f\\u0644 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0644\\u0627\\u0632\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0641\\u0631\\u0627\\u0647\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u0632 \\u0642\\u0646\\u062f \\u0648 \\u0646\\u0645\\u06a9 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Continue iron, calcium, protein and omega-3 and get enough fiber and water. Nutritious balanced meals provide energy for labor; limit excess sugar and salt.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc\\u060c \\u0634\\u0646\\u0627 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u0645\\u0644\\u0627\\u06cc\\u0645 \\u0628\\u0647 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0648 \\u067e\\u0631\\u062e\\u0637\\u0631 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Walking, swimming and gentle exercise aid birth readiness. Keep pelvic floor and breathing exercises and avoid heavy or risky activities.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0631\\u0634\\u062f \\u0648 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0642\\u0631\\u0627\\u0631\\u06af\\u06cc\\u0631\\u06cc \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits include blood pressure, weight, growth and the baby\\u2019s position. Your doctor may do an ultrasound to check position; report labor and pre-eclampsia signs.\"}','{\"fa\":[{\"question\":\"\\u063a\\u0631\\u06cc\\u0632\\u0647 \\u0644\\u0627\\u0646\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0645\\u06cc\\u0644 \\u0646\\u0627\\u06af\\u0647\\u0627\\u0646\\u06cc \\u0628\\u0647 \\u062a\\u0645\\u06cc\\u0632 \\u06a9\\u0631\\u062f\\u0646 \\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u062e\\u0627\\u0646\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u0646\\u0648\\u0632\\u0627\\u062f \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u062f\\u0631 \\u0627\\u0648\\u0627\\u062e\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a \\u0648 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0645\\u062d\\u0633\\u0648\\u0628 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0641\\u0634\\u0627\\u0631 \\u062f\\u0631 \\u0644\\u06af\\u0646 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u0628\\u0627 \\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u0622\\u0645\\u062f\\u0646 \\u062c\\u0646\\u06cc\\u0646\\u060c \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061b \\u0627\\u0645\\u0627 \\u0641\\u0634\\u0627\\u0631 \\u0631\\u06cc\\u062a\\u0645\\u06cc\\u06a9 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u062f\\u0631\\u062f \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0646\\u0634\\u0627\\u0646\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u0634\\u062f.\"}],\"en\":[{\"question\":\"What is the nesting instinct?\",\"answer\":\"It is a sudden urge to clean and prepare the home for the baby, common in late pregnancy and considered normal.\"},{\"question\":\"Is pelvic pressure normal?\",\"answer\":\"As the baby drops, pelvic pressure is normal, but rhythmic pressure with pain may signal labor.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(34,34,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u0686\\u0647\\u0627\\u0631\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0637\\u0627\\u0644\\u0628\\u06cc\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4\\u06f5 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f2.\\u06f1 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u062a\\u0642\\u0631\\u06cc\\u0628\\u0627\\u064b \\u0628\\u0627\\u0644\\u063a \\u0634\\u062f\\u0647\\u200c\\u0627\\u0646\\u062f \\u0648 \\u0633\\u06cc\\u0633\\u062a\\u0645 \\u0639\\u0635\\u0628\\u06cc \\u0645\\u0631\\u06a9\\u0632\\u06cc \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u062a\\u06a9\\u0627\\u0645\\u0644 \\u0627\\u0633\\u062a. \\u0627\\u06af\\u0631 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u0628\\u0647 \\u062f\\u0646\\u06cc\\u0627 \\u0628\\u06cc\\u0627\\u06cc\\u062f\\u060c \\u0634\\u0627\\u0646\\u0633 \\u062e\\u0648\\u0628\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0633\\u0644\\u0627\\u0645\\u062a \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"At week thirty-four the fetus is about the size of a cantaloupe, roughly 45 cm and nearly 2.1 kg. The lungs are nearly mature and the central nervous system is developing; a baby born now has a good chance of doing well.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633\\u060c \\u062a\\u0648\\u0631\\u0645\\u060c \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc \\u0648 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0642\\u0648\\u06cc \\u0627\\u0645\\u0627 \\u0645\\u062d\\u062f\\u0648\\u062f\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0648 \\u0645\\u0634\\u06a9\\u0644\\u0627\\u062a \\u062e\\u0648\\u0627\\u0628 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Shortness of breath, swelling, pelvic pressure and practice contractions may increase. Movements are strong but more limited, and you may have fatigue and sleep issues.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0628\\u0647 \\u067e\\u0647\\u0644\\u0648 \\u0628\\u062e\\u0648\\u0627\\u0628\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take movement counting seriously. Know labor and pre-eclampsia signs, rest enough, and sleep on your side.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0645\\u0646\\u0638\\u0645 \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc GBS \\u067e\\u06cc\\u0634 \\u0631\\u0648 \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u06cc\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0645\\u0633\\u06cc\\u0631 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0631\\u0627 \\u0627\\u0632 \\u0642\\u0628\\u0644 \\u0645\\u0634\\u062e\\u0635 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep regular visits and discuss the upcoming GBS screening with your doctor. Your birth plan and hospital bag should be ready; plan your route to the hospital.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u0641\\u0636\\u0627\\u06cc \\u0632\\u06cc\\u0627\\u062f\\u06cc \\u06af\\u0631\\u0641\\u062a\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0648 \\u0644\\u06af\\u0646 \\u0632\\u06cc\\u0627\\u062f \\u0627\\u0633\\u062a. \\u0645\\u0641\\u0627\\u0635\\u0644 \\u0644\\u06af\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0634\\u0644\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0630\\u062e\\u06cc\\u0631\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"The uterus takes much space with high pressure on the lungs and pelvis. Pelvic joints loosen for birth as the body stores energy for labor.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0628\\u0631\\u0627\\u06cc \\u062f\\u06cc\\u062f\\u0646 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0628\\u0627 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u0631 \\u062e\\u0644\\u0642\\u200c\\u0648\\u062e\\u0648 \\u0627\\u062b\\u0631 \\u0628\\u06af\\u0630\\u0627\\u0631\\u062f. \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0639\\u0627\\u0637\\u0641\\u06cc \\u0648 \\u0622\\u0645\\u0648\\u0632\\u0634 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0645\\u06cc\\u200c\\u0622\\u0648\\u0631\\u062f.\",\"en\":\"Anticipation to meet the baby may mix with birth anxiety. Fatigue can affect mood; emotional support and birth education bring calm.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0645\\u063a\\u0630\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0630\\u062e\\u06cc\\u0631\\u0647 \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0633\\u0648\\u0632\\u0634 \\u0633\\u0631\\u062f\\u0644 \\u0631\\u0627 \\u06a9\\u0627\\u0647\\u0634 \\u0645\\u06cc\\u200c\\u062f\\u0647\\u062f.\",\"en\":\"Continue iron, calcium, protein and fiber and drink enough water. Nutritious foods help store energy for labor, and small meals reduce heartburn.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0648 \\u0634\\u0646\\u0627 \\u0628\\u0647 \\u06af\\u0631\\u062f\\u0634 \\u062e\\u0648\\u0646 \\u0648 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0648 \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Walking and swimming aid circulation and birth readiness. Keep pelvic floor and breathing exercises, avoid heavy activity, and rest.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0631\\u0634\\u062f \\u0648 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0627\\u0633\\u062a\\u0631\\u067e\\u062a\\u0648\\u06a9\\u0648\\u06a9 \\u06af\\u0631\\u0648\\u0647 B (GBS) \\u0628\\u0647\\u200c\\u0632\\u0648\\u062f\\u06cc \\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06f3\\u06f5 \\u062a\\u0627 \\u06f3\\u06f7 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0647\\u0634\\u062f\\u0627\\u0631 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Routine visits include blood pressure, weight, growth and the baby\\u2019s position. Group B strep (GBS) screening is done soon in weeks 35 to 37; report warning signs.\"}','{\"fa\":[{\"question\":\"\\u0627\\u06af\\u0631 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0632\\u0648\\u062f\\u062a\\u0631 \\u0634\\u0631\\u0648\\u0639 \\u0634\\u0648\\u062f \\u0686\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061f\",\"answer\":\"\\u062f\\u0631 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u062a\\u0642\\u0631\\u06cc\\u0628\\u0627\\u064b \\u0628\\u0627\\u0644\\u063a\\u200c\\u0627\\u0646\\u062f \\u0648 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062e\\u0648\\u0628\\u06cc \\u062f\\u0627\\u0631\\u062f\\u060c \\u0647\\u0631\\u0686\\u0646\\u062f \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0647 \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u06a9\\u0648\\u062a\\u0627\\u0647 \\u0646\\u06cc\\u0627\\u0632 \\u0628\\u0627\\u0634\\u062f.\"},{\"question\":\"\\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc GBS \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u06cc\\u06a9 \\u0646\\u0645\\u0648\\u0646\\u0647\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0633\\u0627\\u062f\\u0647 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0628\\u0627\\u06a9\\u062a\\u0631\\u06cc \\u0627\\u0633\\u062a\\u0631\\u067e\\u062a\\u0648\\u06a9\\u0648\\u06a9 \\u06af\\u0631\\u0648\\u0647 B \\u0627\\u0633\\u062a \\u062a\\u0627 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0648\\u062c\\u0648\\u062f\\u060c \\u0647\\u0646\\u06af\\u0627\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0622\\u0646\\u062a\\u06cc\\u200c\\u0628\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u062a\\u062c\\u0648\\u06cc\\u0632 \\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"What if labor starts earlier?\",\"answer\":\"By this week the lungs are nearly mature and the baby usually does well, though brief care may be needed.\"},{\"question\":\"What is GBS screening?\",\"answer\":\"It is a simple swab to check for group B strep bacteria so antibiotics can be given during labor if present.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(35,35,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u067e\\u0646\\u062c\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u062e\\u0631\\u0628\\u0632\\u0647\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4\\u06f6.\\u06f2 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f2.\\u06f4 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u06a9\\u0644\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0628\\u0647\\u200c\\u0637\\u0648\\u0631 \\u06a9\\u0627\\u0645\\u0644 \\u0631\\u0634\\u062f \\u06a9\\u0631\\u062f\\u0647\\u200c\\u0627\\u0646\\u062f \\u0648 \\u06a9\\u0628\\u062f \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u067e\\u0631\\u062f\\u0627\\u0632\\u0634 \\u0645\\u0648\\u0627\\u062f \\u0632\\u0627\\u0626\\u062f \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647\\u200c\\u0633\\u0631\\u0639\\u062a \\u0648\\u0632\\u0646 \\u0627\\u0636\\u0627\\u0641\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u0641\\u0636\\u0627\\u06cc \\u0631\\u062d\\u0645 \\u062a\\u0646\\u06af\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"At week thirty-five the fetus is about the size of a honeydew, roughly 46.2 cm and nearly 2.4 kg. The kidneys are fully developed and the liver begins processing waste, while the baby gains weight fast and the womb grows snug.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc\\u060c \\u062a\\u06a9\\u0631\\u0631 \\u0627\\u062f\\u0631\\u0627\\u0631 \\u0648 \\u062a\\u0646\\u06af\\u06cc \\u0646\\u0641\\u0633 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0628\\u0647\\u200c\\u0635\\u0648\\u0631\\u062a \\u067e\\u06cc\\u0686\\u200c\\u0648\\u062a\\u0627\\u0628 \\u062d\\u0633 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0645\\u06a9\\u0631\\u0631 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Pelvic pressure, frequent urination and shortness of breath may increase. Movements feel more like squirms, and you may have frequent practice contractions.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648\\u0627\\u0642\\u0639\\u06cc \\u0648 \\u067e\\u0631\\u0647\\u200c\\u0627\\u06a9\\u0644\\u0627\\u0645\\u067e\\u0633\\u06cc \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f \\u0648 \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0646\\u06af\\u0647 \\u062f\\u0627\\u0631\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take movement counting seriously. Know true labor and pre-eclampsia signs, rest enough, and keep the hospital bag ready.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0645\\u06a9\\u0631\\u0631\\u200c\\u062a\\u0631 \\u0634\\u0648\\u062f\\u061b \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc GBS \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0645\\u0633\\u06cc\\u0631 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0631\\u0627 \\u0645\\u0634\\u062e\\u0635 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0631\\u0627\\u06cc \\u0634\\u06cc\\u0631\\u062f\\u0647\\u06cc \\u0648 \\u0645\\u0631\\u0627\\u0642\\u0628\\u062a \\u0627\\u0632 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0648\\u06cc\\u062f.\",\"en\":\"Visits may become more frequent, and GBS screening is done from this week. Finalize your birth plan and hospital route and prepare for breastfeeding and newborn care.\"}','{\"fa\":\"\\u0631\\u062d\\u0645 \\u062a\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0642\\u0641\\u0633\\u0647 \\u0633\\u06cc\\u0646\\u0647 \\u0628\\u0627\\u0644\\u0627 \\u0622\\u0645\\u062f\\u0647 \\u0648 \\u0641\\u0634\\u0627\\u0631 \\u0628\\u0631 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u0648 \\u0645\\u0639\\u062f\\u0647 \\u0632\\u06cc\\u0627\\u062f \\u0627\\u0633\\u062a. \\u0644\\u06af\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0634\\u0644 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u062f\\u0646 \\u062f\\u0631 \\u0645\\u0631\\u062d\\u0644\\u0647 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0627\\u0633\\u062a.\",\"en\":\"The uterus has risen near the ribs with high pressure on the lungs and stomach. The pelvis loosens for birth as the body enters its final preparation.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u062f\\u06cc\\u062f\\u0646 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0628\\u0627 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u063a\\u0631\\u06cc\\u0632\\u0647 \\u0644\\u0627\\u0646\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0642\\u0648\\u06cc \\u0634\\u0648\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0648 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0639\\u0627\\u0637\\u0641\\u06cc \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"Excitement to meet the baby may mix with birth anxiety and waiting. The nesting instinct may grow strong; rest and emotional support matter.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0627\\u0645\\u06af\\u0627-\\u06f3 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0645\\u0635\\u0631\\u0641 \\u06a9\\u0646\\u06cc\\u062f. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0628\\u0647 \\u062f\\u0644\\u06cc\\u0644 \\u0641\\u0636\\u0627\\u06cc \\u06a9\\u0645 \\u0645\\u0639\\u062f\\u0647 \\u0628\\u0647\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0627\\u0632 \\u0642\\u0646\\u062f \\u0648 \\u0646\\u0645\\u06a9 \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Continue iron, calcium, protein and omega-3 and get enough fiber and water. Small frequent meals suit the reduced stomach space; limit excess sugar and salt.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0628\\u0647 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u062f\\u0631\\u062f \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0632 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a\\u200c\\u0647\\u0627\\u06cc \\u0633\\u0646\\u06af\\u06cc\\u0646 \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Light walking and pelvic floor exercises aid birth readiness. Practice breathing exercises to manage labor pain and avoid heavy activity.\"}','{\"fa\":\"\\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc \\u0627\\u0633\\u062a\\u0631\\u067e\\u062a\\u0648\\u06a9\\u0648\\u06a9 \\u06af\\u0631\\u0648\\u0647 B (GBS) \\u0628\\u0627 \\u0646\\u0645\\u0648\\u0646\\u0647\\u200c\\u06af\\u06cc\\u0631\\u06cc \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0631\\u0648\\u062a\\u06cc\\u0646 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u06af\\u0627\\u0647\\u06cc \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0627\\u0633\\u062a. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Group B strep (GBS) screening by swab is done from this week. Routine visits include blood pressure, weight, the baby\\u2019s position and sometimes a cervical check.\"}','{\"fa\":[{\"question\":\"\\u062a\\u0641\\u0627\\u0648\\u062a \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636 \\u0648\\u0627\\u0642\\u0639\\u06cc \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0627\\u0646\\u0642\\u0628\\u0627\\u0636 \\u0648\\u0627\\u0642\\u0639\\u06cc \\u0645\\u0646\\u0638\\u0645\\u060c \\u0641\\u0632\\u0627\\u06cc\\u0646\\u062f\\u0647 \\u0648 \\u062f\\u0631\\u062f\\u0646\\u0627\\u06a9 \\u0627\\u0633\\u062a \\u0648 \\u0628\\u0627 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u0645\\u062a\\u0648\\u0642\\u0641 \\u0646\\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u060c \\u0627\\u0645\\u0627 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0646\\u0627\\u0645\\u0646\\u0638\\u0645 \\u0648 \\u06af\\u0630\\u0631\\u0627\\u0633\\u062a.\"},{\"question\":\"\\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc GBS \\u0686\\u06af\\u0648\\u0646\\u0647 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u06cc\\u06a9 \\u0646\\u0645\\u0648\\u0646\\u0647 \\u0633\\u0627\\u062f\\u0647 \\u0627\\u0632 \\u0648\\u0627\\u0698\\u0646 \\u0648 \\u0645\\u0642\\u0639\\u062f \\u06af\\u0631\\u0641\\u062a\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0645\\u062b\\u0628\\u062a \\u0628\\u0648\\u062f\\u0646\\u060c \\u0647\\u0646\\u06af\\u0627\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0622\\u0646\\u062a\\u06cc\\u200c\\u0628\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u062f\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"What is the difference between real and practice contractions?\",\"answer\":\"Real contractions are regular, intensifying and painful and don\\u2019t stop with rest, while practice ones are irregular and fleeting.\"},{\"question\":\"How is GBS screening done?\",\"answer\":\"A simple swab of the vagina and rectum is taken, and if positive, antibiotics are given during labor.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(36,36,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u0634\\u0634\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06a9\\u0627\\u0647\\u0648 \\u0631\\u0648\\u0645\\u06cc\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4\\u06f7.\\u06f4 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f2.\\u06f6 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u062f\\u0631 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0631\\u0648 \\u0628\\u0647 \\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u062f \\u0648 \\u06a9\\u0631\\u06a9 \\u0644\\u0627\\u0646\\u0648\\u06af\\u0648 \\u062a\\u0642\\u0631\\u06cc\\u0628\\u0627\\u064b \\u0627\\u0632 \\u0628\\u06cc\\u0646 \\u0631\\u0641\\u062a\\u0647 \\u0627\\u0633\\u062a. \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u062f\\u0631 \\u062d\\u0627\\u0644 \\u06a9\\u0627\\u0645\\u0644 \\u0634\\u062f\\u0646 \\u0647\\u0633\\u062a\\u0646\\u062f.\",\"en\":\"At week thirty-six the fetus is about the size of a romaine lettuce, roughly 47.4 cm and nearly 2.6 kg. The baby usually settles head-down, the lanugo is nearly gone, and the lungs are almost fully developed.\"}','{\"fa\":\"\\u0628\\u0627 \\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u0622\\u0645\\u062f\\u0646 \\u062c\\u0646\\u06cc\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0646\\u0641\\u0633 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0627\\u0645\\u0627 \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062a\\u06a9\\u0631\\u0631 \\u0627\\u062f\\u0631\\u0627\\u0631 \\u0648 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u0645\\u06cc\\u200c\\u06cc\\u0627\\u0628\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0632\\u06cc\\u0627\\u062f\\u06cc \\u0627\\u062d\\u0633\\u0627\\u0633 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"As the baby drops, breathing may ease but pelvic pressure increases. Frequent urination and practice contractions rise, and you may feel very tired.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648\\u0627\\u0642\\u0639\\u06cc \\u0631\\u0627 \\u0628\\u0634\\u0646\\u0627\\u0633\\u06cc\\u062f \\u0648 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628 \\u0641\\u0648\\u0631\\u0627\\u064b \\u0627\\u0642\\u062f\\u0627\\u0645 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take movement counting seriously. Know true labor signs and act at once if your waters break; rest enough.\"}','{\"fa\":\"\\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627 \\u0645\\u0639\\u0645\\u0648\\u0644\\u0627\\u064b \\u0647\\u0641\\u062a\\u06af\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0627\\u06af\\u0631 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc GBS \\u0631\\u0627 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f. \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u06cc\\u062f \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f.\",\"en\":\"From this week visits usually become weekly. Do the GBS screening if not done, and your hospital bag and birth plan should be fully ready.\"}','{\"fa\":\"\\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0633\\u0645\\u062a \\u0644\\u06af\\u0646 \\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u0622\\u06cc\\u062f \\u06a9\\u0647 \\u0641\\u0634\\u0627\\u0631 \\u0642\\u0641\\u0633\\u0647 \\u0633\\u06cc\\u0646\\u0647 \\u0631\\u0627 \\u06a9\\u0645 \\u0627\\u0645\\u0627 \\u0641\\u0634\\u0627\\u0631 \\u0645\\u062b\\u0627\\u0646\\u0647 \\u0631\\u0627 \\u0632\\u06cc\\u0627\\u062f \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u0646\\u0631\\u0645 \\u0634\\u062f\\u0646 \\u06a9\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"The baby moves down into the pelvis, easing chest pressure but increasing bladder pressure. The cervix may begin to soften as the body prepares for labor.\"}','{\"fa\":\"\\u0628\\u0627 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0634\\u062f\\u0646 \\u0628\\u0647 \\u0645\\u0648\\u0639\\u062f \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0648 \\u0628\\u06cc\\u200c\\u0635\\u0628\\u0631\\u06cc \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0622\\u0645\\u0627\\u062f\\u0647\\u200c\\u0633\\u0627\\u0632\\u06cc \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0628\\u062f\\u0647\\u062f. \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0627\\u0637\\u0631\\u0627\\u0641\\u06cc\\u0627\\u0646 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"As the due date nears you may feel excitement and impatience along with anxiety. Final preparations can bring calm, and support from others matters.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0647\\u0636\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0645\\u063a\\u0630\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a.\",\"en\":\"Continue iron, calcium, protein and fiber and drink enough water. Small frequent meals digest more easily, and nutritious foods help energy for labor.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0628\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0632 \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0632\\u06cc\\u0627\\u062f \\u0628\\u067e\\u0631\\u0647\\u06cc\\u0632\\u06cc\\u062f.\",\"en\":\"Light walking and pelvic floor exercises help prepare for labor. Practice breathing exercises, listen to your body, and avoid overexertion.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627 \\u0627\\u0632 \\u0627\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u0647\\u0641\\u062a\\u06af\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0627\\u0633\\u062a. \\u0646\\u062a\\u06cc\\u062c\\u0647 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc GBS \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Visits become weekly from this week and include blood pressure, weight, the baby\\u2019s position and a cervical check. The GBS result is reviewed; report labor signs.\"}','{\"fa\":[{\"question\":\"\\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u0622\\u0645\\u062f\\u0646 \\u062c\\u0646\\u06cc\\u0646 \\u06cc\\u0639\\u0646\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0627\\u0633\\u062a\\u061f\",\"answer\":\"\\u067e\\u0627\\u06cc\\u06cc\\u0646 \\u0622\\u0645\\u062f\\u0646 \\u062c\\u0646\\u06cc\\u0646 \\u0646\\u0634\\u0627\\u0646\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u0628\\u062f\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0645\\u0627 \\u0644\\u0632\\u0648\\u0645\\u0627\\u064b \\u0628\\u0647 \\u0645\\u0639\\u0646\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0641\\u0648\\u0631\\u06cc \\u0646\\u06cc\\u0633\\u062a \\u0648 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0647\\u0641\\u062a\\u0647\\u200c\\u0647\\u0627 \\u0632\\u0648\\u062f\\u062a\\u0631 \\u0631\\u062e \\u062f\\u0647\\u062f.\"},{\"question\":\"\\u0627\\u06af\\u0631 \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628 \\u067e\\u0627\\u0631\\u0647 \\u0634\\u0648\\u062f \\u0686\\u0647 \\u06a9\\u0646\\u0645\\u061f\",\"answer\":\"\\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0646\\u0634\\u062a \\u06cc\\u0627 \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628\\u060c \\u0641\\u0648\\u0631\\u0627\\u064b \\u0628\\u0627 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u06cc\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062a\\u0645\\u0627\\u0633 \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f \\u062d\\u062a\\u06cc \\u0627\\u06af\\u0631 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636 \\u0646\\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\"}],\"en\":[{\"question\":\"Does the baby dropping mean labor is near?\",\"answer\":\"Dropping shows the body is getting ready but doesn\\u2019t necessarily mean immediate labor and can happen weeks early.\"},{\"question\":\"What if my waters break?\",\"answer\":\"If your waters leak or break, contact the hospital or doctor immediately even without contractions.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(37,37,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u0647\\u0641\\u062a\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0628\\u0631\\u06af \\u0686\\u063a\\u0646\\u062f\\u0631\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4\\u06f8.\\u06f6 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f2.\\u06f9 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a \\u0648 \\u0627\\u06a9\\u0646\\u0648\\u0646 \\u00ab\\u062a\\u0631\\u0645 \\u0627\\u0648\\u0644\\u06cc\\u0647\\u00bb \\u0645\\u062d\\u0633\\u0648\\u0628 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0646\\u0641\\u0633\\u060c \\u0645\\u06a9\\u06cc\\u062f\\u0646 \\u0648 \\u0628\\u0644\\u0639\\u06cc\\u062f\\u0646 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u0631\\u06cc\\u0647\\u200c\\u0647\\u0627 \\u062a\\u0642\\u0631\\u06cc\\u0628\\u0627\\u064b \\u06a9\\u0627\\u0645\\u0644 \\u0647\\u0633\\u062a\\u0646\\u062f. \\u0686\\u0631\\u0628\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631\\u06cc \\u0632\\u06cc\\u0631 \\u067e\\u0648\\u0633\\u062a \\u0630\\u062e\\u06cc\\u0631\\u0647 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\",\"en\":\"At week thirty-seven the fetus is about the size of a bunch of chard, roughly 48.6 cm and nearly 2.9 kg, and is now considered early term. The baby practices breathing, sucking and swallowing with nearly complete lungs and stores more fat.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc\\u060c \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0648 \\u062a\\u0631\\u0634\\u062d\\u0627\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0641\\u062a\\u0627\\u062f\\u06af\\u06cc \\u0645\\u062e\\u0627\\u0637\\u06cc (\\u0646\\u0634\\u0627\\u0646\\u0647 \\u062e\\u0648\\u0646\\u06cc) \\u0631\\u0627 \\u0628\\u0628\\u06cc\\u0646\\u06cc\\u062f. \\u062e\\u0633\\u062a\\u06af\\u06cc \\u0648 \\u0628\\u06cc\\u200c\\u0642\\u0631\\u0627\\u0631\\u06cc \\u0634\\u0627\\u06cc\\u0639 \\u0627\\u0633\\u062a.\",\"en\":\"Pelvic pressure, practice contractions and discharge may increase. You may notice the mucus plug (bloody show), and fatigue and restlessness are common.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648\\u0627\\u0642\\u0639\\u06cc \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628 \\u06cc\\u0627 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645 \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take true labor signs seriously. Go to the hospital if your waters break or contractions become regular; rest enough.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627 \\u0647\\u0641\\u062a\\u06af\\u06cc \\u0627\\u0633\\u062a \\u0648 \\u0634\\u0627\\u0645\\u0644 \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0648 \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u06cc\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0634\\u0631\\u0648\\u0639 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0632\\u0645\\u0627\\u0646 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0631\\u0627 \\u0645\\u0631\\u0648\\u0631 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Visits are weekly and include a cervical check. Your birth plan and hospital bag should be ready; review labor signs and when to go to the hospital.\"}','{\"fa\":\"\\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0634\\u0631\\u0648\\u0639 \\u0628\\u0647 \\u0646\\u0627\\u0632\\u06a9 \\u0648 \\u0628\\u0627\\u0632 \\u0634\\u062f\\u0646 \\u06a9\\u0646\\u062f \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u062f\\u0631 \\u0644\\u06af\\u0646 \\u067e\\u0627\\u06cc\\u06cc\\u0646\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0622\\u06cc\\u062f. \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0645\\u06a9\\u0631\\u0631\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u062f\\u0646 \\u062f\\u0631 \\u0622\\u0633\\u062a\\u0627\\u0646\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0627\\u0633\\u062a.\",\"en\":\"The cervix may begin to thin and open and the baby settles lower in the pelvis. Practice contractions grow more frequent as the body nears labor.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0631\\u06a9\\u06cc\\u0628\\u06cc \\u0627\\u0632 \\u0647\\u06cc\\u062c\\u0627\\u0646\\u060c \\u0628\\u06cc\\u200c\\u0635\\u0628\\u0631\\u06cc \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0633\\u062e\\u062a \\u0628\\u0627\\u0634\\u062f. \\u062a\\u0645\\u0631\\u06a9\\u0632 \\u0628\\u0631 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u0648 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"You may feel a mix of excitement, impatience and birth anxiety. The waiting can be hard; focusing on preparation and calm helps.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0645\\u063a\\u0630\\u06cc \\u0648 \\u0627\\u0646\\u0631\\u0698\\u06cc\\u200c\\u0632\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0647\\u0636\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"Continue iron, calcium, protein and fiber and drink enough water. Nutritious, energizing foods help for labor, and small meals digest more easily.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0628\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0641\\u0631\\u0627\\u0637 \\u0646\\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Light walking and pelvic floor exercises help prepare for labor. Practice breathing exercises, listen to your body, and don\\u2019t overdo it.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0647\\u0641\\u062a\\u06af\\u06cc \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0646\\u0627\\u0632\\u06a9 \\u0648 \\u0628\\u0627\\u0632 \\u0634\\u062f\\u0646 \\u0627\\u0633\\u062a. \\u0627\\u06af\\u0631 \\u063a\\u0631\\u0628\\u0627\\u0644\\u06af\\u0631\\u06cc GBS \\u0631\\u0627 \\u0646\\u062f\\u0627\\u062f\\u0647\\u200c\\u0627\\u06cc\\u062f \\u0627\\u0646\\u062c\\u0627\\u0645 \\u062f\\u0647\\u06cc\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Weekly visits include blood pressure, weight, the baby\\u2019s position and a cervical check for thinning and dilation. Do GBS screening if not done; report labor signs.\"}','{\"fa\":[{\"question\":\"\\u00ab\\u062a\\u0631\\u0645 \\u0627\\u0648\\u0644\\u06cc\\u0647\\u00bb \\u06cc\\u0639\\u0646\\u06cc \\u0686\\u0647\\u061f\",\"answer\":\"\\u06cc\\u0639\\u0646\\u06cc \\u0646\\u0648\\u0632\\u0627\\u062f \\u0627\\u0632 \\u0647\\u0641\\u062a\\u0647 \\u06f3\\u06f7 \\u0628\\u0647 \\u0628\\u0644\\u0648\\u063a \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0648\\u0644\\u062f \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0627\\u0633\\u062a\\u060c \\u0647\\u0631\\u0686\\u0646\\u062f \\u0645\\u0627\\u0646\\u062f\\u0646 \\u062a\\u0627 \\u0647\\u0641\\u062a\\u0647 \\u06f3\\u06f9 \\u0628\\u0631\\u0627\\u06cc \\u0631\\u0634\\u062f \\u06a9\\u0627\\u0645\\u0644 \\u0628\\u0647\\u062a\\u0631 \\u0627\\u0633\\u062a.\"},{\"question\":\"\\u0646\\u0634\\u0627\\u0646\\u0647 \\u062e\\u0648\\u0646\\u06cc (\\u0627\\u0641\\u062a\\u0627\\u062f\\u06af\\u06cc \\u0645\\u062e\\u0627\\u0637\\u06cc) \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u062e\\u0631\\u0648\\u062c \\u062a\\u0648\\u062f\\u0647 \\u0645\\u062e\\u0627\\u0637\\u06cc \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u06a9\\u0645\\u06cc \\u062e\\u0648\\u0646 \\u0646\\u0634\\u0627\\u0646\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0627\\u0633\\u062a \\u0648 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0686\\u0646\\u062f \\u0631\\u0648\\u0632 \\u067e\\u06cc\\u0634 \\u0627\\u0632 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u062e \\u062f\\u0647\\u062f.\"}],\"en\":[{\"question\":\"What does early term mean?\",\"answer\":\"It means from week 37 the baby is mature enough for birth, though staying to week 39 is better for full development.\"},{\"question\":\"What is the bloody show?\",\"answer\":\"It is the mucus plug with a little blood, a sign the cervix is preparing, and can occur days before labor.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(38,38,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u0647\\u0634\\u062a\\u0645 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u062a\\u0631\\u0647\\u200c\\u0641\\u0631\\u0646\\u06af\\u06cc\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f4\\u06f9.\\u06f8 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f3.\\u06f1 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627 \\u06a9\\u0627\\u0645\\u0644 \\u0634\\u062f\\u0647 \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0646\\u062f\\u06af\\u06cc \\u062e\\u0627\\u0631\\u062c \\u0627\\u0632 \\u0631\\u062d\\u0645 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0686\\u0646\\u06af \\u0632\\u062f\\u0646 \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631 \\u0634\\u062f\\u0647 \\u0648 \\u0631\\u0646\\u06af \\u0686\\u0634\\u0645\\u200c\\u0647\\u0627 \\u0647\\u0646\\u0648\\u0632 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0646\\u06cc\\u0633\\u062a.\",\"en\":\"At week thirty-eight the fetus is about the size of a leek, roughly 49.8 cm and nearly 3.1 kg. The organs are complete and the baby is ready for life outside the womb, with a firmer grasp and eye color not yet final.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc\\u060c \\u062a\\u0648\\u0631\\u0645 \\u067e\\u0627 \\u0648 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0641\\u0632\\u0627\\u06cc\\u0634 \\u062a\\u0631\\u0634\\u062d\\u0627\\u062a \\u06cc\\u0627 \\u0646\\u0634\\u0627\\u0646\\u0647 \\u062e\\u0648\\u0646\\u06cc \\u0631\\u0627 \\u0628\\u0628\\u06cc\\u0646\\u06cc\\u062f. \\u062e\\u0648\\u0627\\u0628 \\u0648 \\u0631\\u0627\\u062d\\u062a\\u06cc \\u062f\\u0634\\u0648\\u0627\\u0631\\u062a\\u0631 \\u0627\\u0633\\u062a.\",\"en\":\"Pelvic pressure, leg swelling and practice contractions may increase. You may notice more discharge or the bloody show, and sleep and comfort are harder.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648\\u0627\\u0642\\u0639\\u06cc \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628 \\u06cc\\u0627 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645 \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0628\\u0631\\u0648\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take true labor signs seriously. Go to the hospital if your waters break or contractions become regular; keep counting movements.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0647\\u0641\\u062a\\u06af\\u06cc \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u0627\\u0637\\u0645\\u06cc\\u0646\\u0627\\u0646 \\u062d\\u0627\\u0635\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u06cc\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0627\\u0636\\u0637\\u0631\\u0627\\u0631\\u06cc \\u0648 \\u0645\\u0633\\u06cc\\u0631 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0631\\u0627 \\u062f\\u0631 \\u062f\\u0633\\u062a\\u0631\\u0633 \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Keep weekly visits and confirm your birth plan and when to come in. Your hospital bag should be ready, and keep emergency numbers and the route handy.\"}','{\"fa\":\"\\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0646\\u0627\\u0632\\u06a9 \\u0648 \\u0628\\u0627\\u0632 \\u0634\\u0648\\u062f \\u0648 \\u062c\\u0646\\u06cc\\u0646 \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u062f\\u0631 \\u0644\\u06af\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u06af\\u06cc\\u0631\\u062f. \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u062a\\u0645\\u0631\\u06cc\\u0646\\u06cc \\u0642\\u0648\\u06cc\\u200c\\u062a\\u0631 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u0628\\u062f\\u0646 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u0631\\u0648\\u0639 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0627\\u0633\\u062a.\",\"en\":\"The cervix may thin and open further and the baby settles fully into the pelvis. Practice contractions strengthen as the body readies for labor.\"}','{\"fa\":\"\\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0647\\u06cc\\u062c\\u0627\\u0646\\u060c \\u0628\\u06cc\\u200c\\u0635\\u0628\\u0631\\u06cc \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0627\\u06cc\\u062c\\u0627\\u062f \\u06a9\\u0646\\u062f. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u0631 \\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0627\\u06cc \\u0631\\u0627 \\u0628\\u0627 \\u062f\\u0642\\u062a \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f. \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0648 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0627\\u0637\\u0631\\u0627\\u0641\\u06cc\\u0627\\u0646 \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a.\",\"en\":\"Waiting for labor can bring excitement, impatience and anxiety. You may watch every sign closely; calm and support from others help.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0645\\u063a\\u0630\\u06cc \\u0648 \\u0627\\u0646\\u0631\\u0698\\u06cc\\u200c\\u0632\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0647\\u0636\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"Continue iron, calcium, protein and fiber and drink enough water. Nutritious, energizing foods help for labor, and small meals digest more easily.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u0648 \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0647 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0634\\u062f\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Light walking and pelvic floor exercises may help prepare for labor. Practice breathing exercises, listen to your body, and rest.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0647\\u0641\\u062a\\u06af\\u06cc \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0627\\u0633\\u062a. \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u0645\\u0627\\u06cc\\u0639 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0631\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u06a9\\u0646\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Weekly visits include blood pressure, weight, the baby\\u2019s position and a cervical check. Your doctor may assess the fetal heartbeat and amniotic fluid; report labor signs.\"}','{\"fa\":[{\"question\":\"\\u0686\\u0647 \\u0632\\u0645\\u0627\\u0646\\u06cc \\u0628\\u0627\\u06cc\\u062f \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0628\\u0631\\u0648\\u0645\\u061f\",\"answer\":\"\\u0628\\u0627 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u062f\\u0631\\u062f\\u0646\\u0627\\u06a9 \\u0628\\u0627 \\u0641\\u0648\\u0627\\u0635\\u0644 \\u06a9\\u0648\\u062a\\u0627\\u0647\\u060c \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628 \\u06cc\\u0627 \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\"},{\"question\":\"\\u0627\\u06af\\u0631 \\u062a\\u0627 \\u0645\\u0648\\u0639\\u062f \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0646\\u0634\\u062f \\u0686\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061f\",\"answer\":\"\\u062a\\u0648\\u0644\\u062f \\u0628\\u06cc\\u0646 \\u0647\\u0641\\u062a\\u0647 \\u06f3\\u06f7 \\u062a\\u0627 \\u06f4\\u06f2 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a\\u061b \\u0627\\u06af\\u0631 \\u0627\\u0632 \\u0645\\u0648\\u0639\\u062f \\u06af\\u0630\\u0634\\u062a\\u060c \\u067e\\u0632\\u0634\\u06a9 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u0631\\u0627 \\u067e\\u0627\\u06cc\\u0634 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f \\u0648 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0644\\u0632\\u0648\\u0645 \\u0627\\u0642\\u062f\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"}],\"en\":[{\"question\":\"When should I go to the hospital?\",\"answer\":\"Go with regular painful contractions at short intervals, if your waters break, or with bleeding.\"},{\"question\":\"What if labor doesn\\u2019t start by the due date?\",\"answer\":\"Birth between weeks 37 and 42 is normal; if you go past due, your doctor monitors and acts if needed.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(39,39,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0633\\u06cc\\u200c\\u0648\\u0646\\u0647\\u0645 \\u06a9\\u0647 \\u00ab\\u062a\\u0631\\u0645 \\u06a9\\u0627\\u0645\\u0644\\u00bb \\u0645\\u062d\\u0633\\u0648\\u0628 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u060c \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u0647\\u0646\\u062f\\u0648\\u0627\\u0646\\u0647 \\u06a9\\u0648\\u0686\\u06a9\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f5\\u06f0.\\u06f7 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f3.\\u06f3 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0627\\u0646\\u062f\\u0627\\u0645\\u200c\\u0647\\u0627 \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u0628\\u0627\\u0644\\u063a \\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u062a\\u0648\\u0644\\u062f \\u0647\\u0633\\u062a\\u0646\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u0686\\u0631\\u0628\\u06cc \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0646\\u0638\\u06cc\\u0645 \\u062f\\u0645\\u0627\\u06cc \\u0628\\u062f\\u0646 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"At week thirty-nine, considered full term, the fetus is about the size of a mini watermelon, roughly 50.7 cm and nearly 3.3 kg. The organs are fully mature and ready for birth, and the baby has enough fat to regulate body temperature.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc\\u060c \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0648 \\u062a\\u0631\\u0634\\u062d\\u0627\\u062a \\u0628\\u06cc\\u0634\\u062a\\u0631 \\u0634\\u0648\\u062f. \\u062e\\u0648\\u0627\\u0628 \\u0648 \\u062d\\u0631\\u06a9\\u062a \\u062f\\u0634\\u0648\\u0627\\u0631\\u062a\\u0631 \\u0627\\u0633\\u062a. \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0627\\u0648\\u0644\\u06cc\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Pelvic pressure, contractions and discharge may increase. Sleep and movement are harder, and you may notice early signs of labor.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648\\u0627\\u0642\\u0639\\u06cc \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628 \\u06cc\\u0627 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645 \\u0641\\u0648\\u0631\\u0627\\u064b \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0628\\u0631\\u0648\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take true labor signs seriously. Go to the hospital at once if your waters break or contractions are regular; keep counting movements.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0647\\u0641\\u062a\\u06af\\u06cc \\u0631\\u0627 \\u062f\\u0646\\u0628\\u0627\\u0644 \\u06a9\\u0646\\u06cc\\u062f \\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0631\\u0641\\u062a\\u0646 \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0633\\u0627\\u06a9 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0648 \\u0628\\u0631\\u0646\\u0627\\u0645\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u06cc\\u062f \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f. \\u0628\\u0627 \\u067e\\u0632\\u0634\\u06a9 \\u062f\\u0631\\u0628\\u0627\\u0631\\u0647 \\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0634\\u0631\\u0648\\u0639 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0635\\u062d\\u0628\\u062a \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Keep weekly visits and be ready to go to the hospital. Your bag and birth plan should be ready; discuss labor onset signs with your doctor.\"}','{\"fa\":\"\\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0646\\u0631\\u0645\\u060c \\u0646\\u0627\\u0632\\u06a9 \\u0648 \\u06a9\\u0645\\u200c\\u06a9\\u0645 \\u0628\\u0627\\u0632 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f. \\u062c\\u0646\\u06cc\\u0646 \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u062f\\u0631 \\u0644\\u06af\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u06af\\u0631\\u0641\\u062a\\u0647 \\u0627\\u0633\\u062a. \\u0628\\u062f\\u0646 \\u062f\\u0631 \\u0622\\u0633\\u062a\\u0627\\u0646\\u0647 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0642\\u0631\\u0627\\u0631 \\u062f\\u0627\\u0631\\u062f.\",\"en\":\"The cervix softens, thins and gradually opens for labor, and the baby is fully settled in the pelvis. The body is on the threshold of labor.\"}','{\"fa\":\"\\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0631\\u0648\\u0632\\u0647\\u0627\\u06cc \\u067e\\u0627\\u06cc\\u0627\\u0646\\u06cc \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u0628\\u06cc\\u200c\\u0635\\u0628\\u0631\\u06cc \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0647\\u0645\\u0631\\u0627\\u0647 \\u0628\\u0627 \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0627\\u06cc\\u062c\\u0627\\u062f \\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06a9\\u0632 \\u0628\\u0631 \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0648 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u06a9\\u0645\\u06a9\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0627\\u0633\\u062a. \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0627\\u0637\\u0631\\u0627\\u0641\\u06cc\\u0627\\u0646 \\u0628\\u0633\\u06cc\\u0627\\u0631 \\u0645\\u0647\\u0645 \\u0627\\u0633\\u062a.\",\"en\":\"Waiting in these final days can bring impatience and anxiety along with excitement. Focusing on calm and readiness helps, and support from others is very important.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0645\\u063a\\u0630\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0646\\u0631\\u0698\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0648 \\u0645\\u06a9\\u0631\\u0631 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0627\\u0633\\u062a.\",\"en\":\"Continue iron, calcium, protein and fiber and drink enough water. Nutritious foods help energy for labor, and small frequent meals are easier.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0647 \\u067e\\u06cc\\u0634\\u0631\\u0641\\u062a \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0648 \\u06a9\\u0641 \\u0644\\u06af\\u0646 \\u0631\\u0627 \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0628\\u06cc\\u0646 \\u0641\\u0639\\u0627\\u0644\\u06cc\\u062a \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u062a\\u0639\\u0627\\u062f\\u0644 \\u0628\\u0631\\u0642\\u0631\\u0627\\u0631 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"Light walking may help labor progress. Practice breathing and pelvic floor exercises, listen to your body, and balance activity with rest.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0647\\u0641\\u062a\\u06af\\u06cc \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0627\\u0633\\u062a. \\u067e\\u0632\\u0634\\u06a9 \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0646\\u06cc\\u0627\\u0632 \\u0645\\u0627\\u06cc\\u0639 \\u0622\\u0645\\u0646\\u06cc\\u0648\\u062a\\u06cc\\u06a9 \\u0631\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Weekly visits include blood pressure, weight, the baby\\u2019s position and a cervical check. The doctor assesses the fetal heartbeat and, if needed, amniotic fluid.\"}','{\"fa\":[{\"question\":\"\\u00ab\\u062a\\u0631\\u0645 \\u06a9\\u0627\\u0645\\u0644\\u00bb \\u0686\\u0647 \\u0627\\u0647\\u0645\\u06cc\\u062a\\u06cc \\u062f\\u0627\\u0631\\u062f\\u061f\",\"answer\":\"\\u0627\\u0632 \\u0647\\u0641\\u062a\\u0647 \\u06f3\\u06f9 \\u0646\\u0648\\u0632\\u0627\\u062f \\u0628\\u0647 \\u0628\\u0644\\u0648\\u063a \\u06a9\\u0627\\u0645\\u0644 \\u0631\\u0633\\u06cc\\u062f\\u0647 \\u0648 \\u0628\\u0647\\u062a\\u0631\\u06cc\\u0646 \\u0632\\u0645\\u0627\\u0646 \\u0628\\u0631\\u0627\\u06cc \\u062a\\u0648\\u0644\\u062f \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0645\\u062d\\u0633\\u0648\\u0628 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"},{\"question\":\"\\u0686\\u0637\\u0648\\u0631 \\u0634\\u0631\\u0648\\u0639 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u062a\\u0634\\u062e\\u06cc\\u0635 \\u062f\\u0647\\u0645\\u061f\",\"answer\":\"\\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645 \\u0648 \\u0641\\u0632\\u0627\\u06cc\\u0646\\u062f\\u0647\\u060c \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628 \\u06cc\\u0627 \\u0646\\u0634\\u0627\\u0646\\u0647 \\u062e\\u0648\\u0646\\u06cc \\u0627\\u0632 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0634\\u0631\\u0648\\u0639 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0647\\u0633\\u062a\\u0646\\u062f \\u0648 \\u0646\\u06cc\\u0627\\u0632 \\u0628\\u0647 \\u0645\\u0631\\u0627\\u062c\\u0639\\u0647 \\u062f\\u0627\\u0631\\u0646\\u062f.\"}],\"en\":[{\"question\":\"Why does full term matter?\",\"answer\":\"From week 39 the baby has reached full maturity and it is the best time for a natural birth.\"},{\"question\":\"How do I know labor is starting?\",\"answer\":\"Regular intensifying contractions, waters breaking or the bloody show are signs of labor needing attention.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00'),
(40,40,'{\"fa\":\"\\u062f\\u0631 \\u0647\\u0641\\u062a\\u0647 \\u0686\\u0647\\u0644\\u0645 \\u06a9\\u0647 \\u0645\\u0648\\u0639\\u062f \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0627\\u0633\\u062a\\u060c \\u062c\\u0646\\u06cc\\u0646 \\u0628\\u0647 \\u0627\\u0646\\u062f\\u0627\\u0632\\u0647 \\u06cc\\u06a9 \\u06a9\\u062f\\u0648 \\u062a\\u0646\\u0628\\u0644 \\u06a9\\u0648\\u0686\\u06a9\\u060c \\u062d\\u062f\\u0648\\u062f \\u06f5\\u06f1.\\u06f2 \\u0633\\u0627\\u0646\\u062a\\u06cc\\u200c\\u0645\\u062a\\u0631 \\u0648 \\u0646\\u0632\\u062f\\u06cc\\u06a9 \\u0628\\u0647 \\u06f3.\\u06f4 \\u06a9\\u06cc\\u0644\\u0648\\u06af\\u0631\\u0645 \\u0627\\u0633\\u062a. \\u0646\\u0648\\u0632\\u0627\\u062f \\u06a9\\u0627\\u0645\\u0644\\u0627\\u064b \\u0631\\u0634\\u062f \\u06a9\\u0631\\u062f\\u0647 \\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u062a\\u0648\\u0644\\u062f \\u0627\\u0633\\u062a. \\u0627\\u0633\\u062a\\u062e\\u0648\\u0627\\u0646\\u200c\\u0647\\u0627\\u06cc \\u062c\\u0645\\u062c\\u0645\\u0647 \\u0647\\u0646\\u0648\\u0632 \\u0646\\u0631\\u0645\\u200c\\u0627\\u0646\\u062f \\u062a\\u0627 \\u0627\\u0632 \\u06a9\\u0627\\u0646\\u0627\\u0644 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0639\\u0628\\u0648\\u0631 \\u06a9\\u0646\\u0646\\u062f.\",\"en\":\"At week forty, the due date, the fetus is about the size of a small pumpkin, roughly 51.2 cm and nearly 3.4 kg. The baby is fully grown and ready to be born, with skull bones still soft to pass through the birth canal.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0641\\u0634\\u0627\\u0631 \\u0644\\u06af\\u0646\\u06cc \\u0634\\u062f\\u06cc\\u062f\\u060c \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0648 \\u0628\\u06cc\\u200c\\u0642\\u0631\\u0627\\u0631\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f. \\u0646\\u0634\\u0627\\u0646\\u0647\\u200c\\u0647\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0627\\u0646\\u0646\\u062f \\u0646\\u0634\\u0627\\u0646\\u0647 \\u062e\\u0648\\u0646\\u06cc \\u06cc\\u0627 \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0638\\u0627\\u0647\\u0631 \\u0634\\u0648\\u062f. \\u0627\\u0646\\u062a\\u0638\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u062a\\u0648\\u0627\\u0646\\u062f \\u062e\\u0633\\u062a\\u0647\\u200c\\u06a9\\u0646\\u0646\\u062f\\u0647 \\u0628\\u0627\\u0634\\u062f.\",\"en\":\"You may have strong pelvic pressure, contractions and restlessness. Labor signs like the bloody show or waters breaking may appear, and waiting can be tiring.\"}','{\"fa\":\"\\u062a\\u063a\\u0630\\u06cc\\u0647 \\u0633\\u0627\\u0644\\u0645 \\u0648 \\u0645\\u06a9\\u0645\\u0644\\u200c\\u0647\\u0627 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u062c\\u062f\\u06cc \\u0628\\u06af\\u06cc\\u0631\\u06cc\\u062f. \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u067e\\u0627\\u0631\\u06af\\u06cc \\u06a9\\u06cc\\u0633\\u0647 \\u0622\\u0628\\u060c \\u062e\\u0648\\u0646\\u0631\\u06cc\\u0632\\u06cc \\u06cc\\u0627 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0645\\u0646\\u0638\\u0645 \\u0641\\u0648\\u0631\\u0627\\u064b \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0628\\u0631\\u0648\\u06cc\\u062f. \\u0634\\u0645\\u0627\\u0631\\u0634 \\u062d\\u0631\\u06a9\\u0627\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Continue healthy eating and supplements and take labor signs seriously. Go to the hospital at once if your waters break, you bleed, or contractions are regular; keep counting movements.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a\\u200c\\u0647\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0627\\u0631\\u062f \\u0648 \\u067e\\u0632\\u0634\\u06a9 \\u0648\\u0636\\u0639\\u06cc\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u0648 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0631\\u0627 \\u067e\\u0627\\u06cc\\u0634 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f. \\u0627\\u06af\\u0631 \\u062a\\u0627 \\u0686\\u0646\\u062f \\u0631\\u0648\\u0632 \\u067e\\u0633 \\u0627\\u0632 \\u0645\\u0648\\u0639\\u062f \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0646\\u0634\\u062f\\u060c \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0627\\u0644\\u0642\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0628\\u0631\\u0631\\u0633\\u06cc \\u06a9\\u0646\\u062f. \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0631\\u0641\\u062a\\u0646 \\u0628\\u0647 \\u0628\\u06cc\\u0645\\u0627\\u0631\\u0633\\u062a\\u0627\\u0646 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Visits continue and the doctor monitors the baby and cervix. If labor doesn\\u2019t start a few days past the due date, the doctor may consider induction; be ready to go in.\"}','{\"fa\":\"\\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0627\\u0632 \\u0648 \\u0622\\u0645\\u0627\\u062f\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f \\u0648 \\u0627\\u0646\\u0642\\u0628\\u0627\\u0636\\u0627\\u062a \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0647\\u0631 \\u0644\\u062d\\u0638\\u0647 \\u0634\\u0631\\u0648\\u0639 \\u0634\\u0648\\u0646\\u062f. \\u0628\\u062f\\u0646 \\u062a\\u0645\\u0627\\u0645 \\u0622\\u0645\\u0627\\u062f\\u06af\\u06cc \\u062e\\u0648\\u062f \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u0647 \\u06a9\\u0627\\u0631 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u062f. \\u0627\\u06cc\\u0646 \\u0645\\u0631\\u062d\\u0644\\u0647 \\u0646\\u0647\\u0627\\u06cc\\u06cc \\u0633\\u0641\\u0631 \\u0628\\u0627\\u0631\\u062f\\u0627\\u0631\\u06cc \\u0627\\u0633\\u062a.\",\"en\":\"The cervix opens and readies for birth and contractions may begin any moment. The body brings all its readiness to labor in this final stage of the pregnancy journey.\"}','{\"fa\":\"\\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u062a\\u0631\\u06a9\\u06cc\\u0628\\u06cc \\u0627\\u0632 \\u0647\\u06cc\\u062c\\u0627\\u0646 \\u0634\\u062f\\u06cc\\u062f\\u060c \\u0628\\u06cc\\u200c\\u0635\\u0628\\u0631\\u06cc \\u0648 \\u0627\\u0636\\u0637\\u0631\\u0627\\u0628 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u062a\\u062c\\u0631\\u0628\\u0647 \\u06a9\\u0646\\u06cc\\u062f. \\u0627\\u06af\\u0631 \\u0627\\u0632 \\u0645\\u0648\\u0639\\u062f \\u06af\\u0630\\u0634\\u062a\\u060c \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0645\\u06cc \\u0646\\u0627\\u0627\\u0645\\u06cc\\u062f \\u0634\\u0648\\u06cc\\u062f \\u06a9\\u0647 \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0627\\u0633\\u062a. \\u0622\\u0631\\u0627\\u0645\\u0634 \\u0648 \\u062d\\u0645\\u0627\\u06cc\\u062a \\u0631\\u0627 \\u062d\\u0641\\u0638 \\u06a9\\u0646\\u06cc\\u062f.\",\"en\":\"You may feel a mix of intense excitement, impatience and birth anxiety. If you go past due you may feel a little discouraged, which is normal; keep calm and supported.\"}','{\"fa\":\"\\u0622\\u0647\\u0646\\u060c \\u06a9\\u0644\\u0633\\u06cc\\u0645\\u060c \\u067e\\u0631\\u0648\\u062a\\u0626\\u06cc\\u0646 \\u0648 \\u0641\\u06cc\\u0628\\u0631 \\u0631\\u0627 \\u0627\\u062f\\u0627\\u0645\\u0647 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0622\\u0628 \\u06a9\\u0627\\u0641\\u06cc \\u0628\\u0646\\u0648\\u0634\\u06cc\\u062f. \\u063a\\u0630\\u0627\\u0647\\u0627\\u06cc \\u0633\\u0628\\u06a9 \\u0648 \\u0627\\u0646\\u0631\\u0698\\u06cc\\u200c\\u0632\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0645\\u0641\\u06cc\\u062f \\u0627\\u0633\\u062a. \\u0648\\u0639\\u062f\\u0647\\u200c\\u0647\\u0627\\u06cc \\u06a9\\u0648\\u0686\\u06a9 \\u0631\\u0627\\u062d\\u062a\\u200c\\u062a\\u0631 \\u0647\\u0636\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\",\"en\":\"Continue iron, calcium, protein and fiber and drink enough water. Light, energizing foods help for labor, and small meals digest more easily.\"}','{\"fa\":\"\\u067e\\u06cc\\u0627\\u062f\\u0647\\u200c\\u0631\\u0648\\u06cc \\u0633\\u0628\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0628\\u0647 \\u0634\\u0631\\u0648\\u0639 \\u06cc\\u0627 \\u067e\\u06cc\\u0634\\u0631\\u0641\\u062a \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u06a9\\u0645\\u06a9 \\u06a9\\u0646\\u062f. \\u062a\\u0645\\u0631\\u06cc\\u0646\\u0627\\u062a \\u062a\\u0646\\u0641\\u0633\\u06cc \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0645\\u062f\\u06cc\\u0631\\u06cc\\u062a \\u062f\\u0631\\u062f \\u062a\\u0645\\u0631\\u06cc\\u0646 \\u06a9\\u0646\\u06cc\\u062f. \\u0628\\u0647 \\u0628\\u062f\\u0646 \\u062e\\u0648\\u062f \\u06af\\u0648\\u0634 \\u062f\\u0647\\u06cc\\u062f \\u0648 \\u0627\\u0633\\u062a\\u0631\\u0627\\u062d\\u062a \\u06a9\\u0627\\u0641\\u06cc \\u062f\\u0627\\u0634\\u062a\\u0647 \\u0628\\u0627\\u0634\\u06cc\\u062f.\",\"en\":\"Light walking may help start or progress labor. Practice breathing exercises to manage pain, listen to your body, and rest enough.\"}','{\"fa\":\"\\u0648\\u06cc\\u0632\\u06cc\\u062a \\u0634\\u0627\\u0645\\u0644 \\u0641\\u0634\\u0627\\u0631 \\u062e\\u0648\\u0646\\u060c \\u0648\\u0632\\u0646\\u060c \\u0645\\u0639\\u0627\\u06cc\\u0646\\u0647 \\u062f\\u0647\\u0627\\u0646\\u0647 \\u0631\\u062d\\u0645 \\u0648 \\u067e\\u0627\\u06cc\\u0634 \\u0636\\u0631\\u0628\\u0627\\u0646 \\u0642\\u0644\\u0628 \\u062c\\u0646\\u06cc\\u0646 \\u0627\\u0633\\u062a. \\u0627\\u06af\\u0631 \\u0627\\u0632 \\u0645\\u0648\\u0639\\u062f \\u06af\\u0630\\u0634\\u062a\\u060c \\u067e\\u0632\\u0634\\u06a9 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0633\\u0648\\u0646\\u0648\\u06af\\u0631\\u0627\\u0641\\u06cc \\u0648 \\u062a\\u0633\\u062a \\u0633\\u0644\\u0627\\u0645\\u062a \\u062c\\u0646\\u06cc\\u0646 (NST) \\u0631\\u0627 \\u0628\\u0631\\u0627\\u06cc \\u0627\\u0637\\u0645\\u06cc\\u0646\\u0627\\u0646 \\u062a\\u0648\\u0635\\u06cc\\u0647 \\u06a9\\u0646\\u062f. \\u0639\\u0644\\u0627\\u0626\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u06af\\u0632\\u0627\\u0631\\u0634 \\u062f\\u0647\\u06cc\\u062f.\",\"en\":\"Visits include blood pressure, weight, a cervical check and fetal heartbeat monitoring. Past due, the doctor may advise an ultrasound and a non-stress test (NST) for reassurance.\"}','{\"fa\":[{\"question\":\"\\u0627\\u06af\\u0631 \\u0627\\u0632 \\u0645\\u0648\\u0639\\u062f \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0628\\u06af\\u0630\\u0631\\u0645 \\u0686\\u0647 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f\\u061f\",\"answer\":\"\\u062a\\u0627 \\u0647\\u0641\\u062a\\u0647 \\u06f4\\u06f2 \\u0645\\u0645\\u06a9\\u0646 \\u0627\\u0633\\u062a \\u0637\\u0628\\u06cc\\u0639\\u06cc \\u0628\\u0627\\u0634\\u062f\\u061b \\u067e\\u0632\\u0634\\u06a9 \\u0628\\u0627 \\u067e\\u0627\\u06cc\\u0634 \\u0633\\u0644\\u0627\\u0645\\u062a \\u062c\\u0646\\u06cc\\u0646 \\u062a\\u0635\\u0645\\u06cc\\u0645 \\u0645\\u06cc\\u200c\\u06af\\u06cc\\u0631\\u062f \\u0648 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u0644\\u0632\\u0648\\u0645 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0631\\u0627 \\u0627\\u0644\\u0642\\u0627 \\u0645\\u06cc\\u200c\\u06a9\\u0646\\u062f.\"},{\"question\":\"\\u0627\\u0644\\u0642\\u0627\\u06cc \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0686\\u06cc\\u0633\\u062a\\u061f\",\"answer\":\"\\u0631\\u0648\\u0634\\u06cc \\u067e\\u0632\\u0634\\u06a9\\u06cc \\u0628\\u0631\\u0627\\u06cc \\u0634\\u0631\\u0648\\u0639 \\u0632\\u0627\\u06cc\\u0645\\u0627\\u0646 \\u0627\\u0633\\u062a \\u06a9\\u0647 \\u062f\\u0631 \\u0635\\u0648\\u0631\\u062a \\u06af\\u0630\\u0634\\u062a\\u0646 \\u0627\\u0632 \\u0645\\u0648\\u0639\\u062f \\u06cc\\u0627 \\u0648\\u062c\\u0648\\u062f \\u062f\\u0644\\u0627\\u06cc\\u0644 \\u067e\\u0632\\u0634\\u06a9\\u06cc \\u062a\\u0648\\u0633\\u0637 \\u067e\\u0632\\u0634\\u06a9 \\u0627\\u0646\\u062c\\u0627\\u0645 \\u0645\\u06cc\\u200c\\u0634\\u0648\\u062f.\"}],\"en\":[{\"question\":\"What if I go past my due date?\",\"answer\":\"Up to week 42 can be normal; the doctor monitors the baby\\u2019s health and induces labor if needed.\"},{\"question\":\"What is labor induction?\",\"answer\":\"It is a medical way to start labor, done by the doctor when you are past due or for medical reasons.\"}]}','2026-09-23 09:00:00','2026-09-23 09:00:00');
